"""
Игровое полотно: карта, токены и растровые инструменты рисования.

Ключевые возможности отображения карты:
  * автоматическое центрирование карты при её загрузке;
  * независимое масштабирование вида (колесо мыши) и панорамирование;
  * ручное изменение положения/размера самой карты за угловые ручки
    (аналогично инструменту "Свободное трансформирование" в Photoshop);
  * перемещение карты мышью при выбранном инструменте "перемещение".

Слои и выделение:
  * токены лежат ВЫШЕ карты: клик по токену обрабатывается раньше карты;
  * карта получает рамку с ручками только когда её выбрали в левой панели;
  * клик по пустому месту снимает выделение со всего;
  * на токенах постоянной рамки выделения нет.
"""
