# --- Движок отрисовки стола -------------------------------------------------
#: Стол по умолчанию рисует видеокарта: GameCanvas наследует QOpenGLWidget,
#: и Qt ведёт весь QPainter через OpenGL (текстуры, сглаживание, композиция).
#: VTT_RENDERER=cpu возвращает прежний растровый движок: он нужен тестам без
#: экрана (offscreen) и выручает на машине, где OpenGL не завёлся.
def fit_map_image(image: QImage) -> Tuple[QImage, bool]:
    """Уменьшить картинку карты до размера, который примет видеокарта.

    Возвращает ``(картинка, уменьшена ли)``. Пропорции сохраняются, а
    обычные карты возвращаются как есть — лишнего пересчёта нет.

    Почему это нужно: рисование карты идёт через ``drawPixmap``, а GL-движок
    Qt загружает такую картинку ОДНОЙ текстурой. При превышении
    ``GL_MAX_TEXTURE_SIZE`` (или нехватке памяти под текстуру) загрузка
    молча проваливается, и вместо карты виден чёрный прямоугольник.
    """
    if image is None or image.isNull():
        return image, False
    width, height = image.width(), image.height()
    if width <= 0 or height <= 0:
        return image, False
    scale = 1.0
    if width > MAP_TEXTURE_MAX_SIDE or height > MAP_TEXTURE_MAX_SIDE:
        scale = min(MAP_TEXTURE_MAX_SIDE / float(width),
                    MAP_TEXTURE_MAX_SIDE / float(height))
    pixels = float(width) * float(height)
    if pixels * scale * scale > MAP_TEXTURE_MAX_PIXELS:
        scale = min(scale, math.sqrt(MAP_TEXTURE_MAX_PIXELS / pixels))
    if scale >= 0.999:
        return image, False
    target_w = max(1, int(round(width * scale)))
    target_h = max(1, int(round(height * scale)))
    # Плавное уменьшение 60+ Мпикс за один проход — это секунды загрузки.
    # Сначала грубо вдвое (быстро), затем последний шаг — качественно.
    work = image
    while work.width() > target_w * 2 or work.height() > target_h * 2:
        work = work.scaled(max(target_w, work.width() // 2),
                           max(target_h, work.height() // 2),
                           Qt.IgnoreAspectRatio, Qt.FastTransformation)
    work = work.scaled(target_w, target_h, Qt.IgnoreAspectRatio,
                       Qt.SmoothTransformation)
    return work, True


def split_map_tiles(pixmap: QPixmap) -> List[Tuple[QRectF, QRectF, QPixmap]]:
    """Нарезать карту на плитки, чтобы каждая стала отдельной текстурой.

    Возвращает список ``(своя часть, кусок с запасом, плитка)``. Оба куска
    заданы в пикселях исходной картинки: по ним холст считает, куда плитку
    положить и где её обрезать. Маленькие карты не режутся — им хватает
    одной текстуры.
    """
    if pixmap is None or pixmap.isNull():
        return []
    width, height = pixmap.width(), pixmap.height()
    if width <= MAP_TILE_FROM and height <= MAP_TILE_FROM:
        return []
    tiles: List[Tuple[QRectF, QRectF, QPixmap]] = []
    for top in range(0, height, MAP_TILE_SIZE):
        for left in range(0, width, MAP_TILE_SIZE):
            own_w = min(MAP_TILE_SIZE, width - left)
            own_h = min(MAP_TILE_SIZE, height - top)
            own = QRect(left, top, own_w, own_h)
            # Один пиксель запаса со всех сторон: сглаживание на краю плитки
            # берёт настоящих соседей, а не край текстуры. Без запаса на
            # стыке вылезала тонкая тёмная полоса.
            x0, y0 = max(0, left - 1), max(0, top - 1)
            x1 = min(width, left + own_w + 1)
            y1 = min(height, top + own_h + 1)
            padded = QRect(x0, y0, x1 - x0, y1 - y0)
            tiles.append((QRectF(own), QRectF(padded), pixmap.copy(padded)))
    return tiles


def render_mode() -> str:
    """Какой движок рисовать: «gpu» (OpenGL) или «cpu» (растр)."""
    forced = os.environ.get("VTT_RENDERER", "").strip().casefold()
    if forced in ("cpu", "raster", "software"):
        return "cpu"
    if forced in ("gpu", "opengl", "gl"):
        return "gpu"
    # Без настоящего окна OpenGL-контекста нет: тесты и сборка скриншотов
    # должны работать на растре, иначе они падают без видеодрайвера.
    platform = os.environ.get("QT_QPA_PLATFORM", "").strip().casefold()
    if platform in ("offscreen", "minimal"):
        return "cpu"
    return "gpu"


RENDER_MODE = render_mode()
#: Базовый класс холста выбирается один раз при импорте: QOpenGLWidget
#: нельзя «включить» у уже созданного виджета.
_CANVAS_BASE = QOpenGLWidget if RENDER_MODE == "gpu" else QWidget


def renderer_name(mode: str = "") -> str:
    """Человеческое название движка — для журнала и подсказок."""
    return ("видеокарта (OpenGL)" if (mode or RENDER_MODE) == "gpu"
            else "процессор (растр)")


