def _turn_delta(source: float, target: float) -> float:
    """Кратчайший поворот от source к target в градусах (−180…180).

    Без него доводка с 350° к 10° пошла бы длинной дорогой через полный круг.
    """
    return (float(target) - float(source) + 180.0) % 360.0 - 180.0


def fill_menu_entries(menu: QMenu, entries):
    """Заполнить ``menu`` по общему описанию пунктов.

    Один формат на все меню стола (ПКМ по холсту и кнопка «Стол» в верхней
    панели), чтобы они не расходились:

    * ``None`` — разделитель;
    * ``("Текст", "подсказка", действие)`` — пункт (действие может быть None);
    * ``("Текст", "подсказка", [пункты])`` — подменю;
    * четвёртый элемент-словарь ``{"checkable": True, "checked": ...}`` —
      галочка (например, «Привязка токенов к клеткам»), ``{"enabled": False}`` —
      погашенный пункт (у запертой двери «Открыть» недоступно).
    """
    for item in entries:
        if item is None:
            menu.addSeparator()
            continue
        label, hint, slot = item[:3]
        extra = item[3] if len(item) > 3 else {}
        if isinstance(slot, (list, tuple)):
            sub = menu.addMenu(label)
            sub.setToolTipsVisible(True)
            if hint:
                sub.setToolTip(hint)
            fill_menu_entries(sub, slot)
            continue
        act = QAction(label, menu)
        if hint:
            act.setToolTip(hint)
        if extra.get("checkable"):
            act.setCheckable(True)
            act.setChecked(bool(extra.get("checked")))
        if extra.get("enabled") is False:
            act.setEnabled(False)
        if slot is not None:
            act.triggered.connect(slot)
        menu.addAction(act)


def fit_token_art(rect, image_width, image_height):
    """Вписать картинку токена в квадрат, сохранив пропорции.

    Портреты в библиотеке бывают не квадратными (Тараск — 2200×5000), а
    раньше картинка растягивалась на весь квадрат токена и выглядела
    сплющенной. Вписываем по меньшей стороне и центрируем: ничего не
    обрезаем и не искажаем, прозрачные поля остаются прозрачными.
    """
    try:
        width = float(image_width)
        height = float(image_height)
    except (TypeError, ValueError):
        return rect
    if width <= 0 or height <= 0:
        return rect
    factor = min(rect.width() / width, rect.height() / height)
    draw_w = width * factor
    draw_h = height * factor
    return QRectF(rect.center().x() - draw_w / 2.0,
                  rect.center().y() - draw_h / 2.0,
                  draw_w, draw_h)
# Индикаторы на токене (состояния и спасброски от смерти) заданы в ЭКРАННЫХ
