# Значки состояний, череп со спасбросками и подпись — ДОЛИ РАЗМЕРА ТОКЕНА.
# Экранный размер пробовали — вышло хуже: при отдалении крошечный токен
# обрастал значками крупнее себя, и ряд висел над картой гирляндой.
# Доли сохраняют привычную картинку на 100 % и держат всё вместе с портретом
# на любом зуме: отдалили — уменьшились и значки, и череп, и имя.
