def condition_icon_key(name) -> Optional[str]:
    """Ключ иконки для названия состояния (или None, если не знаем)."""
    text = " ".join(str(name or "").strip().casefold().split())
    text = text.replace("ё", "е")
    if not text:
        return None
    if text in _ICON_KEYS:
        return text
    for prefix, key in _CONDITION_ICON_ROOTS:
        if text.startswith(prefix):
            return key
    return None

