# Полный боевой эффект: выпад — до удара, тряска/вспышка — после.
ATTACK_FX_S = 0.95
ATTACK_IMPACT = 0.34          # доля эффекта до момента попадания
ATTACK_LUNGE_RATIO = 0.16     # выпад в долях размера токена
ATTACK_SHAKE_RATIO = 0.09     # амплитуда тряски в долях размера
# Полоса хитов догоняет новое значение, а не перескакивает.
HP_BAR_ANIM_S = 0.35
ANIM_FRAME_MS = 16
# Поворот токена клавишей R. Стартовая задержка нужна, чтобы случайное
# касание мыши не дёргало токен: первые 0.35 с он стоит, потом плавно
# догоняет курсор. Второе R не запускает отдельную доводку: пружина и так
# мягко тормозит у цели, а доводка с нулевой скоростью обрывала движение на
# полушаге — токен вставал и снова разгонялся, это и читалось как рывок.
TOKEN_TURN_START_DELAY_S = 0.35
# Взгляд догоняет курсор пружиной, а не перезапускаемым твином: у твина
# каждый сдвиг мыши начинал движение заново с нуля, и токен дёргался —
# стартовал рывком, а при частых событиях почти не двигался.
# Пружина критически задемпфированная (2√k): разгон из покоя, мягкое
# торможение у цели, без качания вокруг неё. Собственная частота
# ω = 16 1/с — полный поворот успокаивается примерно за 0.25 с.
TOKEN_TURN_STIFFNESS = 256.0
TOKEN_TURN_DAMPING = 32.0
#: Предел угловой скорости: резкий рывок мыши через весь холст не должен
#: раскручивать портрет до мельтешения.
TOKEN_TURN_MAX_SPEED = 900.0
#: Ближе этого — доводим точно и останавливаем пружину. Остаток 0.05° на
#: экране — четверть пикселя, его не видно. Больше нельзя: дожим в полградуса
#: на медленном подходе (5°/с) давал скачок в шесть раз больше шага — это и
#: читалось как подергивание на остановке.
TOKEN_TURN_SNAP_DEG = 0.05
TOKEN_TURN_SNAP_SPEED = 3.0
#: Собственная частота пружины: критическое демпфирование — это ω = √k.
TOKEN_TURN_OMEGA = math.sqrt(TOKEN_TURN_STIFFNESS)
#: Предел одного шага: после долгого подвисания взгляд доедет одним кадром,
#: а не поедет рывком. Точное решение пружины от dt не ломается, поэтому
#: предел здесь только чтобы кадр не прыгал через полкарты.
TOKEN_TURN_MAX_DT = 0.25
# Переход день/ночь: карта не заливается темнотой рывком, а гаснет за
# NIGHT_FADE_S с мягкими краями — как заходит солнце.
NIGHT_FADE_S = 0.9
# Дверь: створка поворачивается на петле за 0.35 с. Раньше открытая дверь
# рисовалась сразу в новом положении, поверх старого — на холсте стояли две
# створки. Теперь створка одна и ходит: закрыта — лежит в стене, распахнута —
# стоит поперёк. Пока не дошла до DOOR_PASS_ANGLE, пройти нельзя: токен
# упирается в створку, как в настоящую дверь, и проходит, когда она открылась.
DOOR_SWING_S = 0.35
DOOR_OPEN_ANGLE = 90.0
DOOR_PASS_ANGLE = 80.0
# Лечение: мягкая зелёная волна и частицы. Дольше удара — эффект должен
# читаться как «восстановление», а не как ещё одно попадание.
# --- Большие карты ---------------------------------------------------------
# Карта рисуется одной текстурой: QOpenGLWidget передаёт весь QPixmap в
# glTexImage2D и НЕ режет его на части. Если сторона больше лимита
# видеокарты или картинка не влезает в её память, Qt не проверяет ошибку
# загрузки — на холсте остаётся чёрный прямоугольник. Поэтому слишком
# большие карты один раз уменьшаем до безопасного размера: сторону 8192 и
# 24 Мпикс (96 МБ в RGBA — ниже типичного предела одной текстуры). Мир,
# сетка и координаты не меняются: они считаются по ИСХОДНЫМ пикселям.
MAP_TEXTURE_MAX_SIDE = 8192
MAP_TEXTURE_MAX_PIXELS = 24_000_000
# Даже уложенная в лимит карта рисуется ОДНОЙ текстурой: видеокарта с малым
# GL_MAX_TEXTURE_SIZE или без свободной памяти под такую текстуру молча
# оставляет чёрный прямоугольник. Поэтому картинку режем на плитки — каждая
# уходит в свою небольшую текстуру. 1024 — безопасный размер для любой
# видеокарты, а нахлёст в один исходный пиксель прячет шов между плитками.
MAP_TILE_SIZE = 1024
#: С этих размеров карта уже режется: 2048 берёт даже минимальный OpenGL.
MAP_TILE_FROM = 2048

# --- Кэш световых масок ----------------------------------------------------
# Маска ночи и дневного отсвета считается в мировых координатах и
# привязывается к сетке мира, а не к экрану: только так она ездит вместе с
# камерой бесплатно. Шаг привязки — в мировых единицах (у стола клетка
# обычно 30–70), запас — доля экрана, чтобы небольшое движение мыши не
# вызывало пересчёт всех теней.
MASK_SNAP = 256.0
MASK_MARGIN = 0.3
#: Дольше этого кадр считается тормознутым — по этому порогу показывается
#: подсказка в отчёте о графике.
FRAME_WARN_MS = 40.0

HEAL_FX_S = 1.35
HEAL_PARTICLE_COUNT = 34
# Цепная молния: дуга разряда. Живёт меньше лечения — это удар, а не волна,
# но дольше удара: цепочку из нескольких дуг должно быть видно целиком.
ARC_FX_S = 0.66
# Сколько изломов у дуги и насколько она уходит в сторону (доля длины).
ARC_SEGMENTS = 9
ARC_DRIFT_RATIO = 0.075

# --- Кровь от попаданий ------------------------------------------------------
# Кровь живёт по времени, а не по кадрам:
#   * 3 минуты — свежая и влажная (глянец, яркий цвет);
#   * 2 минуты — сохнет: цвет темнеет, блеск уходит, к 5-й минуте пятно
#     выглядит уже высохшим;
#   * 10 минут — тихо исчезает;
#   * после — остаются шероховатые порезы и бурые корки, как место боя
#     в Age of Empires. Всего 15 минут на всё.
BLOOD_WET_S = 3 * 60.0
BLOOD_DRY_S = 2 * 60.0
BLOOD_FADE_S = 10 * 60.0
#: Полный срок жизни пятна: влажное → высохшее → пропало.
BLOOD_LIFE_S = BLOOD_WET_S + BLOOD_DRY_S + BLOOD_FADE_S
#: Сколько летят капли (дольше не нужно: анимация держит таймер кадров).
BLOOD_SPLASH_S = 1.1
#: За сколько секунд лужа растекается до своего размера.
BLOOD_POOL_SPREAD_S = 2.2
#: Предел растекания от центра токена в клетках: кровь заходит на соседние
#: клетки, но не заливает полкарты.
BLOOD_REACH_CELLS = 0.85
#: Сколько всплесков помним: старые высыхают в отметины, лимит — от памяти.
BLOOD_MAX_HITS = 80
#: Раз в сколько секунд перерисовывать высыхающую кровь (медленное увядание
#: не требует 60 кадров в секунду).
BLOOD_DRY_TICK_MS = 15000
#: Пока хитов половина и больше — только капли; лужа появляется строго
#: ниже середины.
BLOOD_HEAVY_RATIO = 0.5
#: На последних 10% хитов с раны медленно капает кровь.
BLOOD_DRIP_RATIO = 0.10
BLOOD_DRIP_INTERVAL_S = 5.0
BLOOD_DRIP_TICK_MS = 1000

