# --- Нежить ---------------------------------------------------------------
#: Нежить не кровит: от неё отлетают сине-зелёные куски, а лужи и порезов
#: не остаётся. Маркеры типа ищутся в статблоке — там тип по-русски
#: («нежить», «нежить (оборотень)»), но понимаем и английский.
UNDEAD_MARKERS = ("нежить", "undead")
#: Сколько живут куски нежити: короткий разлёт, потом пятно тает.
ICHOR_LIFE_S = 4.0
#: Пока куски нежити тают, перерисовываем чаще, чем сохнущую кровь.
ICHOR_TICK_MS = 1000
#: Сколько следов можно запечь в картинку за один кадр.
BLOOD_BAKE_PER_FRAME = 4
#: Ступени плотности запечённого следа (пикселей картинки на единицу мира).
#: Плотность идёт за зумом, чтобы край пятна оставался резким; ступени не
#: дают перепекать след на каждом шаге колеса мыши. Последняя ступень —
#: предел: при большем приближении честнее нарисовать след вектором.
#: Плотность идёт за зумом до самого предела приближения: на 20× пятно
#: шириной в полторы клетки — это 1600 пикселей экрана, и печь его выгодно:
#: кадр потом обходится одним выводом картинки вместо десятка заливок.
#: Плотность запечённого пятна: пикселей картинки на единицу мира. Одна и
#: та же на любом зуме: иначе приближение и отдаление перепекали бы пятно,
#: и рисунок крови «перещёлкивался» бы на упрощённый.
BLOOD_SPRITE_DENSITY = 6.0
#: Сторона одной запечённой картинки — 1600 px ≈ 10 МБ памяти.
BLOOD_SPRITE_MAX_SIDE = 1600
#: Сколько пикселей картинок следов можно держать в памяти разом.
#: Дальше картинки пятен за краем кадра отпускаются: за долгую сессию
#: их накапливаются сотни мегабайт.
BLOOD_SPRITE_BUDGET_PX = 24_000_000
#: С какого и до какого масштаба проявляется мелкая фактура пятна
#: (крошка, сгустки, трещины корки). На общем виде она была бы шумом,
#: а на сильном зуме без неё лужа выглядит плоской заливкой.
BLOOD_DETAIL_ZOOM_START = 3.0
BLOOD_DETAIL_ZOOM_FULL = 8.0
#: Сколько крупинок и трещин живёт в самом крупном слое фактуры. Крупа
#: мелкая: на общем виде она меньше пикселя, на сильном зуме читается
#: как фактура.
BLOOD_DETAIL_SPECKS = 110
BLOOD_DETAIL_CRACKS = 11
#: Фактура идёт в несколько октав — слоёв разного масштаба. Одна и та же
#: крупа в мире выглядит по-разному в зависимости от зума: на общем виде
#: она мелкая и плотная, а на предельном приближении отдельная крупинка
#: разрастается в пятно размером с ладонь, и лужа снова становится плоской
#: заливкой. Поэтому с каждым шагом зума включается более мелкая октава:
#: частота текстуры в пикселях экрана остаётся примерно постоянной, и
#: детали не теряются на всём диапазоне приближения.
#: (множитель радиуса крупинки, сколько крупинок, зум появления,
#:  зум полной силы)
#: Две октавы закрывают весь диапазон до 20×: крупа второй на предельном
#: приближении — 2–7 пикселей экрана, мельче уже не читается, а кадр
#: платит за каждый слой полной заливкой области пятна.
BLOOD_DETAIL_OCTAVES = (
    (1.0, BLOOD_DETAIL_SPECKS, BLOOD_DETAIL_ZOOM_START,
     BLOOD_DETAIL_ZOOM_FULL),
    (0.34, 340, 7.0, 13.0),
)
#: Сколько октав фактуры разрешено собрать за один кадр. При резком прыжке
#: зума (колесо мыши) иначе один кадр собирал бы сотни крупинок для всех
#: пятен сразу — это заметный рывок.
BLOOD_DETAIL_BUILD_PER_FRAME = 2
#: Толщина трещин корки на экране. В мире она пересчитывается по зуму:
#: иначе на предельном приближении волосяная трещина становится толщиной
#: с палец, а вместе с ней уходит и вся выразительность сухого следа.
BLOOD_CRACK_SCREEN_PX = 2.6  # в пикселях оформления (design)
BLOOD_CRACK_HAIR_SCREEN_PX = 1.4
#: Запас вокруг кадра при отборе пятен, в пикселях экрана. Всё, что дальше,
#: не рисуется вообще: на сильном зуме пятен за краем становится особенно
#: много, а их фактура — самая дорогая часть кадра.
BLOOD_CULL_MARGIN_PX = 96.0


def is_undead(token) -> bool:
    """Существо из справочника типа «нежить»?"""
    block = getattr(token, "statblock", None)
    if not isinstance(block, dict):
        return False
    kind = " ".join(str(block.get(key) or "")
                    for key in ("type", "ctype")).lower()
    return any(marker in kind for marker in UNDEAD_MARKERS)

# Инструмент растрового рисования
# Линия рисуется в тот же растровый слой, что и кисть. Так у неё сразу есть
# привязка к карте, ластик, Ctrl+Z и «стереть всё» — всё то, что уже работает
# для кисти, и не нужен отдельный векторный объект.
RASTER_TOOLS = ('brush', 'line', 'circle', 'square', 'polygon', 'eraser')

# Курсор-окружность рисуется под фактическую толщину кисти. Ниже этого
# диаметра кольцо уже не читается как кольцо — показываем перекрестье.
MIN_CURSOR_CIRCLE_PX = 5
# Крупнее этого курсор делать нельзя: система ограничивает размер указателя
# (обычно 128 px), и большой курсор превратился бы в пустой квадрат.
MAX_CURSOR_PX = 128
# Инструменты, которые тянут вторую точку (а не набор точек)


def tool_needs_second_point(mode) -> bool:
    return mode in ('line', 'circle', 'square')


class GameCanvas(_CANVAS_BASE):
    """Основное полотно игры.

    На обычном запуске базовый класс — QOpenGLWidget: QPainter в paintEvent
    рисует через OpenGL, то есть карту и токены считает видеокарта. Тесты и
    запуск без экрана работают на QWidget (растр), см. `render_mode()`.
    """

    # --- Сигналы ---
    token_moved = pyqtSignal(str, float, float)
    # Групповое перемещение: список словарей {'token_id', 'x', 'y'}.
    # Отдельный сигнал, чтобы тащить пачку токенов одной операцией.
    tokens_moved = pyqtSignal(list)
    token_selected = pyqtSignal(str)
    #: Выделение на холсте изменилось целиком (в т.ч. рамкой по нескольким
    #: токенам): по нему список сцены подсвечивает все выбранные строки.
    token_selection_changed = pyqtSignal()
    token_deselected = pyqtSignal()
    map_selected = pyqtSignal()
    map_deselected = pyqtSignal()
    # Настройки объекта (стрелка на объекте): main_window открывает диалог.
    # Объект подвинули/растянули: новую геометрию надо разослать.
    object_updated = pyqtSignal(dict)
    #: Актёра из библиотеки «Мои актёры» перетащили на карту.
    my_actor_dropped = pyqtSignal(str, float, float)
    #: Предмет из инвентаря или справочника брошен на токен: (payload, token_id).
    item_dropped = pyqtSignal(dict, str)
    map_clicked = pyqtSignal(float, float)
    add_token_requested = pyqtSignal(float, float)
    add_map_requested = pyqtSignal(float, float)
    map_updated = pyqtSignal(dict)
    remove_token_requested = pyqtSignal(str)
    remove_tokens_requested = pyqtSignal(list)   # пакетное удаление выделенных
    remove_map_requested = pyqtSignal(str)       # удалить карту по id
    token_updated_requested = pyqtSignal(dict)
    #: Холст переключил день/ночь: окно отправит новое освещение на сервер.
    time_of_day_changed = pyqtSignal(str)
    #: Мастер сменил цвет или плотность ночи (цвет #rrggbb, проценты).
    night_tint_changed = pyqtSignal(str, int)
    #: Источники света карты изменились (полный список) — окно шлёт на сервер.
    lights_changed = pyqtSignal(list)
    #: Стены и проёмы карты изменились (полные списки) — окно шлёт на сервер.
    walls_changed = pyqtSignal(list, list)
    #: Магнит стен изменился: (включён, шаг в долях клетки). Окно отправляет
    #: это на сервер, чтобы настройка сохранилась вместе с миром.
    wall_snap_changed = pyqtSignal(bool, float)
    #: Дверь толкнули: (opening_id, open) — окно шлёт на сервер, а сервер
    #: объявляет всем, и у всех хлопает звук.
    door_toggled = pyqtSignal(str, bool)
    #: Мастер запрашивает замок двери: (opening_id, locked).
    door_lock_requested = pyqtSignal(str, bool)
    #: Привязка токенов к клеткам переключена мастером — окно шлёт это
    #: на сервер, чтобы у игроков токены ходили по клеткам так же.
    snap_changed = pyqtSignal(bool)
    #: Мастер меняет плотность тумана: ("room" | "world", проценты).
    fog_alpha_changed = pyqtSignal(str, int)
    #: Мастер сменил вид тумана: ("mono" | "sepia" | "color" | "custom",
    #: свой цвет #rrggbb). Вид — настройка карты, поэтому окно шлёт его всем.
    fog_style_changed = pyqtSignal(str, str)
    #: Стол разведал новые комнаты: (id карты, подписи комнат). Окно шлёт их
    #: на сервер, чтобы разведка сохранилась вместе с миром.
    explored_rooms_changed = pyqtSignal(str, list)
    #: Мастер сменил зрение игроков: "cone" или "around". Настройка стола,
    #: поэтому окно пересылает её на сервер для всех клиентов.
    vision_mode_changed = pyqtSignal(str)
    #: Створка пошла в новое положение (opening_id, open). Звук двери
    #: играется здесь, а не по эху сервера: своё действие слышно в тот
    #: момент, когда дверь действительно начала двигаться.
    door_swing_started = pyqtSignal(str, bool)
    #: Заготовку света притащили на карту: (созданный источник).
    light_preset_dropped = pyqtSignal(dict)
    #: Del/X при выбранном источнике: (id источников) — окно удаляет и
    #: обновляет список.
    light_delete_requested = pyqtSignal(list)
    #: Источник выделен кликом на холсте (id): список в окне подсвечивает
    #: ту же строку, иначе выбор виден только на карте.
    light_selected = pyqtSignal(str)
    #: хоткей особой атаки (token_id, attack_id) — нажата назначенная клавиша
    special_attack_hotkey_requested = pyqtSignal(str, str)
    grid_settings_requested = pyqtSignal()
    graphics_settings_requested = pyqtSignal()
    files_dropped = pyqtSignal(str)
    # Растровый рисунок
    draw_op_committed = pyqtSignal(dict)      # новая операция рисования
    # Текстовые надписи: объекты, а не штрихи. Сигналы несут уже готовые
    # данные для сети; состояние на сервере — единственный источник правды.
    text_added = pyqtSignal(dict)             # новая надпись
    text_updated = pyqtSignal(str, dict)      # (id, изменённые поля)
    text_removed = pyqtSignal(str)            # id удалённой надписи
    text_selected = pyqtSignal(object)        # id или None — панель текста
    token_visibility_toggled = pyqtSignal(str, bool)  # глазок: (token_id, visible)
    # Выставить хиты/КД токена (ДМ): диалог открывает main_window
    token_hp_requested = pyqtSignal(str)
    # Боевые действия из меню токена: единая карточка актёра, атака,
    # спасбросок и состояния.
    template_done = pyqtSignal(dict)          # шаблон AoE зафиксирован: клетки
    template_cancelled = pyqtSignal()         # шаблон закрыт без применения
    #: Заклинание взведено на цель: клик по токену несёт его id.
    target_picked = pyqtSignal(str)
    #: Выбор цели отменён (Esc, ПКМ, другой каст) — расход не случился.
    target_pick_cancelled = pyqtSignal()
    token_attack_requested = pyqtSignal(str)
    token_save_requested = pyqtSignal(str)
    token_conditions_requested = pyqtSignal(str)
    # Быстрая атака: клик по другому токену при выбранном атакующем.
    # Несёт (attacker_id, target_id) — окно само подставит базовую атаку.
    token_quick_attack_requested = pyqtSignal(str, str)
    #: Взвод/сброс быстрой атаки: окно по этому сигналу обновляет кнопку
    #: тулбара и подсказку, ведь после удара режим снимается сам.
    quick_attack_mode_changed = pyqtSignal(bool)
    #: Q/Й на холсте: включить или выключить режим быстрой атаки.
    #: QShortcut ловит латиницу, а кириллицу приходится разбирать здесь.
    quick_attack_toggle_requested = pyqtSignal()
    # Редактируемая карточка актёра (Foundry-лист) по токену.
    token_actor_sheet_requested = pyqtSignal(str)
    # Воскрешение мёртвого токена (только мастер).
    token_revive_requested = pyqtSignal(str)
    # Токен не может двигаться (скорость 0): текст для чата.
    movement_blocked = pyqtSignal(str)
    #: Сколько футов осталось на ход — короткая строка для статусбара.
    movement_reported = pyqtSignal(str)
    #: Игрок нажал рывок: главное окно сообщает серверу, чтобы тот
    #: увеличил бюджет и принимал шаги дальше обычной скорости.
    dash_used = pyqtSignal(str)
    clear_drawings_requested = pyqtSignal()   # стереть весь рисунок
    undo_drawing_requested = pyqtSignal()     # отменить последний штрих
    tool_changed = pyqtSignal(str)            # сменился активный инструмент
    grid_calibrated = pyqtSignal(dict)        # калибровка сетки по двум точкам
    grid_changed = pyqtSignal(dict)           # сетка изменилась (шаг/смещение)
    # Завершена правка: перетаскивание токенов или карты, ресайз карты.
    # Несёт снимок «до» и состояние «после» — из них окно строит запись истории.
    edit_finished = pyqtSignal(dict)

    def __init__(self, parent=None):
        super().__init__(parent)

        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.StrongFocus)
        self.setAcceptDrops(True)

        # Состояние вида
        self.offset_x = 0.0
        self.offset_y = 0.0
        self.scale = 1.0
        #: Положение холста внутри родителя: по нему видно, когда граница
        #: левой панели сдвинула холст, и вид компенсирует это смещение.
        self._view_origin: Optional[QPoint] = None
        self.min_scale = 0.05
        self.max_scale = 20.0

        # Текущая карта
        self.current_map: Optional[MapData] = None
        self.map_image: Optional[QPixmap] = None
        #: Плитки карты: (кусок исходной картинки, плитка). Пусто — карта
        #: рисуется целиком одной текстурой (она маленькая).
        self._map_tiles: List[Tuple[QRectF, QRectF, QPixmap]] = []
        self._map_image_path: Optional[str] = None
        #: Подпись о том, что большая карта была уменьшена (пусто — не было).
        self.map_downscaled_note: str = ""
        #: Подпись о том, что файл карты не найден или не читается.
        self.map_error_note: str = ""

        # Игровые объекты
        self.tokens: Dict[str, Token] = {}
        self.token_images: Dict[str, QPixmap] = {}
        # Объекты карты: PNG-слои (крыши, деревья, декор). Хранятся отдельно
        # от токенов: у них своя геометрия, прозрачность и слой.
        self.objects: Dict[str, MapObject] = {}
        self.object_images: Dict[str, QPixmap] = {}
        self.selected_object_id: Optional[str] = None
        self.moving_object = False
        self.resizing_object = False
        self.rotating_object = False
        #: Режим поворота токена (R): первый R включает, второй — фиксирует.
        #: Пока он включён, мышь вокруг токена меняет направление взгляда, а
        #: на карте подсвечен жёлтым конус зрения.
        self.rotating_token_id: Optional[str] = None
        self._rotate_token_restore: Optional[float] = None
        #: Плавный поворот: какую цель задала мышь и где токен сейчас.
        self._turn_token_id: Optional[str] = None
        self._turn_target: Optional[float] = None
        #: Угловая скорость пружины взгляда и время её последнего шага.
        self._turn_speed = 0.0
        self._turn_last_step = 0.0
        self._turn_ready_at = 0.0
        #: Второе R нажали: пружину доводим до цели и фиксируем угол.
        #: Внутри лежит прежний угол — он нужен Ctrl+Z.
        self._turn_commit: Optional[dict] = None
        #: Модуль освещения включён в стартовом окне: ночь вырезает свет
        #: источников, а маркеры можно таскать с открытой вкладкой.
        self.lighting_enabled = False
        self.light_editing = False
        self.selected_light_id: Optional[str] = None
        self._dragging_light_id: Optional[str] = None
        self._light_drag_offset = (0.0, 0.0)
        #: Куда и с каким радиусом встанет свет из перетаскивания: круг под
        #: курсором, пока заготовку несут над картой.
        self._light_drop_preview: Optional[dict] = None
        #: Плавный переход день/ночь: {from, to, start} в долях 0…1.
        self._night_fade: Optional[dict] = None
        #: Буфер маски ночи: пересоздаётся только при смене размера окна,
        #: а не на каждом кадре.
        self._night_mask_image: Optional[QImage] = None
        #: Подпись содержимого маски: если не изменилась, слой не пересчитываем.
        self._night_mask_signature = None
        #: Слой источников БЕЗ выреза тёмного зрения и его подпись. Свет
        #: пересобирается только когда меняются сами источники, стены, зум
        #: или цвет ночи. Раньше вырез зрения входил в общую подпись, и на
        #: карте с 57 источниками каждый шаг взгляда заново считал все 57
        #: кругов с тенями — 11 мс кадра вместо одной копии готового слоя.
        self._night_lights_image: Optional[QImage] = None
        self._night_lights_signature = None
        #: Подпись маски «ночь без источников» (заливка + вырез зрения).
        self._night_plain_signature = None
        #: Слой дневного отсвета «сверх силы» и его подпись.
        self._day_glow_image: Optional[QImage] = None
        self._day_glow_signature = None
        #: Буфер слоя объектов для ночного затемнения (силуэты без света).
        self._object_layer_image: Optional[QImage] = None
        #: Буфер собранного кадра тумана игрока: две картинки (чб и цвет)
        #: склеиваются в него в растре, а холст получает готовый кадр.
        self._fog_frame_image: Optional[QImage] = None
        #: Буфер сцены для игрока: сцена рисуется в него перед ч/б-копией.
        self._fog_scene_image: Optional[QImage] = None
        #: Мелкие слои кадра (туман по сектору, пятно тёмного зрения). Их
        #: нельзя создавать заново каждый кадр: см. `scratch_image`.
        self._scratch_images: Dict[str, QImage] = {}
        #: Замкнутые области карты (комнаты) в мире и их экранный путь:
        #: меняются только вместе с геометрией и камерой.
        self._rooms_cache: Optional[list] = None
        self._rooms_key = None
        #: Комнаты полигонами (контур по стенам) — для заливки тумана.
        self._room_polys_cache: Optional[list] = None
        self._room_polys_key = None
        self._room_path_cache: Optional[QPainterPath] = None
        self._room_path_key = None
        #: Разведанные комнаты: их туман комнат больше не заливает. Ключ —
        #: карта, значение — подписи комнат (см. room_signature). Живёт до
        #: конца сессии: правка стен меняет подписи, и комнаты считаются
        #: заново, но перезагрузка мира разведку не обещает.
        self._explored_rooms = {}
        self._explored_path_cache: Optional[QPainterPath] = None
        self._explored_path_key = None
        #: Полосы запасного расчёта, склеенные в комнаты — кэш по геометрии.
        self._room_groups_cache = None
        self._room_groups_key = None

        #: Что игрок видит цветным: "around" — всё вокруг токена (как
        #: раньше), "cone" — только сектор обзора, куда токен смотрит.
        #: Настройка мастера, одна на всех его игроков.
        self.player_vision_mode = "around"
        #: Мастер спрятал у себя стены и окна (для игры на телевизоре):
        #: двери остаются видны, линий геометрии на столе нет.
        self.hide_dm_walls = False
        #: Чьи токены в этом кадре рисуются поверх тумана. В сцену их уже
        #: не кладём: иначе токен рисовался бы дважды за кадр, а
        #: полупрозрачная плашка смешивалась бы сама с собой и мигала.
        self._fog_overlay_ids = frozenset()
        #: Мастер смотрит на стол глазами игроков: туман считается по всем
        #: токенам игроков сразу, а его актёры вне обзора не рисуются.
        #: Управлять такими актёрами всё равно можно — через список сцены.
        self.dm_fog_enabled = False
        #: Как достать лист персонажа по токену (ставит главное окно):
        #: тёмное зрение живёт в листе, а не в самом токене.
        self.sheet_lookup = None
        #: Область, которую ночь не затемняет (тёмное зрение своих токенов):
        #: в экранных координатах, на один кадр. Через неё _paint_night_mask
        #: вырезает дырки, а _paint_player_fog рисует там ч/б.
        self._night_cut_path: Optional[QPainterPath] = None
        self._night_cut_key = None
        #: Куски, из которых собран `_night_cut_path`: ночь стирается ими по
        #: одному, а не объединённым путём (у объединения обратный обход
        #: перекрытий, и на стыке остаются непробитые серпы).
        self._night_cut_parts: tuple = ()
        #: Круги тёмного зрения и подпись, по которой они собраны: за кадр
        #: их спрашивают несколько раз, а меняются они только вместе с
        #: токеном и камерой.
        self._dark_state_cache = None
        #: Полигоны видимости по токенам: тёмное зрение строится тем же
        #: правилом, что и зрение, и при совпавшей дальности берёт готовый
        #: полигон вместо второго расчёта по тем же стенам.
        self._sight_poly_cache: Dict[tuple, object] = {}
        #: Дальность тёмного зрения на момент последнего пересчёта: по ней
        #: видно, надо ли перерисовывать кадр после прихода листа.
        self._darkvision_signature = None


        # Стены карты: ломаные, окна и двери (правила — shared/walls.py).
        #: Активный инструмент стен: None, "rect", "points", "edit",
        #: "window", "door", "delete".
        self.wall_tool: Optional[str] = None
        self.selected_wall_id: Optional[str] = None
        self.selected_opening_id: Optional[str] = None
        #: Ширина нового окна или двери в футах (одна на оба инструмента).
        self.wall_opening_ft = wall_rules.DEFAULT_DOOR_FT
        #: Ломаная, которую сейчас расставляют по точкам.
        self._wall_draft: List[tuple] = []
        #: Точка стены, которую тянут: (wall_id, индекс).
        self._wall_drag_point: Optional[tuple] = None
        #: Снимок стен на момент нажатия по точке: по нему окно запишет
        #: отмену, когда перетаскивание закончится.
        self._wall_drag_before = None
        #: Снимок «до» последней зафиксированной правки — отдаётся окну
        #: вместе с сигналом, чтобы Ctrl+Z вернул стену целиком.
        self._walls_before = None
        #: Снимок света «до» последней зафиксированной правки — отдаётся
        #: окну вместе с сигналом, чтобы Ctrl+Z вернул источник целиком.
        self._lights_before = None
        #: Снимок света на момент нажатия по иконке: по нему окно запишет
        #: отмену, когда перетаскивание закончится.
        self._light_drag_before = None
        #: Начало и текущий угол прямоугольника стены (ЛКМ зажата).
        self._wall_rect_start: Optional[tuple] = None
        self._wall_rect_current: Optional[tuple] = None
        #: Конец недорисованной ломаной — под курсором.
        self._wall_draft_cursor: Optional[tuple] = None
        #: Курсор над стеной: (wall_id, сегмент, расстояние) — подсказка.
        self._wall_hover = None
        #: Точка стены под ластиком: (wall_id, индекс). В режиме удаления
        #: точек не видно, поэтому холст подсвечивает ту, что удалит клик.
        self._wall_hover_point = None
        #: Проём под ластиком: id двери или окна, которое удалит клик.
        #: Стена при этом остаётся — ластик по створке не ломает комнату.
        self._wall_hover_opening: Optional[str] = None
        #: Ход створки каждой двери: id -> {from, to, start}. Угол берётся
        #: из модели (открыта/закрыта), а плавность — отсюда.
        self._door_anims: dict = {}
        #: Путь видимости игрока в экранных координатах: по нему режется
        #: цветной мир и выключаются чужие токены за стенами.
        self._visible_path: Optional[QPainterPath] = None
        #: Кэш маски зрения: 220 лучей на токен — не для каждого кадра.
        self._vision_cache_key = None
        self._vision_cache_path = None
        #: Кэш стен и проёмов: нормализация сотни стен на каждом кадре
        #: (а её требуют свет, туман, стены и инструменты) стоила дороже
        #: самого рисунка. Сбрасывается только при правке геометрии.
        self._walls_cache: Optional[list] = None
        self._openings_cache: Optional[list] = None
        #: Куски стен: для света/взгляда и для хода — два разных списка.
        self._spans_cache: Dict[bool, list] = {}
        #: Живое состояние дверей на момент кэша: дверь меняет куски стен,
        #: и без этого подписи открытая дверь оставалась бы преградой.
        self._openings_signature = None
        self._spans_signature: Dict[bool, tuple] = {}
        #: Версия геометрии: растёт на каждой правке стен. По ней сбрасываются
        #: многоугольники видимости — они зависят только от стен.
        self._geometry_version = 0
        #: Многоугольники света: (позиция, радиус, версия геометрии) ->
        #: (полигон видимости, тени объектов), всё в мировых координатах.
        #: 220 лучей × 24 источника — это секунды, а свет стоит на месте.
        self._light_polygons: Dict[tuple, tuple] = {}
        #: Настройки графики (лучи теней, сглаживание, тени, дневной отсвет).
        self.graphics = dict(graphics_rules.DEFAULTS)
        #: Длительность последнего кадра и сглаженное среднее: по ним видно,
        #: лагает ли стол на самом деле, а не «кажется».
        self.last_frame_ms = 0.0
        self.frame_ms_avg = 0.0
        #: Индекс отрезков стен для света: с ним каждый источник смотрит
        #: только на ближние стены, а не на всю карту.
        self._sight_index = None
        self._sight_index_version = -1
        #: Тени объектов карты: пересчитываются только при движении объектов,
        #: а не на каждом кадре — углы повёрнутых объектов считаются дорого.
        self._occluders_cache = None
        self._occluders_key = None
        #: Пути многоугольников света в пикселях маски: при сдвиге маски они
        #: просто переносятся, а не пересчитываются по точкам.
        self._light_paths: Dict[int, tuple] = {}
        #: Слой сетки: пунктир дорогой, поэтому рисуется в картинку с запасом.
        self._grid_image = None
        self._grid_signature = None
        #: Иконки факелов: сам рисунок (древко, пламя, ореол) один на цвет и
        #: состояние, поэтому он рисуется один раз в картинку, а не каждый
        #: кадр путями по 24 источника.
        self._torch_icon_cache: Dict[tuple, QPixmap] = {}
        #: Назначенные клавиши особых атак: {"B": (token_id, attack_id)}.
        #: Собирает главное окно из статблоков токенов, холст только ловит.
        self.special_attack_hotkeys: Dict[str, tuple] = {}
        self.object_resize_handle: Optional[str] = None
        self._object_drag_offset = QPointF()
        self._object_drag_before = None
        self._rotate_start_angle: Optional[float] = None
        self._rotate_start_rotation = 0.0
        #: id -> текущая непрозрачность крыши (1 — видна, 0 — исчезла).
        self._roof_alpha: Dict[str, float] = {}
        self._roof_last_tick = time.monotonic()
        #: Кэш мягкой маски зрения: пересчитывается только при смене
        #: геометрии обзора (движение токена, поворот, стены, камера).
        self._soft_mask_cache: Dict[tuple, QImage] = {}

        # Движение токена с клавиатуры: необязательный режим из настроек.
        #: Включён ли WASD у этого клиента.
        self.wasd_movement = False
        #: Зажатые клавиши направления в порядке нажатия — ходит последняя.
        self._wasd_keys: List[int] = []
        self._wasd_timer: Optional[QTimer] = None
        # Иконки состояний грузятся с диска лениво и кешируются: paintEvent
        # вызывается на каждое движение мыши, читать PNG каждый кадр нельзя.
        self._condition_icon_cache: Dict[str, Optional[QPixmap]] = {}

        # Взаимодействие
        self.dragging_token: Optional[str] = None
        #: След одиночного перетаскивания (x, y): по нему отправляется путь.
        self._token_drag_trail: List[tuple] = []
        #: Сжатый путь последнего перетаскивания: его забирает окно для сети.
        self._token_move_path: List[tuple] = []
        #: Следы группового перетаскивания: {id токена: [(x, y), …]}.
        self._token_drag_trails: Dict[str, list] = {}
        # Перетаскивание группы, выделенной рамкой: список id и смещения
        # каждого токена относительно курсора, чтобы не сбить их взаимное
        # расположение при движении.
        self.dragging_tokens: List[str] = []
        self.group_drag_offsets: Dict[str, Tuple[float, float]] = {}
        # Снимок ДО перетаскивания: Token — общий объект с game_state, поэтому
        # после драга старое положение уже потеряно. Нужен для отмены (Ctrl+Z).
        self._drag_snapshot: Optional[dict] = None
        self.dragging_map_view = False
        self.moving_map = False
        self._map_drag_moved = False   # реально ли сдвинули карту за это нажатие
        self.resizing_map = False
        self.resize_handle: Optional[str] = None
        self.map_drag_offset = QPointF()
        self.drag_start_pos = QPointF()
        #: Групповой жест: откуда тянут и как токены стояли до нажатия.
        #: Пока ЛКМ зажата, группа собирается к курсору («магнит»), а после
        #: отпускания возвращается в ту же расстановку вокруг точки броска.
        self._group_magnet_anchor = None
        self._group_magnet_start: Dict[str, tuple] = {}
        self.selected_token: Optional[str] = None
        self.map_is_selected = False
        # Токен, чей ход идёт сейчас (очередь инициативы). Пусто — боя нет.
        self.turn_token_id: Optional[str] = None
        # Бой идёт: токены с инициативой ходят «как в шахматах» — выбор
        # токена, подсветка клеток в радиусе скорости и клик по клетке.
        self.combat_active = False
        self.chess_token_id: Optional[str] = None
        #: Функция token -> футы скорости; её ставит главное окно, чтобы
        #: у персонажа скорость бралась с листа, а не только из статблока.
        self.speed_resolver = None
        # Боевой ход: сколько футов токен уже прошёл и потратил ли рывок.
        # Считаем именно путь (гипотенузу между клетками), а не число клеток:
        # диагональ стоит дороже прямой, как на столе. Значения сбрасываются
        # при смене хода/раунда.
        self.turn_round = 1
        self.turn_index = 0
        self._turn_signature = None
        self._move_spent_ft: Dict[str, float] = {}
        self._dash_used = set()
        #: token_id -> последний раунд, в котором действует зелье скорости.
        self._haste_until: Dict[str, int] = {}
        #: Зелье, выпитое вне боя: дождётся первого раунда.
        self._haste_pending: Dict[str, int] = {}
        #: Бюджет, который назвал сервер: он авторитетнее локальной скорости.
        #: Нужен, если лист/статблок разошлись или сервер ещё не прислал ход.
        self._move_total_override: Dict[str, int] = {}
        #: Плоская прибавка скорости от сервера (Удар Зефира: +30 футов).
        self._move_bonus_ft: Dict[str, int] = {}
        # Взведённая быстрая атака: следующий клик по другому токену — удар.
        # Режим снимается сам после удара, по Esc или клику мимо цели.
        self.quick_attack_mode = False
        #: Подпись плашки сверху: «Герой: Длинный меч (1d8+3)».
        self.quick_attack_hint = ""

        # Выделение рамкой: тянем левой кнопкой по пустому месту.
        # selected_tokens хранит всё, что попало в рамку.
        self.selected_tokens = set()
        # Видимость имени/полосы независимо переключается; по умолчанию
        # подписи показываем только у выбранного токена.
        self.show_token_names = True
        self.show_token_hp = True
        self.labels_selected_only = True
        self.rubber_origin = None      # QPointF в мировых координатах
        self.rubber_current = None
        self.rubber_active = False

        # Рисование
        self.drawing_mode = None
        #: Заклинание ждёт клика по цели: пока режим включён, клик по
        #: токену отдаёт target_picked, а Esc/ПКМ закрывают его без расхода.
        self.target_pick_mode = False
        self.target_pick_label = ""
        self.target_pick_hover: Optional[str] = None
        #: Надписи открытой карты. Порядок — порядок появления: новые
        #: ложатся сверху, как слои текста в Photoshop.
        self.map_texts: List[dict] = []
        #: Какая надпись выбрана: её подсвечиваем и правим.
        self.selected_text_id: Optional[str] = None
        #: Оформление для НОВЫХ надписей (панель текста меняет его).
        self.text_style = dict(text_rules.DEFAULTS)
        self.text_style["color"] = list(text_rules.DEFAULTS["color"])
        #: Перетаскивание надписи: id, точка захвата и исходные координаты.
        self._text_drag: Optional[dict] = None
        #: Плавающее поле правки прямо над надписью.
        self._text_editor: Optional[QLineEdit] = None
        self._editing_text_id: Optional[str] = None
        self._text_edit_original: Optional[dict] = None
        #: Правка только что созданной надписи: на сервер её отправлять
        #: нужно только при подтверждении, а не каждым кликом.
        self._text_edit_new = False
        self.drawing_points: List[Tuple[float, float]] = []
        self.drawing_color = (255, 255, 255)
        self.brush_size = 3.0
        self.brush_opacity = 1.0

        # Растровый слой рисунка (прозрачная картинка поверх карты).
        # Кисть/линия/круг/квадрат рисуют в него пиксели, ластик стирает
        # пиксели этого слоя. Карта и токены — отдельные слои, их не задевает.
        self.draw_layer: Optional[QImage] = None
        self.draw_layer_scale = 1.0          # пикселей слоя на единицу карты
        # id карты, которой принадлежит слой. Именно id, а не путь к
        # картинке: у карт без файла путь пустой, и по нему они делили бы
        # один слой между собой.
        self.draw_layer_map_id: Optional[str] = None
        self.drawing_is_eraser = False
        self._preview_points: List[Tuple[float, float]] = []
        # Заливать ли фигуры (как зоны заклинаний в Roll20). В исходной версии
        # круг/квадрат/треугольник рисовались полупрозрачной заливкой.
        self.fill_shapes = True

        # Операции рисования — для сети, отмены и для новых игроков
        self.draw_ops: List[dict] = []
        self._draw_undo_stack: List[QImage] = []
        self.max_draw_undo = 40

        # Роль
        self.player_role = Role.PLAYER
        self.player_id: Optional[str] = None

        # Курсоры инструментов: диаметр -> готовый QCursor. Кэш нужен, чтобы
        # не перерисовывать картинку курсора на каждое движение мыши.
        self._cursor_cache: Dict[int, QCursor] = {}

        # Сетка живёт в самой карте (current_map.grid); своей копии холст
        # не держит, чтобы не было двух источников истины.
        self.snap_tokens = False
        # Калибровка сетки по двум кликам DM
        self._calibration_cells = 1
        self._calibration_points: List[Tuple[float, float]] = []
        self._grid_calibrating = False
        # Линейка: неподвижное начало и конец, который тянется мышью.
        self.ruler_start: Optional[Tuple[float, float]] = None
        self.ruler_end: Optional[Tuple[float, float]] = None
        self.ruler_active = False
        self.template_origin = None   # режим шаблона AoE
        self.template_aim = None
        self.template_kind = "circle"
        self.template_size_ft = 20.0
        #: Для конуса/линии центр заранее стоит на колдуне: по правилам
        #: эти области начинаются от него, а не от произвольной клетки.
        self.template_preset = False
        self.template_result = None
        #: Последняя сработавшая область: клетки и время жизни. Это не
        #: превью шаблона, а след заклинания — он виден всем клиентам.
        self._area_overlay: Optional[dict] = None

        #: Токен под курсором во время перетаскивания предмета из инвентаря
        #: или справочника. Пока он задан, вокруг фигуры рисуется зелёное
        #: кольцо с плюсом: видно, кто именно получит зелье, если отпустить
        #: кнопку здесь.
        self.item_drop_target_id: Optional[str] = None

        #: Короткая подсказка справа в строке состояния («шаблон отменён»,
        #: «этот предмет нельзя применить»). Раньше её только записывали в
        #: атрибут, но нигде не рисовали — подсказки пропадали молча.
        self.statusBar_hint = ""
        self._hint_timer = QTimer(self)
        self._hint_timer.setSingleShot(True)
        self._hint_timer.timeout.connect(self._clear_status_hint)

        # Анимации: плавное движение, боевые эффекты и полоса хитов.
        # Время храним монотонное (time.monotonic), чтобы смена системных
        # часов не растягивала кадр на минуты.
        self._motions: Dict[str, dict] = {}
        self._combat_fx: List[dict] = []
        self._hp_anims: Dict[str, dict] = {}
        #: token_id -> время начала предсмертной тряски. Отдельно от
        #: боевых эффектов: смерть может прийти без атаки (третий провал).
        self._death_anims: Dict[str, dict] = {}
        self._anim_timer = QTimer(self)
        self._anim_timer.setTimerType(Qt.PreciseTimer)
        self._anim_timer.setInterval(ANIM_FRAME_MS)
        self._anim_timer.timeout.connect(self._on_anim_tick)

        # Загрузка карты: крутящийся жёлтый d20 и шутливые подписи поверх
        # холста. Свой таймер, потому что set_map() сбрасывает боевые
        # анимации, а заставка должна пережить этот сброс.
        self._map_loading: Optional[dict] = None
        self._loading_timer = QTimer(self)
        self._loading_timer.setTimerType(Qt.PreciseTimer)
        self._loading_timer.setInterval(MAP_LOADING_FRAME_MS)
        self._loading_timer.timeout.connect(self._on_loading_tick)

        # Кровь: пятна лежат в мировых координатах карты и живут минутами.
        # Запись — центр попадания, капли и будущие порезы; карта хранится
        # в записи, чтобы пятна не переезжали на другую карту.
        self._blood_hits: List[dict] = []
        #: Холст рисует видеокарта — картинку пятна нельзя печь прямо в кадре:
        #: новый QPixmap, нарисованный посреди paintEvent, ложится сплошным
        #: чёрным прямоугольником по своему размеру. Поэтому запросы копятся
        #: и печутся сразу после отрисовки (см. `_queue_blood_bake`).
        self._blood_images_wait = (RENDER_MODE == "gpu")
        self._blood_pending: Dict[tuple, tuple] = {}
        self._blood_bake_queued = False
        #: Идёт ли сейчас отрисовка кадра. Пока идёт, картинки не создаются:
        #: на холсте с видеокартой (QOpenGLWidget) новый QPixmap, выведенный
        #: в том же кадре, ложится сплошным чёрным квадратом по своему
        #: размеру — так мелькала лужа крови при ударе по умирающему токену.
        self._painting = False
        #: Иконки состояний грузятся с диска тоже только вне кадра.
        self._condition_icons_wait = (RENDER_MODE == "gpu")
        self._icon_pending: set = set()
        # Галочка «Эффекты в бою» из настроек мастера. Выключенная — нет
        # крови и звуков, но сам эффект удара (выпад, вспышка, число)
        # рисуется точно так же: анимация от галочки не зависит.
        self.combat_effects_enabled = True
        #: Прозрачность крови в процентах: 0 — обычная, 100 — не видно.
        self.blood_transparency = 0
        # Высыхание — медленный процесс: перерисовываем его редко, чтобы
        # не крутить 60 кадров в секунду десятки минут.
        self._blood_timer = QTimer(self)
        self._blood_timer.setInterval(BLOOD_DRY_TICK_MS)
        self._blood_timer.timeout.connect(self._on_blood_tick)
        #: token_id -> когда с раны последний раз капало (монотонное время).
        #: Низкие хиты — это не удар, а медленное умирание: капля раз в 5 с.
        self._wound_last: Dict[str, float] = {}
        self._wound_timer = QTimer(self)
        self._wound_timer.setInterval(BLOOD_DRIP_TICK_MS)
        self._wound_timer.timeout.connect(self._on_wound_tick)
        self._wound_timer.start()

        self.setMinimumSize(600, 400)

    # ------------------------------------------------------------------
    # Настройка
    # ------------------------------------------------------------------
    def set_player_info(self, player_id: str, role: Role):
        self.player_id = player_id
        self.player_role = role
        self.update()

    @property
    def is_dm(self) -> bool:
        return self.player_role == Role.DM

    def set_combat_effects_enabled(self, enabled: bool):
        """Включить/выключить кровь и звуки, не трогая анимацию удара."""
        self.combat_effects_enabled = bool(enabled)
        if not self.combat_effects_enabled:
            self._blood_hits.clear()
            self._blood_pending.clear()
            self._blood_sprite_px = 0
            self._blood_bake_count = 0
            self._blood_timer.stop()
            # Иначе после включения эффектов кровь хлынула бы сразу у всех
            # раненых: таймеры копились, пока эффекты были выключены.
            self._wound_last.clear()
        self.update()

    def set_blood_transparency(self, percent: int):
        """Сделать всю кровь на карте прозрачнее (0…100)."""
        self.blood_transparency = max(0, min(100, int(percent)))
        self.update()

    # ------------------------------------------------------------------
    # Заставка загрузки карты
    # ------------------------------------------------------------------
    def begin_map_loading(self, map_id: Optional[str] = None):
        """Показать на холсте крутящийся d20, пока карта не готова.

        Подписи идут случайным порядком, по 2 секунды. Если загрузка
        началась для другой карты, заставка начинается заново: иначе
        название старой карты и её таймер переехали бы на новую.
        """
        now = time.monotonic()
        current = self._map_loading
        if current is not None and current.get('map_id') == map_id:
            return
        captions = list(MAP_LOADING_CAPTIONS)
        random.shuffle(captions)
        self._map_loading = {
            'map_id': map_id,
            'start': now,
            'min_until': now + MAP_LOADING_MIN_S,
            'captions': captions,
            'caption_index': 0,
            'caption_start': now,
            'finish_requested': False,
        }
        if not self._loading_timer.isActive():
            self._loading_timer.start()
        self.update()

    def finish_map_loading(self, map_id: Optional[str] = None):
        """Карта готова: убрать заставку, но дать ей доиграть минимум.

        ``map_id`` защищает от гонки: картинка старой карты, пришедшая
        после переключения, не должна снять заставку новой.
        """
        state = self._map_loading
        if state is None:
            return
        if map_id is not None and state.get('map_id') not in (None, map_id):
            return
        state['finish_requested'] = True
        if time.monotonic() >= state['min_until']:
            self.cancel_map_loading()
        else:
            self.update()

    def cancel_map_loading(self, map_id: Optional[str] = None):
        """Убрать заставку сразу (карту удалили или переключились)."""
        state = self._map_loading
        if state is None:
            return
        if map_id is not None and state.get('map_id') not in (None, map_id):
            return
        self._map_loading = None
        self._loading_timer.stop()
        self.update()

    def is_map_loading(self) -> bool:
        return self._map_loading is not None

    def map_loading_map_id(self) -> Optional[str]:
        return (self._map_loading or {}).get('map_id')

    def map_loading_caption(self) -> str:
        state = self._map_loading
        if not state:
            return ""
        captions = state.get('captions') or []
        index = int(state.get('caption_index', 0))
        return captions[index] if 0 <= index < len(captions) else ""

    def _next_loading_caption(self, state: dict, now: float):
        """Следующая подпись; после полного круга порядок снова случайный."""
        captions = state.get('captions') or []
        index = int(state.get('caption_index', 0)) + 1
        if index >= len(captions):
            previous = captions[-1] if captions else ""
            fresh = list(MAP_LOADING_CAPTIONS)
            random.shuffle(fresh)
            # Не показываем одну и ту же фразу два раза подряд на стыке
            # кругов: это выглядит как застывшая подпись.
            if len(fresh) > 1 and fresh[0] == previous:
                fresh[0], fresh[1] = fresh[1], fresh[0]
            state['captions'] = fresh
            index = 0
        state['caption_index'] = index
        state['caption_start'] = now

    def _on_loading_tick(self):
        state = self._map_loading
        if state is None:
            self._loading_timer.stop()
            return
        now = time.monotonic()
        # Догоняем подписи, если окно на миг подвисло: каждая всё равно
        # должна отсчитать свои 2 секунды, а не прогореть пачкой.
        guard = 0
        while now - state['caption_start'] >= MAP_LOADING_CAPTION_S and guard < 8:
            self._next_loading_caption(state, state['caption_start']
                                       + MAP_LOADING_CAPTION_S)
            guard += 1
        if state.get('finish_requested') and now >= state['min_until']:
            self.cancel_map_loading()
            return
        self.update()

    def set_map(self, map_data: MapData, image_path: str = None):
        """Показать карту и автоматически отцентрировать её в окне"""
        # Эффекты и недоехавшие токены принадлежат прежней карте: на новой
        # они рисовались бы поверх чужих координат.
        self.clear_animations()
        self.current_map = map_data
        # Выбранный свет принадлежит прежней карте: на новой такого id нет,
        # и панель показывала бы чужой радиус.
        self.selected_light_id = None
        # Стены тоже принадлежат карте: недорисованная ломаная и выбранная
        # точка с прежней сцены на новом столе означали бы чужую геометрию.
        self.selected_wall_id = None
        self.selected_opening_id = None
        self._wall_draft = []
        self._wall_draft_cursor = None
        self._wall_rect_start = None
        self._wall_rect_current = None
        self._wall_drag_point = None
        self._wall_drag_before = None
        self._walls_before = None
        #: Снимок света «до» последней зафиксированной правки — отдаётся
        #: окну вместе с сигналом, чтобы Ctrl+Z вернул источник целиком.
        self._lights_before = None
        #: Снимок света на момент нажатия по иконке: по нему окно запишет
        #: отмену, когда перетаскивание закончится.
        self._light_drag_before = None
        self._vision_cache_key = None
        # Разведка комнат живёт на карте: у новой карты она своя, поэтому
        # разобранный набор прежней выбрасываем и читаем заново.
        self._explored_rooms.pop(getattr(map_data, "id", None), None)
        self._explored_path_cache = None
        # Стены, проёмы и всё, что по ним посчитано, — от прежней карты.
        self.invalidate_walls_cache()
        self.map_error_note = ""
        path = image_path or map_data.image_path

        if path and os.path.exists(path):
            if path != self._map_image_path:
                pix, source_w, source_h = self._load_map_image(path)
                if pix is not None and not pix.isNull():
                    self.map_image = pix
                    self._map_tiles = split_map_tiles(pix)
                    self._map_image_path = path
                    # Если размер не задан явно — берём размер изображения.
                    # Мир и сетка считаются по ИСХОДНЫМ пикселям, даже если
                    # для видеокарты картинка была уменьшена: иначе шаг
                    # сетки уехал бы вместе с текстурой.
                    if map_data.width <= 1 or map_data.height <= 1:
                        map_data.width = source_w or pix.width()
                        map_data.height = source_h or pix.height()
                    # Запоминаем пиксельный размер картинки: по нему шаг сетки
                    # пересчитывается в мировые единицы после ресайза карты.
                    map_data.img_width = float(source_w or pix.width())
                    map_data.img_height = float(source_h or pix.height())
                else:
                    # Файл есть, но не читается: старая картинка к новой карте
                    # отношения не имеет — иначе на холсте остался бы чужой
                    # рисунок, растянутый под новый размер.
                    self.map_image = None
                    self._map_tiles = []
                    self._map_image_path = None
                    self.map_error_note = (
                        "Карта не читается: "
                        + os.path.basename(path))
        else:
            self.map_image = None
            self._map_tiles = []
            self._map_image_path = None
            self.map_downscaled_note = ""
            if path:
                self.map_error_note = (
                    "Файл карты не найден: " + os.path.basename(path))

        # Сетка живёт в самой карте; холст читает её оттуда.
        # Карта НЕ выделяется автоматически: рамка появляется только когда
        # карту осознанно выбрали в левой панели.
        self.map_is_selected = False
        self.selected_object_id = None
        self.moving_object = False
        self.resizing_object = False
        self.rotating_object = False
        self.object_resize_handle = None
        self._rotate_start_angle = None

        # Растровый слой готовим сразу под размер новой карты
        self.ensure_draw_layer()

        # Карта всегда появляется по центру — это и есть исправление
        self.center_on_map()
        # На этой карте могут быть крыши с токенами под ними.
        if self._roofs_exist():
            self._ensure_anim_timer()

    def _load_map_image(self, path: str):
        """Прочитать картинку карты и уместить её в лимит видеокарты.

        Возвращает ``(pixmap, исходная_ширина, исходная_высота)``.
        ``pixmap`` — None, если файл не читается.
        """
        self.map_downscaled_note = ""
        image = QImage(path)
        if image.isNull():
            # Запасной путь: редкий PNG может не открыться через QImageReader,
            # но прочитаться платформенным загрузчиком QPixmap.
            fallback = QPixmap()
            if not fallback.load(path):
                return None, 0, 0
            image = fallback.toImage()
        source_w, source_h = image.width(), image.height()
        image, scaled = fit_map_image(image)
        if scaled:
            self.map_downscaled_note = (
                f"Карта уменьшена до {image.width()}×{image.height()} "
                f"(исходник {source_w}×{source_h}): видеокарта не примет "
                "текстуру большего размера. Сетка и координаты не изменились")
        return QPixmap.fromImage(image), source_w, source_h

    def center_on_map(self):
        """Отцентрировать вид на карте и вписать её в окно"""
        if not self.current_map:
            self.update()
            return

        w = max(1, self.width())
        h = max(1, self.height())
        mw = max(1.0, float(self.current_map.width))
        mh = max(1.0, float(self.current_map.height))

        fit = min((w - 40) / mw, (h - 40) / mh)
        self.scale = max(self.min_scale, min(self.max_scale, fit))

        cx = self.current_map.pos_x + mw / 2.0
        cy = self.current_map.pos_y + mh / 2.0
        self.offset_x = w / 2.0 - cx * self.scale
        self.offset_y = h / 2.0 - cy * self.scale
        self.update()

    def fit_map_to_screen(self):
        self.center_on_map()

    def _keep_view_anchor(self):
        """Сдвиг холста на экране не должен уводить карту.

        Ширину левой панели держит QSplitter, и при перетаскивании её границы
        холст переезжает вправо-влево. ``offset_x``/``offset_y`` считаются от
        левого верхнего угла холста, поэтому карта уезжала вместе с границей —
        казалось, что двигается камера. Компенсируем смещение: карта остаётся
        на том же месте экрана, как у правой панели, которая холст только
        сужает, но не перемещает.

        Смещение берём внутри родителя (сплиттера), а не в координатах экрана:
        тогда обычное перетаскивание окна карту за собой тянет, как и раньше.
        """
        origin = self.pos()
        previous = self._view_origin
        self._view_origin = QPoint(origin)
        if previous is None:
            return
        dx = origin.x() - previous.x()
        dy = origin.y() - previous.y()
        if not dx and not dy:
            return
        self.offset_x -= dx
        self.offset_y -= dy
        # Поле правки надписи стоит в экранных координатах холста.
        self.update_text_editor_geometry()
        self.update()

    def moveEvent(self, event):
        super().moveEvent(event)
        self._keep_view_anchor()

    def resizeEvent(self, event):
        """Ширина холста изменилась — вид остаётся на месте.

        Оба события нужны: Qt может прислать изменение размера и перемещения
        в любом порядке, а компенсация должна сработать ровно один раз.
        """
        super().resizeEvent(event)
        self._keep_view_anchor()

    def select_map(self):
        """Выделить карту (рамка + ручки) — вызывается из левой панели."""
        if not self.is_dm:
            return
        if not self.map_is_selected:
            self.map_is_selected = True
            self.map_selected.emit()
        # Карта и объект не выделяются одновременно.
        self.selected_token = None
        self.selected_object_id = None
        self.moving_object = False
        self.resizing_object = False
        self.rotating_object = False
        self.object_resize_handle = None
        self._rotate_start_angle = None
        self.update()

    def deselect_map(self):
        """Снять выделение карты."""
        if self.map_is_selected:
            self.map_is_selected = False
            self.map_deselected.emit()
        self.update()

    def map_rect_world(self) -> Optional[QRectF]:
        if not self.current_map:
            return None
        return QRectF(self.current_map.pos_x, self.current_map.pos_y,
                      self.current_map.width, self.current_map.height)

    # ------------------------------------------------------------------
    # Токены и объекты
    # ------------------------------------------------------------------
    def add_token(self, token: Token, image_path: str = None):
        self.tokens[token.id] = token
        path = image_path or token.image_path
        if path and os.path.exists(path) and token.id not in self.token_images:
            pix = QPixmap()
            pix.load(path)
            if not pix.isNull():
                self.token_images[token.id] = pix
        # Новый токен мог появиться сразу под крышей.
        if self._roofs_exist():
            self._ensure_anim_timer()
        self.update()

    def remove_token(self, token_id: str):
        self.tokens.pop(token_id, None)
        self.token_images.pop(token_id, None)
        # Анимации удалённого токена больше некому показывать.
        self._motions.pop(token_id, None)
        self._hp_anims.pop(token_id, None)
        self._death_anims.pop(token_id, None)
        self._combat_fx = [fx for fx in self._combat_fx
                           if token_id not in (fx.get('attacker'),
                                               fx.get('target'))]
        # Удалённый токен не должен оставаться ни в выделении, ни в группе
        # перетаскивания: иначе группа при следующем движении полезла бы
        # за несуществующим токеном.
        self.selected_tokens.discard(token_id)
        self.dragging_tokens = [t for t in self.dragging_tokens if t != token_id]
        self.group_drag_offsets.pop(token_id, None)
        if self.selected_token == token_id:
            self.selected_token = None
        # Игрок ушёл с карты — крыша над ним возвращается.
        if self._roofs_exist():
            self._ensure_anim_timer()
        self.update()

    # ------------------------------------------------------------------
    # Объекты карты
    # ------------------------------------------------------------------
    def object_belongs_to_current_map(self, obj) -> bool:
        """Показывать ли объект на текущей карте (как у токенов)."""
        if self.current_map is None or getattr(obj, 'map_id', None) is None:
            return True
        return obj.map_id == self.current_map.id

    def current_map_objects(self) -> Dict[str, MapObject]:
        return {oid: obj for oid, obj in self.objects.items()
                if self.object_belongs_to_current_map(obj)}

    def add_object(self, obj: MapObject, image_path: str = None):
        """Добавить объект и подгрузить его PNG."""
        self.objects[obj.id] = obj
        path = image_path or obj.image_path
        if path and os.path.exists(path) and obj.id not in self.object_images:
            pix = QPixmap()
            pix.load(path)
            if not pix.isNull():
                self.object_images[obj.id] = pix
        self._roof_alpha.setdefault(obj.id, 1.0)
        if obj.roof:
            self._ensure_anim_timer()
        self.update()

    def remove_object(self, object_id: str):
        self.objects.pop(object_id, None)
        self.object_images.pop(object_id, None)
        self._roof_alpha.pop(object_id, None)
        if self.selected_object_id == object_id:
            self.selected_object_id = None
        if self.resizing_object:
            self.resizing_object = False
            self.object_resize_handle = None
        if self.rotating_object:
            self.rotating_object = False
            self._rotate_start_angle = None
        if self.moving_object:
            self.moving_object = False
        self.update()

    def object_rect_world(self, obj) -> QRectF:
        """Прямоугольник ДО поворота: им живут модель, ресайз и клик."""
        return QRectF(float(obj.x), float(obj.y),
                      max(OBJECT_MIN_SIZE, float(obj.width)),
                      max(OBJECT_MIN_SIZE, float(obj.height)))

    @staticmethod
    def _object_center(obj) -> Tuple[float, float]:
        return (float(obj.x) + float(obj.width) / 2.0,
                float(obj.y) + float(obj.height) / 2.0)

    @staticmethod
    def _rotate_xy(dx: float, dy: float, degrees: float) -> Tuple[float, float]:
        if not degrees:
            return dx, dy
        rad = math.radians(degrees)
        cos_a, sin_a = math.cos(rad), math.sin(rad)
        return dx * cos_a - dy * sin_a, dx * sin_a + dy * cos_a

    def object_corners_world(self, obj) -> list:
        """Углы объекта с учётом поворота: nw, ne, se, sw."""
        cx, cy = self._object_center(obj)
        hw = max(OBJECT_MIN_SIZE, float(obj.width)) / 2.0
        hh = max(OBJECT_MIN_SIZE, float(obj.height)) / 2.0
        out = []
        for dx, dy in ((-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)):
            rx, ry = self._rotate_xy(dx, dy, float(obj.rotation or 0.0))
            out.append((cx + rx, cy + ry))
        return out

    def object_polygon(self, obj) -> QPolygonF:
        return QPolygonF([QPointF(x, y) for x, y in self.object_corners_world(obj)])

    def world_to_object_local(self, obj, wx: float, wy: float):
        """Точка в системе координат неповёрнутого объекта (центр — его центр)."""
        cx, cy = self._object_center(obj)
        return self._rotate_xy(wx - cx, wy - cy, -float(obj.rotation or 0.0))

    def _object_z_order(self) -> list:
        """Объекты открытой карты снизу вверх: сначала z, при равенстве — добавление."""
        return sorted(self.current_map_objects().values(),
                      key=lambda obj: int(getattr(obj, 'z', 0) or 0))

    def get_object_at(self, wx: float, wy: float,
                      above: bool) -> Optional[str]:
        """Верхний объект под курсором в своём слое (запертые не ловят клики)."""
        for obj in reversed(self._object_z_order()):
            if obj.locked or not obj.visible:
                continue
            if bool(obj.above_tokens) != above:
                continue
            if not obj.rotation:
                if self.object_rect_world(obj).contains(wx, wy):
                    return obj.id
                continue
            # Повёрнутый объект: переводим клик в его собственную систему.
            lx, ly = self.world_to_object_local(obj, wx, wy)
            if abs(lx) <= float(obj.width) / 2.0 and abs(ly) <= float(obj.height) / 2.0:
                return obj.id
        return None

    def object_handle_positions(self, obj) -> Dict[str, QPointF]:
        """Углы объекта с учётом поворота — как ручки карты."""
        corners = self.object_corners_world(obj)
        keys = ('nw', 'ne', 'se', 'sw')
        return {k: QPointF(*self.world_to_screen(x, y))
                for k, (x, y) in zip(keys, corners)}

    def object_rotation_handle_world(self, obj) -> Tuple[float, float]:
        """Точка ручки поворота: над верхним краем, снаружи объекта."""
        cx, cy = self._object_center(obj)
        half_h = max(OBJECT_MIN_SIZE, float(obj.height)) / 2.0
        # Отступ в пикселях оформления: ручка стоит на месте относительно
        # объекта при любом зуме.
        gap = self.design(OBJECT_ROTATE_GAP_PX)
        dx, dy = self._rotate_xy(0.0, -(half_h + gap),
                                 float(obj.rotation or 0.0))
        return cx + dx, cy + dy

    def object_rotation_handle_pos(self, obj) -> QPointF:
        return QPointF(*self.world_to_screen(
            *self.object_rotation_handle_world(obj)))

    def hit_test_object_rotation_handle(self, screen_pos: QPointF) -> bool:
        """Попал ли курсор в ручку поворота выбранного объекта."""
        if not self.is_dm or not self.selected_object_id:
            return False
        obj = self.objects.get(self.selected_object_id)
        if obj is None or obj.locked or not obj.visible:
            return False
        pos = self.object_rotation_handle_pos(obj)
        reach = self.overlay_px(OBJECT_ROTATE_HIT_PX)
        return (abs(pos.x() - screen_pos.x()) <= reach
                and abs(pos.y() - screen_pos.y()) <= reach)

    def hit_test_object_handle(self, screen_pos: QPointF) -> Optional[str]:
        if not self.is_dm or not self.selected_object_id:
            return None
        obj = self.objects.get(self.selected_object_id)
        if obj is None or obj.locked:
            return None
        reach = self.overlay_px(HANDLE_HIT_TOLERANCE)
        for name, pos in self.object_handle_positions(obj).items():
            if (abs(pos.x() - screen_pos.x()) <= reach
                    and abs(pos.y() - screen_pos.y()) <= reach):
                return name
        return None

    def _start_object_drag(self, object_id: str, wx: float, wy: float):
        obj = self.objects.get(object_id)
        if obj is None or obj.locked:
            return
        had_token = (self.selected_token is not None or bool(self.selected_tokens))
        self.selected_object_id = object_id
        self.moving_object = True
        self.resizing_object = False
        self.object_resize_handle = None
        self._object_drag_before = self._object_payload(obj)
        self._object_drag_offset = QPointF(wx - obj.x, wy - obj.y)
        self.rotating_object = False
        self.selected_token = None
        self.selected_tokens.clear()
        self.dragging_token = None
        self.dragging_tokens = []
        self.group_drag_offsets.clear()
        if self.map_is_selected:
            self.map_is_selected = False
            self.map_deselected.emit()
        if had_token:
            self.token_deselected.emit()
        self.setCursor(Qt.ClosedHandCursor)
        self.update()

    def apply_object_resize(self, wx: float, wy: float):
        """Тянуть угол объекта — Shift сохраняет пропорции, поворот учитывается.

        Считаем в собственной системе объекта: неподвижный (противоположный)
        угол остаётся на месте в мире даже у повёрнутого объекта.
        """
        obj = self.objects.get(self.selected_object_id)
        handle = self.object_resize_handle
        if obj is None or handle is None:
            return
        cx, cy = self._object_center(obj)
        mx, my = self.world_to_object_local(obj, wx, wy)
        old_w = max(OBJECT_MIN_SIZE, float(obj.width))
        old_h = max(OBJECT_MIN_SIZE, float(obj.height))

        # Неподвижный угол — противоположный тому, за который тянем.
        fx = -old_w / 2.0 if 'e' in handle else old_w / 2.0
        fy = -old_h / 2.0 if 's' in handle else old_h / 2.0
        new_w = abs(mx - fx)
        new_h = abs(my - fy)

        if QApplication.keyboardModifiers() & Qt.ShiftModifier and old_h:
            ratio = old_w / old_h
            if new_w / max(new_h, 1.0) > ratio:
                new_w = new_h * ratio
            else:
                new_h = new_w / ratio
        new_w = max(OBJECT_MIN_SIZE, new_w)
        new_h = max(OBJECT_MIN_SIZE, new_h)

        # Прямоугольник снова строим от неподвижного угла: так объект не
        # «прыгает» при смене размера и не переворачивается через себя.
        if 'e' in handle:
            left, right = fx, fx + new_w
        else:
            left, right = fx - new_w, fx
        if 's' in handle:
            top, bottom = fy, fy + new_h
        else:
            top, bottom = fy - new_h, fy

        new_cx = (left + right) / 2.0
        new_cy = (top + bottom) / 2.0
        rx, ry = self._rotate_xy(new_cx, new_cy, float(obj.rotation or 0.0))
        obj.width = new_w
        obj.height = new_h
        obj.x = cx + rx - new_w / 2.0
        obj.y = cy + ry - new_h / 2.0
        if self._roofs_exist():
            self._ensure_anim_timer()
        self.update()

    def _start_object_rotation(self, object_id: str, wx: float, wy: float):
        """Взять ручку поворота: дальше угол считается от центра объекта."""
        obj = self.objects.get(object_id)
        if obj is None or obj.locked:
            return
        had_token = (self.selected_token is not None or bool(self.selected_tokens))
        self.selected_object_id = object_id
        self.rotating_object = True
        self.moving_object = False
        self.resizing_object = False
        self.object_resize_handle = None
        self._object_drag_before = self._object_payload(obj)
        cx, cy = self._object_center(obj)
        self._rotate_start_angle = math.degrees(math.atan2(wy - cy, wx - cx))
        self._rotate_start_rotation = float(obj.rotation or 0.0)
        self.selected_token = None
        self.selected_tokens.clear()
        self.dragging_token = None
        self.dragging_tokens = []
        self.group_drag_offsets.clear()
        if self.map_is_selected:
            self.map_is_selected = False
            self.map_deselected.emit()
        if had_token:
            self.token_deselected.emit()
        self.setCursor(Qt.CrossCursor)
        self.update()

    def apply_object_rotation(self, wx: float, wy: float):
        """Повернуть объект вслед за ручкой; Shift — шаг 15 градусов."""
        obj = self.objects.get(self.selected_object_id)
        if obj is None or self._rotate_start_angle is None:
            return
        cx, cy = self._object_center(obj)
        angle = math.degrees(math.atan2(wy - cy, wx - cx))
        rotation = (self._rotate_start_rotation
                    + angle - self._rotate_start_angle)
        if QApplication.keyboardModifiers() & Qt.ShiftModifier:
            rotation = (round(rotation / OBJECT_ROTATE_STEP_DEG)
                        * OBJECT_ROTATE_STEP_DEG)
        obj.rotation = rotation % 360.0
        if self._roofs_exist():
            self._ensure_anim_timer()
        self.update()

    def _object_payload(self, obj) -> dict:
        return {'object_id': obj.id, 'x': obj.x, 'y': obj.y,
                'width': obj.width, 'height': obj.height,
                'rotation': float(obj.rotation or 0.0)}

    def select_object(self, object_id: Optional[str]):
        """Выделить объект из панели (двойной клик по строке)."""
        obj = self.objects.get(object_id) if object_id else None
        if obj is None or obj.locked or not obj.visible:
            return
        self.selected_object_id = object_id
        self.selected_token = None
        self.selected_tokens.clear()
        if self.map_is_selected:
            self.map_is_selected = False
            self.map_deselected.emit()
        self.update()

    def _roofs_exist(self) -> bool:
        return any(obj.roof for obj in self.current_map_objects().values())

    def _token_screen_rect_world(self, token) -> QRectF:
        x, y = self._token_visual_pos(token)
        size = max(MIN_TOKEN_DRAW_PX, self.grid_cell_world
                   * max(0.1, float(getattr(token, 'size', 1.0) or 1.0)))
        half = size / 2.0
        return QRectF(x - half, y - half, size, size)

    def roof_target(self, obj) -> float:
        """1 — крыша видна, 0 — под ней стоит токен игрока (не актёра)."""
        if not obj.roof:
            return 1.0
        rect = self.object_rect_world(obj)
        poly = self.object_polygon(obj) if obj.rotation else None
        for token in self.current_map_tokens().values():
            # Только ИГРОК: НПС и существа под крышей её не открывают.
            if not token.visible or not token_kind.is_player(token):
                continue
            token_rect = self._token_screen_rect_world(token)
            if poly is None:
                if rect.intersects(token_rect):
                    return 0.0
                continue
            # Повёрнутая крыша: проверяем и центр токена, и его углы —
            # иначе маленький объект под большим токеном «не замечался».
            if poly.containsPoint(token_rect.center(), Qt.OddEvenFill):
                return 0.0
            for cx, cy in ((token_rect.left(), token_rect.top()),
                           (token_rect.right(), token_rect.top()),
                           (token_rect.left(), token_rect.bottom()),
                           (token_rect.right(), token_rect.bottom())):
                if poly.containsPoint(QPointF(cx, cy), Qt.OddEvenFill):
                    return 0.0
            if token_rect.contains(QPointF(poly.at(0))):
                return 0.0
        return 1.0

    def _advance_roof_fades(self, now: float) -> bool:
        """Плавно подвести крыши к цели. True — кадр был нужен."""
        dt = max(0.0, min(0.1, now - self._roof_last_tick))
        self._roof_last_tick = now
        changed = False
        for object_id, obj in self.current_map_objects().items():
            alpha = self._roof_alpha.get(object_id, 1.0)
            if not obj.roof:
                self._roof_alpha[object_id] = 1.0
                continue
            target = self.roof_target(obj)
            if abs(alpha - target) <= 0.001:
                alpha = target
            else:
                step = dt / ROOF_FADE_S if dt > 0.0 else 0.016 / ROOF_FADE_S
                alpha += step if target > alpha else -step
                alpha = max(0.0, min(1.0, alpha))
                changed = True
            self._roof_alpha[object_id] = alpha
        return changed

    def _roofs_animating(self) -> bool:
        for object_id, obj in self.current_map_objects().items():
            if not obj.roof:
                continue
            if abs(self._roof_alpha.get(object_id, 1.0)
                   - self.roof_target(obj)) > 0.001:
                return True
        return False

    def update_token_position(self, token_id: str, x: float, y: float,
                              animate: bool = False):
        """Переместить токен.

        ``animate=True`` — для чужих перемещений из сети: координаты в модели
        меняются сразу, а на экране токен доезжает за MOVE_ANIM_S. Локальный
        drag идёт без анимации (``animate=False``), иначе токен отставал бы
        от курсора.
        """
        token = self.tokens.get(token_id)
        if token is None:
            return
        if not animate:
            # Стена не пропускает и при перетаскивании: иначе токен на глазах
            # у зрителя проходил бы сквозь неё и возвращался с сервера.
            # Идём к курсору мелкими шагами (см. _walk_token_to): один прямой
            # отрезок от прежней точки до курсора задевал стену при быстром
            # жесте, и фишка замирала — будто её откинуло назад.
            # Захлопнутую дверь на пути по-прежнему толкаем сами: звук
            # хлопка тогда слышат все.
            dragging = bool(self.dragging_token or self.dragging_tokens)
            map_data = self.current_map
            if dragging and map_data is not None:
                walk = self._walk_token_to(token, map_data, x, y)
                x, y = walk[-1]
                if self.dragging_token and not self.dragging_tokens:
                    # След одиночной перетаски — для отправки пути серверу.
                    self._token_drag_trail.extend(walk[1:])
                elif token_id in self._token_drag_trails:
                    self._token_drag_trails[token_id].extend(walk[1:])
            self._motions.pop(token_id, None)
            token.x = x
            token.y = y
            # Вход/выход из-под крыши — такой же повод перерисовать кадры.
            if self._roofs_exist():
                self._ensure_anim_timer()
            self.update()
            return

        start_x, start_y = self._token_visual_pos(token)
        token.x = x
        token.y = y
        if abs(start_x - x) < 0.01 and abs(start_y - y) < 0.01:
            self._motions.pop(token_id, None)
            return
        self._motions[token_id] = {
            'from': (start_x, start_y),
            'to': (x, y),
            'start': time.monotonic(),
            'duration': MOVE_ANIM_S,
        }
        self._ensure_anim_timer()
        self.update()

    def _drag_step_size(self) -> float:
        """Шаг проверки пути при перетаскивании: треть клетки, но не меньше."""
        cell = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        if cell > 0:
            return max(2.0, cell * DRAG_STEP_FRACTION)
        return 12.0

    def _walk_spans(self, map_data) -> list:
        """Куски стен, сквозь которые токен сейчас не пройдёт.

        Отличие от ``wall_rules.wall_spans(light=False)`` одно: дверь, которая
        только начала открываться, ещё считается закрытой. Без этого токен
        проезжал бы сквозь створку в том же кадре, где она дёрнулась, — на
        экране это выглядит как проход через закрытую дверь. Как только
        створка встала поперёк, проём — просто проход.
        """
        spans = wall_rules.wall_spans(map_data, light=False)
        walls = wall_rules.map_walls(map_data)
        if not walls:
            return spans
        by_id = {wall["id"]: wall for wall in walls}
        now = time.monotonic()
        for opening in wall_rules.map_openings(map_data, walls):
            if opening.get("kind") != wall_rules.DOOR:
                continue
            if not opening.get("open"):
                continue
            if self.door_angle(opening, now) >= DOOR_PASS_ANGLE:
                continue
            wall = by_id.get(opening.get("wall_id"))
            if wall is None:
                continue
            segment = wall_rules.opening_segment(wall, opening)
            if segment is not None:
                spans.append(segment)
        return spans

    def _walk_token_to(self, token, map_data, x: float, y: float) -> list:
        """Довести токен до точки мелкими шагами, не проходя сквозь стены.

        Раньше проверялся один прямой отрезок от прежнего положения до
        курсора: мышь обгоняет фишку, отрезок задевает стену — и токен
        замирал, а после отпускания сервер присылал его обратно. Теперь путь
        идёт по той дороге, которой ведёт курсор: шаг за шагом. Упёршись в
        стену, токен подходит к ней вплотную и стоит там до тех пор, пока
        курсор не обойдёт её, — а не возвращается туда, откуда пришёл.

        Возвращает пройденные точки, включая начальную и конечную.
        """
        start = (float(token.x), float(token.y))
        trail = [start]
        distance = math.hypot(x - start[0], y - start[1])
        if distance <= 1e-6:
            return trail
        segments = self._walk_spans(map_data)
        if not segments:
            # Стен нет — идём сразу, без лишних шагов.
            return [start, (float(x), float(y))]
        step = self._drag_step_size()
        steps = max(1, min(60, int(math.ceil(distance / step))))
        cx, cy = start
        for index in range(1, steps + 1):
            share = index / float(steps)
            nx = start[0] + (x - start[0]) * share
            ny = start[1] + (y - start[1]) * share
            if not wall_rules.path_blocked(cx, cy, nx, ny, segments):
                cx, cy = nx, ny
                trail.append((cx, cy))
                continue
            door = wall_rules.door_crossing(map_data, cx, cy, nx, ny)
            if door is not None:
                # Дверь распахиваем только у себя и без сети: сервер сам
                # откроет её, когда дойдёт шаг через проём. Раньше каждый
                # пиксель перетаскивания отправлял TOGGLE_DOOR, дверь
                # хлопала туда-обратно, а пока токен был ещё далеко, сервер
                # отвечал «дверь слишком далеко» — это засоряло чат.
                if not door.get("open"):
                    self.toggle_door(door["id"], True, notify=False)
                # Дверь только начала открываться — она всё ещё перекрыта.
                segments = self._walk_spans(map_data)
                if not wall_rules.path_blocked(cx, cy, nx, ny, segments):
                    cx, cy = nx, ny
                    trail.append((cx, cy))
                    continue
            elif wall_rules.door_crossing(map_data, cx, cy, nx, ny,
                                          include_locked=True) is not None:
                # Замок — не стена: скажем об этом словом, а не молча.
                self.show_hint("Дверь заперта — попросите мастера отпереть")
            # Подрезаем шаг до самой стены: фишка упирается в неё, а не
            # отпрыгивает назад.
            low, high = 0.0, 1.0
            for _ in range(8):
                mid = (low + high) / 2.0
                if wall_rules.path_blocked(cx, cy,
                                           cx + (nx - cx) * mid,
                                           cy + (ny - cy) * mid, segments):
                    high = mid
                else:
                    low = mid
            if low <= 1e-4:
                break
            cx += (nx - cx) * low
            cy += (ny - cy) * low
            trail.append((cx, cy))
            break
        return trail

    def _compress_drag_trail(self, trail, map_data) -> list:
        """Проредить пройденный путь: оставить только обходы стен.

        Отправлять на сервер каждую точку жеста — сотня сообщений на одну
        перетаску. Но и двух точек мало: прямая от начала к концу может
        резать стену, хотя фишку обвели через дверь — такую перетаску сервер
        отклонит, и токен вернётся назад. Поэтому собираем путь из возможно
        длинных прямых: каждая следующая точка — самая далёкая, до которой
        ещё можно идти, не задевая стену.
        """
        points = [(float(px), float(py)) for px, py in trail or []]
        if len(points) < 3 or map_data is None:
            return points
        segments = self._walk_spans(map_data)
        if not segments:
            return [points[0], points[-1]]
        kept = [points[0]]
        index = 1
        while index < len(points):
            best = index
            probe = index
            while probe < len(points) and not wall_rules.path_blocked(
                    kept[-1][0], kept[-1][1],
                    points[probe][0], points[probe][1], segments):
                best = probe
                probe += 1
            kept.append(points[best])
            index = best + 1
        return kept

    def take_token_move_path(self) -> list:
        """Забрать путь последнего перетаскивания токена (и очистить)."""
        path = self._token_move_path
        self._token_move_path = []
        return path

    def set_turn_token(self, token_id: Optional[str]):
        """Показать (или убрать) кольцо текущего хода на токене."""
        changed = self.turn_token_id != token_id
        self.turn_token_id = token_id
        if changed:
            # Новый ход — новый бюджет движения и новая попытка рывка.
            self._reset_turn_actions()
        if changed and self.combat_active:
            # Новый ход — снова готовим шахматное перемещение его токена.
            self._arm_chess_move(token_id)
        if changed:
            self.update()

    def set_turn_context(self, round_no, turn_index, token_id: Optional[str]):
        """Сообщить холсту номер раунда и хода.

        Одного id токена мало: в одиночном бою один и тот же участник ходит
        каждый раунд, и без номера раунда его потраченная скорость не
        сбрасывалась бы. Контекст приходит из INITIATIVE_UPDATE (и из полного
        состояния), поэтому одинаков у всех клиентов.
        """
        try:
            round_no = max(1, int(round_no))
            turn_index = max(0, int(turn_index))
        except (TypeError, ValueError):
            round_no, turn_index = 1, 0
        signature = (round_no, turn_index)
        changed = signature != self._turn_signature
        self._turn_signature = signature
        self.turn_round = round_no
        self.turn_index = turn_index
        if changed:
            self._reset_turn_actions()
        self.set_turn_token(token_id)

    def _reset_turn_actions(self):
        """Сбросить потраченное движение и рывок для нового хода."""
        self._move_spent_ft.clear()
        self._dash_used.clear()
        self._move_total_override.clear()

    def set_combat_mode(self, active: bool):
        """Включить или выключить боевое перемещение по клеткам.

        Вне боя и у токенов без инициативы остаётся обычное перетаскивание.
        """
        active = bool(active)
        if self.combat_active == active:
            return
        self.combat_active = active
        if not active:
            self.chess_token_id = None
            self._reset_turn_actions()
            self._haste_until.clear()
            self._haste_pending.clear()
            self._move_total_override.clear()
        else:
            self._activate_pending_haste()
            self._arm_chess_move(self.turn_token_id)
        self.update()

    def _activate_pending_haste(self):
        """Зелье, выпитое вне боя, начинает действовать с первого раунда."""
        if not self._haste_pending:
            return
        for token_id, rounds in self._haste_pending.items():
            if rounds <= 0:
                continue
            until = self.turn_round + rounds - 1
            self._haste_until[token_id] = max(
                until, self._haste_until.get(token_id, 0))
        self._haste_pending.clear()

    # ------------------------------------------------------------------
    # Перемещение в бою: клик по токену → подсвеченные клетки → клик
    # по клетке. Радиус — ОСТАТОК скорости на этот ход, 5 футов на клетку,
    # диагонали считаются по прямой (теорема Пифагора), как линейкой.
    # ------------------------------------------------------------------
    def _token_in_combat(self, token) -> bool:
        return bool(self.combat_active and token is not None
                    and getattr(token, "initiative", None) is not None)

    def _can_control_token(self, token) -> bool:
        return bool(token is not None
                    and (self.is_dm or token.owner_id == self.player_id))

    def _turn_allows_move(self, token) -> tuple:
        """Может ли этот клиент двигать токен в текущий момент.

        В бою игрок ходит только своим токеном и только когда его ход: иначе
        можно было кликнуть своего персонажа в чужой ход и пройти клетки,
        хотя очередь ещё не дошла. Мастер двигает любой токен и вне очереди —
        это его инструмент подготовки и правок сцены.
        """
        if token is None:
            return False, "Токен не выбран"
        if self.is_dm or not self.combat_active:
            return True, ""
        current_id = self.turn_token_id
        if not current_id or token.id == current_id:
            return True, ""
        current = self.tokens.get(current_id)
        name = current.name if current is not None else "другого участника"
        return False, (f"Сейчас ход «{name}» — «{token.name}» "
                       "двигать нельзя")

    def _token_speed_feet(self, token) -> int:
        resolver = getattr(self, "speed_resolver", None)
        if callable(resolver):
            try:
                value = resolver(token)
                if value is not None:
                    return max(0, int(value))
            except Exception:
                pass
        return token_stats.token_speed_ft(token)

    def _hasted(self, token) -> bool:
        """Действует ли на токен зелье скорости в текущем раунде."""
        if token is None or not self.combat_active:
            return False
        until = self._haste_until.get(token.id, 0)
        return until >= self.turn_round

    def _haste_left_rounds(self, token) -> int:
        if token is None or not self.combat_active:
            return 0
        return max(0, self._haste_until.get(token.id, 0) - self.turn_round + 1)

    def movement_total(self, token) -> int:
        """Сколько футов доступно за этот ход (с рывком/зельем, но не выше ×2).

        Если сервер уже прислал бюджет, показываем его: у клиента скорость
        может разойтись с листом на сервере, а ходить надо по серверному
        остатку.
        """
        if token is not None:
            override = self._move_total_override.get(token.id)
            if override is not None:
                return max(0, int(override))
        speed = self._token_speed_feet(token)
        if speed <= 0:
            return 0
        dashed = token.id in self._dash_used or self._hasted(token)
        # Удар Зефира прибавляет 30 футов, а не удваивает: прибавка идёт
        # после удвоения и складывается с ним.
        return speed * (2 if dashed else 1) + self._move_bonus_ft.get(token.id, 0)

    def movement_spent(self, token) -> float:
        """Сколько футов токен уже прошёл за этот ход."""
        if token is None:
            return 0.0
        return float(self._move_spent_ft.get(token.id, 0.0))

    def movement_left(self, token) -> float:
        """Остаток скорости в футах; отрицательного не бывает."""
        if token is None:
            return 0.0
        return max(0.0, float(self.movement_total(token))
                   - self.movement_spent(token))

    def movement_text(self, token) -> str:
        """Строка для статусбара: потрачено/всего и остаток."""
        if token is None:
            return ""
        total = self.movement_total(token)
        used = int(round(self.movement_spent(token)))
        left = int(round(self.movement_left(token)))
        text = f"«{token.name}»: {used}/{total} фт — осталось {left} фт"
        bonus = int(self._move_bonus_ft.get(token.id, 0) or 0)
        if bonus:
            text += f" (удар зефира: +{bonus} фт)"
        if self._hasted(token):
            text += f" (зелье скорости: ещё {self._haste_left_rounds(token)} р.)"
        elif token.id in self._dash_used:
            text += " (рывок)"
        return text

    def apply_speed_potion(self, token_id: str, rounds: int = 10) -> str:
        """Зелье скорости: удвоение темпа на N раундов (по умолчанию 10).

        Работает как рывок, но не складывается с ним: максимум всё равно
        ×2. Вне боя зелье запоминается и включается с первым раундом, чтобы
        выпитое перед стычкой не пропало.
        """
        token = self.tokens.get(token_id)
        if token is None:
            return "Зелье скорости: токен не найден"
        try:
            rounds = max(1, int(rounds))
        except (TypeError, ValueError):
            rounds = 10
        if not self.combat_active:
            self._haste_pending[token.id] = max(
                rounds, self._haste_pending.get(token.id, 0))
            return (f"«{token.name}»: зелье скорости выпито — "
                    f"×2 начнётся с первым раундом боя")
        was_doubled = self._hasted(token) or token.id in self._dash_used
        until = self.turn_round + rounds - 1
        self._haste_until[token.id] = max(
            until, self._haste_until.get(token.id, 0))
        if token.id in self._move_total_override and not was_doubled:
            self._move_total_override[token.id] = (
                self._move_total_override[token.id] * 2)
        if token.id in (self.chess_token_id, self.turn_token_id):
            self._arm_chess_move(token.id)
        self.update()
        self.movement_reported.emit(self.movement_text(token))
        return (f"«{token.name}»: зелье скорости — скорость ×2 "
                f"на {rounds} раундов")

    def apply_movement_state(self, states) -> None:
        """Принять бюджет от сервера: потрачено, всего, рывок и зелье.

        Сервер — источник истины. Клиентский счётчик нужен только для
        мгновенной подсветки между сообщениями; после ответа сервера он
        подменяется серверным, включая откат отклонённого шага.
        """
        if isinstance(states, dict):
            states = [states]
        if not isinstance(states, (list, tuple)):
            return
        for state in states:
            if not isinstance(state, dict):
                continue
            token_id = state.get('token_id')
            if not token_id:
                continue
            try:
                spent = max(0.0, float(state.get('spent', 0.0)))
            except (TypeError, ValueError):
                spent = 0.0
            self._move_spent_ft[token_id] = spent
            if state.get('dash'):
                self._dash_used.add(token_id)
            else:
                self._dash_used.discard(token_id)
            try:
                haste = max(0, int(state.get('haste_rounds') or 0))
            except (TypeError, ValueError):
                haste = 0
            if haste:
                self._haste_until[token_id] = self.turn_round + haste - 1
            else:
                self._haste_until.pop(token_id, None)
            try:
                bonus_ft = max(0, int(state.get('speed_bonus') or 0))
            except (TypeError, ValueError):
                bonus_ft = 0
            if bonus_ft:
                self._move_bonus_ft[token_id] = bonus_ft
            else:
                self._move_bonus_ft.pop(token_id, None)
            total = state.get('total')
            if total is None:
                self._move_total_override.pop(token_id, None)
            else:
                try:
                    self._move_total_override[token_id] = max(0, int(total))
                except (TypeError, ValueError):
                    self._move_total_override.pop(token_id, None)
        self.update()

    def dash_action(self) -> bool:
        """Рывок: один раз за ход добавить к скорости ещё одну скорость.

        Срабатывает только для того, чей сейчас ход. Повторное нажатие в том
        же ходу ничего не добавляет: максимум — двойная скорость. Новый ход
        снова даёт рывок.
        """
        token = None
        if self.turn_token_id:
            token = self.tokens.get(self.turn_token_id)
            if token is not None and not self._can_control_token(token):
                self.movement_blocked.emit("Сейчас не ваш ход: рывок недоступен")
                return False
        if token is None:
            token = self.tokens.get(self.chess_token_id or self.selected_token or "")
        if token is None:
            self.movement_blocked.emit("Выберите токен для рывка")
            return False
        if not self.combat_active or not self._token_in_combat(token):
            self.movement_blocked.emit(
                f"«{token.name}»: рывок доступен только в бою")
            return False
        if not self._can_control_token(token):
            self.movement_blocked.emit(
                f"«{token.name}»: это не ваш токен")
            return False
        allowed, why = self._turn_allows_move(token)
        if not allowed:
            self.movement_blocked.emit(f"Рывок недоступен: {why}")
            return False
        if combat_rules.death_save_state(
                getattr(token, 'death_saves', None))['dead']:
            self.movement_blocked.emit(f"«{token.name}» мёртв")
            return False
        movable, why = conditions_rules.can_move(
            getattr(token, 'conditions', None), hp=getattr(token, 'hp', None))
        if not movable:
            self.movement_blocked.emit(
                f"«{token.name}» не может двигаться: {why}")
            return False
        if self._token_speed_feet(token) <= 0:
            self.movement_blocked.emit(f"«{token.name}»: скорость 0")
            return False
        if self._hasted(token):
            self.movement_reported.emit(
                f"«{token.name}»: скорость уже удвоена зельем")
            return False
        if token.id in self._dash_used:
            self.movement_reported.emit(
                f"«{token.name}»: рывок уже использован в этом ходу")
            return False
        was_doubled = self._hasted(token) or token.id in self._dash_used
        self._dash_used.add(token.id)
        # Пока сервер не ответил, показываем удвоенный бюджет сразу.
        if token.id in self._move_total_override and not was_doubled:
            self._move_total_override[token.id] = (
                self._move_total_override[token.id] * 2)
        self.chess_token_id = token.id
        self.setCursor(Qt.PointingHandCursor)
        self.update()
        # Сервер должен узнать о рывке до следующего MOVE_TOKEN, иначе
        # отклонит законный шаг дальше обычной скорости.
        self.dash_used.emit(token.id)
        self.movement_reported.emit(self.movement_text(token))
        return True

    def _arm_chess_move(self, token_id: Optional[str]):
        """Взять токен для шахматного хода (если он в бою и его ход)."""
        token = self.tokens.get(token_id) if token_id else None
        allowed, _why = self._turn_allows_move(token)
        if (self._token_in_combat(token) and self._can_control_token(token)
                and allowed
                and not combat_rules.death_save_state(
                    getattr(token, 'death_saves', None))['dead']):
            self.chess_token_id = token.id
        else:
            self.chess_token_id = None
        self.update()

    def chess_cells(self) -> set:
        """Клетки, куда может шагнуть выбранный в бою токен."""
        token = self.tokens.get(self.chess_token_id or "")
        m = self.current_map
        if token is None or m is None or not m.grid.valid:
            return set()
        if not self._token_in_combat(token) or not self._can_control_token(token):
            return set()
        allowed, _why = self._turn_allows_move(token)
        if not allowed:
            return set()
        if combat_rules.death_save_state(
                getattr(token, 'death_saves', None))['dead']:
            return set()
        movable, _why = conditions_rules.can_move(
            getattr(token, 'conditions', None),
            hp=getattr(token, 'hp', None))
        if not movable:
            return set()
        left = self.movement_left(token)
        # Меньше клетки пути — идти некуда: зелёная подсветка гаснет.
        if left < 5.0 - 1e-6:
            return set()
        cell_w, cell_h = m.grid_cell_world
        if cell_w <= 0 or cell_h <= 0:
            return set()
        radius = left / 5.0
        start_x = int((float(token.x) - m.pos_x) / cell_w)
        start_y = int((float(token.y) - m.pos_y) / cell_h)
        reach = int(math.ceil(radius))
        cells = set()
        for gy in range(max(0, start_y - reach),
                        min(m.grid.rows, start_y + reach + 1)):
            for gx in range(max(0, start_x - reach),
                            min(m.grid.cols, start_x + reach + 1)):
                if (gx, gy) == (start_x, start_y):
                    continue
                # Диагональ считаем по прямой, а не по клеткам: шесть
                # клеток по диагонали — это 8,5 клетки пути, то есть вне
                # 30 футов, как и на столе.
                if math.hypot(gx - start_x, gy - start_y) > radius + 1e-6:
                    continue
                cx = m.pos_x + (gx + 0.5) * cell_w
                cy = m.pos_y + (gy + 0.5) * cell_h
                if self._cell_occupied(cx, cy, cell_w, cell_h, token.id):
                    continue
                cells.add((gx, gy))
        return cells

    def _cell_occupied(self, x, y, cell_w, cell_h, skip_id) -> bool:
        """Занята ли клетка другим токеном (через неё не встать)."""
        for other in self.current_map_tokens().values():
            if other.id == skip_id or not other.visible:
                continue
            half_w = cell_w * max(1.0, float(other.size or 1.0)) / 2.0
            half_h = cell_h * max(1.0, float(other.size or 1.0)) / 2.0
            if abs(x - float(other.x)) < half_w and abs(y - float(other.y)) < half_h:
                return True
        return False

    def _cell_at(self, wx: float, wy: float):
        m = self.current_map
        if m is None or not m.grid.valid:
            return None
        cell_w, cell_h = m.grid_cell_world
        if cell_w <= 0 or cell_h <= 0:
            return None
        gx = int((wx - m.pos_x) / cell_w)
        gy = int((wy - m.pos_y) / cell_h)
        if 0 <= gx < m.grid.cols and 0 <= gy < m.grid.rows:
            return gx, gy
        return None

    def _try_chess_move(self, wx: float, wy: float) -> bool:
        """Клик по подсвеченной клетке: плавно переставить токен."""
        if not self.chess_token_id:
            return False
        token = self.tokens.get(self.chess_token_id)
        allowed, why = self._turn_allows_move(token)
        if not allowed:
            self.movement_blocked.emit(why)
            return False
        cell = self._cell_at(wx, wy)
        if cell is None or cell not in self.chess_cells():
            return False
        m = self.current_map
        if token is None or m is None:
            return False
        cell_w, cell_h = m.grid_cell_world
        x = m.pos_x + (cell[0] + 0.5) * cell_w
        y = m.pos_y + (cell[1] + 0.5) * cell_h
        before = (token.x, token.y)
        # Путь считаем в футах по прямой между центрами клеток: диагональ
        # стоит дороже, поэтому шестая диагональная клетка не «съедает»
        # весь ход, как и при подсветке радиуса.
        cost = math.hypot((x - before[0]) / cell_w,
                          (y - before[1]) / cell_h) * 5.0
        if cost > self.movement_left(token) + 1e-6:
            return False
        # Модель меняется сразу, а на экране токен доезжает: ту же
        # анимацию использует сетевое перемещение.
        self.update_token_position(token.id, x, y, animate=True)
        self._move_spent_ft[token.id] = self.movement_spent(token) + cost
        self.token_moved.emit(token.id, x, y)
        self.edit_finished.emit({
            'kind': 'tokens',
            'before': {token.id: before},
            'after': {token.id: (x, y)},
        })
        self.update()
        self.movement_reported.emit(self.movement_text(token))
        return True

    def set_quick_attack_mode(self, enabled: bool):
        """Взвести или снять быструю атаку (один удар).

        Это не долгий режим, а взвод: после первого удара (или клика по
        пустому месту, Esc) атака снимается сама. Поэтому состояние видно
        и на холсте: кольцо вокруг атакующего и плашка сверху с оружием.
        """
        enabled = bool(enabled)
        if self.quick_attack_mode == enabled:
            return
        self.quick_attack_mode = enabled
        if not enabled:
            self.quick_attack_hint = ""
        self.setCursor(Qt.CrossCursor if enabled else Qt.ArrowCursor)
        self.quick_attack_mode_changed.emit(enabled)
        self.update()

    def set_quick_attack_hint(self, text: str):
        """Подпись плашки «чем бьём»; пустая — плашки нет."""
        self.quick_attack_hint = str(text or "").strip()
        self.update()

    def draw_quick_attack_banner(self, painter: QPainter):
        """Плашка сверху холста: видно, что атака взведена и чем бьём."""
        if not self.quick_attack_mode or not self.current_map:
            return
        text = self.quick_attack_hint or "Быстрая атака — выберите цель"
        font = QFont(painter.font())
        font.setPointSize(10)
        font.setBold(True)
        painter.setFont(font)
        metrics = QFontMetrics(font)
        hint = metrics.elidedText(text, Qt.ElideRight,
                                  max(160, int(self.width() * 0.7)))
        width = metrics.horizontalAdvance(hint) + 34
        rect = QRectF((self.width() - width) / 2.0, 12.0, width, 30.0)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(46, 20, 16, 238)))
        painter.drawRoundedRect(rect, 8.0, 8.0)
        pen = QPen(QColor(226, 89, 63))
        pen.setWidthF(1.4)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawRoundedRect(rect, 8.0, 8.0)
        painter.setPen(QPen(QColor(255, 214, 190)))
        painter.drawText(rect, Qt.AlignCenter, hint)

    def update_token(self, data: dict):
        token = self.tokens.get(data.get('token_id'))
        if not token:
            return
        was_dead = (token.hp is not None
                    and combat_rules.death_save_state(
                        getattr(token, 'death_saves', None))['dead'])
        if 'hp' in data or 'hp_max' in data:
            before = self._hp_ratio(token)
            for field in ('hp', 'hp_max'):
                if field in data:
                    setattr(token, field, data[field])
            after = self._hp_ratio(token)
            if abs(after - before) > 0.002:
                self._hp_anims[token.id] = {
                    'from': before, 'to': after,
                    'start': time.monotonic(), 'duration': HP_BAR_ANIM_S,
                }
                self._ensure_anim_timer()
        # Обновляем ВСЕ поля токена, которые присылает сервер. Раньше список
        # был коротким, и состояния/статблок доезжали до сети, но не до
        # модели на клиенте: карточка при повторном открытии показывала старые
        # галочки, а иконки на токене не появлялись.
        turning = token.id in (self.rotating_token_id, self._turn_token_id)
        for field in ('name', 'size', 'owner_id', 'visible', 'ac',
                      'initiative', 'dex', 'kind', 'map_id', 'hp_temp',
                      'facing', 'vision_angle', 'vision_range'):
            if field not in data:
                continue
            if field == 'facing' and turning:
                # Пока взглядом ведёт пружина, эхо прежнего угла с сервера
                # отбросило бы токен назад посреди движения. Свой угол
                # зафиксируем сами, когда пружина встанет.
                continue
            setattr(token, field, data[field])
        if 'conditions' in data:
            token.conditions = [str(v) for v in (data.get('conditions') or [])
                                if str(v).strip()]
        if 'active_effects' in data:
            token.active_effects = [
                dict(effect) for effect in (data.get('active_effects') or [])
                if isinstance(effect, dict)]
        if 'death_saves' in data:
            token.death_saves = combat_rules.normalize_death_saves(
                data.get('death_saves'))
        for field in ('resist', 'immune', 'vulnerable'):
            if field in data:
                setattr(token, field, list(data.get(field) or []))
        if 'statblock' in data and isinstance(data['statblock'], dict):
            token.statblock = dict(data['statblock'])

        dead_now = (token.hp is not None and token.hp <= 0
                    and combat_rules.death_save_state(
                        getattr(token, 'death_saves', None))['dead'])
        if dead_now and not was_dead:
            self._start_death_anim(token.id)
        elif not dead_now:
            self._death_anims.pop(token.id, None)
        self.update()

    # ------------------------------------------------------------------
    # Взгляд токена: поворот клавишей R и конус зрения
    # ------------------------------------------------------------------
    def set_special_attack_hotkeys(self, mapping: dict):
        """Раздать холсту хоткеи особых атак: {буква: (token_id, attack_id)}."""
        self.special_attack_hotkeys = {
            str(key).upper(): tuple(value)
            for key, value in (mapping or {}).items()
            if str(key).strip()
        }

    def _rotation_target_token_id(self) -> Optional[str]:
        """Какой токен крутим: выделенный или единственный в группе."""
        if self.selected_token and self.selected_token in self.tokens:
            return self.selected_token
        if len(self.selected_tokens) == 1:
            return next(iter(self.selected_tokens))
        return None

    def toggle_token_rotation(self) -> bool:
        """R: первый раз включает поворот, второй — фиксирует. -> включён ли.

        Мышь ведёт взгляд вокруг центра токена, и вместе с ним
        разворачивается сам портрет: токен смотрит туда, куда повёрнут.
        Заодно подсвечивается жёлтый сектор обзора — видно, насколько
        широко токен видит в эту сторону.
        """
        if self.rotating_token_id:
            self.finish_token_rotation()
            return False
        token_id = self._rotation_target_token_id()
        token = self.tokens.get(token_id or "")
        if token is None:
            self.show_hint("Поворот токена: сначала выделите один токен")
            return False
        now = time.monotonic()
        self.rotating_token_id = token_id
        self._rotate_token_restore = vision_rules.normalize_facing(
            getattr(token, "facing", None))
        self._turn_token_id = token_id
        self._turn_target = self._rotate_token_restore
        self._turn_speed = 0.0
        self._turn_last_step = now
        self._turn_commit = None
        # Первые TOKEN_TURN_START_DELAY_S секунд режима токен стоит.
        self._turn_ready_at = now + TOKEN_TURN_START_DELAY_S
        self.setCursor(Qt.CrossCursor)
        self.show_hint(
            f"Поворот «{token.name}»: ведите мышь вокруг токена · "
            "R — зафиксировать · Esc — отмена")
        self._ensure_anim_timer()
        self.update()
        return True

    def rotate_token_towards(self, wx: float, wy: float) -> bool:
        """Задать направление взгляда мышью — вокруг центра токена.

        Мышь только ставит цель: взгляд ведёт пружина
        (`TOKEN_TURN_STIFFNESS` / `TOKEN_TURN_DAMPING`), а сразу после
        включения режима он стоит `TOKEN_TURN_START_DELAY_S`. Пружина не
        перезапускается на каждом пикселе: движение начинается из покоя и
        тормозит у цели, поэтому и на медленном, и на резком движении
        курсора портрет едет ровно, без рывков.
        """
        token = self.tokens.get(self.rotating_token_id or "")
        if token is None:
            return False
        cx, cy = self._token_visual_pos(token)
        target = vision_rules.facing_between(
            cx, cy, wx, wy, default=vision_rules.normalize_facing(
                getattr(token, "facing", None)))
        self._turn_target = target
        now = time.monotonic()
        # Пока идёт стартовая задержка, цель только запоминается: тогда
        # токен не дёрнется от случайного касания, а после паузы сам
        # пойдёт к последней точке курсора.
        if now >= self._turn_ready_at and self._turn_commit is None:
            self._start_turn_tween(target, now)
        self._ensure_anim_timer()
        self.update()
        return True

    def _start_turn_tween(self, target: float, now: float):
        """Принять новую цель пружины — без перезапуска с нуля.

        Имя сохранилось от прежней 0.12-секундной доводки: раньше здесь
        заново ставился твин, и каждое событие мыши обрывало предыдущее
        движение — отсюда рывки. Теперь движение одно на весь жест: угол
        хранит сама модель, а шаг считает `_step_token_turn`.
        """
        self._turn_target = vision_rules.normalize_facing(target)
        if not self._anim_timer.isActive():
            # Пружина стояла: отсчёт новых кадров начинаем с этого момента,
            # иначе первый шаг получил бы накопленный большой dt.
            self._turn_speed = 0.0
            self._turn_last_step = now

    def _step_token_turn(self, now: float = None) -> bool:
        """Один кадр пружины взгляда — её крутит общий таймер холста.

        Критически задемпфированная пружина: скорость растёт из нуля
        (мягкий разгон), а у цели падает до нуля (мягкое торможение).
        Возвращает True, пока нужен следующий кадр. Время можно передать
        явно: так тесты проверяют задержку и доводку без реального ожидания.
        """
        now = time.monotonic() if now is None else now
        token = self.tokens.get(self._turn_token_id or "")
        if token is None:
            self._reset_token_turn()
            return False
        # Стартовая пауза: взгляд стоит, хотя цель уже запомнена.
        if now < self._turn_ready_at:
            self._turn_last_step = now
            return True
        target = self._turn_target
        if target is None:
            return False
        # Стартовая пауза в шаг не входит: иначе первый кадр после неё
        # отыграл бы все 0.35 с разом и взгляд прыгнул бы через полсектора.
        dt = max(0.0, now - max(self._turn_last_step, self._turn_ready_at))
        self._turn_last_step = now
        if dt <= 0:
            return True
        # Шаг пружины считается по ТОЧНОМУ решению, а не по Эйлеру. У Эйлера
        # демпфирование — это c·dt: при 60 кадрах в секунду оно перетормаживало
        # (взгляд полз к цели), а при 20–30 (ночной туман, слабая видеокарта)
        # скорость за кадр перелетала через ноль — взгляд отъезжал назад на
        # пару кадров и снова шёл вперёд. Это и читалось как подёргивание на
        # остановке. Точное решение одной и той же пружины не зависит от
        # частоты кадров: и на 15, и на 144 кадрах путь один и тот же, а
        # ошибка не меняет знак — назад взгляд не отъезжает никогда.
        dt = min(dt, TOKEN_TURN_MAX_DT)
        error = _turn_delta(token.facing, target)
        speed = max(-TOKEN_TURN_MAX_SPEED,
                    min(TOKEN_TURN_MAX_SPEED, self._turn_speed))
        omega = TOKEN_TURN_OMEGA
        # Критическое демпфирование: e(t) = (e₀ + (ė₀ + ω·e₀)·t)·e^(−ωt).
        push = -speed + omega * error
        decay = math.exp(-omega * dt)
        remain = (error + push * dt) * decay
        velocity = (speed + omega * push * dt) * decay
        step = error - remain
        if (remain * error <= 0.0
                or (abs(remain) <= TOKEN_TURN_SNAP_DEG
                    and abs(velocity) <= TOKEN_TURN_SNAP_SPEED)):
            # Догнали: встаём точно в цель без перелёта и без качания.
            token.facing = vision_rules.normalize_facing(target)
            self._turn_speed = 0.0
            if self._turn_commit is not None:
                self._commit_token_turn(token)
            return False
        token.facing = vision_rules.normalize_facing(token.facing + step)
        self._turn_speed = velocity
        return True

    def _commit_token_turn(self, token):
        """Второе R: угол доехал — сохраняем его на сервере.

        Фиксация не трогает ни угол, ни скорость: пружина уже стоит в цели,
        поэтому взгляд заканчивает движение там, где его оставил курсор.
        """
        restore = (self._turn_commit or {}).get("restore")
        facing = vision_rules.normalize_facing(getattr(token, "facing", None))
        token.facing = facing
        self._reset_token_turn()
        # _before — для Ctrl+Z: без него отмена не знала бы прежний угол.
        self.token_updated_requested.emit({
            "token_id": token.id,
            "facing": facing,
            "_before": {"facing": restore},
        })
        self.show_hint(f"Токен «{token.name}» повёрнут и зафиксирован")

    def _reset_token_turn(self):
        self._turn_token_id = None
        self._turn_target = None
        self._turn_speed = 0.0
        self._turn_commit = None

    def _turn_pending(self) -> bool:
        """Идёт ли ещё плавный поворот (нужен ли кадр таймера)."""
        if not self._turn_token_id:
            return False
        if self._turn_commit is not None:
            # Фиксация ждёт, пока пружина доедет и встанет в цель.
            return True
        token = self.tokens.get(self._turn_token_id)
        if token is None or self._turn_target is None:
            return False
        return (abs(_turn_delta(token.facing, self._turn_target))
                > TOKEN_TURN_SNAP_DEG
                or abs(self._turn_speed) > TOKEN_TURN_SNAP_SPEED)

    def finish_token_rotation(self):
        """Второе R: довести взгляд до цели и сохранить его на сервере."""
        token = self.tokens.get(self.rotating_token_id or "")
        before = self._rotate_token_restore
        self.rotating_token_id = None
        self._rotate_token_restore = None
        self.setCursor(Qt.ArrowCursor)
        if token is None:
            self._reset_token_turn()
            self.update()
            return
        facing = vision_rules.normalize_facing(
            getattr(token, "facing", None))
        target = self._turn_target
        target = facing if target is None else vision_rules.normalize_facing(
            target)
        self._turn_token_id = token.id
        self._turn_target = target
        self._turn_commit = {"restore": before}
        # Скорость и время последнего шага не трогаем: пружина продолжает
        # движение с тем же разгоном и так же мягко тормозит у цели.
        if (abs(_turn_delta(facing, target)) <= TOKEN_TURN_SNAP_DEG
                and abs(self._turn_speed) <= TOKEN_TURN_SNAP_SPEED):
            # Пружина уже стоит — фиксируем сразу, без пустых кадров.
            token.facing = target
            self._commit_token_turn(token)
            self.update()
            return
        # Кадр не просим: пружину ведёт таймер, а лишняя отрисовка без шага
        # давала посреди движения мёртвый кадр — ещё один микро-рывок.
        self._ensure_anim_timer()

    def cancel_token_rotation(self):
        """Esc в режиме поворота: вернуть прежний угол и выйти."""
        token = self.tokens.get(self.rotating_token_id or "")
        if token is not None and self._rotate_token_restore is not None:
            token.facing = self._rotate_token_restore
        self.rotating_token_id = None
        self._rotate_token_restore = None
        self._reset_token_turn()
        self.setCursor(Qt.ArrowCursor)
        self.show_hint("Поворот отменён")
        self.update()

    def token_vision_radius_world(self, token) -> float:
        """Дальность зрения в мировых единицах: футы → клетки → пиксели."""
        cell_w = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        feet = vision_rules.normalize_range(
            getattr(token, "vision_range", None))
        if cell_w <= 0:
            return 0.0
        return (feet / vision_rules.FT_PER_CELL) * cell_w

    def draw_token_vision_cone(self, painter: QPainter, token):
        """Сектор зрения токена — поверх пола, под телами.

        Угол берётся из настроек токена (по умолчанию 70°), дальность — из
        футов, пересчитанных в клетки карты. Геометрия та же, что и у
        серверной проверки скрытности (shared.vision), поэтому подсвеченное
        на экране и запрет «вас видят» всегда совпадают.

        Цвет зависит от того, кто смотрит. Мастеру нужен жёлтый сектор: он
        ведёт сцену и проверяет, куда смотрит существо. Игроку заливка
        мешает — он и так знает, куда смотрит его токен, а на карте жёлтое
        пятно спорит с освещением. Поэтому у игрока остаётся только еле
        заметный тёмный контур: видно направление взгляда, но цветная карта
        не перекрашивается.

        Мастер с включённым «туманом войны как у игроков» смотрит стол
        глазами стола — и токены игроков тоже без жёлтой заливки: иначе этот
        режим не давал бы увидеть сцену такой, какой её видят за столом.
        Свои актёры (НПС) у него остаются с жёлтым сектором.
        """
        radius = self.token_vision_radius_world(token)
        if radius <= 0:
            return
        cx, cy = self._token_visual_pos(token)
        angle = vision_rules.normalize_angle(
            getattr(token, "vision_angle", None))
        facing = vision_rules.normalize_facing(getattr(token, "facing", None))
        # Геометрия сектора одна и та же на холсте и в маске зрения игрока.
        path = self.vision_cone_path(cx, cy, radius, facing, angle)

        painter.save()
        # Жёлтый сектор — взгляд мастера. Но в режиме «туман войны как у
        # игроков» мастер смотрит глазами стола, и у токенов игроков заливки
        # нет: иначе он видел бы не то, что игроки.
        show_fill = self.is_dm and not (
            self.dm_fog_enabled and token_kind.is_player(token))
        if show_fill:
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(255, 214, 90, 64)))
            painter.drawPath(path)
            pen = QPen(QColor(255, 205, 70, 200))
            # Луч по центру: видно точное направление взгляда, а не только сектор.
            ray = True
        else:
            pen = QPen(QColor(24, 24, 28, 80))
            ray = False
        pen.setWidthF(self.design(1.2))
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawPath(path)
        if ray:
            dx, dy = vision_rules.direction(facing)
            painter.drawLine(QPointF(cx, cy),
                             QPointF(cx + dx * radius, cy + dy * radius))
        painter.restore()

    def _start_death_anim(self, token_id: str):
        """Запустить короткую тряску токена в момент окончательной смерти."""
        self._death_anims[token_id] = {'start': time.monotonic()}
        self._ensure_anim_timer()

    # ------------------------------------------------------------------
    # Анимации
    # ------------------------------------------------------------------
    def clear_animations(self):
        """Сбросить все анимации (смена карты, загрузка полного состояния)."""
        self._motions.clear()
        self._door_anims.clear()
        self._combat_fx.clear()
        self._hp_anims.clear()
        self._death_anims.clear()
        self._area_overlay = None
        # Ночь новой карты начинается со своего состояния, без наплыва
        # темноты от прежней карты.
        self._night_fade = None
        # Слой дневного отсвета принадлежит прежней карте.
        self._day_glow_signature = None
        # Подсветка цели перетаскивания принадлежит прежней карте.
        self.item_drop_target_id = None
        self._anim_timer.stop()

    def _ensure_anim_timer(self):
        if not self._anim_timer.isActive():
            self._anim_timer.start()

    def _has_active_animations(self) -> bool:
        """Есть ли что перерисовывать (нужно тестам и таймеру)."""
        now = time.monotonic()
        # Всплеск крови живёт дольше боевого эффекта, но тоже недолго:
        # 60 кадров в секунду нужны только пока летят капли.
        splash = any(now - hit['start'] < BLOOD_SPLASH_S
                     for hit in self._blood_hits)
        overlay = (self._area_overlay is not None
                   and now < float(self._area_overlay.get('until') or 0.0))
        return bool(self._motions or self._combat_fx or self._hp_anims
                    or self._death_anims or splash or overlay
                    or self._roofs_animating() or self._turn_pending()
                    or self._doors_animating()
                    or self._night_anim_pending())

    def _on_anim_tick(self):
        now = time.monotonic()
        # Просроченные движения отдаём модели: с этого кадра token.x/y — истина.
        for token_id, motion in list(self._motions.items()):
            if now >= motion['start'] + motion['duration']:
                self._motions.pop(token_id, None)
        for token_id, anim in list(self._hp_anims.items()):
            if now >= anim['start'] + anim['duration']:
                self._hp_anims.pop(token_id, None)
        for token_id, anim in list(self._death_anims.items()):
            if now >= anim['start'] + DEATH_SHAKE_S:
                self._death_anims.pop(token_id, None)
        self._combat_fx = [fx for fx in self._combat_fx
                           if now < fx['start'] + fx['duration']]
        if (self._area_overlay is not None
                and now >= float(self._area_overlay.get('until') or 0.0)):
            self._area_overlay = None
        self._advance_roof_fades(now)
        self._step_token_turn(now)
        self.update()
        if not self._has_active_animations():
            self._anim_timer.stop()

    def _token_visual_pos(self, token) -> Tuple[float, float]:
        """Где токен нарисован сейчас (с учётом плавного перемещения)."""
        motion = self._motions.get(token.id)
        if not motion:
            return token.x, token.y
        progress = (time.monotonic() - motion['start']) / motion['duration']
        progress = max(0.0, min(1.0, progress))
        # ease-out cubic: быстрый старт и мягкое торможение, как в Foundry.
        eased = 1.0 - (1.0 - progress) ** 3
        (x1, y1), (x2, y2) = motion['from'], motion['to']
        return x1 + (x2 - x1) * eased, y1 + (y2 - y1) * eased

    def _token_combat_offset(self, token) -> Tuple[float, float]:
        """Смещение от боевого эффекта и предсмертной тряски токена."""
        if not self._combat_fx and not self._death_anims:
            return 0.0, 0.0
        now = time.monotonic()
        size = max(MIN_TOKEN_DRAW_PX, self.grid_cell_world * token.size)
        dx = dy = 0.0
        for fx in self._combat_fx:
            # Лечение, ауры и дуги не трясут цель: у них только свечение.
            if fx.get('kind') in ('heal', 'spell_aura', 'projectile',
                                  'explosion', 'dart', 'impact', 'beam',
                                  'arc'):
                continue
            progress = (now - fx['start']) / fx['duration']
            if progress < 0.0 or progress > 1.0:
                continue
            # Отмена атаки прокручивает эффект назад: выпад убирается к
            # атакующему, а тряска цели затухает в обратном порядке.
            if fx.get('reverse'):
                progress = 1.0 - progress
            if fx.get('attacker') == token.id:
                # Выпад в сторону цели до удара и возврат к моменту контакта.
                if progress <= ATTACK_IMPACT:
                    phase = progress / ATTACK_IMPACT
                    reach = math.sin(math.pi * phase) * ATTACK_LUNGE_RATIO * size
                    dx += fx.get('dir_x', 0.0) * reach
                    dy += fx.get('dir_y', 0.0) * reach
            if fx.get('target') == token.id and progress >= ATTACK_IMPACT:
                after = (progress - ATTACK_IMPACT) / (1.0 - ATTACK_IMPACT)
                if after <= 0.45:
                    power = (1.0 - after / 0.45) * ATTACK_SHAKE_RATIO * size
                    dx += math.sin(after * 95.0) * power
                    dy += math.cos(after * 71.0) * power * 0.7

        death = self._death_anims.get(token.id)
        if death:
            progress = (now - death['start']) / DEATH_SHAKE_S
            if 0.0 <= progress <= 1.0:
                # Затухающая дрожь: смерть «оседает», а не гуляет по клетке.
                power = ((1.0 - progress) ** 1.6) * DEATH_SHAKE_RATIO * size
                dx += math.sin(progress * 112.0) * power
                dy += math.cos(progress * 79.0) * power * 0.55
        return dx, dy

    def _token_hit_flash(self, token_id: str) -> Tuple[float, bool]:
        """Яркость вспышки на цели: (0..1, критическая ли)."""
        now = time.monotonic()
        for fx in self._combat_fx:
            if fx.get('target') != token_id or not fx.get('hit'):
                continue
            progress = (now - fx['start']) / fx['duration']
            if fx.get('reverse'):
                progress = 1.0 - progress
            after = (progress - ATTACK_IMPACT) / (1.0 - ATTACK_IMPACT)
            if 0.0 <= after <= 0.5:
                return 1.0 - after / 0.5, bool(fx.get('critical'))
        return 0.0, False

    def _hp_ratio(self, token) -> float:
        """Доля хитов для полосы (с плавным догоном после урона)."""
        anim = self._hp_anims.get(token.id)
        if anim:
            progress = (time.monotonic() - anim['start']) / anim['duration']
            progress = max(0.0, min(1.0, progress))
            eased = 1.0 - (1.0 - progress) ** 3
            return anim['from'] + (anim['to'] - anim['from']) * eased
        if token.hp_max and token.hp_max > 0:
            return max(0.0, min(1.0, (token.hp or 0) / token.hp_max))
        return 1.0 if token.hp and token.hp > 0 else 0.0

    def show_attack_effect(self, attacker_id, target_id, *, hit=False,
                           critical=False, miss=False, amount=None,
                           label="", reverse=False):
        """Боевой эффект как в Foundry: выпад, вспышка, тряска, число урона.

        Вызывается из main_window после ATTACK_RESULT. Работает только для
        токенов, которые сейчас видны на открытой карте: скрытая цель не должна
        выдавать себя вспышкой.
        """
        attacker = self.tokens.get(attacker_id) if attacker_id else None
        target = self.tokens.get(target_id) if target_id else None

        def visible(tok):
            return (tok is not None and tok.visible
                    and self.token_belongs_to_current_map(tok))

        if not visible(attacker) and not visible(target):
            return
        if target is not None and not visible(target):
            target = None
        if attacker is not None and not visible(attacker):
            attacker = None
        if target is None:
            return

        dx = target.x - (attacker.x if attacker else target.x)
        dy = target.y - (attacker.y if attacker else target.y)
        length = math.hypot(dx, dy)
        if length > 0.001:
            dir_x, dir_y = dx / length, dy / length
        else:
            dir_x, dir_y = 1.0, 0.0

        # Полоса хитов должна просесть в момент удара, а не в момент
        # прихода UPDATE_TOKEN (сервер шлёт его раньше ATTACK_RESULT).
        hp_anim = self._hp_anims.get(target.id)
        start = time.monotonic()
        if hp_anim and hit and not reverse:
            hp_anim['start'] = start + ATTACK_FX_S * ATTACK_IMPACT
            hp_anim['duration'] = HP_BAR_ANIM_S

        text = label or ""
        if critical and amount:
            text = f"КРИТ! −{amount}"
        elif hit and amount:
            text = f"−{amount}"
        elif miss:
            text = "промах"

        # Кровь — только на живой удар: промах не должен брызгать, а
        # обратная прокрутка (Ctrl+Z) не должна добавлять новую кровь.
        # Выключенные «Эффекты в бою» убирают кровь, но не сам удар.
        if hit and not reverse and self.combat_effects_enabled:
            self._spawn_blood(target, critical=bool(critical),
                              direction=(dir_x, dir_y))

        self._combat_fx.append({
            'attacker': attacker.id if attacker else None,
            'target': target.id,
            'start': start,
            'duration': ATTACK_FX_S,
            'hit': bool(hit),
            'critical': bool(critical),
            'miss': bool(miss),
            'amount': amount,
            'text': text,
            'dir_x': dir_x,
            'dir_y': dir_y,
            'from': (attacker.x, attacker.y) if attacker else (target.x, target.y),
            'to': (target.x, target.y),
            'reverse': bool(reverse),
        })
        self._ensure_anim_timer()
        self.update()

    def show_heal_effect(self, target_id, amount=None, *, style="item",
                         label="", reverse=False):
        """Зелёная волна лечения: число, искры и мягкое свечение.

        ``style`` различает зелье и заклинание: у зелья частицы-пузырьки,
        у заклинания — звёздочки и руническое кольцо. Оба варианта зелёные,
        чтобы за столом лечение не путали с уроном.
        """
        target = self.tokens.get(target_id) if target_id else None
        if target is None or not target.visible:
            return
        if not self.token_belongs_to_current_map(target):
            return
        try:
            amount = int(amount) if amount is not None else 0
        except (TypeError, ValueError):
            amount = 0
        text = label or (f"+{amount}" if amount else "+")
        now = time.monotonic()
        particles = []
        for _index in range(HEAL_PARTICLE_COUNT):
            particles.append({
                'angle': random.uniform(0.0, math.tau),
                'distance': random.uniform(0.25, 0.9),
                'rise': random.uniform(20.0, 54.0),
                'size': random.uniform(1.5, 3.8),
                'delay': random.uniform(0.0, 0.34),
                'swirl': random.uniform(-0.8, 0.8),
            })
        self._combat_fx.append({
            'kind': 'heal',
            'target': target.id,
            'start': now,
            'duration': HEAL_FX_S,
            'to': (target.x, target.y),
            'from': (target.x, target.y),
            'text': text,
            'amount': amount,
            # Наложение рук — золотое свечение, а не зелёное зелье: за
            # столом видно, что это классовая особенность паладина.
            'style': (style if style in ('spell', 'lay_on_hands')
                      else 'item'),
            'base_radius': max(18.0, min(70.0,
                                        self.grid_cell_world
                                        * max(0.1, float(target.size or 1.0))
                                        * self.scale * 0.55)),
            'particles': particles,
            'reverse': bool(reverse),
        })
        self._ensure_anim_timer()
        self.update()

    def show_buff_effect(self, target_id, label):
        """Голубое кольцо с подписью: на токен наложен эффект зелья.

        Лечение остаётся зелёным и с цифрой; эффект сопротивления или
        невидимости — холодный синий, поэтому за столом их не путают.
        """
        self.show_heal_effect(target_id, 0, style="buff", label=str(label or ""))

    @staticmethod
    def _damage_color(damage_type: str) -> QColor:
        """Цвет цифры урона по типу: огонь — оранжевый, холод — голубой."""
        palette = {
            'fire': (255, 132, 58), 'cold': (120, 198, 255),
            'lightning': (196, 160, 255), 'acid': (150, 230, 90),
            'poison': (130, 210, 110), 'necrotic': (170, 120, 210),
            'radiant': (255, 226, 120), 'psychic': (245, 130, 210),
            'thunder': (130, 220, 240), 'force': (130, 170, 255),
        }
        rgb = palette.get(str(damage_type or '').casefold(), (255, 110, 96))
        return QColor(*rgb)

    def show_damage_effect(self, target_id, amount, *, damage_type="",
                           saved=False, label="", delay=0.0):
        """Красная цифра урона: число, вспышка и искры в цвете типа урона.

        ``saved`` рисует пометку «½» — цель преуспела в спасброске и
        получила половину. Это не атака: трассера нет, число поднимается
        прямо над токеном.
        """
        target = self.tokens.get(target_id) if target_id else None
        if target is None or not target.visible:
            return
        if not self.token_belongs_to_current_map(target):
            return
        try:
            amount = int(amount) if amount is not None else 0
        except (TypeError, ValueError):
            amount = 0
        if amount <= 0:
            return
        text = label or (f"−{amount} ½" if saved else f"−{amount}")
        self._combat_fx.append({
            'kind': 'damage', 'target': target.id,
            'start': time.monotonic() + max(0.0, float(delay or 0.0)),
            'duration': 1.7,
            'to': (target.x, target.y),
            'from': (target.x, target.y),
            'text': text, 'amount': amount,
            'damage_type': damage_type, 'saved': bool(saved),
        })
        self._ensure_anim_timer()
        self.update()

    def show_area_result(self, data: dict):
        """Показать область заклинания и урон её целей.

        Сервер уже всё посчитал: клетки, спасброски и новые хиты. Клиент
        только рисует след области и цифры — без повторного броска.
        """
        if not isinstance(data, dict):
            return
        cells = data.get('cells') or []
        map_id = (self.current_map.id if self.current_map else None)
        # Огненный шар сначала летит, потом взрывается. След области и
        # цифры урона включаются в момент взрыва, иначе шар «телепортирует»
        # урон раньше, чем долетит — самый заметный провал отклика.
        fx = str(data.get('fx') or data.get('spell_key') or '')
        delay = 0.0
        if fx == 'fireball':
            caster = self.tokens.get(str(data.get('caster_id') or ''))
            center = data.get('center')
            if (caster is not None and isinstance(center, (list, tuple))
                    and len(center) == 2
                    and self.token_belongs_to_current_map(caster)):
                self._spawn_spell_projectile(
                    (float(caster.x), float(caster.y)),
                    (float(center[0]), float(center[1])),
                    kind='fireball', impact_delay=0.55)
                # Только если шар действительно летит: скрытый колдун не
                # получает задержку урона без взрыва.
                delay = 0.62
        start = time.monotonic() + delay
        if cells and map_id:
            self._area_overlay = {
                'map_id': map_id, 'cells': [list(c) for c in cells],
                'start': start, 'until': start + 4.5,
                'damage_type': str(data.get('damage_type') or ''),
                'shape': str(data.get('shape') or 'circle'),
            }
        for target in data.get('targets') or []:
            if not isinstance(target, dict):
                continue
            try:
                delta = int(target.get('delta') or 0)
            except (TypeError, ValueError):
                delta = 0
            if delta > 0:
                self.show_heal_effect(
                    target.get('token_id'), delta,
                    style='spell')
                continue
            amount = abs(delta)
            if amount:
                self.show_damage_effect(
                    target.get('token_id'), amount,
                    damage_type=str(data.get('damage_type') or ''),
                    saved=bool(target.get('save_success')),
                    delay=delay)
        self._ensure_anim_timer()
        self.update()

    def draw_area_result(self, painter: QPainter):
        """След области: затухающие клетки в цвете урона."""
        overlay = self._area_overlay
        if not overlay or self.current_map is None:
            return
        if overlay.get('map_id') != self.current_map.id:
            return
        now = time.monotonic()
        started = float(overlay.get('start') or now)
        until = float(overlay.get('until') or now)
        if now < started or now >= until:
            return
        life = max(0.25, until - started)
        fade = max(0.0, min(1.0, (until - now) / life))
        color = self._damage_color(overlay.get('damage_type'))
        grid = self.grid
        m = self.current_map
        if not grid or not grid.cols or not grid.rows:
            return
        cw = m.width / grid.cols
        ch = m.height / grid.rows
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(color.red(), color.green(),
                                       color.blue(), int(72 * fade))))
        for c, r in overlay.get('cells') or []:
            x1, y1 = self.world_to_screen(m.pos_x + c * cw,
                                          m.pos_y + r * ch)
            x2, y2 = self.world_to_screen(m.pos_x + (c + 1) * cw,
                                          m.pos_y + (r + 1) * ch)
            painter.drawRect(QRectF(x1, y1, x2 - x1, y2 - y1))
        pen = QPen(QColor(color.red(), color.green(), color.blue(),
                          int(180 * fade)))
        pen.setWidthF(2.0)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        for c, r in overlay.get('cells') or []:
            x1, y1 = self.world_to_screen(m.pos_x + c * cw,
                                          m.pos_y + r * ch)
            x2, y2 = self.world_to_screen(m.pos_x + (c + 1) * cw,
                                          m.pos_y + (r + 1) * ch)
            painter.drawRect(QRectF(x1, y1, x2 - x1, y2 - y1))

    # ------------------------------------------------------------------
    # Отклик заклинаний
    #
    # Фаербол летит снарядом с дымным следом и взрывается, Волшебная
    # стрела — тремя росчерками с отдельным попаданием каждого, Щит —
    # бирюзовым куполом, Благословение — золотой аурой, лечащие
    # заклинания — руническим кругом. Всё живёт в `_combat_fx`, поэтому
    # затухает и перерисовывается тем же таймером, что кровь и удар.
    # ------------------------------------------------------------------
    def _spell_radius(self, token) -> float:
        """Радиус эффекта вокруг токена в экранных пикселях."""
        try:
            size = max(0.4, float(getattr(token, 'size', 1.0) or 1.0))
        except (TypeError, ValueError):
            size = 1.0
        cell = max(12.0, float(self.grid_cell_world or 50.0))
        return max(18.0, cell * size * max(0.2, float(self.scale)) * 0.62)

    def _spawn_spell_projectile(self, start, end, *, kind: str,
                                impact_delay: float = 0.55):
        """Снаряд заклинания + взрыв в точке попадания."""
        now = time.monotonic()
        self._combat_fx.append({
            'kind': 'projectile', 'fx': kind, 'start': now,
            'duration': max(0.18, impact_delay - 0.04),
            'from': (float(start[0]), float(start[1])),
            'to': (float(end[0]), float(end[1])),
        })
        embers = []
        for index in range(18):
            embers.append({
                'angle': random.uniform(0.0, math.tau),
                'speed': random.uniform(0.45, 1.0),
                'size': random.uniform(1.6, 3.6),
                'delay': random.uniform(0.0, 0.16),
            })
        self._combat_fx.append({
            'kind': 'explosion', 'fx': kind,
            'start': now + max(0.05, impact_delay - 0.04),
            'duration': 1.45,
            'from': (float(end[0]), float(end[1])),
            'to': (float(end[0]), float(end[1])),
            'embers': embers,
        })

    def show_spell_result(self, data: dict):
        """Отклик серверного заклинания: снаряды, лечение, блокада Щитом."""
        if not isinstance(data, dict):
            return
        fx = str(data.get('fx') or data.get('spell_key') or '')
        target_row = data.get('target') or {}
        target_id = str(target_row.get('token_id')
                        or data.get('target_id') or '')
        target = self.tokens.get(target_id)
        caster = self.tokens.get(str(data.get('caster_id') or ''))
        visible = (target is not None and target.visible
                   and self.token_belongs_to_current_map(target))
        if not visible:
            return
        if data.get('blocked'):
            self.show_effect_fx(target_id, 'shield')
            return
        if fx == 'magic_missile':
            darts = [row for row in (data.get('darts') or [])
                     if isinstance(row, dict)]
            caster_visible = (caster is not None and caster.visible
                              and self.token_belongs_to_current_map(caster))
            if caster_visible and darts:
                start = time.monotonic()
                for index, dart in enumerate(darts):
                    offset = index * 0.13
                    self._combat_fx.append({
                        'kind': 'dart', 'fx': 'magic_missile',
                        'start': start + offset, 'duration': 0.62,
                        'from': (float(caster.x), float(caster.y)),
                        'to': (float(target.x), float(target.y)),
                        'index': index,
                    })
                    self._combat_fx.append({
                        'kind': 'impact', 'fx': 'force',
                        'start': start + offset + 0.44, 'duration': 0.55,
                        'to': (float(target.x), float(target.y)),
                        'from': (float(target.x), float(target.y)),
                    })
                    try:
                        amount = int(dart.get('total') or 0)
                    except (TypeError, ValueError):
                        amount = 0
                    if amount:
                        self.show_damage_effect(
                            target_id, amount, damage_type='force',
                            delay=offset + 0.46)
            else:
                self.show_effect_fx(target_id, 'magic_missile')
            self._ensure_anim_timer()
            self.update()
            return
        if data.get('kind') == 'save_target':
            # Заговор со спасброском: луча нет — снаряд не летит, цель сама
            # проходит спасбросок. Поэтому рисуем вспышку школы на цели и
            # цифру урона: у преуспевшей цели с половиной — с пометкой «½».
            self.show_effect_fx(target_id, fx or 'spell_radiant')
            chain = data.get('chain') if isinstance(data.get('chain'), dict) else {}
            if chain:
                # Цепная молния: по правилу разряды отходят от ПЕРВОЙ цели, а
                # не цепочкой «цель за целью». Поэтому дугу рисуем от первой
                # цели к каждому разряду, а к самой первой — от колдуна, иначе
                # в цепочке не видно, откуда пришёл разряд.
                damage_type = str(data.get('damage_type') or 'lightning')
                if chain.get('primary'):
                    self.show_spell_arc(data.get('caster_id'), target_id,
                                        damage_type=damage_type)
                else:
                    self.show_spell_arc(
                        chain.get('primary_id') or chain.get('from_id'),
                        target_id, damage_type=damage_type,
                        delay=0.06 * max(0, int(chain.get('index') or 1) - 1))
            amount = int(target_row.get('amount') or 0)
            if amount:
                self.show_damage_effect(
                    target_id, amount,
                    damage_type=str(data.get('damage_type') or ''),
                    saved=bool((data.get('save') or {}).get('half')),
                    delay=0.35)
            self._ensure_anim_timer()
            self.update()
            return
        if data.get('kind') == 'heal' or fx in ('healing_word', 'cure_wounds'):
            self.show_effect_fx(target_id, fx or 'healing_word')
            self._ensure_anim_timer()
            self.update()

    def show_spell_arc(self, from_id, to_id, *, damage_type="lightning",
                       delay=0.0, duration=ARC_FX_S, seed=None) -> bool:
        """Дуга молнии между двумя токенами — разряд Цепной молнии.

        Разряды отходят от ПЕРВОЙ цели (SRD 5.1), поэтому дуга рисуется от
        неё к каждой цели-разряду, а не «от цели к следующей»: иначе за
        столом молния читалась бы как цепочка попаданий, а не как разряды
        из одной точки. Позиции берём по id и пересчитываем на каждом кадре,
        поэтому дуга не отстаёт при панораме, зуме и движении токена.

        Возвращает False, если дугу рисовать нельзя: один из токенов скрыт
        от этого клиента или лежит на другой карте. Нарисовать дугу «из
        ниоткуда» — выдать скрытого противника, так что лучше промолчать.
        """
        start_token = self.tokens.get(str(from_id or ""))
        end_token = self.tokens.get(str(to_id or ""))
        if start_token is None or end_token is None:
            return False
        if start_token.id == end_token.id:
            return False
        for token in (start_token, end_token):
            if not token.visible:
                return False
            if not self.token_belongs_to_current_map(token):
                return False
        rng = random.Random(seed if seed is not None
                            else random.randrange(1 << 30))
        # Форма запоминается один раз: иначе дуга дёргалась бы как шум на
        # каждом кадре. Изломы затухают к концам — дуга входит в токены.
        path = []
        for index in range(1, ARC_SEGMENTS):
            frac = index / float(ARC_SEGMENTS)
            taper = math.sin(math.pi * frac) ** 0.7
            path.append((frac, rng.uniform(-ARC_DRIFT_RATIO, ARC_DRIFT_RATIO)
                         * taper))
        forks = []
        for _index in range(3):
            forks.append({'at': rng.uniform(0.22, 0.82),
                          'angle': rng.uniform(-1.1, 1.1),
                          'side': rng.choice((-1, 1)),
                          'length': rng.uniform(0.10, 0.20)})
        self._combat_fx.append({
            'kind': 'arc',
            'start': time.monotonic() + max(0.0, float(delay)),
            'duration': max(0.15, float(duration)),
            'from_id': start_token.id,
            'to_id': end_token.id,
            'from': (float(start_token.x), float(start_token.y)),
            'to': (float(end_token.x), float(end_token.y)),
            'damage_type': str(damage_type or ''),
            'path': path,
            'forks': forks,
        })
        self._ensure_anim_timer()
        self.update()
        return True

    def show_spell_attack(self, data: dict):
        """Атака заклинанием: луч от колдуна к цели и вспышка попадания."""
        if not isinstance(data, dict):
            return
        fx = str(data.get('fx') or '')
        if not fx:
            return
        attacker = self.tokens.get(str(data.get('attacker_id') or ''))
        target = self.tokens.get(str(data.get('target_id') or ''))
        if (attacker is None or target is None or not target.visible
                or not attacker.visible
                or not self.token_belongs_to_current_map(attacker)
                or not self.token_belongs_to_current_map(target)):
            return
        now = time.monotonic()
        hit = bool((data.get('attack') or {}).get('hit'))
        self._combat_fx.append({
            'kind': 'beam', 'fx': fx, 'start': now, 'duration': 0.8,
            'from': (float(attacker.x), float(attacker.y)),
            'to': (float(target.x), float(target.y)),
        })
        if hit:
            self._combat_fx.append({
                'kind': 'impact', 'fx': 'radiant',
                'start': now + 0.34, 'duration': 0.6,
                'from': (float(target.x), float(target.y)),
                'to': (float(target.x), float(target.y)),
            })
        self._ensure_anim_timer()
        self.update()

    def show_effect_fx(self, token_id: str, fx: str):
        """Аура заклинания вокруг токена: Щит, Благословение, слово лечения."""
        token = self.tokens.get(token_id) if token_id else None
        if token is None or not token.visible:
            return
        if not self.token_belongs_to_current_map(token):
            return
        durations = {
            'shield': 2.4, 'bless': 2.6,
            'healing_word': 1.8, 'cure_wounds': 1.6,
            'magic_missile': 1.2,
            # Ускорение и Доспехи мага — длительные баффы: аура живёт
            # дольше мгновенного отклика, чтобы её успели заметить все.
            'haste': 2.9, 'mage_armor': 2.7,
            # Метка охотника живёт долго — её видно, пока не спадёт
            # концентрация; всполох кары наоборот короткий и резкий.
            'hunters_mark': 3.0, 'divine_smite': 1.7,
            # Ярость — бафф на минуту, но отклик короткий: это вспышка
            # включения, а длительность видна чипом эффекта.
            'rage': 2.8,
        }
        self._combat_fx.append({
            'kind': 'spell_aura', 'fx': str(fx or 'shield'),
            'target': token.id, 'start': time.monotonic(),
            'duration': durations.get(str(fx), 2.0),
            'from': (token.x, token.y), 'to': (token.x, token.y),
            'radius': self._spell_radius(token),
        })
        self._ensure_anim_timer()
        self.update()

    def _draw_spell_projectile(self, painter: QPainter, fx: dict,
                               progress: float):
        """Летящий снаряд: огненный шар или магический росчерк."""
        (sx, sy), (ex, ey) = fx['from'], fx['to']
        dx, dy = ex - sx, ey - sy
        length = math.hypot(dx, dy)
        if length < 0.01:
            return
        kind = str(fx.get('fx') or 'fireball')
        t = max(0.0, min(1.0, progress))
        eased = t * t * (3.0 - 2.0 * t)
        # Дуга: шар летит по параболе, росчерк — почти прямо.
        perp = (-dy / length, dx / length)
        arc = min(140.0, length * 0.18) if kind == 'fireball' else 10.0
        cx = (sx + ex) / 2.0 + perp[0] * arc
        cy = (sy + ey) / 2.0 + perp[1] * arc
        px = (1 - eased) ** 2 * sx + 2 * (1 - eased) * eased * cx + eased ** 2 * ex
        py = (1 - eased) ** 2 * sy + 2 * (1 - eased) * eased * cy + eased ** 2 * ey
        tx, ty = self.world_to_screen(px, py)
        if kind == 'fireball':
            core = QColor(255, 250, 214)
            hot = QColor(255, 168, 58)
            outer = QColor(236, 84, 24)
            radius = self.overlay_px(11.0)
            trail = 9
        else:
            core = QColor(236, 247, 255)
            hot = QColor(132, 198, 255)
            outer = QColor(78, 120, 236)
            radius = self.overlay_px(5.0)
            trail = 12
        # След из затухающих сгустков — читается и на светлой, и на тёмной карте.
        for step in range(trail, 0, -1):
            back = max(0.0, eased - step * 0.028)
            bx = (1 - back) ** 2 * sx + 2 * (1 - back) * back * cx + back ** 2 * ex
            by = (1 - back) ** 2 * sy + 2 * (1 - back) * back * cy + back ** 2 * ey
            bx_s, by_s = self.world_to_screen(bx, by)
            alpha = int((1.0 - step / (trail + 1.0)) * (120 if kind == 'fireball' else 150))
            colour = QColor(outer if kind == 'fireball' else hot)
            colour.setAlpha(max(0, alpha))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(colour))
            size = radius * (1.0 - step / (trail + 2.5))
            painter.drawEllipse(QPointF(bx_s, by_s), size, size)
        glow = QRadialGradient(QPointF(tx, ty), radius * 2.8)
        glow.setColorAt(0.0, QColor(255, 255, 255, 235))
        mid = QColor(hot)
        mid.setAlpha(190)
        glow.setColorAt(0.42, mid)
        edge = QColor(outer)
        edge.setAlpha(0)
        glow.setColorAt(1.0, edge)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(tx, ty), radius * 2.8, radius * 2.8)
        painter.setBrush(QBrush(QColor(core)))
        painter.drawEllipse(QPointF(tx, ty), radius * 0.55, radius * 0.55)

    def _draw_spell_explosion(self, painter: QPainter, fx: dict,
                              progress: float):
        """Взрыв огненного шара: ядро, ударная волна, искры и дым."""
        cx, cy = self.world_to_screen(*fx['to'])
        t = max(0.0, min(1.0, progress))
        fade = (1.0 - t) ** 1.25
        radius = self.overlay_px(96.0) * (0.35 + 0.9 * (1 - (1 - t) ** 3))
        glow = QRadialGradient(QPointF(cx, cy), radius)
        glow.setColorAt(0.0, QColor(255, 252, 230, int(245 * fade)))
        glow.setColorAt(0.28, QColor(255, 206, 92, int(220 * fade)))
        glow.setColorAt(0.62, QColor(248, 118, 28, int(170 * fade)))
        glow.setColorAt(1.0, QColor(140, 28, 8, 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(cx, cy), radius, radius)
        # Ударная волна: тонкое кольцо обгоняет ядро и растворяется.
        if t <= 0.75:
            ring_t = t / 0.75
            ring = QColor(255, 214, 140, int(190 * (1 - ring_t)))
            pen = QPen(ring)
            pen.setWidthF(max(1.0, 3.2 * (1 - ring_t)))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            ring_r = radius * (0.7 + 0.8 * ring_t)
            painter.drawEllipse(QPointF(cx, cy), ring_r, ring_r)
        # Искры: детерминированные углы лежат в fx, поэтому кадры не дрожат.
        for ember in fx.get('embers') or []:
            delay = float(ember.get('delay') or 0.0)
            local = (t - delay) / max(0.05, 1.0 - delay)
            if local <= 0.0 or local >= 1.0:
                continue
            distance = radius * 1.35 * float(ember.get('speed') or 0.7) * local
            px = cx + math.cos(ember['angle']) * distance
            py = cy + math.sin(ember['angle']) * distance * 0.72 - 18.0 * local
            alpha = int(235 * (1.0 - local))
            size = max(1.0, float(ember.get('size') or 2.0) * (1.0 - 0.55 * local))
            colour = QColor(255, int(120 + 90 * (1 - local)), 60, alpha)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(colour))
            painter.drawEllipse(QPointF(px, py), size, size)
        # Дым поднимается после вспышки, а не вместе с ней.
        if t > 0.25:
            smoke_t = (t - 0.25) / 0.75
            for index in range(5):
                angle = index * 1.256 + 0.4
                sx = cx + math.cos(angle) * radius * 0.5
                sy = cy + math.sin(angle) * radius * 0.32 - 34.0 * smoke_t
                sr = radius * (0.22 + 0.12 * index) * (0.6 + smoke_t)
                smoke = QColor(54, 42, 38, int(58 * (1 - smoke_t)))
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(smoke))
                painter.drawEllipse(QPointF(sx, sy), sr, sr * 0.8)

    def _draw_dart(self, painter: QPainter, fx: dict, progress: float):
        """Росчерк Волшебной стрелы: световой дротик с хвостом."""
        (sx, sy), (ex, ey) = fx['from'], fx['to']
        dx, dy = ex - sx, ey - sy
        length = math.hypot(dx, dy)
        if length < 0.01:
            return
        t = max(0.0, min(1.0, progress))
        eased = t * t * (3.0 - 2.0 * t)
        perp = (-dy / length, dx / length)
        arc = min(40.0, length * 0.08) * (1 if int(fx.get('index') or 0) % 2 else -1)
        cx = (sx + ex) / 2.0 + perp[0] * arc
        cy = (sy + ey) / 2.0 + perp[1] * arc
        px = (1 - eased) ** 2 * sx + 2 * (1 - eased) * eased * cx + eased ** 2 * ex
        py = (1 - eased) ** 2 * sy + 2 * (1 - eased) * eased * cy + eased ** 2 * ey
        tx, ty = self.world_to_screen(px, py)
        prev_t = max(0.0, eased - 0.08)
        qx = (1 - prev_t) ** 2 * sx + 2 * (1 - prev_t) * prev_t * cx + prev_t ** 2 * ex
        qy = (1 - prev_t) ** 2 * sy + 2 * (1 - prev_t) * prev_t * cy + prev_t ** 2 * ey
        qx, qy = self.world_to_screen(qx, qy)
        pen = QPen(QColor(120, 190, 255, 190))
        pen.setWidthF(max(1.5, 3.0 * self.scale))
        pen.setCapStyle(Qt.RoundCap)
        painter.setPen(pen)
        painter.drawLine(QPointF(qx, qy), QPointF(tx, ty))
        glow = QRadialGradient(QPointF(tx, ty), self.overlay_px(16.0))
        glow.setColorAt(0.0, QColor(255, 255, 255, 240))
        glow.setColorAt(0.45, QColor(150, 205, 255, 180))
        glow.setColorAt(1.0, QColor(70, 120, 235, 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(tx, ty), 9.0, 9.0)

    def _draw_spell_aura(self, painter: QPainter, fx: dict, progress: float):
        """Аура на токене: купол Щита, золото Благословения, руны лечения."""
        cx, cy = self.world_to_screen(*fx['to'])
        radius = float(fx.get('radius') or 24.0)
        kind = str(fx.get('fx') or 'shield')
        t = max(0.0, min(1.0, progress))
        appear = min(1.0, t / 0.18)
        fade = 1.0 - max(0.0, (t - 0.72) / 0.28)
        alpha = max(0.0, min(1.0, appear * fade))
        if kind == 'shield':
            core = QColor(190, 244, 255)
            edge = QColor(74, 160, 236)
            for scale, strength in ((1.02, 0.30), (0.80, 0.16)):
                glow = QRadialGradient(QPointF(cx, cy), radius * scale)
                start = QColor(core)
                start.setAlpha(int(120 * alpha * strength / 0.30))
                mid = QColor(edge)
                mid.setAlpha(int(60 * alpha))
                glow.setColorAt(0.0, start)
                glow.setColorAt(0.7, mid)
                glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(glow))
                painter.drawEllipse(QPointF(cx, cy), radius * scale, radius * scale)
            # Купол: шестиугольник с медленно плывущими гранями.
            spin = t * 0.9
            for ring_index, ring_scale in ((0, 1.0), (1, 0.72)):
                points = []
                for corner in range(6):
                    angle = spin * (1 if ring_index == 0 else -0.7) \
                        + corner * math.pi / 3.0
                    points.append(QPointF(cx + math.cos(angle) * radius * ring_scale,
                                          cy + math.sin(angle) * radius * ring_scale))
                pen = QPen(QColor(core.red(), core.green(), core.blue(),
                                  int(190 * alpha * (1.0 - ring_index * 0.35))))
                pen.setWidthF(2.2 if ring_index == 0 else 1.1)
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawPolygon(QPolygonF(points))
            # Блики по граням — купол выглядит стеклянным.
            pen = QPen(QColor(255, 255, 255, int(120 * alpha)))
            pen.setWidthF(1.4)
            painter.setPen(pen)
            painter.drawArc(QRectF(cx - radius * 0.9, cy - radius * 0.9,
                                   radius * 1.8, radius * 1.8),
                            int(40 * 16 + t * 90 * 16), int(70 * 16))
            painter.drawArc(QRectF(cx - radius * 0.7, cy - radius * 0.7,
                                   radius * 1.4, radius * 1.4),
                            int(210 * 16 - t * 70 * 16), int(45 * 16))
        elif kind == 'rage':
            # Ярость: жар от земли, пульсирующие кольца и искры вверх.
            core = QColor(255, 154, 92)
            edge = QColor(196, 42, 24)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.35)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(150 * alpha)))
            glow.setColorAt(0.55, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(90 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.35, radius * 1.35)
            for index in range(2):
                wave = (t * 1.7 + index * 0.5) % 1.0
                ring = radius * (0.55 + 0.75 * wave)
                pen = QPen(QColor(core.red(), core.green(), core.blue(),
                                  int(200 * alpha * (1.0 - wave))))
                pen.setWidthF(2.6 if index == 0 else 1.6)
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawEllipse(QPointF(cx, cy), ring, ring)
            painter.setPen(Qt.NoPen)
            for spark in range(7):
                phase = (t * 2.2 + spark / 7.0) % 1.0
                angle = spark * 1.1 + t * 2.4
                sx = cx + math.cos(angle) * radius * 0.55
                sy = cy + radius * 0.75 - phase * radius * 1.5
                size = 2.4 * (1.0 - phase * 0.6)
                painter.setBrush(QColor(255, 214, 140,
                                        int(210 * alpha * (1.0 - phase))))
                painter.drawEllipse(QPointF(sx, sy), size, size)
        elif kind == 'bless':
            core = QColor(255, 236, 168)
            edge = QColor(232, 178, 64)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.25)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(150 * alpha)))
            glow.setColorAt(0.62, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(72 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.25, radius * 1.25)
            spin = -t * 1.1
            pen = QPen(QColor(core.red(), core.green(), core.blue(),
                              int(210 * alpha)))
            pen.setWidthF(2.0)
            pen.setStyle(Qt.DashLine)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPointF(cx, cy), radius, radius * 0.92)
            pen.setStyle(Qt.SolidLine)
            painter.setPen(pen)
            for corner in range(8):
                angle = spin + corner * math.pi / 4.0
                x1 = cx + math.cos(angle) * radius * 1.02
                y1 = cy + math.sin(angle) * radius * 0.94
                x2 = cx + math.cos(angle) * radius * 1.16
                y2 = cy + math.sin(angle) * radius * 1.06
                painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))
            # Мелкие звёзды поднимаются вверх — «благословение».
            for index in range(9):
                seed = (index * 0.618033) % 1.0
                up = (t * 1.15 + seed) % 1.0
                angle = index * 2.4 + t * 0.6
                px = cx + math.cos(angle) * radius * (0.25 + seed * 0.7)
                py = cy + radius * 0.55 - up * radius * 1.6
                star_alpha = int(200 * alpha * math.sin(math.pi * up))
                if star_alpha <= 0:
                    continue
                star = QColor(255, 248, 210, star_alpha)
                painter.setPen(QPen(star, 1.2))
                size = max(1.5, radius * 0.06)
                painter.drawLine(QPointF(px - size, py), QPointF(px + size, py))
                painter.drawLine(QPointF(px, py - size), QPointF(px, py + size))
        elif kind == 'haste':
            # Ускорение: лиловый вихрь со стрелками движения и кольцом
            # делений — «время пошло быстрее». Не путается с золотом
            # Благословения и льдом Щита.
            core = QColor(232, 216, 255)
            edge = QColor(132, 96, 226)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.15)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(120 * alpha)))
            glow.setColorAt(0.62, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(64 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.15, radius * 1.15)
            # Два кольца навстречу друг другу — ускоренное вращение.
            for ring, (scale, direction, width) in enumerate(
                    ((1.0, 1.0, 2.0), (0.74, -1.7, 1.2))):
                pen = QPen(QColor(core.red(), core.green(), core.blue(),
                                  int((200 - ring * 60) * alpha)))
                pen.setWidthF(width)
                pen.setStyle(Qt.DashLine)
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawEllipse(QPointF(cx, cy),
                                    radius * scale, radius * scale * 0.94)
            # Деления по кругу: 12 рисок бегут вместе с вихрем.
            pen = QPen(QColor(core.red(), core.green(), core.blue(),
                              int(190 * alpha)))
            pen.setWidthF(1.4)
            painter.setPen(pen)
            spin = t * 5.2
            for tick in range(12):
                angle = spin + tick * math.pi / 6.0
                r1 = radius * (1.02 if tick % 3 else 0.94)
                r2 = radius * (1.16 if tick % 3 else 1.22)
                painter.drawLine(
                    QPointF(cx + math.cos(angle) * r1,
                            cy + math.sin(angle) * r1 * 0.94),
                    QPointF(cx + math.cos(angle) * r2,
                            cy + math.sin(angle) * r2 * 0.94))
            # Следы движения вокруг токена: короткие черты, летящие по кругу.
            for index in range(14):
                angle = index * 0.449 + t * 6.4
                drift = (t * 1.6 + index * 0.13) % 1.0
                r = radius * (0.50 + 0.95 * drift)
                length = radius * (0.42 * (1.0 - drift) + 0.08)
                streak_alpha = int(215 * alpha * math.sin(math.pi * drift))
                if streak_alpha <= 0:
                    continue
                colour = QColor(240, 232, 255, streak_alpha)
                pen = QPen(colour, 1.9)
                pen.setCapStyle(Qt.RoundCap)
                painter.setPen(pen)
                x1, y1 = cx + math.cos(angle) * r, cy + math.sin(angle) * r * 0.94
                x2 = cx + math.cos(angle) * (r + length)
                y2 = cy + math.sin(angle) * (r + length) * 0.94
                painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))
        elif kind == 'mage_armor':
            # Доспехи мага: бронзовые пластины, собравшиеся из искр.
            core = QColor(255, 236, 196)
            edge = QColor(186, 132, 58)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.1)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(96 * alpha)))
            glow.setColorAt(0.55, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(62 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.1, radius * 1.1)
            # Восемь пластин: каждая раскрывается со своей задержкой.
            for plate in range(8):
                delay = plate * 0.045
                local = max(0.0, min(1.0, (t - delay) / 0.45))
                if local <= 0:
                    continue
                angle = plate * math.pi / 4.0 - math.pi / 8.0 + t * 0.12
                span = math.pi / 4.0 * 0.72
                grow = radius * (0.86 + 0.16 * local)
                inner = grow * (0.80 + 0.10 * (1.0 - local))
                plate_alpha = int(210 * alpha * local)
                # QPainter.drawArc ждёт углы в шестнадцатых долях градуса,
                # а не радианы: без перевода пластины вырождались в точку.
                start = math.degrees(-angle - span / 2.0) * 16.0
                sweep = math.degrees(span) * 16.0
                pen = QPen(QColor(core.red(), core.green(), core.blue(),
                                  plate_alpha))
                pen.setWidthF(1.2 + 1.4 * local)
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawArc(QRectF(cx - inner, cy - inner * 0.94,
                                       inner * 2, inner * 2),
                                int(start), int(sweep))
                pen.setColor(QColor(edge.red(), edge.green(), edge.blue(),
                                    int(180 * alpha * local)))
                pen.setWidthF(2.6)
                painter.setPen(pen)
                painter.drawArc(QRectF(cx - grow, cy - grow * 0.94,
                                       grow * 2, grow * 2),
                                int(start), int(sweep))
                # Замок на стыке пластин: короткая поперечная риска, по
                # ней видно, что сегменты смыкаются, а не просто лежат.
                joint = angle + span / 2.0
                if local > 0.5:
                    pen.setColor(QColor(core.red(), core.green(), core.blue(),
                                        int(190 * alpha * local)))
                    pen.setWidthF(1.6)
                    painter.setPen(pen)
                    painter.drawLine(
                        QPointF(cx + math.cos(joint) * (grow - 3.0),
                                cy + math.sin(joint) * (grow - 3.0) * 0.94),
                        QPointF(cx + math.cos(joint) * (grow + 3.0),
                                cy + math.sin(joint) * (grow + 3.0) * 0.94))
            # Замковый камень на груди: короткая вспышка в начале каста.
            flash = math.sin(math.pi * min(1.0, t / 0.55)) if t < 0.55 else 0.0
            if flash > 0:
                gem = QColor(255, 248, 226, int(200 * alpha * flash))
                painter.setPen(QPen(gem, 1.6))
                size = max(2.0, radius * 0.16)
                painter.drawLine(QPointF(cx - size, cy),
                                 QPointF(cx + size, cy))
                painter.drawLine(QPointF(cx, cy - size),
                                 QPointF(cx, cy + size))
        elif kind == 'hunters_mark':
            # Метка охотника: лиловый прицел на цели. Кольцо сжимается к
            # центру, четыре засечки сходятся — «цель захвачена».
            core = QColor(226, 208, 255)
            edge = QColor(124, 92, 214)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.2)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(110 * alpha)))
            glow.setColorAt(0.62, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(58 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.2, radius * 1.2)
            # Внешнее кольцо сжимается, внутреннее медленно вращается.
            shrink = 1.35 - 0.35 * min(1.0, t / 0.5)
            pen = QPen(QColor(core.red(), core.green(), core.blue(),
                              int(210 * alpha)))
            pen.setWidthF(1.9)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPointF(cx, cy), radius * shrink,
                                radius * shrink * 0.94)
            pen.setStyle(Qt.DashLine)
            pen.setWidthF(1.3)
            pen.setColor(QColor(edge.red(), edge.green(), edge.blue(),
                                int(190 * alpha)))
            painter.setPen(pen)
            painter.drawEllipse(QPointF(cx, cy), radius * 0.66, radius * 0.62)
            # Четыре засечки-стрелки: короткие «шевроны» у края круга.
            pen.setStyle(Qt.SolidLine)
            pen.setColor(QColor(core.red(), core.green(), core.blue(),
                                int(230 * alpha)))
            pen.setWidthF(1.8)
            painter.setPen(pen)
            arrow = radius * 0.20
            for corner in range(4):
                angle = corner * math.pi / 2.0 + t * 0.35
                tip = radius * 0.92
                for side in (-1, 1):
                    painter.drawLine(
                        QPointF(cx + math.cos(angle) * tip,
                                cy + math.sin(angle) * tip * 0.94),
                        QPointF(cx + math.cos(angle + side * 0.30)
                                * (tip - arrow),
                                cy + math.sin(angle + side * 0.30)
                                * (tip - arrow) * 0.94))
            # Тонкий луч в центр: метка «держит» цель.
            pulse = int(120 + 90 * math.sin(t * 8.0))
            pen.setColor(QColor(core.red(), core.green(), core.blue(),
                                int(max(0, pulse) * alpha)))
            pen.setWidthF(1.1)
            painter.setPen(pen)
            painter.drawLine(QPointF(cx - radius * 0.14, cy),
                             QPointF(cx + radius * 0.14, cy))
            painter.drawLine(QPointF(cx, cy - radius * 0.14),
                             QPointF(cx, cy + radius * 0.14))
        elif kind == 'divine_smite':
            # Божественная кара: столб золотого света и расходящееся кольцо.
            core = QColor(255, 250, 224)
            edge = QColor(232, 186, 74)
            burst = max(0.0, 1.0 - t / 0.75)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.3)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(170 * alpha * burst)))
            glow.setColorAt(0.55, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(90 * alpha * burst)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.3, radius * 1.3)
            # Столб света: от цели вверх, сужается к концу вспышки.
            beam = QLinearGradient(QPointF(cx, cy + radius * 0.2),
                                   QPointF(cx, cy - radius * 2.4))
            beam.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(220 * alpha)))
            beam.setColorAt(1.0, QColor(core.red(), core.green(), core.blue(), 0))
            painter.setBrush(QBrush(beam))
            width = radius * (0.34 + 0.10 * math.sin(t * 9.0))
            painter.drawRect(QRectF(cx - width / 2.0, cy - radius * 2.4,
                                    width, radius * 2.6))
            pen = QPen(QColor(core.red(), core.green(), core.blue(),
                              int(230 * alpha)))
            pen.setWidthF(2.2)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPointF(cx, cy), radius * (0.5 + 0.9 * t),
                                radius * (0.5 + 0.9 * t) * 0.55)
            # Копья света по кругу — вспышка удара.
            for ray in range(8):
                angle = ray * math.pi / 4.0 + t * 0.8
                inner = radius * (0.35 + 0.25 * t)
                outer = radius * (0.95 + 0.35 * math.sin(math.pi * t))
                ray_alpha = int(220 * alpha * (1.0 - t))
                if ray_alpha <= 0:
                    continue
                pen.setColor(QColor(core.red(), core.green(), core.blue(),
                                    ray_alpha))
                pen.setWidthF(1.8)
                painter.setPen(pen)
                painter.drawLine(
                    QPointF(cx + math.cos(angle) * inner,
                            cy + math.sin(angle) * inner * 0.94),
                    QPointF(cx + math.cos(angle) * outer,
                            cy + math.sin(angle) * outer * 0.94))
        elif kind.startswith('spell_'):
            # Любое заклинание из таблицы SRD: аура цвета стихии или школы.
            # Так у Огненного шара, Ледяного ножа и Удержания личности есть
            # свой отклик, даже если для них нет отдельной анимации.
            palettes = {
                'fire': ((255, 226, 168), (224, 108, 48)),
                'cold': ((224, 246, 255), (86, 156, 214)),
                'acid': ((226, 255, 196), (124, 190, 70)),
                'lightning': ((236, 240, 255), (120, 148, 236)),
                'thunder': ((228, 232, 255), (110, 120, 190)),
                'poison': ((212, 244, 200), (92, 150, 96)),
                'necrotic': ((206, 200, 226), (96, 76, 128)),
                'radiant': ((255, 250, 216), (236, 196, 92)),
                'psychic': ((246, 214, 255), (172, 104, 206)),
                'impact': ((238, 234, 230), (150, 140, 132)),
                'abjuration': ((220, 236, 255), (108, 152, 206)),
                'conjuration': ((230, 220, 255), (132, 108, 200)),
                'divination': ((226, 244, 240), (96, 160, 152)),
                'enchantment': ((248, 222, 240), (190, 108, 156)),
                'evocation': ((255, 234, 210), (214, 138, 78)),
                'illusion': ((236, 226, 255), (140, 116, 206)),
                'necromancy': ((208, 202, 226), (94, 78, 126)),
                'transmutation': ((226, 240, 216), (110, 158, 96)),
            }
            core_rgb, edge_rgb = palettes.get(
                kind[6:], ((232, 238, 248), (122, 148, 196)))
            core = QColor(*core_rgb)
            edge = QColor(*edge_rgb)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.15)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                       int(130 * alpha)))
            glow.setColorAt(0.6, QColor(edge.red(), edge.green(), edge.blue(),
                                        int(60 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.15, radius * 1.15)
            # Два кольца, вращающиеся в разные стороны, и искры по кругу.
            for index, (scale, speed, alpha_scale) in enumerate(
                    ((0.92, 1.0, 1.0), (0.68, -1.4, 0.7))):
                spin = t * speed + index * 0.8
                pen = QPen(QColor(core.red(), core.green(), core.blue(),
                                  int(200 * alpha * alpha_scale)))
                pen.setWidthF(1.8 if not index else 1.2)
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawEllipse(QPointF(cx, cy), radius * scale,
                                    radius * scale * 0.94)
                for tick in range(4 + index * 2):
                    angle = spin + tick * math.pi / (2 + index)
                    inner = radius * (scale - 0.10)
                    outer = radius * (scale + 0.04)
                    painter.drawLine(
                        QPointF(cx + math.cos(angle) * inner,
                                cy + math.sin(angle) * inner * 0.94),
                        QPointF(cx + math.cos(angle) * outer,
                                cy + math.sin(angle) * outer * 0.94))
            for spark in range(8):
                angle = spark * 0.785 + t * 1.1
                rise = (t * 0.8 + spark * 0.17) % 1.0
                px = cx + math.cos(angle) * radius * (0.3 + 0.5 * rise)
                py = cy + math.sin(angle) * radius * (0.3 + 0.5 * rise) * 0.94
                spark_alpha = int(190 * alpha * math.sin(math.pi * rise))
                if spark_alpha <= 0:
                    continue
                painter.setPen(QPen(QColor(core.red(), core.green(),
                                           core.blue(), spark_alpha), 1.4))
                size = max(1.4, radius * 0.05)
                painter.drawEllipse(QPointF(px, py), size, size)
        else:
            # healing_word / cure_wounds: зелёный рунический круг.
            core = QColor(198, 255, 176)
            edge = QColor(74, 196, 112)
            glow = QRadialGradient(QPointF(cx, cy), radius * 1.1)
            glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                        int(110 * alpha)))
            glow.setColorAt(0.6, QColor(edge.red(), edge.green(), edge.blue(),
                                         int(52 * alpha)))
            glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(glow))
            painter.drawEllipse(QPointF(cx, cy), radius * 1.1, radius * 1.1)
            spin = t * 1.4
            pen = QPen(QColor(core.red(), core.green(), core.blue(),
                              int(220 * alpha)))
            pen.setWidthF(1.8)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPointF(cx, cy), radius * 0.9, radius * 0.86)
            for rune in range(6):
                angle = spin + rune * math.pi / 3.0
                r1 = radius * 0.78
                r2 = radius * 0.95
                x1 = cx + math.cos(angle) * r1
                y1 = cy + math.sin(angle) * r1 * 0.94
                x2 = cx + math.cos(angle) * r2
                y2 = cy + math.sin(angle) * r2 * 0.94
                painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))
                tick = angle + math.pi / 6.0
                painter.drawLine(
                    QPointF(cx + math.cos(tick) * radius * 0.84,
                            cy + math.sin(tick) * radius * 0.80),
                    QPointF(cx + math.cos(tick) * radius * 0.92,
                            cy + math.sin(tick) * radius * 0.88))
            for index in range(10):
                angle = index * 0.628 + t * 0.9
                rise = ((t * 0.9 + index * 0.13) % 1.0)
                px = cx + math.cos(angle) * radius * (0.2 + 0.22 * (index % 3))
                py = cy + radius * 0.5 - rise * radius * 1.5
                spark_alpha = int(225 * alpha * math.sin(math.pi * rise))
                if spark_alpha <= 0:
                    continue
                spark = QColor(240, 255, 214, spark_alpha)
                painter.setPen(QPen(spark, 1.6))
                size = max(1.5, radius * 0.055)
                painter.drawEllipse(QPointF(px, py), size, size)

    def _draw_beam(self, painter: QPainter, fx: dict, progress: float):
        """Луч заклинания: яркое ядро, ореол и плывущий блик."""
        sx, sy = self.world_to_screen(*fx['from'])
        ex, ey = self.world_to_screen(*fx['to'])
        t = max(0.0, min(1.0, progress))
        # Луч вырастает за первые 30% и гаснет к концу.
        reach = min(1.0, t / 0.3)
        fade = 1.0 - max(0.0, (t - 0.4) / 0.6)
        if fade <= 0:
            return
        kind = str(fx.get('fx') or 'guiding_bolt')
        if kind == 'guiding_bolt':
            core, edge = QColor(255, 252, 226), QColor(255, 196, 84)
        elif kind == 'sacred_flame':
            core, edge = QColor(255, 246, 196), QColor(248, 168, 56)
        else:
            core, edge = QColor(240, 250, 255), QColor(120, 176, 255)
        px = sx + (ex - sx) * reach
        py = sy + (ey - sy) * reach
        for width, colour, alpha_scale in ((13.0, edge, 0.18),
                                           (6.0, edge, 0.42),
                                           (2.2, core, 0.95)):
            colour = QColor(colour)
            colour.setAlpha(int(255 * fade * alpha_scale))
            pen = QPen(colour)
            pen.setWidthF(max(1.0, width))
            pen.setCapStyle(Qt.RoundCap)
            painter.setPen(pen)
            painter.drawLine(QPointF(sx, sy), QPointF(px, py))
        # Блик бежит по лучу — луч читается как летящий, а не нарисованный.
        shine = min(1.0, reach)
        hx = sx + (ex - sx) * shine
        hy = sy + (ey - sy) * shine
        glow = QRadialGradient(QPointF(hx, hy), 22.0)
        glow.setColorAt(0.0, QColor(255, 255, 240, int(230 * fade)))
        glow.setColorAt(0.5, QColor(edge.red(), edge.green(), edge.blue(),
                                     int(120 * fade)))
        glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(hx, hy), 22.0, 22.0)

    def _draw_arc(self, painter: QPainter, fx: dict, progress: float):
        """Дуга молнии: изломистая ломаная с ответвлениями и вспышкой.

        Рисуется в экранных пикселях: толщина и излом не зависят от зума,
        поэтому на максимальном приближении разряд остаётся читаемым, а на
        дальнем не превращается в пятно.
        """
        start = self.tokens.get(str(fx.get('from_id') or ''))
        end = self.tokens.get(str(fx.get('to_id') or ''))
        if start is not None:
            from_world = self._token_visual_pos(start)
        else:
            from_world = fx.get('from') or (0.0, 0.0)
        if end is not None:
            to_world = self._token_visual_pos(end)
        else:
            to_world = fx.get('to') or (0.0, 0.0)
        sx, sy = self.world_to_screen(*from_world)
        ex, ey = self.world_to_screen(*to_world)
        dx, dy = ex - sx, ey - sy
        length = math.hypot(dx, dy)
        if length < 2.0:
            return
        t = max(0.0, min(1.0, progress))
        # Разряд вспыхивает почти мгновенно и гаснет к концу; дрожание
        # яркости маленькое, чтобы не рябило в глазах.
        reveal = min(1.0, t / 0.12)
        fade = 1.0 - max(0.0, (t - 0.42) / 0.58)
        if fade <= 0.0:
            return
        alpha = fade * (0.84 + 0.16 * math.sin(t * 62.0))
        ux, uy = dx / length, dy / length
        px, py = -uy, ux
        amp = min(30.0, max(6.0, length * 0.09))
        points = [QPointF(sx, sy)]
        for frac, offset in fx.get('path') or []:
            if frac > reveal:
                break
            # Мелкое дрожание по времени: дуга «живая», но не скачет.
            drift = math.sin(frac * 21.0 + t * 44.0) * amp * 0.16
            shift = float(offset) * length + drift
            points.append(QPointF(sx + dx * frac + px * shift,
                                  sy + dy * frac + py * shift))
        points.append(QPointF(sx + dx * reveal, sy + dy * reveal))
        edge = self._damage_color(fx.get('damage_type') or 'lightning')
        core = QColor(248, 252, 255)
        path_obj = QPainterPath(points[0])
        for point in points[1:]:
            path_obj.lineTo(point)
        for width, colour, scale in ((9.0, edge, 0.20),
                                     (4.2, edge, 0.50),
                                     (1.7, core, 0.95)):
            pen = QPen(QColor(colour.red(), colour.green(), colour.blue(),
                              int(255 * alpha * scale)))
            pen.setWidthF(max(1.0, width))
            pen.setCapStyle(Qt.RoundCap)
            pen.setJoinStyle(Qt.RoundJoin)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawPath(path_obj)
        # Ответвления: короткие форки от середины дуги — так молния читается.
        base_angle = math.atan2(dy, dx)
        for fork in fx.get('forks') or []:
            at = float(fork.get('at') or 0.0)
            if at > reveal or len(points) < 3:
                continue
            index = max(1, min(len(points) - 1, int(at * len(points))))
            origin = points[index]
            angle = (base_angle + math.pi / 2.0 * float(fork.get('side') or 1)
                     + float(fork.get('angle') or 0.0))
            reach = length * float(fork.get('length') or 0.12)
            mid = QPointF(origin.x() + math.cos(angle) * reach * 0.55,
                          origin.y() + math.sin(angle) * reach * 0.55)
            tip = QPointF(mid.x() + math.cos(angle + 0.5) * reach * 0.45,
                          mid.y() + math.sin(angle + 0.5) * reach * 0.45)
            pen = QPen(QColor(core.red(), core.green(), core.blue(),
                              int(210 * alpha * 0.8)))
            pen.setWidthF(1.2)
            painter.setPen(pen)
            painter.drawLine(origin, mid)
            painter.drawLine(mid, tip)
        # Вспышка на цели: точка удара разряда.
        glow = QRadialGradient(QPointF(ex, ey), 10.0 + 16.0 * t)
        glow.setColorAt(0.0, QColor(core.red(), core.green(), core.blue(),
                                    int(220 * fade)))
        glow.setColorAt(0.55, QColor(edge.red(), edge.green(), edge.blue(),
                                     int(110 * fade)))
        glow.setColorAt(1.0, QColor(edge.red(), edge.green(), edge.blue(), 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(ex, ey), 10.0 + 16.0 * t,
                            10.0 + 16.0 * t)

    def _draw_impact(self, painter: QPainter, fx: dict, progress: float):
        """Короткая вспышка в точке попадания снаряда."""
        cx, cy = self.world_to_screen(*fx['to'])
        t = max(0.0, min(1.0, progress))
        alpha = int(210 * (1 - t))
        if alpha <= 0:
            return
        radius = 6.0 + 20.0 * t
        if fx.get('fx') == 'radiant':
            pen = QPen(QColor(255, 226, 132, alpha))
        else:
            pen = QPen(QColor(170, 220, 255, alpha))
        pen.setWidthF(max(1.0, 2.5 * (1 - t)))
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawEllipse(QPointF(cx, cy), radius, radius)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(255, 255, 255, int(alpha * 0.8))))
        painter.drawEllipse(QPointF(cx, cy), max(1.0, 4.0 * (1 - t)),
                            max(1.0, 4.0 * (1 - t)))

    # ------------------------------------------------------------------
    # Кровь
    # ------------------------------------------------------------------
    def _spawn_blood(self, token, critical: bool = False, direction=None):
        """Создать всплеск крови на месте попадания.

        Кровь — не анимация на кадр, а запись со временем: сначала брызги
        летят, потом остаётся пятно. Форма выбирается из нескольких стилей
        (клякса, взрыв, направленный веер, лужа, потёк), поэтому два удара
        подряд не выглядят близнецами.
        """
        map_id = getattr(self.current_map, "id", None)
        if map_id is None:
            return
        cell = max(1.0, float(self.grid_cell_world or 0.0) or 50.0)
        size = max(MIN_TOKEN_DRAW_PX,
                   cell * max(0.1, float(getattr(token, 'size', 1.0) or 1.0)))
        # Предел — соседняя клетка от края токена: дальше кровь не летит.
        reach = size * 0.5 + cell * BLOOD_REACH_CELLS
        boost = 1.20 if critical else 1.0
        # Нежить не кровит: у неё вместо капель — сине-зелёные куски.
        kind = "ichor" if is_undead(token) else "blood"
        # Пока хитов половина и больше, рана только сочится каплями:
        # крупная лужа — признак тяжёлого ранения, а не каждой царапины.
        hp_ratio = self._token_hp_ratio(token)
        if (kind == "blood" and hp_ratio is not None
                and hp_ratio >= BLOOD_HEAVY_RATIO):
            self._spawn_light_blood(token, critical, direction,
                                    map_id, cell, size, reach)
            return
        style = "ichor"
        pool = 0.0
        pool_shape = []
        pool_flow = 0.0
        pool_stretch = 0.0
        spikes = []
        satellites = []
        mist = []
        streaks = []
        gloss = []
        clots = []
        lobes = []
        flecks = []
        fingers = []
        holes = []

        if kind == "ichor":
            drops = []
            for _ in range(13 if critical else 9):
                drops.append({
                    'angle': random.uniform(0.0, 2.0 * math.pi),
                    'distance': random.uniform(0.32, 0.95) * reach,
                    'radius': random.uniform(0.055, 0.105) * cell * boost,
                    'delay': random.uniform(0.0, 0.10),
                    'life': random.uniform(0.30, 0.62),
                    'land_radius': random.uniform(0.040, 0.085) * cell * boost,
                    # Поворот куска: обломок должен лететь гранью, а не
                    # выглядеть ровным кружком.
                    'spin': random.uniform(0.0, 2.0 * math.pi),
                })
            # Лужи и порезов нет: куски нежити тают без следа.
            marks = []
        else:
            if critical:
                style = random.choice(("burst", "splat", "spray"))
            else:
                style = random.choices(
                    ("splat", "burst", "spray", "pool", "drip"),
                    weights=(3, 2, 2, 2, 1))[0]
            if direction and math.hypot(*direction) > 0.001:
                flow = math.atan2(direction[1], direction[0])
            else:
                flow = random.uniform(0.0, 2.0 * math.pi)
            if style == "drip":
                flow = math.pi / 2.0

            # Капли. Веер летит по направлению удара, потёк — вниз,
            # остальные стили разлетаются вокруг точки попадания.
            drops = []
            for _ in range(17 if critical else 12):
                if style == "spray":
                    angle = flow + random.uniform(-0.62, 0.62)
                elif style == "drip":
                    angle = flow + random.uniform(-0.85, 0.85)
                else:
                    angle = random.uniform(0.0, 2.0 * math.pi)
                distance = random.uniform(0.40, 0.92) * reach
                if style == "spray":
                    distance *= random.uniform(0.98, 1.10)
                drops.append({
                    'angle': angle,
                    'distance': min(distance, reach * 0.92),
                    'radius': random.uniform(0.022, 0.064) * cell * boost,
                    'delay': random.uniform(0.0, 0.08),
                    'life': random.uniform(0.26, 0.58),
                    'land_radius': random.uniform(0.035, 0.105) * cell * boost,
                    # Капля вытянута по полёту: это читается как брызги,
                    # а не как ровный горох.
                    'stretch': random.uniform(1.0, 2.0),
                    # След на полу: часть капель круглая, часть смазана.
                    'land_stretch': random.uniform(0.9, 1.7),
                })

            # Неровный контур лужи: длинные зубцы и глубокие вырезы.
            count = random.randint(20, 26)
            pool_shape = []
            for index in range(count):
                angle = (2.0 * math.pi * index / count
                         + random.uniform(-0.035, 0.035))
                factor = random.uniform(0.72, 1.16)
                pool_shape.append([angle, factor])
            # Число и глубина долей зависят от стиля: лужа круглая,
            # клякса рваная, веер вытянут по удару.
            lobes_count, cuts_count = {
                "splat": (4, 3), "burst": (5, 3), "spray": (3, 2),
                "pool": (2, 2), "drip": (3, 2),
            }[style]
            lobes_count += 2 if critical else 0
            for index in random.sample(range(count), k=lobes_count):
                angle, _ = pool_shape[index]
                pool_shape[index] = [angle, random.uniform(1.12, 1.36)]
            for index in random.sample(range(count), k=cuts_count):
                angle, _ = pool_shape[index]
                pool_shape[index] = [angle, random.uniform(0.64, 0.80)]

            pool_stretch = {
                "spray": 0.95, "drip": 1.05, "burst": 0.05,
                "splat": 0.10, "pool": 0.0,
            }[style]
            pool_flow = flow
            # Стили должны различаться силуэтом, а не только деталями:
            # искры россыпью, узкий фонтан, широкая лужа, потёк вниз.
            # Основная клякса заметно меньше прежней: кровь должна читаться
            # как брызги, а не заливать половину клетки.
            # Лужа — только центр композиции, а не половина клетки.
            # Основной силуэт собирается из долей, поэтому даже маленькое
            # пятно выглядит рваным, а не ровным кружком.
            base_pool = min(reach * 0.30, cell * 0.36)
            pool = (base_pool * boost
                    * {"splat": 1.0, "burst": 0.58, "spray": 0.80,
                       "pool": 1.08, "drip": 0.94}[style])
            if critical:
                # Критический удар брызгает крупнее любого обычного, даже
                # если выпал «искристый» стиль с маленькой кляксой.
                pool = max(pool, base_pool * 1.10)
            lobes = self._make_blood_lobes(pool, critical)

            # Тянущиеся в стороны «пальцы» — от них силуэт перестаёт
            # читаться как ровная клякса. Основания прячутся под лужей.
            for _ in range(4 + (2 if critical else 0)):
                if style in ("spray", "drip"):
                    angle = flow + random.uniform(-0.95, 0.95)
                else:
                    angle = random.uniform(0.0, 2.0 * math.pi)
                fingers.append({
                    'angle': angle,
                    'length': random.uniform(0.38, 0.85) * pool,
                    'width': random.uniform(0.12, 0.24) * pool,
                    'bend': random.uniform(-0.20, 0.20) * pool,
                })
            # Сквозные просветы: кровь обтекает неровности пола.
            for _ in range(random.randint(1, 3) + (1 if critical else 0)):
                angle = random.uniform(0.0, 2.0 * math.pi)
                distance = random.uniform(0.12, 0.46) * pool
                holes.append({
                    'dx': math.cos(angle) * distance,
                    'dy': math.sin(angle) * distance,
                    'radius': random.uniform(0.07, 0.15) * pool,
                })

            # Лучи-зубцы вокруг лужи.
            spike_count = {"burst": 6, "splat": 4, "spray": 3,
                           "pool": 1, "drip": 1}[style]
            spikes = []
            for _ in range(spike_count + (2 if critical else 0)):
                if style == "spray":
                    angle = flow + random.uniform(-0.45, 0.45)
                elif style == "drip":
                    angle = flow + random.uniform(-0.35, 0.35)
                else:
                    angle = random.uniform(0.0, 2.0 * math.pi)
                spikes.append({
                    'angle': angle,
                    # Короткие лучи только разбивают край лужицы.
                    # Длинные брызги дают отдельные капли, а не звезду.
                    'factor': random.uniform(1.10, 1.30),
                    'width': random.uniform(0.010, 0.026),
                })

            # Отлетевшие самостоятельные кляксы: именно они дают
            # «живой» силуэт брызг на референсах.
            satellites = []
            base_sats = {"splat": 7, "burst": 14, "spray": 9,
                         "pool": 3, "drip": 5}[style]
            for _ in range(base_sats + (4 if critical else 0)
                           + random.randint(0, 2)):
                angle = (flow + random.uniform(-1.05, 1.05)
                         if style in ("spray", "drip")
                         else random.uniform(0.0, 2.0 * math.pi))
                # Большая часть клякс — снаружи лужи, иначе их не видно.
                distance = random.uniform(0.46, 1.02) * reach
                if style == "burst":
                    distance = random.uniform(0.60, 1.02) * reach
                elif style == "pool":
                    distance = random.uniform(0.85, 1.05) * reach
                if distance < pool * 1.05:
                    distance = pool * random.uniform(1.0, 1.12)
                sat_shape = []
                for index in range(random.randint(6, 10)):
                    sat_shape.append([
                        2.0 * math.pi * index / 9.0
                        + random.uniform(-0.10, 0.10),
                        random.uniform(0.68, 1.28)])
                satellites.append({
                    'dx': math.cos(angle) * distance,
                    'dy': math.sin(angle) * distance,
                    'radius': random.uniform(0.020, 0.098) * cell * boost,
                    'shape': sat_shape,
                    'angle': angle,
                    # Часть клякс вытянута в полёте — след брызг.
                    'stretch': random.choices((1.0, 1.0, 1.7, 2.4, 3.0),
                                              weights=(4, 3, 2, 2, 1))[0],
                })

            # Мелкая взвесь — почти пыль. Сразу после удара она гуще.
            mist = []
            for _ in range(46 if critical else 32):
                angle = (flow + random.uniform(-1.05, 1.05)
                         if style in ("spray", "drip")
                         else random.uniform(0.0, 2.0 * math.pi))
                mist.append({
                    'angle': angle,
                    'distance': random.uniform(0.32, 1.0) * reach,
                    'radius': random.uniform(0.008, 0.030) * cell,
                    # Мелочь разного размера: не горошины одного калибра.
                    'stretch': random.uniform(1.0, 2.1),
                })

            # Длинные мазки: их хорошо видно на первом кадре удара.
            streaks = []
            for _ in range(7 if critical else 4):
                angle = (flow + random.uniform(-0.55, 0.55)
                         if style in ("spray", "drip")
                         else random.uniform(0.0, 2.0 * math.pi))
                streaks.append({
                    'angle': angle,
                    'start': random.uniform(0.55, 0.95) * pool,
                    'length': random.uniform(0.20, 0.62) * reach,
                    'width': random.uniform(0.010, 0.030) * cell,
                    'bend': random.uniform(-0.20, 0.20),
                })

            # Блик и тёмные сгустки: кровь должна выглядеть влажной.
            gloss = []
            for _ in range(2 if critical else 1):
                gloss.append({
                    'dx': random.uniform(-0.30, 0.05) * pool,
                    'dy': random.uniform(-0.38, -0.08) * pool,
                    'rx': random.uniform(0.08, 0.18) * pool,
                    'ry': random.uniform(0.018, 0.042) * pool,
                    'angle': random.uniform(-0.55, 0.15),
                })
            clots = []
            for _ in range(random.randint(1, 3)):
                clots.append({
                    'dx': random.uniform(-0.55, 0.55) * pool,
                    'dy': random.uniform(-0.55, 0.55) * pool,
                    'radius': random.uniform(0.05, 0.12) * pool,
                })

            # Порезы, капли и мелкие брызги — то, что останется после
            # высыхания. Часть царапин длинная, часть — совсем мелкая.
            marks = []
            for _ in range(7 if critical else 5):
                marks.append({
                    'dx': random.uniform(-0.5, 0.5) * reach,
                    'dy': random.uniform(-0.5, 0.5) * reach,
                    'length': random.uniform(0.10, 0.30) * cell,
                    'angle': random.uniform(0.0, math.pi),
                    'width': random.uniform(0.012, 0.034) * cell,
                })
            for _ in range(6 if critical else 4):
                marks.append({
                    'dx': random.uniform(-0.55, 0.55) * reach,
                    'dy': random.uniform(-0.55, 0.55) * reach,
                    'radius': random.uniform(0.025, 0.075) * cell,
                })

            # Совсем мелкие брызги вокруг лужи: на референсах силуэт
            # разбивается десятком точек, а не заканчивается ровным краем.
            flecks = []
            for _ in range(16 if critical else 11):
                angle = random.uniform(0.0, 2.0 * math.pi)
                distance = random.uniform(0.55, 1.05) * reach
                flecks.append({
                    'dx': math.cos(angle) * distance,
                    'dy': math.sin(angle) * distance,
                    'radius': random.uniform(0.006, 0.021) * cell * boost,
                    'stretch': random.uniform(1.0, 2.3),
                    'angle': angle,
                })

        self._store_blood_hit({
            'map_id': map_id,
            'kind': kind,
            'style': style,
            'life': ICHOR_LIFE_S if kind == "ichor"
                    else BLOOD_LIFE_S,
            'start': time.monotonic(),
            'x': float(token.x),
            'y': float(token.y),
            'pool': pool,
            'lobes': lobes,
            'pool_shape': pool_shape,
            'pool_flow': pool_flow,
            'pool_stretch': pool_stretch,
            'spikes': spikes,
            'satellites': satellites,
            'mist': mist,
            'streaks': streaks,
            'gloss': gloss,
            'clots': clots,
            'flecks': flecks,
            'fingers': fingers,
            'holes': holes,
            'drops': drops,
            'marks': marks,
            'critical': bool(critical),
        })
        if (hp_ratio is not None and 0 < hp_ratio <= BLOOD_DRIP_RATIO
                and kind == "blood"):
            # Удар уже дал всплеск; первая капля с раны — через 5 секунд.
            self._wound_last[token.id] = time.monotonic()

    @staticmethod
    def _token_hp_ratio(token):
        """Доля оставшихся хитов (0…1) или None, если хиты неизвестны."""
        try:
            hp = float(getattr(token, 'hp', None))
            hp_max = float(getattr(token, 'hp_max', None))
        except (TypeError, ValueError):
            return None
        if hp_max <= 0 or hp < 0:
            return None
        return max(0.0, min(1.0, hp / hp_max))

    def _store_blood_hit(self, hit: dict):
        """Положить всплеск в общую историю и запустить его анимацию."""
        self._blood_hits.append(hit)
        # Старые всплески не копим бесконечно: память дороже истории пятен.
        if len(self._blood_hits) > BLOOD_MAX_HITS:
            del self._blood_hits[:-BLOOD_MAX_HITS]
        self._ensure_anim_timer()
        if (hit.get('kind') == "ichor"
                and self._blood_timer.interval() != ICHOR_TICK_MS):
            self._blood_timer.setInterval(ICHOR_TICK_MS)
        if not self._blood_timer.isActive():
            self._blood_timer.start()
        self.update()

    @staticmethod
    def _make_blood_lobes(pool: float, critical: bool) -> list:
        """Несколько налегающих друг на друга долей вместо одной кляксы.

        Референсы — это не ровный круг: центр лужицы собран из 4–7
        органических пятен, между которыми читаются вырезы и перемычки.
        """
        if pool <= 0.5:
            return []
        count = 4 + (2 if critical else 0) + random.randint(0, 2)
        lobes = []
        for index in range(count):
            angle = (2.0 * math.pi * index / count
                     + random.uniform(-0.28, 0.28))
            distance = pool * random.uniform(0.32, 0.54)
            radius = pool * random.uniform(0.40, 0.62)
            points = random.randint(9, 13)
            shape = []
            for point in range(points):
                shape.append([
                    2.0 * math.pi * point / points
                    + random.uniform(-0.06, 0.06),
                    random.uniform(0.74, 1.22)])
            lobes.append({
                'dx': math.cos(angle) * distance,
                'dy': math.sin(angle) * distance,
                'radius': radius,
                'shape': shape,
                # Доля проявляется не сразу: пятно сначала узкое, потом
                # расползается в стороны — как настоящая капля на полу.
                'side': random.uniform(0.0, 0.28),
            })
        # Центральная доля закрывает стыки между лепестками.
        shape = []
        for point in range(10):
            shape.append([2.0 * math.pi * point / 10.0,
                          random.uniform(0.78, 1.16)])
        lobes.append({'dx': 0.0, 'dy': 0.0, 'radius': pool * 0.54,
                      'shape': shape, 'side': 0.0})
        return lobes

    def _spawn_light_blood(self, token, critical: bool, direction,
                           map_id: str, cell: float, size: float,
                           reach: float):
        """Царапина при хитах выше половины: только отдельные капли.

        Никакой лужи и длинных лучей: несколько круглых капель, короткие
        следы и маленькие отметины. Тяжёлый всплеск начинается только
        после BLOOD_HEAVY_RATIO.
        """
        if direction and math.hypot(*direction) > 0.001:
            flow = math.atan2(direction[1], direction[0])
        else:
            flow = random.uniform(0.0, 2.0 * math.pi)
        drops = []
        for _ in range((7 if critical else 4) + random.randint(0, 1)):
            angle = flow + random.uniform(-1.05, 1.05)
            distance = random.uniform(0.18, 0.62) * reach
            drops.append({
                'angle': angle,
                'distance': distance,
                'radius': random.uniform(0.018, 0.042) * cell,
                'delay': random.uniform(0.0, 0.05),
                'life': random.uniform(0.28, 0.56),
                'land_radius': random.uniform(0.022, 0.052) * cell,
                'stretch': random.uniform(1.05, 1.75),
                'land_stretch': random.uniform(0.9, 1.5),
            })
        marks = []
        for _ in range(3 if critical else 2):
            marks.append({
                'dx': random.uniform(-0.42, 0.42) * reach,
                'dy': random.uniform(-0.42, 0.42) * reach,
                'length': random.uniform(0.06, 0.15) * cell,
                'angle': random.uniform(0.0, math.pi),
                'width': random.uniform(0.008, 0.018) * cell,
            })
        for _ in range(2):
            marks.append({
                'dx': random.uniform(-0.38, 0.38) * reach,
                'dy': random.uniform(-0.38, 0.38) * reach,
                'radius': random.uniform(0.018, 0.038) * cell,
            })
        self._store_blood_hit({
            'map_id': map_id,
            'kind': 'blood',
            'style': 'drops',
            'life': BLOOD_LIFE_S,
            'start': time.monotonic(),
            'x': float(token.x),
            'y': float(token.y),
            'pool': 0.0,
            'lobes': [],
            'pool_shape': [],
            'pool_flow': flow,
            'pool_stretch': 0.0,
            'spikes': [],
            'satellites': [],
            'mist': [],
            'streaks': [],
            'gloss': [],
            'clots': [],
            'drops': drops,
            'marks': marks,
            'critical': bool(critical),
        })

    def _on_wound_tick(self):
        """Раз в секунду проверяет, с кого капает кровь на последних хитах."""
        if not self.combat_effects_enabled or self.current_map is None:
            return
        now = time.monotonic()
        active = set()
        for token in self.current_map_tokens().values():
            if not getattr(token, 'visible', True):
                continue
            if is_undead(token):
                continue
            ratio = self._token_hp_ratio(token)
            if ratio is None or not (0.0 < ratio <= BLOOD_DRIP_RATIO):
                continue
            active.add(token.id)
            last = self._wound_last.get(token.id, 0.0)
            if now - last < BLOOD_DRIP_INTERVAL_S:
                continue
            self._wound_last[token.id] = now
            self._spawn_wound_drip(token)
        # Токен вылечили или убрали с карты — не держим для него таймер.
        for token_id in list(self._wound_last):
            if token_id not in active:
                self._wound_last.pop(token_id, None)

    def _spawn_wound_drip(self, token):
        """Одна медленная капля с раны вниз, почти без разлёта."""
        map_id = getattr(self.current_map, 'id', None)
        if map_id is None:
            return
        cell = max(1.0, float(self.grid_cell_world or 0.0) or 50.0)
        size = max(MIN_TOKEN_DRAW_PX,
                   cell * max(0.1, float(getattr(token, 'size', 1.0) or 1.0)))
        x = float(token.x) + random.uniform(-0.18, 0.18) * size
        y = float(token.y) + size * random.uniform(0.26, 0.36)
        angle = math.pi / 2.0 + random.uniform(-0.08, 0.08)
        radius = max(0.9, random.uniform(0.012, 0.026) * cell)
        self._store_blood_hit({
            'map_id': map_id,
            'kind': 'blood',
            'style': 'wound',
            'life': BLOOD_LIFE_S,
            'start': time.monotonic(),
            'x': x,
            'y': y,
            'pool': 0.0,
            'lobes': [],
            'pool_shape': [],
            'pool_flow': angle,
            'pool_stretch': 0.0,
            'spikes': [],
            'satellites': [],
            'mist': [],
            'streaks': [],
            'gloss': [],
            'clots': [],
            'drops': [{
                'angle': angle,
                'distance': random.uniform(0.12, 0.26) * cell,
                'radius': radius,
                'delay': 0.0,
                'life': random.uniform(0.48, 0.78),
                'land_radius': random.uniform(0.018, 0.038) * cell,
                'stretch': random.uniform(1.25, 1.8),
                'land_stretch': random.uniform(0.95, 1.3),
            }],
            'marks': [],
            'critical': False,
        })

    def _on_blood_tick(self):
        """Медленная перерисовка высыхающей крови (раз в 15 секунд)."""
        now = time.monotonic()
        map_id = getattr(self.current_map, 'id', None)
        fading = [hit for hit in self._blood_hits
                  if hit.get('map_id') == map_id
                  and now - hit['start'] < hit.get('life',
                                                   BLOOD_LIFE_S)]
        if not fading:
            self._blood_timer.stop()
        # Куски нежити тают за секунды — их дорисовываем чаще.
        ichor_alive = any(hit.get('kind') == 'ichor' for hit in fading)
        interval = ICHOR_TICK_MS if ichor_alive else BLOOD_DRY_TICK_MS
        if self._blood_timer.interval() != interval:
            self._blood_timer.setInterval(interval)
        self.update()

    @staticmethod
    def _blood_color(fade: float, kind: str = "blood",
                     dryness: float = None) -> QColor:
        """Цвет: кровь — тёмно-красная, куски нежити — сине-зелёные.

        ``dryness`` — насколько пятно высохло (0 — свежее, 1 — корка).
        Без него берётся из прозрачности: старое поведение.
        """
        if dryness is None:
            dryness = 1.0 - max(0.0, min(1.0, fade))
        dryness = max(0.0, min(1.0, dryness))
        if kind == "ichor":
            return QColor(int(64 - 34 * dryness),
                          int(214 - 94 * dryness),
                          int(190 - 74 * dryness))
        return QColor(int(168 - 38 * dryness),
                      int(26 + 20 * dryness),
                      int(32 + 10 * dryness))

    @staticmethod
    def _blood_shape_path(x: float, y: float, radius: float, shape,
                          flow: float = 0.0, stretch: float = 0.0):
        """Живой контур пятна: сглаженные доли, вырезы и вытянутость.

        Точки соединяются кубическими кривыми, а не ломаной: на референсах
        клякса течёт и обтекает, а не выглядит звездой из треугольников.
        """
        path = QPainterPath()
        if radius <= 0.5 or not shape:
            return path
        points = []
        for angle, factor in shape:
            pull = 1.0 + stretch * max(0.0, math.cos(angle - flow)) ** 2
            points.append(QPointF(x + math.cos(angle) * radius * factor * pull,
                                  y + math.sin(angle) * radius * factor * pull))
        return GameCanvas._blood_catmull_path(points)

    @staticmethod
    def _blood_catmull_path(points) -> QPainterPath:
        """Замкнутая Catmull-Rom кривая по точкам — силуэт без углов.

        Каждая точка становится опорной, соседние задают касательные.
        На общем виде многоугольник из точек сходил за пятно, но на
        сильном зуме его грани читались как гранёный полигон — кривая
        остаётся органичной на любом масштабе.
        """
        path = QPainterPath()
        count = len(points)
        if count < 3:
            return path
        tension = 0.70
        start = QPointF((points[-1].x() + points[0].x()) / 2.0,
                        (points[-1].y() + points[0].y()) / 2.0)
        path.moveTo(start)
        for index in range(count):
            p0 = points[(index - 1) % count]
            p1 = points[index]
            p2 = points[(index + 1) % count]
            p3 = points[(index + 2) % count]
            c1 = QPointF(p1.x() + (p2.x() - p0.x()) * tension / 6.0,
                         p1.y() + (p2.y() - p0.y()) * tension / 6.0)
            c2 = QPointF(p2.x() - (p3.x() - p1.x()) * tension / 6.0,
                         p2.y() - (p3.y() - p1.y()) * tension / 6.0)
            path.cubicTo(c1, c2, p2)
        path.closeSubpath()
        return path

    def _blood_fingers_path(self, hit: dict) -> QPainterPath:
        """Готовый путь всех «пальцев» лужи в координатах пятна.

        После растекания пальцы не меняются, а раньше они строились заново
        на каждом кадре: по шесть путей и шесть кружков на пятно.
        """
        cached = hit.get('_finger_path')
        if isinstance(cached, QPainterPath):
            return cached
        path = QPainterPath()
        path.setFillRule(Qt.WindingFill)
        radius = max(0.0, float(hit.get('pool', 0.0)))
        for finger in hit.get('fingers') or []:
            angle = finger['angle']
            cos_a, sin_a = math.cos(angle), math.sin(angle)
            nx, ny = -sin_a, cos_a
            root = radius * 0.38
            length = finger['length']
            half = max(0.6, finger['width'])
            bend = finger['bend']
            tip_x = cos_a * (root + length) + nx * bend
            tip_y = sin_a * (root + length) + ny * bend
            left = QPointF(cos_a * root + nx * half, sin_a * root + ny * half)
            right = QPointF(cos_a * root - nx * half,
                            sin_a * root - ny * half)
            c1 = QPointF(cos_a * (root + length * 0.42)
                         + nx * (half * 1.25 + bend * 0.3),
                         sin_a * (root + length * 0.42)
                         + ny * (half * 1.25 + bend * 0.3))
            c2 = QPointF(cos_a * (root + length * 0.72)
                         + nx * (half * 0.42 + bend * 0.75),
                         sin_a * (root + length * 0.72)
                         + ny * (half * 0.42 + bend * 0.75))
            finger_path = QPainterPath(left)
            finger_path.quadTo(c1, QPointF(tip_x, tip_y))
            finger_path.quadTo(c2, right)
            finger_path.closeSubpath()
            path.addPath(finger_path)
            # Круглый кончик: язык не должен заканчиваться иглой.
            tip = max(0.5, half * 0.55)
            path.addEllipse(QPointF(tip_x, tip_y), tip, tip)
        hit['_finger_path'] = path
        return path

    def _draw_blood_fingers(self, painter: QPainter, hit: dict,
                            color: QColor, fade: float, spread: float):
        """Тянущиеся от лужи «пальцы» с округлым кончиком.

        Референсы показывают не круг, а несколько вытянутых языков, между
        которыми видны глубокие вырезы. Основания пальцев скрывает лужа.
        """
        pool = max(0.0, float(hit.get('pool', 0.0)))
        fingers = hit.get('fingers') or []
        if pool <= 0.5 or not fingers:
            return
        radius = pool * (0.70 + 0.30 * spread)
        x, y = float(hit['x']), float(hit['y'])
        grow = 0.45 + 0.55 * spread
        finger_color = QColor(color).darker(108)
        finger_color.setAlpha(int(225 * fade))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(finger_color))
        if spread >= 0.999:
            # Лужа растекалась и перестала: форма пальцев больше не меняется,
            # и весь язык рисуется одной заливкой из готового пути.
            cached = self._blood_fingers_path(hit)
            if not cached.isEmpty():
                painter.save()
                painter.translate(x, y)
                painter.drawPath(cached)
                painter.restore()
            return
        for finger in fingers:
            angle = finger['angle']
            cos_a, sin_a = math.cos(angle), math.sin(angle)
            # Перпендикуляр задаёт толщину у основания.
            nx, ny = -sin_a, cos_a
            root = radius * 0.38
            length = finger['length'] * grow
            half = max(0.6, finger['width'] * grow)
            bend = finger['bend'] * grow
            tip_x = x + cos_a * (root + length) + nx * bend
            tip_y = y + sin_a * (root + length) + ny * bend
            left = QPointF(x + cos_a * root + nx * half,
                           y + sin_a * root + ny * half)
            right = QPointF(x + cos_a * root - nx * half,
                            y + sin_a * root - ny * half)
            c1 = QPointF(x + cos_a * (root + length * 0.42)
                         + nx * (half * 1.25 + bend * 0.3),
                         y + sin_a * (root + length * 0.42)
                         + ny * (half * 1.25 + bend * 0.3))
            c2 = QPointF(x + cos_a * (root + length * 0.72)
                         + nx * (half * 0.42 + bend * 0.75),
                         y + sin_a * (root + length * 0.72)
                         + ny * (half * 0.42 + bend * 0.75))
            path = QPainterPath(QPointF(left))
            path.quadTo(c1, QPointF(tip_x, tip_y))
            path.quadTo(c2, right)
            path.closeSubpath()
            painter.drawPath(path)
            # Круглый кончик: язык не должен заканчиваться иглой.
            painter.drawEllipse(QPointF(tip_x, tip_y), half * 0.55,
                                max(0.5, half * 0.55))

    def _blood_satellite_paths(self, hit: dict) -> dict:
        """Готовые пути всех отлетевших клякс в координатах пятна.

        Раньше каждая клякса рисовалась двумя-тремя отдельными заливками
        со своими сдвигами и масштабами: на кадре с десятком пятен это
        сотни вызовов, и кровь начинала тормозить как раз на сильном зуме,
        где её и разглядывают. Форма клякс после растекания не меняется,
        поэтому она собирается один раз — три пути по слоям.
        """
        cached = hit.get('_sat_paths')
        if isinstance(cached, dict):
            return cached
        outer = QPainterPath()
        inner = QPainterPath()
        core = QPainterPath()
        for path in (outer, inner, core):
            path.setFillRule(Qt.WindingFill)
        for sat in hit.get('satellites') or []:
            radius = float(sat['radius'])
            stretched = sat.get('stretch', 1.0)
            if stretched > 1.1:
                # Вытянутая клякса с хвостом по направлению разлёта.
                drop = QPainterPath()
                drop.addEllipse(QPointF(0, 0), radius * stretched,
                                radius * 0.74)
                place = QTransform().translate(sat['dx'], sat['dy'])
                place.rotate(math.degrees(sat.get('angle', 0.0)))
                outer.addPath(place.map(drop))
                small = QPainterPath()
                small.addEllipse(QPointF(0, 0), radius * 0.72 * stretched,
                                 radius * 0.72 * 0.74)
                place = QTransform().translate(sat['dx'] - radius * 0.10,
                                               sat['dy'] - radius * 0.10)
                place.rotate(math.degrees(sat.get('angle', 0.0)))
                inner.addPath(place.map(small))
                continue
            shape = self._satellite_path(sat)
            outer.addPath(QTransform().translate(sat['dx'], sat['dy']).map(shape))
            place = QTransform().translate(sat['dx'] - radius * 0.08,
                                          sat['dy'] - radius * 0.08)
            place.scale(0.72, 0.72)
            inner.addPath(place.map(shape))
            place = QTransform().translate(sat['dx'] - radius * 0.08,
                                          sat['dy'] - radius * 0.08)
            place.scale(0.72, 0.72)
            place.translate(-radius * 0.13, -radius * 0.15)
            place.scale(0.56, 0.56)
            core.addPath(place.map(shape))
        hit['_sat_paths'] = {'outer': outer, 'inner': inner, 'core': core}
        return hit['_sat_paths']

    def _blood_satellite_grain(self, hit: dict) -> dict:
        """Крупа внутри отлетевших клякс — для сильного зума.

        На предельном приближении отдельная брызга занимает пол-экрана:
        без крупы она выглядит наклейкой, хотя у настоящей внутри видны
        сгустки и просветы. Точки лежат в координатах пятна, как и пути
        самих клякс, поэтому при панорамировании не плывут.
        """
        cached = hit.get('_sat_grain')
        if isinstance(cached, dict):
            return cached
        dark = QPainterPath()
        light = QPainterPath()
        for path in (dark, light):
            path.setFillRule(Qt.WindingFill)
        rng = random.Random(int(hit['x'] * 29) ^ int(hit['y'] * 17) ^ 0x2B1)
        for sat in hit.get('satellites') or []:
            radius = max(0.6, float(sat['radius']))
            stretch = max(1.0, float(sat.get('stretch', 1.0)))
            for _ in range(rng.randint(3, 6)):
                angle = rng.uniform(0.0, 2.0 * math.pi)
                distance = radius * rng.uniform(0.0, 0.60)
                dx = sat['dx'] + math.cos(angle) * distance * stretch
                dy = sat['dy'] + math.sin(angle) * distance * 0.82
                grain = max(0.10, radius * rng.uniform(0.10, 0.24))
                target = dark if rng.random() < 0.62 else light
                target.addEllipse(QPointF(dx, dy),
                                  grain * rng.uniform(0.9, 1.5),
                                  grain * rng.uniform(0.6, 1.0))
        hit['_sat_grain'] = {'dark': dark, 'light': light}
        return hit['_sat_grain']

    def _draw_blood_satellites(self, painter: QPainter, hit: dict,
                               color: QColor, fade: float,
                               spread: float):
        """Отлетевшие кляксы вокруг лужи (общий код кадра и кэша)."""
        satellites = hit.get('satellites') or []
        if not satellites:
            return
        if spread >= 0.999:
            # Всплеск отлетел: все кляксы — три заливки из готовых путей.
            paths = self._blood_satellite_paths(hit)
            sat_outer = QColor(color).darker(118)
            sat_outer.setAlpha(int(214 * fade))
            sat_inner = QColor(min(255, color.red() + 52),
                               min(255, color.green() + 6),
                               min(255, color.blue() + 4))
            sat_inner.setAlpha(int(190 * fade))
            detail = self._blood_detail_alpha()
            painter.save()
            painter.translate(float(hit['x']), float(hit['y']))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(sat_outer))
            painter.drawPath(paths['outer'])
            painter.setBrush(QBrush(sat_inner))
            painter.drawPath(paths['inner'])
            if detail > 0.02 and not paths['core'].isEmpty():
                core = QColor(sat_inner).lighter(118)
                core.setAlpha(int(110 * detail * fade))
                painter.setBrush(QBrush(core))
                painter.drawPath(paths['core'])
            if detail > 0.02:
                # Крупа внутри клякс: на предельном зуме отдельная брызга
                # занимает пол-экрана, и гладкая заливка читается наклейкой.
                grain = self._blood_satellite_grain(hit)
                if not grain['dark'].isEmpty():
                    clot = QColor(color).darker(158)
                    clot.setAlpha(int(74 * detail * fade))
                    painter.setBrush(QBrush(clot))
                    painter.drawPath(grain['dark'])
                if not grain['light'].isEmpty():
                    film = QColor(255, 206, 200)
                    film.setAlpha(int(32 * detail * fade))
                    painter.setBrush(QBrush(film))
                    painter.drawPath(grain['light'])
            painter.restore()
            return
        for sat in satellites:
            sat_radius = sat['radius'] * (0.55 + 0.45 * spread)
            sat_x = hit['x'] + sat['dx'] * (0.45 + 0.55 * spread)
            sat_y = hit['y'] + sat['dy'] * (0.45 + 0.55 * spread)
            if not self._blood_in_view(
                    sat_x, sat_y,
                    sat_radius * max(1.0, sat.get('stretch', 1.0)) * 2.0):
                continue
            sat_outer = QColor(color).darker(118)
            sat_outer.setAlpha(int(214 * fade))
            sat_inner = QColor(min(255, color.red() + 52),
                               min(255, color.green() + 6),
                               min(255, color.blue() + 4))
            sat_inner.setAlpha(int(190 * fade))
            if sat.get('stretch', 1.0) > 1.1:
                # Вытянутая клякса с хвостом по направлению разлёта.
                self._draw_blood_drop(
                    painter, sat_x, sat_y, sat_radius,
                    sat.get('angle', 0.0), sat['stretch'], sat_outer)
                self._draw_blood_drop(
                    painter, sat_x - sat_radius * 0.10,
                    sat_y - sat_radius * 0.10, sat_radius * 0.72,
                    sat.get('angle', 0.0), sat['stretch'], sat_inner)
                continue
            path = self._satellite_path(sat)
            painter.setPen(Qt.NoPen)
            k = 0.55 + 0.45 * spread
            painter.save()
            painter.translate(sat_x, sat_y)
            painter.scale(k, k)
            painter.setBrush(QBrush(sat_outer))
            painter.drawPath(path)
            painter.translate(-sat['radius'] * 0.08, -sat['radius'] * 0.08)
            painter.scale(0.72, 0.72)
            painter.setBrush(QBrush(sat_inner))
            painter.drawPath(path)
            detail = self._blood_detail_alpha()
            if detail > 0.02:
                # На сильном зуме клякса не должна быть плоским овалом:
                # светлое ядро читается как мокрая капля, а не пятно краски.
                painter.translate(-sat['radius'] * 0.13,
                                  -sat['radius'] * 0.15)
                painter.scale(0.56, 0.56)
                core = QColor(sat_inner).lighter(118)
                core.setAlpha(int(110 * detail * fade))
                painter.setBrush(QBrush(core))
                painter.drawPath(path)
            painter.restore()

    def _blood_bake_density(self, bounds: QRectF) -> float:
        """Во сколько пикселей картинки печь один пиксель мира.

        Плотность ПОСТОЯННАЯ и не зависит от зума. Раньше она следовала за
        масштабом, и каждое деление колеса мыши перепекало пятно заново:
        готовый «рисунок» на миг подменялся другим, и полупрозрачные капли
        мигали. Картинка кладётся в свой мировый прямоугольник и растягивается
        вместе с картой, как текстура, поэтому форма и рисунок при любом
        зуме одни и те же.

        0.0 — печь не надо: картинка вышла бы больше лимита стороны.
        """
        try:
            dpr = max(1.0, float(self.devicePixelRatioF()))
        except Exception:  # noqa: BLE001 — старый Qt без этого метода
            dpr = 1.0
        side = max(bounds.width(), bounds.height())
        if side <= 0.5:
            return 0.0
        density = min(BLOOD_SPRITE_DENSITY * dpr,
                      BLOOD_SPRITE_MAX_SIDE / side)
        return density if density >= 1.0 else 0.0

    def _blood_in_view(self, x: float, y: float, radius: float) -> bool:
        """Попадает ли деталь следа в кадр.

        Нужна только пока пятно растекается: там кляксы рисуются по одной.
        Отлетевшая кровь — готовые пути, и там пиксели за краем всё равно
        отсекает сам painter.
        """
        view = getattr(self, '_blood_view', None)
        if view is None:
            return True
        radius = max(0.5, float(radius))
        return (x + radius >= view.left() and x - radius <= view.right()
                and y + radius >= view.top() and y - radius <= view.bottom())

    def _blood_detail_alpha(self) -> float:
        """Насколько показать мелкую фактуру пятна.

        0 — до трёхкратного масштаба (лужа там шириной в десяток пикселей,
        и крупа была бы шумом), 1 — с восьмикратного: на сильном зуме
        плоско залитая красным лужа читается как наклейка.

        Это общий порог «пора показывать фактуру». Насколько сильно виден
        каждый отдельный слой, решает своя октава: мелкие вступают позже
        (см. BLOOD_DETAIL_OCTAVES), чтобы частота крупы в пикселях экрана
        оставалась примерно постоянной на всём диапазоне приближения.
        """
        scale = float(self.scale or 1.0)
        span = max(0.1, BLOOD_DETAIL_ZOOM_FULL - BLOOD_DETAIL_ZOOM_START)
        return max(0.0, min(1.0, (scale - BLOOD_DETAIL_ZOOM_START) / span))

    def _blood_detail_shell(self, hit: dict) -> dict:
        """Заготовка фактуры пятна: слои собираются в неё по мере зума."""
        shell = hit.get('_detail')
        if isinstance(shell, dict):
            return shell
        shell = {'octaves': {}}
        hit['_detail'] = shell
        return shell

    def _blood_detail_octave(self, hit: dict, index: int) -> dict:
        """Мелкая фактура пятна — крупа, мазки сгустков и трещины корки.

        Форма лужи на крупном плане — это плоские заливки в несколько
        цветов; чтобы кровь не выглядела наклейкой, ей нужна крупа, как на
        референсах растёкшейся крови. Фактура собирается в несколько слоёв
        разного масштаба (октав): у каждой свои крупинки и свой зум, на
        котором она проявляется.

        Геометрия собирается один раз и лежит готовыми путями: сотня
        отдельных drawEllipse на кадр стоила десятки миллисекунд, а один
        заполненный путь с сотней подобных фигурок — доли миллисекунды.
        Точки привязаны к миру, поэтому при панорамировании не «плывут».
        """
        shell = self._blood_detail_shell(hit)
        cached = shell['octaves'].get(index)
        if isinstance(cached, dict):
            return cached
        factor, want, zoom_start, zoom_full = BLOOD_DETAIL_OCTAVES[index]
        octave = {'groups': [], 'cracks': None, 'crack_screen': 0.0,
                  'factor': factor, 'zoom_start': zoom_start,
                  'zoom_full': zoom_full, 'grain': (0.0, 0.0), 'specks': 0}
        limit = max(1.0, float(hit.get('pool') or 0.0)) * 0.92
        pool_path = self._blood_pool_path(hit)
        if not pool_path.isEmpty() and limit > 1.5:
            rng = random.Random((int(hit['x'] * 13) ^ int(hit['y'] * 7)
                                 ^ 0x5F3 ^ (index * 0x9E3779B1)))
            # Группа = тон: три цвета, три заливки вместо сотни отдельных
            # крупинок. Сила крупы разная, но разнобой альфы на глаз не
            # заметен, а лишние заливки на зуме стоят кадра.
            buckets = {}
            radii = []
            placed = 0
            tries = 0
            while placed < want and tries < want * 12:
                tries += 1
                dx = rng.uniform(-limit, limit)
                dy = rng.uniform(-limit, limit)
                reach = dx * dx + dy * dy
                if reach > limit * limit:
                    continue
                # Ближе к центру лужа залита всегда — проверять попадание
                # в контур там незачем, а contains() стоит дорого.
                if (reach > (limit * 0.70) ** 2
                        and not pool_path.contains(QPointF(dx, dy))):
                    continue
                # Крупа мельче с каждой октавой: на предельном зуме она
                # держит ту же частоту в пикселях экрана, что крупная на
                # обычном виде.
                radius = max(0.02, rng.uniform(0.004, 0.014) * limit * 2.0
                             * factor)
                rx = radius * rng.uniform(0.9, 1.7)
                ry = radius * rng.uniform(0.55, 1.05)
                # -1 — тёмный сгусток, 0 — тон пятна, +1 — светлая плёнка.
                tone = rng.choice((-1, -1, 0, 1))
                path = buckets.get(tone)
                if path is None:
                    path = QPainterPath()
                    path.setFillRule(Qt.WindingFill)
                    buckets[tone] = path
                path.addEllipse(QPointF(dx, dy), rx, ry)
                radii.append(radius)
                placed += 1
            alpha = 0.62 if index == 0 else 0.52
            for tone, path in buckets.items():
                octave['groups'].append({'tone': tone, 'path': path,
                                         'alpha': alpha})
            octave['specks'] = placed
            # Крупные мазки сгустков и светлой плёнки. На предельном зуме
            # видны только внутренности лужи, и без них она — ровное
            # красное поле с редкими точками: не кровь, а заливка. Мазки
            # дают тон в десяти сантиметрах от глаза, крупа — фактуру.
            if index == 0:
                for tone, count, size in ((-2, 7, (0.12, 0.26)),
                                          (2, 4, (0.08, 0.16))):
                    marks = QPainterPath()
                    marks.setFillRule(Qt.WindingFill)
                    for _ in range(count):
                        angle = rng.uniform(0.0, 2.0 * math.pi)
                        distance = limit * rng.uniform(0.0, 0.72)
                        radius = limit * rng.uniform(*size)
                        shape = radius * rng.uniform(0.55, 1.0)
                        marks.addEllipse(
                            QPointF(math.cos(angle) * distance,
                                    math.sin(angle) * distance * 0.88),
                            radius * rng.uniform(1.0, 1.8), shape)
                    if not marks.isEmpty():
                        octave['groups'].append(
                            {'tone': tone, 'path': marks, 'alpha': 0.30})
            if radii:
                octave['grain'] = (min(radii), max(radii))
            # Трещины корки: на крупном слое длинные, на следующем —
            # короткие волосяные. Мелкая октава их не получает: корка
            # трескается крупно, а не в пыль.
            if index <= 1:
                cracks = QPainterPath()
                count = (BLOOD_DETAIL_CRACKS if index == 0
                         else max(3, BLOOD_DETAIL_CRACKS // 2))
                reach_scale = 1.0 if index == 0 else 0.55
                for _ in range(count):
                    angle = rng.uniform(0.0, 2.0 * math.pi)
                    start = limit * rng.uniform(0.05, 0.50)
                    px = math.cos(angle) * start
                    py = math.sin(angle) * start
                    points = [(px, py)]
                    steps = rng.randint(2, 4)
                    segment = (limit * rng.uniform(0.20, 0.40) / steps
                               * reach_scale)
                    for _ in range(steps):
                        angle += rng.uniform(-0.55, 0.55)
                        px += math.cos(angle) * segment
                        py += math.sin(angle) * segment
                        points.append((px, py))
                    if not all(pool_path.contains(QPointF(a, b))
                               for a, b in points):
                        continue
                    cracks.moveTo(points[0][0], points[0][1])
                    for ox, oy in points[1:]:
                        cracks.lineTo(ox, oy)
                if not cracks.isEmpty():
                    octave['cracks'] = cracks
                    octave['crack_screen'] = (
                        BLOOD_CRACK_SCREEN_PX if index == 0
                        else BLOOD_CRACK_HAIR_SCREEN_PX)
        shell['octaves'][index] = octave
        return octave

    def _blood_build_take(self) -> bool:
        """Взять одну сборку фактуры из бюджета кадра."""
        token = getattr(self, '_blood_frame_token', 0)
        if getattr(self, '_blood_build_token', -1) != token:
            self._blood_build_token = token
            self._blood_build_budget = BLOOD_DETAIL_BUILD_PER_FRAME
        if self._blood_build_budget <= 0:
            return False
        self._blood_build_budget -= 1
        return True

    def _blood_detail_octaves(self, hit: dict) -> list:
        """Слои фактуры, которые видны на текущем зуме: [(слой, сила)].

        Мелкие слои собираются лениво и под бюджетом кадра: зум может
        прыгнуть с 1× сразу на 20×, и собирать сотни крупинок для всех
        пятен в одном кадре — верный рывок. Пропущенный слой появится в
        следующем кадре, а крупный виден всё это время.
        """
        shell = self._blood_detail_shell(hit)
        scale = float(self.scale or 1.0)
        ready = []
        for index in range(len(BLOOD_DETAIL_OCTAVES)):
            zoom_start = BLOOD_DETAIL_OCTAVES[index][2]
            zoom_full = BLOOD_DETAIL_OCTAVES[index][3]
            strength = max(0.0, min(1.0, (scale - zoom_start)
                                    / max(0.1, zoom_full - zoom_start)))
            if strength <= 0.02:
                continue
            octave = shell['octaves'].get(index)
            if octave is None:
                if not self._blood_build_take():
                    continue
                octave = self._blood_detail_octave(hit, index)
            ready.append((octave, strength))
        return ready

    @staticmethod
    def _blood_detail_color(tone: int, color: QColor, dry: bool) -> QColor:
        """Цвет крупинки: сгусток темнее, плёнка светлее, тон — как лужа.

        Большие мазки сгустков (±2) держатся ближе к тону лужи: на сильном
        зуме они занимают пол-экрана, и контраст крупинки там был бы
        грязным пятном.
        """
        if dry and tone <= -2:
            return QColor(80, 32, 23)
        if dry and tone >= 2:
            return QColor(120, 58, 42)
        if tone <= -2:
            return QColor(max(0, color.red() - 26),
                          max(0, color.green() - 4),
                          max(0, color.blue() - 3))
        if tone >= 2:
            return QColor(min(255, color.red() + 20),
                          min(255, color.green() + 8),
                          min(255, color.blue() + 6))
        if dry:
            if tone < 0:
                return QColor(70, 28, 20)
            if tone > 0:
                return QColor(132, 68, 48)
            return QColor(96, 42, 30)
        if tone < 0:
            return QColor(max(0, color.red() - 54),
                          max(0, color.green() - 10),
                          max(0, color.blue() - 8))
        if tone > 0:
            return QColor(min(255, color.red() + 46),
                          min(255, color.green() + 18),
                          min(255, color.blue() + 12))
        return QColor(color).darker(106)

    def _draw_blood_detail(self, painter: QPainter, hit: dict, color: QColor,
                           fade: float, dry: bool = False):
        """Крупа, сгустки и трещины поверх лужи или сухой корки.

        Рисуются только те слои, которые показывает текущий зум. На обычном
        зуме они попадают в запечённую картинку пятна, на предельном — идут
        вектором; в обоих случаях трещины держат толщину в пикселях экрана,
        иначе на 20× они превращаются в бурые шланги.
        """
        if self._blood_detail_alpha() <= 0.02 or fade <= 0.01:
            return
        octaves = self._blood_detail_octaves(hit)
        if not octaves:
            return
        scale = max(0.01, float(self.scale or 1.0))
        painter.save()
        painter.translate(float(hit['x']), float(hit['y']))
        painter.setPen(Qt.NoPen)
        for octave, strength in octaves:
            for group in octave['groups']:
                tint = self._blood_detail_color(group['tone'], color, dry)
                tint.setAlpha(int(130 * strength * fade * group['alpha']))
                painter.setBrush(QBrush(tint))
                painter.drawPath(group['path'])
            if dry and octave['cracks'] is not None:
                pen = QPen(QColor(56, 21, 16, int(170 * strength * fade)))
                pen.setWidthF(max(self.design(0.2),
                                  self.design(octave['crack_screen'])))
                pen.setCapStyle(Qt.RoundCap)
                pen.setJoinStyle(Qt.RoundJoin)
                painter.setBrush(Qt.NoBrush)
                painter.setPen(pen)
                painter.drawPath(octave['cracks'])
                painter.setPen(Qt.NoPen)
        painter.restore()

    def _blood_bounds(self, hit: dict) -> QRectF:
        """Габариты готового следа в мировых координатах (с запасом).

        Форма всплеска не меняется после создания записи, поэтому считается
        один раз: на кадре это только поиск в словаре.
        """
        cached = hit.get('_bounds')
        if isinstance(cached, QRectF):
            return cached
        x, y = float(hit['x']), float(hit['y'])
        extent = max(1.0, float(hit.get('pool', 0.0)) * 1.9)
        for sat in hit.get('satellites') or []:
            extent = max(extent, math.hypot(sat['dx'], sat['dy'])
                         + sat['radius'] * 2.2)
        for fleck in hit.get('flecks') or []:
            extent = max(extent, math.hypot(fleck['dx'], fleck['dy'])
                         + fleck['radius'] * fleck.get('stretch', 1.0))
        for drop in hit.get('drops') or []:
            extent = max(extent, drop['distance'] + drop['land_radius'])
        for mark in hit.get('marks') or []:
            extent = max(extent, math.hypot(mark['dx'], mark['dy'])
                         + mark.get('length', mark.get('radius', 0.0)))
        rect = QRectF(x - extent, y - extent, extent * 2.0, extent * 2.0)
        hit['_bounds'] = rect
        return rect

    def _blood_pool_bounds(self, hit: dict) -> QRectF:
        """Габариты лужи и её пальцев — то, что печётся в картинку.

        Раньше в картинку вместе с лужей попадали и отлетевшие кляксы, а
        они улетают на десятки единиц мира: картинка выходила вчетверо
        больше самой лужи, упиралась в лимит стороны и теряла плотность —
        на среднем зуме пятно переходило на вектор и теряло скорость
        именно там, где её и заметно. Кляксы рисуются отдельно: их три
        готовых пути, и кадр их не замечает.
        """
        cached = hit.get('_pool_bounds')
        if isinstance(cached, QRectF):
            return cached
        x, y = float(hit['x']), float(hit['y'])
        pool = max(0.0, float(hit.get('pool') or 0.0))
        cell = max(1.0, float(self.grid_cell_world or 0.0) or 50.0)
        extent = max(1.0, pool * 1.95, cell * 0.45)
        for lobe in hit.get('lobes') or []:
            extent = max(extent, math.hypot(lobe['dx'], lobe['dy'])
                         + lobe['radius'] * 1.35)
        for finger in hit.get('fingers') or []:
            extent = max(extent, pool * 0.40 + float(finger['length'])
                         + float(finger['width']) * 1.2)
        for hole in hit.get('holes') or []:
            extent = max(extent, math.hypot(hole['dx'], hole['dy'])
                         + float(hole['radius']) * 1.2)
        # Небольшой запас: сглаженный край пятна выходит чуть за опорные
        # точки, и обрезка по точному габариту съедала бы его.
        extent *= 1.06
        rect = QRectF(x - extent, y - extent, extent * 2.0, extent * 2.0)
        hit['_pool_bounds'] = rect
        return rect

    def _blood_mark_bounds(self, hit: dict) -> QRectF:
        """Габариты сухого следа: корка, царапины и крошки вокруг."""
        cached = hit.get('_mark_bounds')
        if isinstance(cached, QRectF):
            return cached
        x, y = float(hit['x']), float(hit['y'])
        pool = max(0.0, float(hit.get('pool') or 0.0))
        cell = max(1.0, float(self.grid_cell_world or 0.0) or 50.0)
        extent = max(1.0, pool * 1.95, cell * 0.45)
        for mark in hit.get('marks') or []:
            extent = max(extent, math.hypot(mark['dx'], mark['dy'])
                         + mark.get('length', mark.get('radius', 0.0)) * 1.2)
        extent *= 1.06
        rect = QRectF(x - extent, y - extent, extent * 2.0, extent * 2.0)
        hit['_mark_bounds'] = rect
        return rect

    def _blood_release_sprites(self, keep: QRectF) -> None:
        """Отпустить картинки пятен далеко за краем кадра.

        Картинки следов копятся всю сессию: после долгого боя на большом
        зуме их набираются сотни мегабайт. Освобождаем только когда памяти
        и правда много, и только для пятен за тройным запасом кадра —
        чтобы обычное панорамирование не заставляло перепекаться заново.
        """
        total = 0
        for hit in self._blood_hits:
            if self._blood_pool_bounds(hit).intersects(keep):
                total += int(hit.get('_sprite_px') or 0)
                total += int(hit.get('_marks_pix_px') or 0)
        if total < BLOOD_SPRITE_BUDGET_PX * 0.6:
            self._blood_sprite_px = total
            return
        for hit in self._blood_hits:
            if self._blood_pool_bounds(hit).intersects(keep):
                continue
            for key, size_key in (('_sprite', '_sprite_px'),
                                  ('_marks_pix', '_marks_pix_px')):
                hit.pop(key, None)
                hit.pop(size_key, None)
            hit.pop('_sprite_key', None)
            hit.pop('_sprite_rect', None)
            hit.pop('_marks_rect', None)
        self._blood_sprite_px = 0
        for hit in self._blood_hits:
            self._blood_sprite_px += int(hit.get('_sprite_px') or 0)
            self._blood_sprite_px += int(hit.get('_marks_pix_px') or 0)

    def _blood_sprite(self, hit: dict, fade: float,
                      dryness: float = 0.0):
        """Готовая картинка высыхающего пятна: (пиксмап, габариты мира).

        Форма лужи и всех брызг фиксирована после всплеска, меняется только
        прозрачность и оттенок. Поэтому пятно один раз рисуется в пиксмап,
        а кадр только выводит его. Пересборка — только когда кровь заметно
        высохла (оттенок): зум и прозрачность в ключ НЕ входят, иначе при
        приближении и отдалении рисунок подменялся бы другим.

        Габариты — только лужа и её пальцы (см. _blood_pool_bounds): печь
        улетевшие капли и кляксы в картинку незачем, а из-за них картинка
        выходила бы вчетверо больше и вдвое мыльнее при том же лимите памяти.
        """
        bounds = self._blood_pool_bounds(hit)
        if bounds.width() <= 1.0:
            return None
        density = self._blood_bake_density(bounds)
        if density <= 0.0:
            # Слишком сильный зум или слишком крупное пятно: вектор.
            return None
        # В ключе только высыхание: оттенок меняется раз в полминуты.
        # Крупа в картинку не входит — она зависит от зума и рисуется
        # вектором каждый кадр, чтобы приближение не меняло рисунок.
        key = (round(dryness * 12),)
        sprite = hit.get('_sprite')
        if (isinstance(sprite, QPixmap) and hit.get('_sprite_key') == key
                and hit.get('_sprite_rect') == bounds):
            # Габариты, а не угол: по ним картинка ложится в свой мир.
            return sprite, bounds
        if getattr(self, '_blood_bake_left', 1) <= 0:
            return None
        self._blood_bake_left -= 1
        width = max(2, int(round(bounds.width() * density)))
        height = max(2, int(round(bounds.height() * density)))
        if width > BLOOD_SPRITE_MAX_SIDE or height > BLOOD_SPRITE_MAX_SIDE:
            return None
        cost = width * height
        total = getattr(self, '_blood_sprite_px', 0)
        previous = int(hit.get('_sprite_px') or 0)
        if total - previous + cost > BLOOD_SPRITE_BUDGET_PX:
            # Память кончилась — рисуем вектором, картинка не обязательна.
            return None
        pix = QPixmap(width, height)
        pix.fill(Qt.transparent)
        painter = QPainter(pix)
        try:
            painter.setRenderHint(QPainter.Antialiasing, True)
            painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
            painter.scale(density, density)
            painter.translate(-bounds.left(), -bounds.top())
            # Цвет печём при полной непрозрачности: прозрачность кадра
            # задаёт painter.setOpacity, поэтому затухание крови не
            # требует перепекания.
            color = self._blood_color(1.0, hit.get('kind', 'blood'),
                                      dryness)
            self._draw_blood_fingers(painter, hit, color, 1.0, 1.0)
            self._draw_blood_pool(painter, hit, color, 1.0, 1.0)
        finally:
            painter.end()
        hit['_sprite'] = pix
        hit['_sprite_key'] = key
        hit['_sprite_rect'] = bounds
        hit['_sprite_px'] = cost
        self._blood_sprite_px = total - previous + cost
        self._blood_bake_count = getattr(self, '_blood_bake_count', 0) + 1
        # Плотность храним рядом: по ней тесты и отладка понимают, сколько
        # пикселей картинки приходится на единицу мира.
        hit['_sprite_density'] = density
        # Отдаём габариты, а не левый верхний угол: картинка испечена
        # с плотностью density, и рисовать её надо в тот же прямоугольник
        # мира, иначе пятно уезжает и расползается вдвое.
        return pix, bounds

    def _blood_sprite_cached(self, hit: dict, fade: float,
                             dryness: float = 0.0):
        """Пятно, если картинка уже испечена; иначе None и запрос на печь.

        Печь здесь нельзя: метод зовётся из отрисовки кадра, а на видеокарте
        QPixmap, созданный посреди рисования, ложится сплошным чёрным
        квадратом размером с пятно. Именно он мелькал при ударе по токену с
        нулём хитов: кровь дорастала до готового слоя и первый раз
        показывалась картинкой, а не вектором.
        """
        bounds = self._blood_pool_bounds(hit)
        if bounds.width() <= 1.0:
            return None
        density = self._blood_bake_density(bounds)
        if density <= 0.0:
            return None
        key = (round(dryness * 12),)
        sprite = hit.get('_sprite')
        if isinstance(sprite, QPixmap) and hit.get('_sprite_rect') == bounds:
            if hit.get('_sprite_key') != key:
                # Оттенок поменялся — перепечём, но кадр пока показывает
                # старую картинку: подменять её вектором нельзя, рисунок
                # мигнул бы другим.
                self._queue_blood_bake(hit, 1.0, dryness)
            return sprite, bounds
        self._queue_blood_bake(hit, 1.0, dryness)
        return None

    def _blood_sprite_for_paint(self, hit: dict, fade: float,
                                dryness: float = 0.0):
        """Пятно для текущего кадра: на видеокарте — только из кэша."""
        if not self._blood_images_wait:
            return self._blood_sprite(hit, fade, dryness)
        return self._blood_sprite_cached(hit, fade, dryness)

    def _blood_marks_cached(self, hit: dict):
        """Высохший след из кэша; иначе None и запрос на печь (см. выше)."""
        bounds = self._blood_mark_bounds(hit)
        if bounds.width() <= 1.0 or not hit.get('marks'):
            return None
        density = self._blood_bake_density(bounds)
        if density <= 0.0:
            return None
        cached = hit.get('_marks_pix')
        if (isinstance(cached, QPixmap)
                and hit.get('_marks_rect') == bounds
                and hit.get('_marks_density') == density):
            return cached, bounds
        self._queue_blood_bake(hit, 1.0, 1.0, marks=True)
        return None

    def _blood_marks_sprite_for_paint(self, hit: dict):
        """След для текущего кадра: на видеокарте — только из кэша."""
        if not self._blood_images_wait:
            return self._blood_marks_sprite(hit)
        return self._blood_marks_cached(hit)

    def _queue_blood_bake(self, hit: dict, fade: float, dryness: float,
                          marks: bool = False):
        """Отложить запекание пятна до конца кадра.

        Картинка создаётся не в paintEvent: холст рисует видеокарта, и новый
        QPixmap, нарисованный посреди кадра, ложится чёрным прямоугольником
        по своему размеру. Пока картинки нет, пятно идёт вектором — этот
        запасной путь уже был на случай кончившегося бюджета перепёка.
        """
        if not self._blood_images_wait:
            return
        pending = self._blood_pending
        if len(pending) < 64:
            pending[(id(hit), bool(marks))] = (hit, fade, dryness, bool(marks))
        if self._blood_bake_queued:
            return
        self._blood_bake_queued = True
        QTimer.singleShot(0, self._bake_blood_pending)

    def _bake_blood_pending(self):
        """Испечь отложенные пятна — уже вне отрисовки кадра."""
        self._blood_bake_queued = False
        pending = list(self._blood_pending.values())[:BLOOD_BAKE_PER_FRAME]
        self._blood_bake_left = BLOOD_BAKE_PER_FRAME
        baked = 0
        for hit, fade, dryness, marks in pending:
            self._blood_pending.pop((id(hit), marks), None)
            if not any(item is hit for item in self._blood_hits):
                continue
            result = (self._blood_marks_sprite(hit) if marks
                      else self._blood_sprite(hit, fade, dryness))
            if result is not None:
                baked += 1
        if baked:
            self.update()
        # Запросов может быть больше лимита: остальное печём следующим ходом
        # цикла событий, а не в одном кадре.
        if self._blood_pending and not self._blood_bake_queued:
            self._blood_bake_queued = True
            QTimer.singleShot(0, self._bake_blood_pending)

    def _satellite_path(self, sat: dict) -> QPainterPath:
        """Контур отлетевшей кляксы — один раз, в локальных координатах.

        Таких капель у крупного всплеска до двадцати, и каждая раньше
        пересобирала Catmull-Rom путь на каждом кадре. Форма зависит только
        от записи, поэтому кэшируется рядом с ней.
        """
        cached = sat.get('_path')
        if isinstance(cached, QPainterPath):
            return cached
        path = self._blood_shape_path(
            0.0, 0.0, max(0.6, float(sat.get('radius') or 0.6)),
            sat.get('shape') or [], 0.0, 0.0)
        sat['_path'] = path
        return path

    def _blood_pool_path(self, hit: dict) -> QPainterPath:
        """Контур лужи строится ОДИН раз на всплеск, а не каждый кадр.

        Раньше на каждую перерисовку canvas собирались три топологически
        сложных пути: Catmull-Rom по 20–26 точкам, до восьми долей и
        булевы вырезания. При десятках пятен и анимации это давало фризы.
        Теперь форма лежит в записи крови и переиспользуется: центр в
        (0, 0), радиус равен ``pool``, доли уже при полном растекании.
        """
        cached = hit.get('_pool_path')
        if isinstance(cached, QPainterPath):
            return cached
        path = QPainterPath()
        pool = max(0.0, float(hit.get('pool', 0.0)))
        shape = hit.get('pool_shape') or []
        if pool > 0.5 and shape:
            flow = float(hit.get('pool_flow', 0.0))
            stretch = float(hit.get('pool_stretch', 0.0))
            path = self._blood_shape_path(0.0, 0.0, pool, shape, flow,
                                          stretch)
            path.setFillRule(Qt.WindingFill)
            for lobe in hit.get('lobes') or []:
                path.addPath(self._blood_shape_path(
                    lobe['dx'], lobe['dy'], lobe['radius'], lobe['shape'],
                    flow, stretch * 0.55))
            # Сквозные просветы — пятно перестаёт быть монолитной кляксой.
            for hole in hit.get('holes') or []:
                hole_path = QPainterPath()
                hole_path.addEllipse(QPointF(hole['dx'], hole['dy']),
                                     max(0.6, hole['radius']),
                                     max(0.6, hole['radius'] * 0.82))
                path = path.subtracted(hole_path)
            path.setFillRule(Qt.WindingFill)
        hit['_pool_path'] = path
        return path

    def _blood_drop_stains_path(self, hit: dict) -> QPainterPath:
        """Готовый путь следов упавших капель (в координатах пятна).

        Каждая капля после падения остаётся вытянутым пятнышком, и их до
        семнадцати на всплеск. Раньше каждое рисовалось отдельным вызовом
        с поворотом и сдвигом — на кадре с десятком старых пятен это
        заметный расход, а форма следа уже не меняется.
        """
        cached = hit.get('_stain_path')
        if isinstance(cached, QPainterPath):
            return cached
        path = QPainterPath()
        path.setFillRule(Qt.WindingFill)
        ichor = hit.get('kind') == 'ichor'
        for drop in hit.get('drops') or []:
            lx = math.cos(drop['angle']) * drop['distance']
            ly = math.sin(drop['angle']) * drop['distance']
            radius = drop['land_radius']
            if ichor:
                # Куски нежити лежат неровными обломками, а не каплями.
                spin = drop.get('spin', 0.0)
                shard = QPainterPath(QPointF(
                    lx + math.cos(spin) * radius * 1.3,
                    ly + math.sin(spin) * radius * 1.3))
                shard.lineTo(QPointF(lx + math.cos(spin + 2.2) * radius * 0.8,
                                     ly + math.sin(spin + 2.2) * radius * 0.8))
                shard.lineTo(QPointF(lx + math.cos(spin + 4.1) * radius * 1.1,
                                     ly + math.sin(spin + 4.1) * radius * 1.1))
                shard.closeSubpath()
                path.addPath(shard)
                continue
            shape = QPainterPath()
            shape.addEllipse(QPointF(0, 0),
                             radius * drop.get('land_stretch', 1.2),
                             radius * 0.74)
            place = QTransform().translate(lx, ly)
            place.rotate(math.degrees(drop['angle']))
            path.addPath(place.map(shape))
        hit['_stain_path'] = path
        return path

    def _blood_pool_extras(self, hit: dict) -> dict:
        """Готовые пути брызг, сгустков и бликов вокруг лужи.

        Их бывает до двадцати на пятно, и каждый рисовался отдельным
        вызовом с поворотом — на зуме с десятком пятен это заметный
        расход. Форма статична, поэтому собирается один раз.
        """
        cached = hit.get('_pool_extras')
        if isinstance(cached, dict):
            return cached
        flecks = QPainterPath()
        clots = QPainterPath()
        gloss = QPainterPath()
        for path in (flecks, clots, gloss):
            path.setFillRule(Qt.WindingFill)
        for fleck in hit.get('flecks') or []:
            shape = QPainterPath()
            shape.addEllipse(QPointF(0, 0),
                             fleck['radius'] * fleck.get('stretch', 1.0),
                             fleck['radius'] * 0.68)
            place = QTransform().translate(fleck['dx'], fleck['dy'])
            place.rotate(math.degrees(fleck.get('angle', 0.0)))
            flecks.addPath(place.map(shape))
        for clot in hit.get('clots') or []:
            clots.addEllipse(QPointF(clot['dx'], clot['dy']),
                             clot['radius'], clot['radius'] * 0.72)
        for glint in hit.get('gloss') or []:
            shape = QPainterPath()
            shape.addEllipse(QPointF(0, 0), glint['rx'], glint['ry'])
            place = QTransform().translate(glint['dx'], glint['dy'])
            place.rotate(math.degrees(glint['angle']))
            gloss.addPath(place.map(shape))
        hit['_pool_extras'] = {'flecks': flecks, 'clots': clots,
                              'gloss': gloss}
        return hit['_pool_extras']

    def _draw_blood_pool(self, painter: QPainter, hit: dict,
                         color: QColor, fade: float, spread: float):
        """Лужа из нескольких долей: рваный силуэт, объём и мелкая взвесь.

        Доли складываются в ОДИН путь с WindingFill: перекрытия заливаются
        один раз, поэтому внутри нет тёмных швов от двойной альфы. Сначала
        рисуется тёмная подложка чуть ниже, затем яркая середина — пятно
        получает край и глубину, как на референсах. Сам путь кэшируется,
        кадр только сдвигает и масштабирует его.
        """
        pool = max(0.0, float(hit.get('pool', 0.0)))
        if pool <= 0.5:
            return
        base = self._blood_pool_path(hit)
        if base.isEmpty():
            return
        radius = pool * (0.70 + 0.30 * spread)
        grow = 0.70 + 0.30 * spread
        x, y = float(hit['x']), float(hit['y'])

        def layer(brush, scale: float, dx: float, dy: float):
            painter.save()
            painter.translate(x + dx, y + dy)
            painter.scale(grow * scale, grow * scale)
            painter.setBrush(QBrush(brush))
            painter.drawPath(base)
            painter.restore()

        # Тёмная подложка — нижняя кромка и лёгкая тень.
        painter.setPen(Qt.NoPen)
        shadow = QColor(color).darker(150)
        shadow.setAlpha(int(120 * fade))
        layer(shadow, 1.02, -radius * 0.015, radius * 0.045)

        outer = QColor(color).darker(112)
        outer.setAlpha(int(232 * fade))
        layer(outer, 1.0, 0.0, 0.0)

        # Внутренний слой светлее: пятно перестаёт быть плоской заливкой.
        # Он смещён вверх-влево, поэтому тёмный кант остаётся неровным.
        inner = QColor(min(255, color.red() + 58),
                       max(0, color.green() + 8),
                       max(0, color.blue() + 6))
        inner.setAlpha(int(222 * fade))
        layer(inner, 0.86, -radius * 0.025, -radius * 0.035)

        # Сгустки, брызги и блики — три заливки из готовых путей: их
        # до тридцати на пятно, и каждый отдельный вызов на кадре заметно
        # стоил на сильном зуме, где кровь как раз и разглядывают.
        extras = self._blood_pool_extras(hit)
        painter.setPen(Qt.NoPen)
        painter.save()
        painter.translate(x, y)
        if not extras['clots'].isEmpty():
            # Тёмные сгустки внутри — кровь не бывает однотонной.
            clot_color = QColor(max(0, color.red() - 58),
                                max(0, color.green() - 4),
                                max(0, color.blue() - 4))
            clot_color.setAlpha(int(58 * fade))
            painter.setBrush(QBrush(clot_color))
            painter.drawPath(extras['clots'])
        if not extras['gloss'].isEmpty():
            # Влажный блик: короткие светлые мазки сверху слева. Именно они
            # отличают свежую кровь от бурого пятна на референсах.
            painter.setBrush(QBrush(QColor(255, 195, 195, int(40 * fade))))
            painter.drawPath(extras['gloss'])
        painter.restore()

    def _draw_blood_pool_flecks(self, painter: QPainter, hit: dict,
                                color: QColor, fade: float):
        """Мелкие брызги вокруг лужи — главное отличие от «кляксы».

        Рисуются отдельно от самой лужи: брызги улетают на полторы клетки,
        и вместе с ними габарит картинки вырастал в четыре раза — картинка
        теряла плотность и на среднем зуме переходила на вектор. Сами
        брызги дешёвые: один готовый путь на всё пятно.
        """
        extras = self._blood_pool_extras(hit)
        if extras['flecks'].isEmpty():
            return
        fleck_color = QColor(color)
        fleck_color.setAlpha(int(200 * fade))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(fleck_color))
        painter.save()
        painter.translate(float(hit['x']), float(hit['y']))
        painter.drawPath(extras['flecks'])
        painter.restore()

    def _draw_blood_drop_stains(self, painter: QPainter, hit: dict,
                                color: QColor, fade: float):
        """Пятна упавших капель вокруг лужи.

        Рисуются всегда — и в векторном кадре, и поверх запечённой лужи.
        Раньше, когда пятно переходило на картинку, эта ветка пропускалась,
        и вокруг лужи пропадали мелкие капли: рисунок всплеска упрощался
        и «перещёлкивался» в момент перехода.
        """
        stains = self._blood_drop_stains_path(hit)
        if stains.isEmpty():
            return
        stain = QColor(color)
        stain.setAlpha(int(180 * fade))
        painter.save()
        painter.translate(float(hit['x']), float(hit['y']))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(stain))
        painter.drawPath(stains)
        painter.restore()

    def _draw_blood_spikes(self, painter: QPainter, hit: dict,
                           color: QColor, fade: float, crown: float):
        """Короткие острые лучи от кляксы — самый «брызговый» слой."""
        pool = max(0.0, float(hit.get('pool', 0.0)))
        if pool <= 0.5 or crown <= 0.0:
            return
        ray = QColor(color)
        ray.setAlpha(int(205 * fade * crown))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(ray))
        x, y = float(hit['x']), float(hit['y'])
        for spike in hit.get('spikes') or []:
            angle = spike['angle']
            base = pool * 0.92
            tip_radius = pool * spike['factor'] * (0.55 + 0.45 * crown)
            half = spike['width']
            path = QPainterPath()
            path.moveTo(x + math.cos(angle - half) * base,
                        y + math.sin(angle - half) * base)
            path.lineTo(x + math.cos(angle) * tip_radius,
                        y + math.sin(angle) * tip_radius)
            path.lineTo(x + math.cos(angle + half) * base,
                        y + math.sin(angle + half) * base)
            path.closeSubpath()
            painter.drawPath(path)

    @staticmethod
    def _draw_blood_drop(painter: QPainter, x: float, y: float,
                         radius: float, angle: float, stretch: float,
                         color: QColor):
        """Капля или её след: вытянута по направлению полёта."""
        if radius <= 0.3 or color.alpha() <= 0:
            return
        painter.save()
        painter.translate(x, y)
        painter.rotate(math.degrees(angle))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(color))
        painter.drawEllipse(QPointF(0, 0), radius * stretch, radius * 0.74)
        painter.restore()

    def _draw_blood_streaks(self, painter: QPainter, hit: dict,
                            color: QColor, fade: float, crown: float,
                            spread: float):
        """Тонкие разлетевшиеся мазки и мелкая взвесь."""
        if crown <= 0.0:
            return
        pool = max(0.0, float(hit.get('pool', 0.0)))
        x, y = float(hit['x']), float(hit['y'])
        for streak in hit.get('streaks') or []:
            angle = streak['angle']
            start = pool * streak['start']
            length = streak['length'] * (0.45 + 0.55 * crown)
            x0 = x + math.cos(angle) * start
            y0 = y + math.sin(angle) * start
            x1 = x + math.cos(angle) * (start + length)
            y1 = y + math.sin(angle) * (start + length)
            mx = (x0 + x1) / 2.0 - math.sin(angle) * streak['bend']
            my = (y0 + y1) / 2.0 + math.cos(angle) * streak['bend']
            path = QPainterPath(QPointF(x0, y0))
            path.quadTo(QPointF(mx, my), QPointF(x1, y1))
            pen = QPen(QColor(color.red(), color.green(), color.blue(),
                              int(150 * fade * crown)))
            pen.setWidthF(max(0.6, streak['width'] * (0.5 + 0.5 * crown)))
            pen.setCapStyle(Qt.RoundCap)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawPath(path)

        for dot in hit.get('mist') or []:
            distance = dot['distance'] * (0.50 + 0.50 * spread)
            alpha = int(125 * fade * crown)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(color.red(), color.green(),
                                          color.blue(), alpha)))
            painter.save()
            painter.translate(x + math.cos(dot['angle']) * distance,
                              y + math.sin(dot['angle']) * distance)
            painter.rotate(math.degrees(dot['angle']))
            painter.drawEllipse(QPointF(0, 0),
                                dot['radius'] * dot.get('stretch', 1.0),
                                dot['radius'] * 0.78)
            painter.restore()

    def draw_blood(self, painter: QPainter):
        """Кровь на карте — под токенами.

        Жизнь пятна: 5 минут свежая и влажная, затем 30 минут медленно
        подсыхает и исчезает. После неё остаются только мелкие порезы и
        тёмные пятна — след боя, как в Age of Empires.
        """
        if (not self.combat_effects_enabled or not self._blood_hits
                or self.current_map is None):
            return
        blood_alpha = 1.0 - max(0, min(100, self.blood_transparency)) / 100.0
        if blood_alpha <= 0.01:
            return
        painter.save()
        painter.setOpacity(blood_alpha)
        # Следы пекутся в картинки постепенно: нельзя один кадр потратить
        # на все пятна сразу — получится заметный рывок.
        self._blood_bake_left = BLOOD_BAKE_PER_FRAME
        # Отдельный бюджет на сборку слоёв фактуры: у неё свой счётчик,
        # иначе печёные пятна съедали бы весь лимит и мелкая крупа
        # появлялась бы только через полсекунды после приближения.
        self._blood_frame_token = getattr(self, '_blood_frame_token', 0) + 1
        now = time.monotonic()
        map_id = self.current_map.id
        # Пятна за пределами экрана не рисуем: при зуме и панорамировании
        # десятки старых всплесков иначе пересобирали бы свои пути зря.
        # Запас — в пикселях экрана, а не в мире: на сильном зуме 256
        # мировых единиц — это километры за краем, и холст честно собирал
        # бы детали невидимых пятен (это и было главной просадкой крови).
        margin = BLOOD_CULL_MARGIN_PX / max(0.01, float(self.scale or 1.0))
        view = self._visible_world_rect().adjusted(-margin, -margin,
                                                   margin, margin)
        # Раз в несколько секунд отпускаем картинки пятен далеко за краем:
        # память под них копится всю сессию, а возвращаться к ним незачем.
        if now - getattr(self, '_blood_release_at', 0.0) > 3.0:
            self._blood_release_at = now
            self._blood_release_sprites(
                self._visible_world_rect().adjusted(-margin * 4, -margin * 4,
                                                    margin * 4, margin * 4))
        # Границы кадра нужны и отдельным кляксам, пока пятно растекается:
        # на сильном зуме большинство из них уже за краем экрана.
        self._blood_view = view
        for hit in self._blood_hits:
            if hit.get('map_id') != map_id:
                continue
            # Не «центр в кадре», а «хоть часть пятна в кадре»: на
            # сильном зуме центр лужи давно за краем, а сама она на экране.
            if not self._blood_bounds(hit).intersects(view):
                continue
            age = now - hit['start']
            if age < 0.0:
                continue
            kind = hit.get('kind', 'blood')
            dryness = 0.0
            if kind == 'ichor':
                # Куски нежити не сохнут: короткий разлёт и растворение.
                fade = 1.0 - age / max(0.05, hit.get('life', ICHOR_LIFE_S))
                if fade <= 0.0:
                    continue
            else:
                # Сначала кровь сохнет (цвет темнеет на месте), и только
                # затем тихо исчезает. К пятой минуте она уже выглядит
                # сухой коркой, а к пятнадцатой — остаются только порезы.
                fade = 1.0
                if age > BLOOD_WET_S:
                    dryness = min(1.0, (age - BLOOD_WET_S)
                                  / max(1.0, BLOOD_DRY_S))
                    if age <= BLOOD_WET_S + BLOOD_DRY_S:
                        fade = 1.0 - 0.22 * dryness
                    else:
                        remain = 1.0 - ((age - BLOOD_WET_S - BLOOD_DRY_S)
                                        / BLOOD_FADE_S)
                        if remain <= 0.0:
                            self._draw_blood_marks(painter, hit)
                            continue
                        fade = 0.78 * remain
                        # Пока лужа тихо тает, под ней уже проступает
                        # постоянный сухой след. Иначе кровь исчезает
                        # полностью и лишь в конце срока «всплывают»
                        # порезы: на карте несколько минут пусто.
                        # Кроссфейд доводит след до полной силы к концу
                        # высыхания — дальше он живёт всегда.
                        residue = min(1.0, (1.0 - remain) * 1.35)
                        if residue > 0.02:
                            painter.save()
                            painter.setOpacity(painter.opacity() * residue)
                            self._draw_blood_marks(painter, hit)
                            painter.restore()
            fade = max(0.0, min(1.0, fade))
            color = self._blood_color(fade, kind, dryness)

            # Лужа растекается первые пару секунд, потом только сохнет.
            # У нежити лужи нет — куски просто разлетаются.
            spread = min(1.0, age / BLOOD_POOL_SPREAD_S)
            spread = 1.0 - (1.0 - spread) ** 2
            crown = (max(0.0, 1.0 - age / 0.62)
                     if kind == 'blood' else 0.0)
            if kind == 'blood' and hit.get('pool', 0.0) > 0:
                # Всплеск закончился — пятно уже не меняет форму. Такой
                # след рисуем из кэшированной картинки: иначе при каждом
                # сдвиге мыши пятна пересобирали бы десятки путей.
                # Форма пятна окончательна только к концу растекания:
                # раньше этого печь нельзя — картинка зафиксировала бы
                # недолитую лужу и «перещёлкнула» бы рисунок.
                if age > BLOOD_POOL_SPREAD_S:
                    sprite = self._blood_sprite_for_paint(hit, fade, dryness)
                    if sprite is not None:
                        # Кляксы и мелкие брызги рисуются отдельно: они
                        # улетают далеко, а картинка печётся только на
                        # лужу — так её плотность упирается в лимит
                        # памяти, а не в разлёт брызг.
                        self._draw_blood_satellites(painter, hit, color, fade,
                                                    1.0)
                        self._draw_blood_pool_flecks(painter, hit, color,
                                                     fade)
                        painter.save()
                        # Общая прозрачность крови — уже у painter: умножаем,
                        # а не заменяем её.
                        painter.setOpacity(painter.opacity() * fade)
                        pix, bounds = sprite
                        painter.drawPixmap(
                            bounds, pix,
                            QRectF(0, 0, pix.width(), pix.height()))
                        painter.restore()
                        # Фактура — вектором каждый кадр: она зависит от
                        # зума, и вмораживать её в картинку нельзя, иначе
                        # приближение меняло бы рисунок крови.
                        self._draw_blood_detail(painter, hit, color, fade)
                        # Пятна упавших капель — часть рисунка всплеска:
                        # без них при переходе на картинку пятно вокруг лужи
                        # теряло мелкие капли и выглядело упрощённым.
                        self._draw_blood_drop_stains(painter, hit, color, fade)
                        continue
                # Сначала лучи и отлетевшие кляксы, затем сама лужа
                # перекрывает их основания — получается единый силуэт.
                if crown > 0.0:
                    self._draw_blood_spikes(painter, hit, color, fade, crown)
                self._draw_blood_satellites(painter, hit, color, fade,
                                            spread)
                self._draw_blood_pool_flecks(painter, hit, color, fade)
                self._draw_blood_fingers(painter, hit, color, fade, spread)
                self._draw_blood_pool(painter, hit, color, fade, spread)
                self._draw_blood_detail(painter, hit, color, fade)
                if crown > 0.0:
                    self._draw_blood_streaks(painter, hit, color, fade,
                                             crown, spread)

            # Капли: короткий полёт, хвостик, затем маленькое пятно.
            if age > BLOOD_SPLASH_S + 1.0:
                # Все капли давно упали — одним путём вместо десятков
                # отдельных пятнышек с поворотами.
                self._draw_blood_drop_stains(painter, hit, color, fade)
                continue
            for drop in hit['drops']:
                progress = (age - drop['delay']) / max(0.05, drop['life'])
                if progress < 0.0:
                    continue
                angle = drop['angle']
                if progress < 1.0:
                    eased = 1.0 - (1.0 - progress) ** 2.4
                    px = hit['x'] + math.cos(angle) * drop['distance'] * eased
                    py = hit['y'] + math.sin(angle) * drop['distance'] * eased
                    radius = drop['radius'] * (1.0 - 0.35 * progress)
                    drop_color = QColor(color)
                    drop_color.setAlpha(int(215 * fade))
                    # Короткий хвост — только пока капля летит быстро: иначе
                    # брызги выглядят как нарисованные палочки.
                    tail = max(0.0, eased - 0.07) if progress < 0.55 else 0.0
                    if tail > 0.0:
                        pen = QPen(QColor(drop_color.red(),
                                          drop_color.green(),
                                          drop_color.blue(),
                                          int(drop_color.alpha() * 0.40)))
                        pen.setWidthF(max(0.6, radius * 0.9))
                        pen.setCapStyle(Qt.RoundCap)
                        painter.setPen(pen)
                        painter.drawLine(
                            QPointF(hit['x'] + math.cos(angle)
                                    * drop['distance'] * tail,
                                    hit['y'] + math.sin(angle)
                                    * drop['distance'] * tail),
                            QPointF(px, py))
                    painter.setPen(Qt.NoPen)
                    painter.setBrush(QBrush(drop_color))
                    if kind == 'ichor':
                        # Куски — неровные обломки, а не капли крови.
                        shard = QPolygonF([
                            QPointF(px + math.cos(drop['spin']) * radius * 1.3,
                                    py + math.sin(drop['spin']) * radius * 1.3),
                            QPointF(px + math.cos(drop['spin'] + 2.2)
                                    * radius * 0.8,
                                    py + math.sin(drop['spin'] + 2.2)
                                    * radius * 0.8),
                            QPointF(px + math.cos(drop['spin'] + 4.1)
                                    * radius * 1.1,
                                    py + math.sin(drop['spin'] + 4.1)
                                    * radius * 1.1),
                        ])
                        painter.drawPolygon(shard)
                    else:
                        self._draw_blood_drop(
                            painter, px, py, radius, angle,
                            drop.get('stretch', 1.4), drop_color)
                else:
                    # Капля упала и осталась маленьким пятном. Краска того же
                    # цвета, но след вытянут по траектории, как на референсах.
                    stain = QColor(color)
                    stain.setAlpha(int(180 * fade))
                    radius = drop['land_radius']
                    lx = hit['x'] + math.cos(angle) * drop['distance']
                    ly = hit['y'] + math.sin(angle) * drop['distance']
                    if kind == 'ichor':
                        painter.setPen(Qt.NoPen)
                        painter.setBrush(QBrush(stain))
                        spin = drop.get('spin', 0.0)
                        painter.drawPolygon(QPolygonF([
                            QPointF(lx + math.cos(spin) * radius * 1.3,
                                    ly + math.sin(spin) * radius * 1.3),
                            QPointF(lx + math.cos(spin + 2.2) * radius * 0.8,
                                    ly + math.sin(spin + 2.2) * radius * 0.8),
                            QPointF(lx + math.cos(spin + 4.1) * radius * 1.1,
                                    ly + math.sin(spin + 4.1) * radius * 1.1),
                        ]))
                    else:
                        self._draw_blood_drop(
                            painter, lx, ly, radius, angle,
                            drop.get('land_stretch', 1.2), stain)

        # Границы кадра живут один кадр: иначе следующий вызов отсекал бы
        # детали по устаревшему кадру (и запекание получило бы обрезанный след).
        self._blood_view = None
        painter.restore()

    def _blood_marks_sprite(self, hit: dict):
        """Высохший след один раз печётся в картинку: (пиксмап, габариты).

        После того как пятно исчезло, отметины живут на карте до конца
        сцены и раньше перерисовывались на каждом кадре: при десятке боёв
        это сотни линий и многоугольников на каждое движение мыши. Царапины
        и корки не меняются — значит, их место в пиксмапе, как у влажного
        пятна.
        """
        bounds = self._blood_mark_bounds(hit)
        if bounds.width() <= 1.0:
            return None
        if not hit.get('marks'):
            return None
        density = self._blood_bake_density(bounds)
        if density <= 0.0:
            # На сильном зуме картинка вышла бы мыльной или тяжёлой:
            # сухие порезы рисуются вектором, он резкий всегда.
            return None
        cached = hit.get('_marks_pix')
        # Плотность и сила крупы — часть ключа: раньше след пёкся один раз
        # навсегда, и после приближения оставался мыльным до конца сцены,
        # а теперь ещё и меняет фактуру с зумом.
        detail = self._blood_detail_alpha()
        if (isinstance(cached, QPixmap)
                and hit.get('_marks_rect') == bounds
                and hit.get('_marks_density') == density):
            return cached, bounds
        # Печём не больше нескольких следов за кадр — как и влажные пятна:
        # после большого боя иначе один кадр собрал бы десятки картинок.
        if getattr(self, '_blood_bake_left', 1) <= 0:
            return None
        self._blood_bake_left -= 1
        width = max(2, int(round(bounds.width() * density)))
        height = max(2, int(round(bounds.height() * density)))
        if width > BLOOD_SPRITE_MAX_SIDE or height > BLOOD_SPRITE_MAX_SIDE:
            return None
        cost = width * height
        total = getattr(self, '_blood_sprite_px', 0)
        previous = int(hit.get('_marks_pix_px') or 0)
        if total - previous + cost > BLOOD_SPRITE_BUDGET_PX:
            return None
        pix = QPixmap(width, height)
        pix.fill(Qt.transparent)
        painter = QPainter(pix)
        try:
            painter.setRenderHint(QPainter.Antialiasing, True)
            painter.scale(density, density)
            painter.translate(-bounds.left(), -bounds.top())
            self._paint_blood_marks(painter, hit)
        finally:
            painter.end()
        hit['_marks_pix'] = pix
        hit['_marks_rect'] = bounds
        hit['_marks_density'] = density
        hit['_marks_detail'] = round(detail * 6)
        hit['_marks_pix_px'] = cost
        self._blood_sprite_px = total - previous + cost
        self._blood_bake_count = getattr(self, '_blood_bake_count', 0) + 1
        return pix, bounds

    def _draw_blood_marks(self, painter: QPainter, hit: dict):
        """Показать высохший след: бурая корка, царапины и крошки."""
        sprite = self._blood_marks_sprite_for_paint(hit)
        if sprite is None:
            # Бюджет перепёка на этот кадр кончился или зум такой, что
            # картинка стала бы мыльной — рисуем векторами, чтобы след
            # не мигал, и добавляем фактуру отдельными путями.
            self._paint_blood_marks(painter, hit)
            self._draw_blood_detail(
                painter, hit,
                self._blood_color(1.0, hit.get('kind', 'blood'), 1.0),
                1.0, dry=True)
        else:
            pix, bounds = sprite
            painter.drawPixmap(bounds, pix,
                               QRectF(0, 0, pix.width(), pix.height()))
            # Крупа и трещины — вектором: они зависят от зума, а картинка
            # следа должна оставаться неизменной на любом масштабе.
            self._draw_blood_detail(
                painter, hit,
                self._blood_color(1.0, hit.get('kind', 'blood'), 1.0),
                1.0, dry=True)

    def _paint_blood_marks(self, painter: QPainter, hit: dict):
        """Нарисовать высохшую кровь в мировых координатах.

        Как на месте боя в Age of Empires: не лужа, а шероховатый след —
        тихое бурое пятно на земле, вокруг рваные порезы с неровным краем
        и мелкие тёмные крошки. Всё с разной плотностью, чтобы след не
        выглядел штампом.
        """
        cx, cy = float(hit['x']), float(hit['y'])
        cell = max(1.0, float(self.grid_cell_world or 0.0) or 50.0)
        pool = float(hit.get('pool') or 0.0)
        # Стабильный «шум» для одного и того же следа: перепекание картинки
        # не должно менять рисунок.
        seed = (int(cx * 7) ^ int(cy * 13) ^ len(hit.get('marks') or []))
        rng = random.Random(seed)

        # 1. Корка: бурое пятно с неровным краем. Центр плотнее — там кровь
        # впиталась глубже, к краю она сходит на нет, как на референсах.
        crust = max(cell * 0.22, pool * 0.86)
        # Рваный контур корки: ровный круг читался бы как наклейка.
        outline = []
        sides = 18
        for index in range(sides):
            angle = 2.0 * math.pi * index / sides
            radius = crust * rng.uniform(0.80, 1.12)
            outline.append(QPointF(cx + math.cos(angle) * radius,
                                   cy + math.sin(angle) * radius * 0.88))
        grad = QRadialGradient(QPointF(cx, cy), crust)
        grad.setColorAt(0.0, QColor(96, 38, 28, 165))
        grad.setColorAt(0.45, QColor(92, 38, 28, 130))
        grad.setColorAt(0.78, QColor(96, 44, 32, 74))
        grad.setColorAt(1.0, QColor(100, 48, 36, 0))
        # Край корки — сглаженная кривая, а не многоугольник: на сильном зуме
        # грани полигона читались бы как гранёная фигура.
        crust_path = self._blood_catmull_path(outline)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(grad))
        painter.drawPath(crust_path)
        # Второй, меньший слой корки: край высох неровно, местами он
        # плотнее — так силуэт не выглядит ровным пятном.
        inner = self._blood_catmull_path([
            QPointF(cx + (point.x() - cx) * rng.uniform(0.42, 0.62),
                    cy + (point.y() - cy) * rng.uniform(0.42, 0.62))
            for point in outline])
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(78, 29, 22, 70)))
        painter.drawPath(inner)
        # Сгустки запёкшейся крови — неровные комки в корке.
        painter.setPen(Qt.NoPen)
        for _ in range(rng.randint(4, 7)):
            angle = rng.uniform(0.0, 2.0 * math.pi)
            distance = crust * rng.uniform(0.0, 0.62)
            blob_r = max(0.7, rng.uniform(0.035, 0.085) * cell)
            points = []
            sides = rng.randint(5, 7)
            for index in range(sides):
                blob_angle = (2.0 * math.pi * index / sides
                              + rng.uniform(-0.2, 0.2))
                r = blob_r * rng.uniform(0.68, 1.16)
                points.append(QPointF(
                    cx + math.cos(angle) * distance
                    + math.cos(blob_angle) * r,
                    cy + math.sin(angle) * distance * 0.86
                    + math.sin(blob_angle) * r * 0.82))
            painter.setBrush(QBrush(QColor(74, 27, 21,
                                           rng.randint(120, 190))))
            # Сгусток — сглаженный комок, а не многоугольник: на сильном
            # зуме пять-семь граней читались как гранёный камень.
            painter.drawPath(self._blood_catmull_path(points))

        # 2. Порезы: рваная линия в два прохода — толще по центру, тоньше
        # к концам, плюс короткий отросток. Так царапина читается как
        # след когтя/клинка, а не как проведённая линейкой черта.
        for mark in hit.get('marks') or []:
            x = cx + mark['dx']
            y = cy + mark['dy']
            if 'length' in mark:
                angle = float(mark['angle'])
                length = max(0.8, float(mark['length']))
                width = max(0.5, float(mark['width']))
                dx = math.cos(angle) * length / 2.0
                dy = math.sin(angle) * length / 2.0
                tone = rng.randint(-10, 14)
                base = QColor(max(0, 70 + tone), max(0, 27 + tone // 2),
                              21, rng.randint(180, 235))
                # Порез сужается к концам: линия одной толщины с
                # круглыми концами на зуме выдаёт рисунок инструментом.
                spread_w = max(0.35, width * 0.85)
                nx, ny = -dy / max(0.001, length), dx / max(0.001, length)
                cut = QPainterPath(QPointF(x - dx, y - dy))
                cut.cubicTo(
                    QPointF(x - dx * 0.40 + nx * spread_w,
                            y - dy * 0.40 + ny * spread_w),
                    QPointF(x + dx * 0.40 + nx * spread_w,
                            y + dy * 0.40 + ny * spread_w),
                    QPointF(x + dx, y + dy))
                cut.cubicTo(
                    QPointF(x + dx * 0.40 - nx * spread_w,
                            y + dy * 0.40 - ny * spread_w),
                    QPointF(x - dx * 0.40 - nx * spread_w,
                            y - dy * 0.40 - ny * spread_w),
                    QPointF(x - dx, y - dy))
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(base))
                painter.drawPath(cut)
                painter.setPen(Qt.NoPen)
                # Рваный край: тонкая линия рядом, чуть короче.
                side = QPen(QColor(base.red(), base.green(), base.blue(),
                                   int(base.alpha() * 0.6)))
                side.setWidthF(max(0.4, width * 0.45))
                side.setCapStyle(Qt.RoundCap)
                painter.setPen(side)
                off = width * 1.2 + 0.3
                nx, ny = -dy / max(0.001, length), dx / max(0.001, length)
                painter.drawLine(
                    QPointF(x - dx * 0.75 + nx * off,
                            y - dy * 0.75 + ny * off),
                    QPointF(x + dx * 0.62 + nx * off,
                            y + dy * 0.62 + ny * off))
                # Короткий отросток — чтобы линия не была симметричной.
                if rng.random() < 0.6:
                    branch = angle + rng.choice((-1, 1)) * rng.uniform(0.5, 1.1)
                    blen = length * rng.uniform(0.22, 0.42)
                    bx, by = math.cos(branch) * blen, math.sin(branch) * blen
                    painter.drawLine(QPointF(x, y), QPointF(x + bx, y + by))
            else:
                # Крошка запёкшейся крови: неровный комок, не кружок.
                radius = max(0.7, float(mark['radius']))
                points = []
                sides = rng.randint(5, 7)
                for index in range(sides):
                    angle = (2.0 * math.pi * index / sides
                             + rng.uniform(-0.16, 0.16))
                    r = radius * rng.uniform(0.72, 1.15)
                    points.append(QPointF(x + math.cos(angle) * r,
                                          y + math.sin(angle) * r * 0.82))
                tone = rng.randint(-8, 12)
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(QColor(max(0, 80 + tone),
                                               max(0, 32 + tone // 2),
                                               25, rng.randint(150, 210))))
                painter.drawPath(self._blood_catmull_path(points))

        # 3. Крошки вокруг: мелкие бурые точки, будто кровь впиталась
        # в камень неровно. Без них след заканчивался бы ровным кругом.
        reach = max(cell * 0.30, pool * 1.05)
        for _ in range(rng.randint(8, 13)):
            angle = rng.uniform(0.0, 2.0 * math.pi)
            distance = reach * rng.uniform(0.28, 1.0)
            radius = max(0.4, cell * rng.uniform(0.007, 0.022))
            painter.setBrush(QBrush(QColor(76, 30, 23, rng.randint(90, 170))))
            painter.drawEllipse(
                QPointF(cx + math.cos(angle) * distance,
                        cy + math.sin(angle) * distance),
                radius, radius * rng.uniform(0.7, 1.0))

        # 4. Сильный зум: мелкая крупа и волосяные царапины. Крупные комки
        # и крошки на предельном приближении разрастаются в пятна, и след
        # снова выглядит нарисованным. Мелкая фракция задаёт размер в
        # пикселях экрана, поэтому читается одинаково на любом масштабе.
        fine = self._blood_detail_alpha()
        if fine <= 0.02:
            return
        scale = max(0.01, float(self.scale or 1.0))
        painter.setPen(Qt.NoPen)
        for _ in range(max(1, int(round(26 * fine)))):
            angle = rng.uniform(0.0, 2.0 * math.pi)
            distance = reach * rng.uniform(0.0, 1.05)
            radius = rng.uniform(0.9, 3.2) / scale
            tone = rng.randint(-10, 16)
            painter.setBrush(QBrush(QColor(max(0, 76 + tone),
                                           max(0, 30 + tone // 2), 24,
                                           int(rng.randint(70, 150) * fine))))
            painter.drawEllipse(
                QPointF(cx + math.cos(angle) * distance,
                        cy + math.sin(angle) * distance),
                radius, radius * rng.uniform(0.6, 1.0))
        hair = QPen(QColor(58, 22, 17, int(150 * fine)))
        hair.setWidthF(max(0.05, 1.3 / scale))
        hair.setCapStyle(Qt.RoundCap)
        painter.setPen(hair)
        painter.setBrush(Qt.NoBrush)
        for _ in range(max(2, int(round(7 * fine)))):
            angle = rng.uniform(0.0, 2.0 * math.pi)
            distance = crust * rng.uniform(0.15, 0.95)
            sx = cx + math.cos(angle) * distance
            sy = cy + math.sin(angle) * distance * 0.88
            # Длина тоже в пикселях экрана: царапина не должна превратиться
            # в борозду во всю лужу при максимальном приближении.
            length = rng.uniform(5.0, 18.0) / scale
            tilt = angle + rng.uniform(-0.9, 0.9)
            bend = rng.uniform(-0.35, 0.35) * length
            path = QPainterPath(QPointF(sx, sy))
            path.quadTo(QPointF((sx + sx + math.cos(tilt) * length) / 2.0
                                - math.sin(tilt) * bend,
                                (sy + sy + math.sin(tilt) * length) / 2.0
                                + math.cos(tilt) * bend),
                        QPointF(sx + math.cos(tilt) * length,
                                sy + math.sin(tilt) * length))
            painter.drawPath(path)
        painter.setPen(Qt.NoPen)

    def _draw_heal_fx(self, painter: QPainter, fx: dict, progress: float):
        """Отрисовать лечение: свечение, кольцо, частицы и зелёное число."""
        tx, ty = self.world_to_screen(*fx['to'])
        base = max(12.0, float(fx.get('base_radius') or 24.0))
        style = fx.get('style')
        spell = style == 'spell'
        buff = style == 'buff'
        hands = style == 'lay_on_hands'
        magic = spell or buff or hands
        if buff:
            core = QColor(205, 232, 255)
            edge = QColor(92, 158, 236)
            spark = QColor(255, 232, 164)
        elif hands:
            core = QColor(255, 246, 214)
            edge = QColor(224, 176, 82)
            spark = QColor(255, 228, 150)
        elif spell:
            core = QColor(200, 255, 150)
            edge = QColor(90, 220, 120)
            spark = QColor(255, 240, 170)
        else:
            core = QColor(150, 255, 180)
            edge = QColor(60, 205, 110)
            spark = QColor(220, 255, 205)

        # Мягкое свечение вокруг цели — оно и читается как «лечение».
        glow_r = max(1.0, base * (1.0 + 1.7 * progress))
        glow = QRadialGradient(QPointF(tx, ty), glow_r)
        start = QColor(edge)
        start.setAlpha(int(90 * (1.0 - progress)))
        middle = QColor(spark)
        middle.setAlpha(int(38 * (1.0 - progress)))
        finish = QColor(edge)
        finish.setAlpha(0)
        glow.setColorAt(0.0, start)
        glow.setColorAt(0.55, middle)
        glow.setColorAt(1.0, finish)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(tx, ty), glow_r, glow_r)

        # Расходящееся кольцо: у заклинания — двойное, у зелья — одно.
        if progress <= 0.9:
            after = progress / 0.9
            ring_color = QColor(core)
            ring_color.setAlpha(int(175 * (1.0 - after)))
            pen = QPen(ring_color)
            pen.setWidthF(2.2 if magic else 1.8)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            radius = base * (0.35 + 1.15 * after)
            painter.drawEllipse(QPointF(tx, ty), radius, radius)
            if magic:
                radius2 = radius * 0.72
                ring2 = QColor(spark)
                ring2.setAlpha(int(120 * (1.0 - after)))
                pen2 = QPen(ring2)
                pen2.setWidthF(1.2)
                painter.setPen(pen2)
                painter.drawEllipse(QPointF(tx, ty), radius2, radius2)

        # Частицы: пузырьки у зелья, четырёхлучевые искры у заклинания.
        for particle in fx.get('particles') or []:
            delay = float(particle.get('delay') or 0.0)
            t = (progress - delay) / max(0.01, 1.0 - delay)
            if t <= 0.0:
                continue
            t = min(1.0, t)
            eased = 1.0 - (1.0 - t) ** 2
            angle = (float(particle.get('angle') or 0.0)
                     + float(particle.get('swirl') or 0.0) * t)
            spread = base * (0.18 + 0.9 * eased) * float(
                particle.get('distance') or 0.5)
            px = tx + math.cos(angle) * spread
            py = (ty + math.sin(angle) * spread * 0.62
                  - float(particle.get('rise') or 30.0) * eased)
            alpha = int(240 * math.sin(math.pi * t))
            if alpha <= 0:
                continue
            color = QColor(spark if magic else core)
            color.setAlpha(alpha)
            size = float(particle.get('size') or 2.0) * (0.7 + 0.5 * t)
            if magic:
                pen = QPen(color)
                pen.setWidthF(max(1.0, size * 0.65))
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawLine(QPointF(px - size * 1.9, py),
                                 QPointF(px + size * 1.9, py))
                painter.drawLine(QPointF(px, py - size * 1.9),
                                 QPointF(px, py + size * 1.9))
            else:
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(color))
                painter.drawEllipse(QPointF(px, py), size, size)

        # Всплывающее число: зелёное, с тёмной обводкой для любой карты.
        text = fx.get('text')
        if not text:
            return
        after = max(0.0, (progress - 0.06) / 0.94)
        alpha = int(255 * max(0.0, 1.0 - after / 0.9))
        if alpha <= 0:
            return
        font = QFont(painter.font())
        font.setBold(True)
        font.setPixelSize(24 if (spell or hands) else 21)
        if len(text) > 8:
            # Подпись эффекта («Сопротивление: огонь») длиннее числа +12.
            # Уменьшаем шрифт, чтобы она не уезжала за карту.
            font.setPixelSize(16 if buff else 18)
        painter.setFont(font)
        rise = 20.0 + 34.0 * after
        text_y = ty - base * 0.9 - rise
        # Центрируем текст: длинная подпись росла вправо от токена.
        text_width = QFontMetricsF(font).horizontalAdvance(text)
        text_x = tx - text_width / 2.0
        painter.setPen(QPen(QColor(0, 0, 0, min(210, alpha))))
        for ox, oy in ((1, 1), (-1, 1), (1, -1), (-1, -1)):
            painter.drawText(QPointF(text_x + ox, text_y + oy), text)
        painter.setPen(QPen(QColor(core.red(), core.green(), core.blue(), alpha)))
        painter.drawText(QPointF(text_x, text_y), text)

    def draw_combat_fx(self, painter: QPainter):
        """Линия удара, кольцо попадания и всплывающее число — в экранных px.

        Эффекты рисуются после восстановления мирового преобразования, чтобы
        толщина линии и размер шрифта не зависели от масштаба карты.
        """
        if not self._combat_fx:
            return
        now = time.monotonic()
        for fx in self._combat_fx:
            progress = (now - fx['start']) / fx['duration']
            if progress < 0.0 or progress > 1.0:
                continue
            if fx.get('reverse'):
                progress = 1.0 - progress
            if fx.get('kind') == 'heal':
                self._draw_heal_fx(painter, fx, progress)
                continue
            if fx.get('kind') == 'damage':
                self._draw_damage_fx(painter, fx, progress)
                continue
            if fx.get('kind') == 'projectile':
                self._draw_spell_projectile(painter, fx, progress)
                continue
            if fx.get('kind') == 'explosion':
                self._draw_spell_explosion(painter, fx, progress)
                continue
            if fx.get('kind') == 'dart':
                self._draw_dart(painter, fx, progress)
                continue
            if fx.get('kind') == 'spell_aura':
                self._draw_spell_aura(painter, fx, progress)
                continue
            if fx.get('kind') == 'impact':
                self._draw_impact(painter, fx, progress)
                continue
            if fx.get('kind') == 'beam':
                self._draw_beam(painter, fx, progress)
                continue
            if fx.get('kind') == 'arc':
                self._draw_arc(painter, fx, progress)
                continue
            tx, ty = self.world_to_screen(*fx['to'])
            ax, ay = self.world_to_screen(*fx['from'])

            # Трассер от атакующего к цели: быстро проявляется и тает.
            trace = max(0.0, 1.0 - progress / 0.5)
            if trace > 0 and fx.get('attacker'):
                pen = QPen(QColor(255, 245, 220, int(150 * trace)))
                pen.setWidthF(2.0)
                painter.setPen(pen)
                painter.drawLine(QPointF(ax, ay), QPointF(tx, ty))

            # Кольцо/вспышка в точке попадания.
            if progress >= ATTACK_IMPACT:
                after = (progress - ATTACK_IMPACT) / (1.0 - ATTACK_IMPACT)
                if after <= 0.6:
                    alpha = int(200 * (1.0 - after / 0.6))
                    if fx.get('critical'):
                        color = QColor(255, 205, 70, alpha)
                    elif fx.get('hit'):
                        color = QColor(235, 80, 70, alpha)
                    else:
                        color = QColor(170, 175, 185, alpha)
                    radius = 8.0 + 34.0 * after
                    pen = QPen(color)
                    pen.setWidthF(3.0 if fx.get('critical') else 2.0)
                    painter.setPen(pen)
                    painter.setBrush(Qt.NoBrush)
                    painter.drawEllipse(QPointF(tx, ty), radius, radius)

            # Всплывающий текст: появляется в момент удара и уходит вверх.
            if progress >= ATTACK_IMPACT and fx.get('text'):
                after = (progress - ATTACK_IMPACT) / (1.0 - ATTACK_IMPACT)
                if after <= 0.85:
                    alpha = int(255 * max(0.0, 1.0 - after / 0.85))
                    if fx.get('critical'):
                        color = QColor(255, 215, 90, alpha)
                    elif fx.get('hit'):
                        color = QColor(255, 120, 110, alpha)
                    elif fx.get('miss'):
                        color = QColor(170, 175, 185, alpha)
                    else:
                        color = QColor(255, 255, 255, alpha)
                    font = QFont(painter.font())
                    font.setBold(True)
                    font.setPixelSize(22 if fx.get('critical') else 18)
                    painter.setFont(font)
                    rise = 18.0 + 34.0 * after
                    text_y = ty - rise
                    # Тёмная обводка делает число читаемым на любой карте.
                    painter.setPen(QPen(QColor(0, 0, 0, min(210, alpha))))
                    for ox, oy in ((1, 1), (-1, 1), (1, -1), (-1, -1)):
                        painter.drawText(QPointF(tx + ox, text_y + oy),
                                         fx['text'])
                    painter.setPen(QPen(color))
                    painter.drawText(QPointF(tx, text_y), fx['text'])

    def _draw_damage_fx(self, painter: QPainter, fx: dict, progress: float):
        """Цифра урона области: подъём, искры и быстрое кольцо."""
        tx, ty = self.world_to_screen(*fx['to'])
        color = self._damage_color(fx.get('damage_type'))
        appear = 0.12
        if progress < appear:
            return
        after = max(0.0, min(1.0, (progress - appear) / (1.0 - appear)))
        alpha = int(255 * max(0.0, 1.0 - after / 0.9))
        if alpha <= 0:
            return
        # Кольцо в момент попадания.
        if after <= 0.45:
            ring = int(190 * (1.0 - after / 0.45))
            pen = QPen(QColor(color.red(), color.green(), color.blue(), ring))
            pen.setWidthF(2.5)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            radius = 10.0 + 26.0 * after
            painter.drawEllipse(QPointF(tx, ty), radius, radius)
        # Искры вверх и в стороны в цвете типа урона.
        for i in range(7):
            angle = -math.pi / 2 + (i - 3) * 0.22
            distance = 12.0 + 26.0 * after + (i % 3) * 4.0
            px = tx + math.cos(angle) * distance
            py = ty + math.sin(angle) * distance * 0.7 - 12.0 * after
            radius = max(1.0, 2.6 * (1.0 - after))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(color.red(), color.green(),
                                           color.blue(), int(alpha * 0.8))))
            painter.drawEllipse(QPointF(px, py), radius, radius)
        font = QFont(painter.font())
        font.setBold(True)
        font.setPixelSize(20)
        painter.setFont(font)
        rise = 20.0 + 42.0 * after
        text_y = ty - rise
        painter.setPen(QPen(QColor(0, 0, 0, min(220, alpha))))
        for ox, oy in ((1, 1), (-1, 1), (1, -1), (-1, -1)):
            painter.drawText(QPointF(tx + ox, text_y + oy), fx['text'])
        painter.setPen(QPen(QColor(color.red(), color.green(),
                                   color.blue(), alpha)))
        painter.drawText(QPointF(tx, text_y), fx['text'])

    # ------------------------------------------------------------------
    # Растровый слой рисунка
    # ------------------------------------------------------------------
    MAX_DRAW_PIXELS = 4096     # предел стороны растрового слоя

    def ensure_draw_layer(self):
        """Создать (или пересоздать) прозрачный растровый слой под размер карты.

        Слой живёт в мировых координатах карты: 1 пиксель слоя = 1 единица
        карты. Для очень больших карт масштаб понижается, чтобы не съесть
        память (4096x4096x4 байта ~ 64 МБ).
        """
        if not self.current_map:
            self.draw_layer = None
            return
        mw = max(1.0, float(self.current_map.width))
        mh = max(1.0, float(self.current_map.height))
        limit = float(self.MAX_DRAW_PIXELS)
        scale = min(1.0, limit / mw, limit / mh)
        w = max(1, int(round(mw * scale)))
        h = max(1, int(round(mh * scale)))

        map_id = self.current_map.id
        if (self.draw_layer is not None and self.draw_layer_map_id == map_id
                and abs(self.draw_layer_scale - scale) < 1e-9
                and self.draw_layer.width() == w and self.draw_layer.height() == h):
            return

        # Операции переигрываем только если карта та же (например, поменялся
        # её размер). При переходе на другую карту список придёт извне —
        # через set_draw_ops.
        same_map = (self.draw_layer_map_id == map_id)
        old_ops = self.draw_ops[:] if same_map else []
        self.draw_layer = QImage(w, h, QImage.Format_ARGB32_Premultiplied)
        self.draw_layer.fill(Qt.transparent)
        self.draw_layer_scale = scale
        self.draw_layer_map_id = map_id
        if old_ops:
            # размер карты поменялся — перерисовываем сохранённые операции
            for op in old_ops:
                self._apply_op_to_layer(op)
            self.draw_ops = old_ops
        else:
            self.draw_ops = []
        self._draw_undo_stack = []

    def _world_to_layer(self, wx: float, wy: float) -> QPointF:
        """Мировые координаты -> пиксели растрового слоя"""
        if not self.current_map:
            return QPointF(wx, wy)
        return QPointF((wx - self.current_map.pos_x) * self.draw_layer_scale,
                       (wy - self.current_map.pos_y) * self.draw_layer_scale)

    def _layer_pen(self, op: dict, painter: QPainter):
        """Настроить перо/кисть под операцию рисования"""
        tool = op.get('tool', 'brush')
        color = QColor(*op.get('color', (255, 255, 255)))
        width = max(1.0, float(op.get('width', 3.0))) * self.draw_layer_scale

        if tool in ('brush', 'line'):
            pen = QPen(color, width)
            pen.setCapStyle(Qt.RoundCap)
            pen.setJoinStyle(Qt.RoundJoin)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
        elif tool == 'eraser':
            # CompositionMode_Clear делает пиксели слоя прозрачными —
            # именно поэтому ластик стирает рисунок, но не карту.
            pen = QPen(Qt.black, width)
            pen.setCapStyle(Qt.RoundCap)
            pen.setJoinStyle(Qt.RoundJoin)
            painter.setPen(pen)
            painter.setBrush(QBrush(Qt.black))
            painter.setCompositionMode(QPainter.CompositionMode_Clear)
        else:
            # Фигуры (круг/квадрат/треугольник): контур, и только при filled=True
            # добавляется заливка полупрозрачным цветом.
            fill = QColor(color)
            fill.setAlpha(int(255 * max(0.0, min(1.0, float(op.get('opacity', 1.0))))))
            pen = QPen(fill, width)
            pen.setCapStyle(Qt.RoundCap)
            pen.setJoinStyle(Qt.RoundJoin)
            painter.setPen(pen)
            if op.get('filled', False):
                brush_col = QColor(color)
                brush_col.setAlpha(int(95 * max(0.0, min(1.0, float(op.get('opacity', 1.0))))))
                painter.setBrush(QBrush(brush_col))
            else:
                painter.setBrush(Qt.NoBrush)

    def _rasterize(self, painter: QPainter, op: dict):
        """Нарисовать одну операцию в текущий painter (без сброса режима)"""
        tool = op.get('tool', 'brush')
        pts = [self._world_to_layer(x, y) for x, y in op.get('points', [])]
        if not pts:
            return
        self._layer_pen(op, painter)

        if tool in ('brush', 'line', 'eraser'):
            if len(pts) == 1:
                # одиночный тычок кистью — точка
                painter.drawPoint(pts[0])
            else:
                for i in range(len(pts) - 1):
                    painter.drawLine(pts[i], pts[i + 1])
        elif tool == 'circle':
            if len(pts) >= 2:
                r = math.hypot(pts[1].x() - pts[0].x(), pts[1].y() - pts[0].y())
                painter.drawEllipse(pts[0], r, r)
            else:
                painter.drawEllipse(pts[0], 1.0, 1.0)
        elif tool == 'square':
            if len(pts) >= 2:
                painter.drawRect(QRectF(pts[0], pts[1]).normalized())
            else:
                painter.drawEllipse(pts[0], 1.0, 1.0)
        elif tool == 'polygon':
            # Фигура строится по ВСЕМ точкам, которые поставил пользователь.
            # Раньше здесь стояло pts[:3], и любая фигура превращалась в
            # треугольник по первым трём вершинам.
            if len(pts) >= 3:
                painter.drawPolygon(QPolygonF(pts))

        painter.setCompositionMode(QPainter.CompositionMode_SourceOver)

    def _apply_op_to_layer(self, op: dict):
        """Применить операцию к растровому слою (и сохранить в истории)"""
        if self.draw_layer is None:
            self.ensure_draw_layer()
        if self.draw_layer is None:
            return
        painter = QPainter(self.draw_layer)
        painter.setRenderHint(QPainter.Antialiasing)
        self._rasterize(painter, op)
        painter.end()

    def commit_draw_op(self, op: dict):
        """Применить операцию локально и отправить в сеть"""
        self._apply_op_to_layer(op)
        self.draw_ops.append(op)
        self.update()
        self.draw_op_committed.emit(op)

    def apply_remote_draw_op(self, op: dict):
        """Пришла операция от другого игрока — применяем без отправки назад"""
        self._apply_op_to_layer(op)
        self.draw_ops.append(op)
        self.update()

    def set_draw_ops(self, ops: list):
        """Полный набор операций (например, из полного состояния сервера)"""
        self.ensure_draw_layer()
        self.draw_ops = []
        self._draw_undo_stack = []
        if self.draw_layer is not None:
            self.draw_layer.fill(Qt.transparent)
        for op in (ops or []):
            self._apply_op_to_layer(op)
            self.draw_ops.append(op)
        self.update()

    def undo_drawing(self, emit: bool = False):
        """Отменить последний штрих.

        При emit=True только СООБЩАЕМ наверх — откат и рассылку делает
        main_window. Иначе отмена случилась бы дважды (тут и там).
        """
        if emit:
            self.undo_drawing_requested.emit()
            return
        if self.draw_layer is None:
            return
        if self.draw_ops:
            self.set_draw_ops(self.draw_ops[:-1])

    def clear_drawings(self, emit: bool = False):
        """Стереть весь рисунок на карте (emit=True — только сообщить наверх)"""
        if emit:
            self.clear_drawings_requested.emit()
            return
        if self.draw_layer is None:
            self.ensure_draw_layer()
        if self.draw_layer is not None:
            self.draw_layer.fill(Qt.transparent)
        self.draw_ops = []
        self.update()

    def draw_draw_layer(self, painter: QPainter):
        """Нанести растровый рисунок на холст"""
        if self.draw_layer is None or self.draw_layer.isNull():
            return
        if not self.current_map:
            return
        # Пустой слой — прозрачная картинка на весь размер карты: её растя-
        # жение под камеру стоило почти 2 мс кадра при том, что рисовать
        # было нечего. Всё, что попадает в слой, идёт через `draw_ops`.
        if not self.draw_ops:
            return
        target = QRectF(self.current_map.pos_x, self.current_map.pos_y,
                        self.draw_layer.width() / self.draw_layer_scale,
                        self.draw_layer.height() / self.draw_layer_scale)
        painter.drawImage(target, self.draw_layer)

    # ------------------------------------------------------------------
    # Текстовые надписи
    # ------------------------------------------------------------------
    #
    # Надпись — объект, а не штрих: её можно выбрать, перетащить, поправить
    # и удалить, не стирая рисунок вокруг (как текстовый слой в Photoshop).
    # Живёт она в мировых координатах, поэтому растёт и ездит вместе с картой.
    def text_by_id(self, text_id) -> Optional[dict]:
        text_id = str(text_id or "")
        for item in self.map_texts:
            if str(item.get("id") or "") == text_id:
                return item
        return None

    def set_map_texts(self, items):
        """Полный набор надписей карты (полное состояние, смена карты)."""
        self.finish_text_edit(commit=True)
        cleaned = []
        for item in (items or []):
            norm = text_rules.normalize(item) if isinstance(item, dict) else None
            if norm is not None:
                cleaned.append(norm)
        self.map_texts = cleaned
        if self.selected_text_id and self.text_by_id(self.selected_text_id) is None:
            self._set_selected_text(None)
        self.update()

    def apply_text_added(self, item: dict):
        """Сервер подтвердил новую надпись (свой id и пределы)."""
        norm = text_rules.normalize(item) if isinstance(item, dict) else None
        if norm is None or self.text_by_id(norm["id"]) is not None:
            return
        self.map_texts.append(norm)
        self.update()

    def apply_text_updated(self, item: dict):
        """Пришла чужая правка: заменяем надпись, но не добавляем новую.

        Обновление без известного id означает, что добавление до нас не
        дошло (например, сервер его отклонил). Дорисовывать такую надпись
        нельзя: у остальных её нет, и она осталась бы призраком.
        """
        norm = text_rules.normalize(item) if isinstance(item, dict) else None
        if norm is None:
            return
        for index, old in enumerate(self.map_texts):
            if str(old.get("id") or "") == norm["id"]:
                self.map_texts[index] = norm
                break
        if self._editing_text_id == norm["id"] and self._text_editor is not None:
            # Эхо собственной правки не должно сбивать курсор в поле.
            self._text_editor.blockSignals(True)
            self._text_editor.setText(norm["text"])
            self._text_editor.blockSignals(False)
        self.update()

    def apply_text_removed(self, text_id: str):
        item = self.text_by_id(text_id)
        if item is None:
            return
        self.map_texts.remove(item)
        if self.selected_text_id == str(text_id):
            self._set_selected_text(None)
        if self._editing_text_id == str(text_id):
            self.finish_text_edit(commit=False)
        self.update()

    def text_font(self, item: dict) -> QFont:
        """Шрифт надписи: размер в мировых пикселях, как толщина кисти."""
        font = QFont(str((item or {}).get("font") or text_rules.DEFAULT_FONT))
        font.setPixelSize(max(1, int(round(float((item or {}).get("size")
                                             or text_rules.DEFAULTS["size"])))))
        font.setBold(bool((item or {}).get("bold")))
        font.setItalic(bool((item or {}).get("italic")))
        font.setUnderline(bool((item or {}).get("underline")))
        font.setStrikeOut(bool((item or {}).get("strike")))
        return font

    def text_rect(self, item: dict) -> QRectF:
        """Прямоугольник надписи в мировых координатах."""
        x = float((item or {}).get("x") or 0.0)
        y = float((item or {}).get("y") or 0.0)
        metrics = QFontMetricsF(self.text_font(item or {}))
        width = max(4.0, metrics.horizontalAdvance(
            str((item or {}).get("text") or "")))
        return QRectF(x, y, width, max(4.0, metrics.height()))

    def text_at(self, wx: float, wy: float) -> Optional[dict]:
        """Надпись под точкой; верхние (новые) важнее."""
        pad = self.design(4.0)
        point = QPointF(wx, wy)
        for item in reversed(self.map_texts):
            if self.text_rect(item).adjusted(-pad, -pad, pad, pad).contains(point):
                return item
        return None

    def draw_map_texts(self, painter: QPainter):
        """Нарисовать надписи: поверх рисунка, но под токенами.

        Под буквами идёт тонкий контур противоположного цвета: белая надпись
        на светлой карте иначе сливается с пергаментом, а контур не зависит
        от выбранного цвета и не требует отдельной настройки.
        """
        for item in self.map_texts:
            if str(item.get("id") or "") == str(self._editing_text_id or ""):
                continue
            font = self.text_font(item)
            painter.setFont(font)
            rect = self.text_rect(item)
            metrics = QFontMetricsF(font)
            point = QPointF(rect.x(), rect.y() + metrics.ascent())
            text = str(item.get("text") or "")
            # Смещение — пиксель оформления в мире: контур растёт вместе с
            # надписью и не живёт на камере. От размера шрифта его брать
            # нельзя: у крупной надписи копии букв разъезжаются на десяток
            # пикселей и выглядят двойным текстом, а не контуром.
            step = self.design(1.3)
            halo = QColor(*text_rules.halo_color(item.get("color")))
            halo.setAlpha(150)
            painter.setPen(QPen(halo))
            for dx, dy in ((-step, 0.0), (step, 0.0),
                           (0.0, -step), (0.0, step)):
                painter.drawText(QPointF(point.x() + dx, point.y() + dy), text)
            painter.setPen(QPen(QColor(*text_rules.rgb(item.get("color")))))
            painter.drawText(point, text)
        # Выбранная надпись получает синюю пунктирную рамку — так видно,
        # что именно поправит панель текста.
        item = self.text_by_id(self.selected_text_id)
        if item is None or not self.is_dm:
            return
        pad = self.design(3.0)
        rect = self.text_rect(item).adjusted(-pad, -pad, pad, pad)
        pen = QPen(QColor(90, 160, 255))
        pen.setWidthF(self.design(1.4))
        pen.setStyle(Qt.DashLine)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawRect(rect)

    def _set_selected_text(self, text_id):
        """Выбрать надпись (или снять выбор) и сказать об этом панели."""
        text_id = str(text_id) if text_id else None
        if text_id == self.selected_text_id:
            return
        self.selected_text_id = text_id
        self.text_selected.emit(text_id)
        self.update()

    def select_text(self, text_id):
        self._set_selected_text(text_id)

    def set_text_style(self, fields: dict, apply_to_selected: bool = True):
        """Оформление новых надписей; выбранную правим сразу."""
        merged = dict(self.text_style)
        for key in text_rules.EDITABLE:
            if key in (fields or {}):
                merged[key] = fields[key]
        norm = text_rules.normalize(merged, text_id="style")
        if norm is not None:
            # Только оформление: координаты и текст здесь были бы лишними —
            # они относятся к конкретной надписи, а не к следующим.
            self.text_style = text_rules.style_of(norm)
        item = self.text_by_id(self.selected_text_id)
        if apply_to_selected and item is not None:
            self.edit_text(item["id"], dict(fields or {}))

    def edit_text(self, text_id: str, patch: dict):
        """Локальная правка + сообщение наверх (сервер — источник правды)."""
        item = self.text_by_id(text_id)
        if item is None or not isinstance(patch, dict):
            return
        updated = text_rules.apply_patch(item, patch)
        index = self.map_texts.index(item)
        self.map_texts[index] = updated
        sent = {key: updated[key] for key in patch if key in updated}
        self.update()
        if sent:
            self.text_updated.emit(str(text_id), sent)

    def delete_selected_text(self) -> bool:
        """Удалить выбранную надпись. Возвращает True, если что-то ушло."""
        text_id = self.selected_text_id
        if not text_id:
            return False
        item = self.text_by_id(text_id)
        if item is not None:
            if self._editing_text_id == text_id:
                self.finish_text_edit(commit=False)
            self.map_texts.remove(item)
        self._set_selected_text(None)
        self.text_removed.emit(str(text_id))
        self.update()
        return True

    def begin_text_edit(self, text_id=None, x: float = 0.0, y: float = 0.0):
        """Открыть плавающее поле правки над надписью.

        Новая надпись попадает на сервер только после подтверждения: иначе
        каждый клик по пустому месту оставлял бы в мире пустую запись.
        """
        if not self.is_dm or self.current_map is None:
            # Без открытой карты надпись некуда записать: она хранится за
            # конкретной картой, а не за столом вообще.
            return
        self.finish_text_edit(commit=True)
        item = self.text_by_id(text_id)
        is_new = item is None
        if item is None:
            item = text_rules.new_text(x, y,
                                       **text_rules.style_of(self.text_style))
            item["text"] = ""
            self.map_texts.append(item)
        self._text_edit_new = is_new
        self._text_edit_original = dict(item)
        self._editing_text_id = item["id"]
        self._set_selected_text(item["id"])
        editor = QLineEdit(self)
        editor.setObjectName("canvas_text_editor")
        editor.setText(str(item.get("text") or ""))
        editor.setFrame(False)
        editor.setToolTip("Enter — готово, Esc — отмена")
        editor.textChanged.connect(self._on_text_editor_changed)
        editor.returnPressed.connect(lambda: self.finish_text_edit(commit=True))
        editor.installEventFilter(self)
        editor.show()
        self._text_editor = editor
        self.update_text_editor_geometry()
        editor.setFocus(Qt.MouseFocusReason)
        editor.selectAll()
        self.update()

    def _on_text_editor_changed(self, text: str):
        item = self.text_by_id(self._editing_text_id)
        if item is None:
            return
        item["text"] = " ".join(str(text).split())
        self.update_text_editor_geometry()
        self.update()

    def update_text_editor_geometry(self):
        """Держать поле правки поверх надписи при зуме и переносе карты."""
        editor = self._text_editor
        item = self.text_by_id(self._editing_text_id)
        if editor is None or item is None:
            return
        rect = self.text_rect(item)
        sx, sy = self.world_to_screen(rect.x(), rect.y())
        width = max(120.0, rect.width() * self.scale + 26.0)
        height = max(24.0, rect.height() * self.scale + 8.0)
        editor.setGeometry(int(sx) - 4, int(sy) - 4, int(width), int(height))
        font = self.text_font(item)
        font.setPixelSize(max(1, int(round(
            float(item.get("size") or 20) * self.scale))))
        editor.setFont(font)
        colour = QColor(*text_rules.rgb(item.get("color")))
        editor.setStyleSheet(
            "QLineEdit { background: rgba(20, 20, 22, 150);"
            f" color: {colour.name()}; border: 1px dashed #5aa0ff;"
            " padding: 0px 3px; }")

    def finish_text_edit(self, commit: bool = True):
        """Закрыть правку: Enter сохраняет, Esc возвращает как было."""
        text_id = self._editing_text_id
        editor = self._text_editor
        original = self._text_edit_original
        is_new = bool(getattr(self, "_text_edit_new", False))
        self._editing_text_id = None
        self._text_editor = None
        self._text_edit_original = None
        self._text_edit_new = False
        if editor is None or text_id is None:
            return
        text = " ".join(str(editor.text()).split())
        editor.blockSignals(True)
        editor.hide()
        editor.deleteLater()
        item = self.text_by_id(text_id)
        if item is None:
            self.update()
            return
        if not commit:
            text = str((original or {}).get("text") or "")
        if not text:
            self.map_texts.remove(item)
            self._set_selected_text(None)
            if not is_new:
                self.text_removed.emit(str(text_id))
            self.update()
            return
        item["text"] = text
        if is_new:
            index = self.map_texts.index(item)
            self.map_texts[index] = text_rules.apply_patch(
                item, {"text": text})
            self.text_added.emit(self.map_texts[index])
        else:
            self.edit_text(str(text_id), {"text": text})
        self.update()

    def eventFilter(self, watched, event):
        """Esc в поле правки — отмена; остальное поле обрабатывает само.

        Сначала надо отобрать Esc у глобального хоткея окна: обычный QShortcut
        срабатывает раньше клавиатурного события поля, и тогда «Esc — отмена»
        из подсказки просто ничего не делал, а набранное оставалось на карте.
        """
        if self._text_editor is not None and watched is self._text_editor:
            if (event.type() == QEvent.ShortcutOverride
                    and event.key() == Qt.Key_Escape):
                event.accept()
                return True
            if (event.type() == QEvent.KeyPress
                    and event.key() == Qt.Key_Escape):
                self.finish_text_edit(commit=False)
                return True
        return super().eventFilter(watched, event)

    # ------------------------------------------------------------------
    # Координаты
    # ------------------------------------------------------------------
    def screen_to_world(self, sx: float, sy: float) -> Tuple[float, float]:
        return (sx - self.offset_x) / self.scale, (sy - self.offset_y) / self.scale

    def world_to_screen(self, wx: float, wy: float) -> Tuple[float, float]:
        return wx * self.scale + self.offset_x, wy * self.scale + self.offset_y

    def _visible_world_rect(self) -> QRectF:
        """Какая часть мира видна при текущем масштабе и смещении."""
        scale = float(self.scale or 1.0)
        if scale <= 0.0:
            scale = 1.0
        return QRectF(-self.offset_x / scale, -self.offset_y / scale,
                      max(1.0, self.width()) / scale,
                      max(1.0, self.height()) / scale)

    def view_center_world(self) -> Tuple[float, float]:
        """Мировая точка в центре окна — туда сейчас смотрит мастер."""
        return self.screen_to_world(self.width() / 2.0, self.height() / 2.0)

    def view_center_snapped(self) -> Tuple[float, float]:
        """Центр экрана, привязанный к клетке: куда ставить новый токен."""
        return self.snap_to_grid(*self.view_center_world())

    def view_center_placement(self) -> Tuple[float, float]:
        """Центр экрана для переноса токена на карту — без обрезки по полотну.

        Привязка к сетке прижимает клетку к карте. Из-за этого токен,
        перенесённый «На эту карту», вставал у её края, хотя мастер смотрит
        в середину комнаты (или вообще за край полотна). Здесь клетка
        округляется без обрезки: токен появляется точно по центру экрана.
        """
        x, y = self.view_center_world()
        m = self.current_map
        if m is None or not m.grid.valid:
            return x, y
        return m.grid.snap(x, y, m.pos_x, m.pos_y, m.width, m.height,
                           clamp=False)

    def snap_to_grid(self, x: float, y: float) -> Tuple[float, float]:
        """Центр ближайшей клетки. Отсчёт от угла карты: первая клетка в углу."""
        m = self.current_map
        if m is None or not m.grid.valid:
            return x, y
        return m.grid.snap(x, y, m.pos_x, m.pos_y, m.width, m.height)

    # ---------------------------------------------------------------
    # Сетка. Единственный источник истины — сетка карты (current_map.grid).
    # Своей копии холст не держит: иначе выходило два состояния, которые
    # приходилось сверять вручную, и одно неизбежно отставало от другого.
    # ---------------------------------------------------------------
    @property
    def grid(self) -> GridConfig:
        m = self.current_map
        return m.grid if m is not None else GridConfig()

    @property
    def grid_cols(self) -> int:
        return self.grid.cols

    @property
    def grid_rows(self) -> int:
        return self.grid.rows

    @property
    def grid_size(self) -> float:
        """Размер клетки в пикселях картинки (вычисляется, не хранится)."""
        m = self.current_map
        if m is None or not m.img_width or not m.grid.cols:
            return 0.0
        return m.grid.cell_sizes(m.img_width, m.img_height)[0]

    @property
    def grid_visible(self) -> bool:
        return self.grid.visible

    @grid_visible.setter
    def grid_visible(self, value):
        m = self.current_map
        if m is None:
            return
        m.grid_visible = bool(value)
        self.update()

    @property
    def grid_cell_world(self) -> float:
        """Размер клетки в мировых единицах: растянутая карта даёт растянутую клетку."""
        m = self.current_map
        if m is None or not m.grid.cols:
            return 0.0
        return m.grid.cell_on_screen(m.width, m.height)[0]

    def set_grid(self, cols=None, rows=None, visible=None, notify: bool = True):
        """Изменить сетку открытой карты и, если нужно, разослать всем."""
        m = self.current_map
        if m is None:
            return
        grid = m.grid
        if cols is not None:
            grid.cols = clamp_cells(cols)
        if rows is not None:
            grid.rows = clamp_cells(rows)
        if visible is not None:
            grid.visible = bool(visible)
        m.apply_grid(grid)
        if notify:
            self.grid_changed.emit({
                'map_id': m.id, 'grid_cols': m.grid_cols,
                'grid_rows': m.grid_rows, 'grid_visible': m.grid_visible})
        self.update()

    # Калибровка по двум кликам: мастер отмечает две линии сетки,
    # по ним считается размер клетки и число клеток.
    # ---------------------------------------------------------------
    def begin_grid_calibration(self, cells: int = 1) -> bool:
        if self.current_map is None:
            return False
        self._calibration_cells = max(1, int(cells))
        self._calibration_points = []
        self._grid_calibrating = True
        self.setCursor(Qt.CrossCursor)
        self.update()
        return True

    def cancel_grid_calibration(self):
        self._calibration_points = []
        self._grid_calibrating = False
        self.unsetCursor()
        self.update()

    @property
    def calibrating(self) -> bool:
        return self._grid_calibrating

    def _handle_calibration_click(self, wx: float, wy: float) -> bool:
        """Клик в режиме калибровки. True — клик поглощён."""
        if not self._grid_calibrating:
            return False
        self._calibration_points.append((wx, wy))
        if len(self._calibration_points) < 2:
            self.update()
            return True

        (x1, y1), (x2, y2) = self._calibration_points[:2]
        m = self.current_map
        dx, dy = abs(x2 - x1), abs(y2 - y1)
        # Ось — та, где смещение больше: точки должны стоять на соседних
        # линиях сетки по одной оси.
        if dx >= dy:
            cell_world = dx / self._calibration_cells
            if cell_world > 0 and m.img_width and m.width:
                measured_px = cell_world * m.img_width / m.width
                grid = m.grid
                grid.cols = cells_from_cell_size(m.img_width, measured_px)
                m.apply_grid(grid)
        else:
            cell_world = dy / self._calibration_cells
            if cell_world > 0 and m.img_height and m.height:
                measured_px = cell_world * m.img_height / m.height
                grid = m.grid
                grid.rows = cells_from_cell_size(m.img_height, measured_px)
                m.apply_grid(grid)

        self._calibration_points = []
        self._grid_calibrating = False
        self.unsetCursor()
        self.update()
        self.grid_calibrated.emit({
            'map_id': m.id,
            'grid_cols': m.grid_cols,
            'grid_rows': m.grid_rows,
            'cells': self._calibration_cells,
        })
        return True

    # ------------------------------------------------------------------
    # Отрисовка
    # ------------------------------------------------------------------
    def _note_frame_ms(self, started: float):
        """Запомнить время кадра: из него считается среднее для отчёта.

        Сглаживание простое (EMA): один медленный кадр не должен выглядеть
        как «стол тормозит», а устойчивые 50 мс должны быть видны сразу.
        """
        self.last_frame_ms = max(0.0, (time.perf_counter() - started)
                                 * 1000.0)
        if self.frame_ms_avg <= 0.0:
            self.frame_ms_avg = self.last_frame_ms
        else:
            self.frame_ms_avg = (self.frame_ms_avg * 0.8
                                 + self.last_frame_ms * 0.2)

    def paintEvent(self, event):
        """Кадр холста; `_painting` отделяет отрисовку от загрузки картинок."""
        self._painting = True
        try:
            self._paint_frame(event)
        finally:
            self._painting = False

    def _paint_frame(self, event):
        started = time.perf_counter()
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.setRenderHint(QPainter.SmoothPixmapTransform)
        painter.fillRect(self.rect(), QColor(35, 35, 38))

        if not self.current_map:
            # Карта ещё не встала на холст (только добавляется): заставка
            # должна быть видна и здесь, иначе на пустом столе нет никакой
            # обратной связи, пока файл едет по сети.
            if self._map_loading is not None:
                self.draw_map_loading(painter)
            else:
                self.draw_empty_hint(painter)
            painter.end()
            self._note_frame_ms(started)
            return

        # Игроку за стенами нужен туман: цветное — только там, куда смотрят
        # его токены. Мастеру и столу без стен туман не нужен вовсе.
        fog = self.player_vision_path()
        fog_key = getattr(self, "_vision_cache_key", None)
        fog_parts = self.player_vision_parts()
        # Тёмное зрение считается один раз на кадр: раньше его спрашивали
        # дважды — здесь и внутри пути тумана, — и каждый раз заново
        # собирались круги объединением путей.
        dark, dark_key, dark_parts = self.player_darkvision_state()
        if fog is None:
            if dark is None:
                self._paint_scene(painter)
            else:
                # Стены тумана не дают, но ночью тёмное зрение снимает с
                # кругов зрения и темноту, и цвет. Раньше такой кадр шёл
                # через весь путь тумана — четыре полных экранных картинки,
                # две ч/б-конверсии и пять накладок на каждый кадр; на
                # 1600×900 это 22–24 мс против 10 сейчас.
                self._paint_scene_plain(painter, dark, dark_key, dark_parts)
        else:
            self._paint_player_fog(painter, fog, fog_key, dark, dark_key,
                                   fog_parts, dark_parts)
        painter.end()
        self._note_frame_ms(started)

    def _paint_scene(self, painter: QPainter):
        """Стол целиком: карта, рисование, свет, стены, тела и интерфейс.

        Отдельным методом, потому что игроку тот же кадр нужен в картинку:
        за стенами мир серый, и цветной слой ложится сверху по маске зрения.
        """
        painter.save()
        painter.translate(self.offset_x, self.offset_y)
        painter.scale(self.scale, self.scale)

        rect = self.map_rect_world()

        # Тень под картой
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(0, 0, 0, 120)))
        painter.drawRect(rect.adjusted(8, 8, 8, 8))

        # Карта
        if self.map_image and not self.map_image.isNull():
            self.draw_map_pixmap(painter, rect)
        else:
            painter.setBrush(QBrush(QColor(70, 70, 76)))
            painter.setPen(QPen(QColor(120, 120, 128), 2))
            painter.drawRect(rect)

        # Рамка выделенной карты
        if self.map_is_selected and self.is_dm:
            pen = QPen(QColor(0, 170, 255))
            pen.setWidthF(self.design(2.0))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawRect(rect)

        # Сетка поверх карты
        if self.grid_visible:
            self.draw_grid(painter)

        # Клетки хода в бою — под токенами, чтобы фигуры оставались видны.
        self.draw_chess_cells(painter)

        # Отметки калибровки: точки и линия между ними
        if self._calibration_points:
            pen = QPen(QColor(255, 200, 60))
            pen.setWidthF(self.design(2.0))
            painter.setPen(pen)
            painter.setBrush(QBrush(QColor(255, 200, 60)))
            r = self.design(5.0)
            for px, py in self._calibration_points:
                painter.drawEllipse(QPointF(px, py), r, r)
            if len(self._calibration_points) > 1:
                x1, y1 = self._calibration_points[0]
                x2, y2 = self._calibration_points[1]
                painter.setBrush(Qt.NoBrush)
                painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))

        # Растровый рисунок (кисть/линии/фигуры/ластик) — поверх карты,
        # но под токенами и рамкой выделения.
        self.draw_draw_layer(painter)

        # Надписи — над рисунком: подпись не должна тонуть в штрихах.
        self.draw_map_texts(painter)

        # Ночь — поверх всей поверхности стола (карта, сетка, рисунок, надписи),
        # но под телами: существ и так видно, а освещение читается с первого
        # взгляда и меняется одним пунктом меню.
        self.draw_time_of_day(painter, rect)

        # Свет «сверх силы» — и на дневной карте: горячий источник
        # (≥ DAYLIGHT_GLOW_KELVIN) виден поверх дня мягким отсветом, и
        # мастер видит, докуда он достаёт.
        self.draw_day_glow(painter, rect)

        # Объекты «ниже токенов»: трава, ковры, тени. Ночью они рисуются уже
        # затемнёнными (силуэтом) поверх слоя ночи — иначе пятно света ложилось
        # бы и на них, а накладка над полом свет ловить не должна.
        self.draw_map_objects(painter, above=False)

        # Стены — часть архитектуры: над полом и накладками, но под телами.
        # Ночью их не гасит затемнение: это то, что отсекает свет.
        self.draw_walls(painter)

        # Зрение токена, который сейчас крутят: жёлтый конус обзора лежит на
        # полу под телами — так видно, куда смотрит токен, но портрет не
        # затемняется. Вне режима поворота конус не рисуется: на столе и без
        # него тесно, а направление взгляда нужно только при настройке.
        # Сектор виден и после второго R, пока пружина доводит взгляд: токен
        # ещё едет к углу, и по сектору видно, куда именно он встанет.
        turn_id = self.rotating_token_id or (
            self._turn_token_id if self._turn_commit is not None else None)
        if turn_id:
            rotated = self.tokens.get(turn_id)
            if rotated is not None and rotated.visible:
                self.draw_token_vision_cone(painter, rotated)

        # Кровь — под токенами: она растекается из-под тела на соседние
        # клетки, поэтому тело её не перекрывает целиком.
        self.draw_blood(painter)

        # Токены — только той карты, что открыта сейчас.
        for token in self.current_map_tokens().values():
            if token.visible:
                self.draw_token(painter, token)

        # Объекты «выше токенов»: крыши, кроны, декор — перекрывают тела.
        self.draw_map_objects(painter, above=True)

        # Метки источников света — поверх тел: иначе факел под токеном
        # не выбрать мышью.
        self.draw_light_markers(painter)

        # Цель перетаскиваемого предмета — поверх всего: пока кнопка мыши
        # зажата, зелье уже «в руке», и видно, кого оно вылечит.
        self.draw_item_drop_target(painter)

        # Взведённое заклинание: кольцо на токене под курсором.
        if self.target_pick_mode:
            self.draw_target_pick_ring(painter)

        # Текущий штрих в процессе рисования (превью)
        if self.drawing_points or self._preview_points:
            self.draw_current_drawing(painter)

        # Рамка выделения — в тех же координатах, что и токены
        if self.rubber_active and self.rubber_origin and self.rubber_current:
            rect = QRectF(self.rubber_origin, self.rubber_current).normalized()
            pen = QPen(QColor(90, 160, 255))
            pen.setWidthF(self.design(1.5))
            pen.setStyle(Qt.DashLine)
            painter.setPen(pen)
            painter.setBrush(QBrush(QColor(90, 160, 255, 40)))
            painter.drawRect(rect)

        painter.restore()

        # След области — поверх токенов, но под цифрами урона.
        self.draw_area_result(painter)

        # Боевые эффекты — поверх токенов, но под интерфейсом (линейка/ручки).
        self.draw_combat_fx(painter)

        # Линейка — в экранных координатах: наконечник и шрифт не зависят
        # от масштаба вида, растягивается только сама стрелка.
        if self.ruler_start is not None and self.ruler_end is not None:
            self.draw_ruler(painter)
        if self.drawing_mode == 'template':
            self.draw_template(painter)

        # Ручки — в экранных координатах, поверх всего
        if self.map_is_selected and self.is_dm:
            self.draw_handles(painter)
        # Стрелки настроек и рамка выбранного объекта.
        self.draw_object_ui(painter)
        # Точки стен и недорисованный контур — только мастеру и только когда
        # его вообще выбрали: иначе они висели бы над каждым кадром стола.
        self.draw_wall_ui(painter)

        # Заставка загрузки — поверх карты, но под строкой состояния:
        # она не должна закрывать подсказки внизу холста.
        if self._map_loading is not None:
            self.draw_map_loading(painter)

        # Плашка взведённой быстрой атаки — поверх карты, но до строки
        # состояния: подсказка важнее, но не должна её закрывать.
        self.draw_quick_attack_banner(painter)
        # Плашка над картой: что ждёт холст и как отменить (выбор цели,
        # шаблон области). Рисуется до строки состояния, чтобы не спорить
        # с её подсказкой.
        self.draw_cast_banner(painter)
        self.draw_status_bar(painter)

    def soft_vision_mask(self, path, key, parts=None) -> QImage:
        """Маска пути зрения: белое «вижу», прозрачное «не вижу».

        По умолчанию край резкий: так видно, как зрение меняется в реальном
        времени (поворот токена, шаг, открытая дверь), и на границе света нет
        мутной полосы. Резкость даёт только один пиксель сглаживания — без
        него край лесенкой.

        Кромка может быть мягкой: `FOG_SOFT_EDGE_PX > 0` включает прежний
        путь — маска растеризуется в уменьшенную картинку и растягивается
        обратно, и обзор гаснет плавно. Переключатель оставлен целиком,
        чтобы стиль можно было вернуть одной константой.

        Маска кэшируется: она меняется только вместе с геометрией обзора
        (токен сдвинулся, повернулся, стены, камера), а не каждый кадр.
        """
        cached = self._soft_mask_cache.get(key)
        if cached is not None and cached.size() == self.size():
            return cached
        size = self.size()
        # Маска рисуется КУСКАМИ, а не одним объединённым путём. `united`
        # возвращает контуры с разным направлением обхода, и при заливке
        # общая часть двух областей зрения вычиталась: у соседних токенов
        # появлялись тёмные серпы, а на большом зуме — целые дыры в цветном
        # слое. Куски рисуются по одному непрозрачной белой кистью поверх
        # друг друга, и союз получается попиксельный — направление контуров
        # на него уже не влияет.
        pieces = []
        for part in (parts or ()):
            if part is None or part.isEmpty():
                continue
            part.setFillRule(Qt.WindingFill)
            pieces.append(part)
        if not pieces and path is not None and not path.isEmpty():
            path.setFillRule(Qt.WindingFill)
            pieces.append(path)
        if FOG_SOFT_EDGE_PX <= 0:
            mask = QImage(size, QImage.Format_ARGB32_Premultiplied)
            mask.fill(Qt.transparent)
            paint = QPainter(mask)
            paint.setRenderHint(QPainter.Antialiasing, True)
            paint.setPen(Qt.NoPen)
            paint.setBrush(QColor(255, 255, 255))
            for part in pieces:
                paint.drawPath(part)
            paint.end()
            if len(self._soft_mask_cache) >= 6:
                self._soft_mask_cache.clear()
            self._soft_mask_cache[key] = mask
            return mask
        shrink = max(2.0, FOG_SOFT_EDGE_PX / 2.0)
        # Шаг размытия подбирается ПОД саму область зрения. Раньше он был
        # постоянным (9), и маленькая область — короткая дальность вроде
        # 5–10 фт или сильное отдаление — после сжатия превращалась в 2 px,
        # а после обратного растягивания в прозрачное пятно: цветного слоя
        # не оставалось нигде, и туман ложился на весь экран с разной
        # плотностью. Теперь самая узкая сторона области в уменьшенной
        # картинке — не мельче 12 px, и форма переживает размытие.
        bounds = path.boundingRect() if hasattr(path, "boundingRect") else None
        narrow = min(bounds.width(), bounds.height()) if bounds else 0.0
        if narrow > 0:
            shrink = min(shrink, max(2.0, narrow / 12.0))
        small_w = max(1, int(round(size.width() / shrink)))
        small_h = max(1, int(round(size.height() / shrink)))
        # Именно ARGB, а не градации серого: у Grayscale8 нет альфы, и после
        # растягивания «чёрное снаружи» становилось бы непрозрачным чёрным —
        # маска перестала бы что-либо отсекать. Здесь важен только альфа-канал.
        small = QImage(small_w, small_h, QImage.Format_ARGB32_Premultiplied)
        small.fill(Qt.transparent)
        paint = QPainter(small)
        paint.setRenderHint(QPainter.Antialiasing, True)
        paint.scale(small_w / max(1.0, float(size.width())),
                    small_h / max(1.0, float(size.height())))
        paint.setPen(Qt.NoPen)
        paint.setBrush(QColor(255, 255, 255))
        for part in pieces:
            paint.drawPath(part)
        paint.end()
        half = QSize(max(1, size.width() // 2), max(1, size.height() // 2))
        mask = small.scaled(half, Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
        mask = mask.scaled(size, Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
        mask = mask.convertToFormat(QImage.Format_ARGB32_Premultiplied)
        if len(self._soft_mask_cache) >= 6:
            self._soft_mask_cache.clear()
        self._soft_mask_cache[key] = mask
        return mask

    def inverse_vision_mask(self, mask: QImage, key) -> QImage:
        """Обратная маска: туман гасится ровно там, где игрок видит."""
        inv_key = ("inverse",) + tuple(key)
        cached = self._soft_mask_cache.get(inv_key)
        if cached is not None and cached.size() == mask.size():
            return cached
        inverse = QImage(mask.size(), QImage.Format_ARGB32_Premultiplied)
        inverse.fill(QColor(255, 255, 255, 255))
        paint = QPainter(inverse)
        paint.setCompositionMode(QPainter.CompositionMode_DestinationOut)
        paint.drawImage(0, 0, mask)
        paint.end()
        if len(self._soft_mask_cache) >= 6:
            self._soft_mask_cache.clear()
        self._soft_mask_cache[inv_key] = inverse
        return inverse

    def roof_screen_path(self) -> Optional[QPainterPath]:
        """Крыши на экране: над ними туман комнат не ложится.

        Крыша — это не помещение, а мир: она и так закрывает пол собой,
        поэтому чёрный туман комнаты ей не нужен. Берём только видимые
        крыши, которые сейчас не растворились под токеном игрока.
        """
        path = QPainterPath()
        for object_id, obj in self.current_map_objects().items():
            if not getattr(obj, "roof", False) or not obj.visible:
                continue
            if (self._roof_alpha.get(object_id, 1.0)
                    < ROOF_FOG_MIN_ALPHA):
                continue
            polygon = self.object_polygon(obj)
            if polygon.isEmpty():
                continue
            screen = QPolygonF([QPointF(*self.world_to_screen(px.x(), px.y()))
                                for px in polygon])
            part = QPainterPath()
            part.addPolygon(screen)
            part.closeSubpath()
            path = part if path.isEmpty() else path.united(part)
        return None if path.isEmpty() else path

    @staticmethod
    def room_signature(polygon) -> tuple:
        """Подпись комнаты-полигона: рамка и площадь с точностью до пикселя.

        Нужна, чтобы помнить разведанные комнаты между кадрами: сам
        многоугольник пересчитывается и живёт в кэше, а подпись остаётся
        одной и той же, пока стены не тронуты.
        """
        xs = [point[0] for point in polygon]
        ys = [point[1] for point in polygon]
        area = 0.0
        count = len(polygon)
        for index in range(count):
            x1, y1 = polygon[index]
            x2, y2 = polygon[(index + 1) % count]
            area += x1 * y2 - x2 * y1
        return ("poly", round(min(xs)), round(min(ys)), round(max(xs)),
                round(max(ys)), round(abs(area) / 2.0))

    @staticmethod
    def region_signature(region) -> tuple:
        """Подпись комнаты-прямоугольника (запасной клеточный расчёт)."""
        x, y, w, h = region
        return ("rect", round(x), round(y), round(w), round(h))

    def room_shapes(self) -> list:
        """Комнаты с подписями: [(подпись, форма)] — полигоны или клетки.

        Форма — либо список точек в мире, либо пара (x, y, w, h).
        Полигоны точнее, но строятся только для замкнутой геометрии: если
        открыть дверь, комната перестаёт быть замкнутой и сливается с тем,
        что за ней. Когда полигонов не остаётся совсем, работает старый
        клеточный расчёт — туман всё равно должен ложиться.
        """
        polygons = self.room_polygons()
        if polygons:
            return [(self.room_signature(polygon), polygon)
                    for polygon in polygons]
        return [(self.region_signature(region), region)
                for region in self.room_regions()]

    def region_groups(self) -> list:
        """Полосы запасного расчёта, уже разложенные по комнатам.

        Запасной расчёт возвращает строки грубой сетки: одна комната — это
        несколько соседних полос, и размечать надо комнату целиком, иначе от
        неё светлеет только ряд с токеном. Группировку делает геометрия
        (`walls.enclosed_room_groups`): по связности клеток, а не по тому,
        касаются ли полосы друг друга — соседние комнаты как раз касаются на
        общей стене, и раньше заход в одну отмечал все.
        """
        m = self.current_map
        if m is None:
            return []
        return [[self.region_signature(region) for region in group]
                for group in wall_rules.enclosed_room_groups(m)]

    def room_groups(self) -> list:
        """Комнаты списками подписей: полигон — сам по себе, полосы — группами.

        Кэш по геометрии: запасной расчёт обходит всю карту грубой сеткой,
        и делать это каждый кадр нельзя.
        """
        polygons = self.room_polygons()
        key = (self._room_polys_key, self._rooms_key,
               bool(polygons), self._geometry_version)
        if (self._room_groups_cache is not None
                and self._room_groups_key == key):
            return self._room_groups_cache
        if polygons:
            groups = [[self.room_signature(polygon)] for polygon in polygons]
        else:
            groups = self.region_groups()
            # Запасной расчёт только что посчитал области — ключ уточняем,
            # иначе кэш не найдётся на следующем кадре.
            key = (self._room_polys_key, self._rooms_key,
                   bool(polygons), self._geometry_version)
        self._room_groups_key = key
        self._room_groups_cache = groups
        return groups

    def room_world_path(self, shape) -> QPainterPath:
        """Комната в экранных координатах: форма из `room_shapes`."""
        part = QPainterPath()
        if isinstance(shape, tuple):
            x, y, w, h = shape
            scale = float(self.scale or 1.0)
            sx, sy = self.world_to_screen(x, y)
            part.addRect(QRectF(sx, sy, w * scale, h * scale))
            return part
        screen = [QPointF(*self.world_to_screen(x, y)) for x, y in shape]
        part.addPolygon(QPolygonF(screen))
        part.closeSubpath()
        return part

    def explored_rooms(self) -> set:
        """Комнаты, которые стол уже разведал (подписи), для открытой карты.

        Хранятся на самой карте (`MapData.explored_rooms`), поэтому едут
        вместе с миром и после перезапуска туман не закрывается заново.
        Набор — только разобранная копия для быстрых проверок в кадре.
        """
        m = self.current_map
        if m is None:
            return set()
        cached = self._explored_rooms.get(m.id)
        if cached is None:
            cached = {tuple(entry) for entry in
                      wall_rules.normalize_explored_rooms(
                          getattr(m, "explored_rooms", None))}
            self._explored_rooms[m.id] = cached
        return cached

    def reload_explored_rooms(self):
        """Перечитать разведку из карты: пришла правка от сервера."""
        m = self.current_map
        if m is None:
            return
        self._explored_rooms[m.id] = {
            tuple(entry) for entry in
            wall_rules.normalize_explored_rooms(
                getattr(m, "explored_rooms", None))}
        self._explored_path_cache = None
        self.update()

    def _remember_explored_rooms(self):
        """Переложить разобранный набор в карту: так его сохранит мир."""
        m = self.current_map
        if m is None:
            return
        explored = self._explored_rooms.get(m.id) or set()
        m.explored_rooms = [list(signature) for signature in sorted(explored)]

    def mark_explored_rooms(self):
        """Запомнить комнату, в которой стоит токен стола.

        Неразведанная комната идёт в чёрный — но та, куда игрок уже вошёл,
        разведана. Без этой пометки туман комнаты заливал всё вокруг
        токена: он переступал порог, и помещение становилось чёрным, как
        будто его там нет, — видно было только конус зрения.
        """
        tokens = self.fog_vision_tokens()
        if not tokens:
            return
        shapes = self.room_shapes()
        if not shapes:
            return
        explored = self.explored_rooms()
        groups = {}
        for group in self.room_groups():
            for signature in group:
                groups[signature] = group
        found = []
        spans = self.wall_spans(light=False)
        for token in tokens:
            # Токен должен стоять именно в комнате, а не на самой стене:
            # иначе касание стены снаружи открывало то, что за ней, а токен,
            # вставший на общую стену двух комнат, открывал сразу обе.
            # Поэтому проверяется только центр токена и с запасом от стен:
            # непонятно, в какой он комнате — значит отметим, когда отойдёт.
            if (spans and wall_rules.nearest_wall_distance(
                    token.x, token.y, spans) <= ROOM_EDGE_EPS_WORLD):
                continue
            for signature, shape in shapes:
                if signature in explored or signature in found:
                    continue
                if isinstance(shape, tuple):
                    x, y, w, h = shape
                    inside = (x <= token.x <= x + w
                              and y <= token.y <= y + h)
                else:
                    inside = wall_rules.point_in_polygon(token.x, token.y,
                                                         shape)
                if not inside:
                    continue
                found.extend(item for item in
                             groups.get(signature, (signature,))
                             if item not in explored)
        if not found:
            return
        explored.update(found)
        self._remember_explored_rooms()
        self._explored_path_cache = None
        # Окно отправит новые комнаты на сервер: у остальных разведка тоже
        # должна открыться, а мир — сохранить её в файле.
        self.explored_rooms_changed.emit(
            self.current_map.id, [list(item) for item in found])

    def explored_room_path(self) -> Optional[QPainterPath]:
        """Разведанные комнаты на экране: их туман комнат не заливает."""
        explored = self.explored_rooms()
        if not explored:
            return None
        shapes = self.room_shapes()
        key = (self._room_polys_key, self._rooms_key, frozenset(explored),
               round(float(self.scale or 1.0), 6),
               round(float(self.offset_x), 2),
               round(float(self.offset_y), 2))
        if (self._explored_path_cache is not None
                and self._explored_path_key == key):
            return self._explored_path_cache
        path = QPainterPath()
        for signature, shape in shapes:
            if signature not in explored:
                continue
            part = self.room_world_path(shape)
            if not part.isEmpty():
                path.addPath(part)
        self._explored_path_key = key
        self._explored_path_cache = None if path.isEmpty() else path
        return self._explored_path_cache

    def fog_room_path(self) -> Optional[QPainterPath]:
        """Что красить как неразведанную комнату: комнаты минус крыши.

        Без этого игрок снаружи видел чёрный прямоугольник вместо дома:
        туман комнат ложился поверх крыши, хотя крыша и так скрывает всё,
        что внутри. Под крышей туман остаётся обычным, «мирским».

        Разведанные комнаты (где токен стола уже стоял) из заливки вычтены:
        чёрным остаётся только то, куда стол ещё не заходил.
        """
        self.mark_explored_rooms()
        rooms = self.room_screen_path()
        if rooms is None:
            return None
        entered = self.explored_room_path()
        if entered is not None:
            rooms = rooms.subtracted(entered)
            if rooms.isEmpty():
                return None
        roofs = self.roof_screen_path()
        if roofs is not None:
            rooms = rooms.subtracted(roofs)
            if rooms.isEmpty():
                return None
        return rooms

    def _paint_scene_plain(self, painter: QPainter, dark: QPainterPath,
                           dark_key=None, dark_parts=None):
        """Кадр без тумана, но с тёмным зрением игрока.

        У стола без стен тумана нет, и весь кадр рисуется прямо на холст.
        Тёмное зрение при этом значит только две вещи: ночь не затемняет его
        круги (`_night_cut_path`) и внутри кругов мир ч/б. То и другое
        делается поверх готового кадра, а не пересборкой экрана.
        """
        self._night_cut_path = dark
        self._night_cut_key = dark_key
        self._night_cut_parts = dark_parts or ()
        try:
            self._paint_scene(painter)
        finally:
            self._night_cut_path = None
            self._night_cut_key = None
            self._night_cut_parts = ()
        self._paint_dark_patches(painter, dark, dark_key, dark_parts)

    def _paint_dark_patches(self, painter: QPainter, dark: QPainterPath,
                            dark_key=None, parts=None):
        """Ч/б внутри кругов тёмного зрения — только их прямоугольники.

        Кадр уже на холсте. Чтобы получить ч/б, сцена рисуется ещё раз — но
        не в картину во весь экран, а в маленькую, размером с круги зрения,
        и там же переводится в ч/б. Дальше она ложится обратно по готовой
        маске кругов (`soft_vision_mask`, она кэширована).

        Стоит это несколько миллисекунд, а не пересборка всего экрана:
        раньше ради того же участка строилась полная ч/б копия плюс ещё две
        картинки во весь экран (22–24 мс на 1600×900 вместо 10).
        """
        if dark is None or dark.isEmpty() or self.current_map is None:
            return
        area = dark.boundingRect().intersected(QRectF(self.rect()))
        if area.isEmpty():
            return
        rect = area.toAlignedRect().adjusted(-1, -1, 1, 1).intersected(
            self.rect())
        if rect.isEmpty():
            return
        patch = QImage(rect.size(), QImage.Format_ARGB32_Premultiplied)
        patch.fill(QColor(35, 35, 38))
        own = QPainter(patch)
        own.setRenderHint(QPainter.Antialiasing)
        own.setRenderHint(QPainter.SmoothPixmapTransform)
        own.setClipRect(QRectF(rect.translated(-rect.x(), -rect.y())))
        own.translate(-rect.x(), -rect.y())
        # Ночь в пятачке уже вырезана кругом зрения, а невидимые токены и
        # здесь остаются скрытыми: сцена рисуется теми же правилами.
        night_cut, night_key = self._night_cut_path, self._night_cut_key
        self._night_cut_path = dark
        self._night_cut_key = dark_key
        try:
            self._paint_scene(own)
        finally:
            self._night_cut_path = night_cut
            self._night_cut_key = night_key
            own.end()
        gray = patch.convertToFormat(QImage.Format_Grayscale8)
        # Ключ зрения — мировой, без камеры: она уже входит в `dark_mask_key`,
        # а форма кусков от сдвига вида не зависит.
        mask = self.soft_vision_mask(
            dark,
            self.dark_mask_key(dark_key,
                               getattr(self, "_vision_world_key", None)),
            parts or ())
        # Пятачок собирается в постоянном буфере: новая картинка на видеокарте
        # ложилась чёрным квадратом вместо ч/б тёмного зрения.
        layer = self.scratch_image("dark_plain", rect.size(), FOG_LAYER_STEP_PX)
        cut = QPainter(layer)
        cut.setCompositionMode(QPainter.CompositionMode_Source)
        cut.drawImage(0, 0, gray)
        cut.setCompositionMode(QPainter.CompositionMode_DestinationIn)
        # Только нужный кусок маски: она во весь экран, а пятачок — нет.
        cut.drawImage(0, 0, mask, rect.x(), rect.y(),
                      rect.width(), rect.height())
        cut.end()
        painter.drawImage(rect.topLeft(), layer,
                          QRect(0, 0, rect.width(), rect.height()))

    def dark_mask_key(self, dark_key, vision_key=None) -> tuple:
        """Ключ кэша маски тёмного зрения.

        Сами круги живут в экранных координатах, поэтому в ключе есть и
        камера: тот же токен при сдвинутом виде даёт другую маску. Ключ же
        для слоя ночи — мировой (см. `player_darkvision_state`), иначе каждый
        сдвиг камеры заставлял бы пересобирать всю маску ночи со светом.

        Когда маска строится по кругам, обрезанным сектором обзора
        (`_compose_dark_patch`), в ключ обязан входить и ключ зрения: поворот
        на `R` меняет форму пересечения, а круги, камера и размер окна
        остаются прежними. Без этого маска не пересобиралась — тёмное
        зрение отставало от поворота, и у ведущего края сектора оставалась
        цветная полоса прежнего обзора.
        """
        cut = None if vision_key is None else hash(vision_key)
        return ("dark", hash(dark_key), cut,
                round(float(self.scale or 1.0), 6),
                round(float(self.offset_x), 2),
                round(float(self.offset_y), 2), self.width(), self.height())

    def _compose_dark_patch(self, compose: QPainter, gray: QImage,
                            dark: QPainterPath, dark_key, size,
                            vision_key=None, parts=None):
        """Ч/б от тёмного зрения поверх собранного кадра — только по кругам.

        Раньше ради этого копировался кадр целиком и строилась маска на весь
        экран: две картинки и две накладки в каждом кадре. Теперь берётся
        прямоугольник кругов, в нём вырезается маска, и он же ложится на кадр.
        """
        frame = QRectF(0.0, 0.0, size.width(), size.height())
        area = dark.boundingRect().intersected(frame)
        if area.isEmpty():
            return
        rect = area.toAlignedRect().adjusted(-1, -1, 1, 1).intersected(
            QRect(0, 0, size.width(), size.height()))
        if rect.isEmpty():
            return
        # В буфер кладётся только кусок кругов, а не весь экран: конверсия
        # на 1600×900 стоит дороже всего остального в пятачке. Буфер живёт
        # между кадрами — см. `scratch_image`.
        layer = self.scratch_image("dark_fog", rect.size(), FOG_LAYER_STEP_PX)
        # `dark` здесь уже обрезан сектором обзора, поэтому в ключ идёт и он.
        # Куски заливаются по одному: у объединённого пути перекрытия идут с
        # обратным обходом, и на стыке двух тёмных зрений оставался бы
        # цветной серп.
        mask = self.soft_vision_mask(
            dark, self.dark_mask_key(dark_key, vision_key), parts or ())
        cut = QPainter(layer)
        cut.setCompositionMode(QPainter.CompositionMode_Source)
        cut.drawImage(0, 0, gray, rect.x(), rect.y(),
                      rect.width(), rect.height())
        cut.setCompositionMode(QPainter.CompositionMode_DestinationIn)
        cut.drawImage(QRectF(0, 0, rect.width(), rect.height()), mask,
                      QRectF(rect))
        cut.end()
        compose.drawImage(rect.topLeft(), layer,
                          QRect(0, 0, rect.width(), rect.height()))

    def _paint_own_tokens_over_fog(self, painter: QPainter):
        """Свои токены — поверх тумана: тело, имя и значки остаются цветными.

        Раньше ради этого в маске зрения прорезались круг тела, плашка имени
        и значки состояния. Токен выходил цветным, но вместе с ним цветным
        становилось всё под ним: под фишкой и под подписью появлялось пятно
        света, а чужая фишка, попавшая в это пятно, становилась видна даже
        за стеной. Теперь маска — только куски настоящего зрения, а свой
        токен рисуется ещё раз поверх собранного кадра.
        """
        if not isinstance(painter, QPainter):
            # Подставной painter (туман в тестах стен проверяют записью
            # вызовов) токенов не рисует: ему нужны только картинки тумана.
            return
        tokens = [token for token in self.fog_vision_tokens()
                  if token.visible and token.id in self.current_map_tokens()]
        if not tokens:
            return
        # Сглаживание включается здесь, а не приходит от вызывающего: кадр
        # собирается и в картинку (эталон в тестах), и прямо на холст, и край
        # фишки в обоих случаях обязан совпадать пиксель в пиксель.
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        # Тот же переход в мировые координаты, что и в `_paint_scene`: тела
        # живут в мире, а плашка имени сама сбрасывает преобразование.
        painter.save()
        painter.translate(self.offset_x, self.offset_y)
        painter.scale(self.scale, self.scale)
        # Плашка и полоса хитов здесь непрозрачные: под ними — кромка зрения,
        # которая при повороте взгляда идёт прямо под токеном. Сквозь
        # полупрозрачную плашку она просвечивала, и подпись «мигала».
        self._token_overlay_opaque = True
        try:
            for token in tokens:
                self.draw_token(painter, token)
        finally:
            self._token_overlay_opaque = False
            painter.restore()

    def _paint_player_fog(self, painter: QPainter, visible: QPainterPath,
                          vision_key=None, dark: QPainterPath = None,
                          dark_key=None, visible_parts=None,
                          dark_parts=None):
        """Игрок видит цветным только то, куда смотрят его токены.

        Кадр целиком рисуется в картинку, из неё делается чб-копия
        (`Format_Grayscale8` — конверсия в C++, без циклов на Python), чб
        ложится на холст, а цветной слой — по маске зрения. Так за стеной
        остаётся читаемый, но обесцвеченный мир, а не чёрная дыра: игрок
        видит планировку уже разведанных комнат.

        Тёмное зрение ночью — отдельный слой: в его кругах ночная заливка
        вырезана («темноты нет»), а мир там ч/б, поэтому поверх цветного
        слоя кладётся та же серая копия кадра.

        Край зрения резкий (см. `soft_vision_mask`): цветной мир обрывается
        точной линией сектора, поэтому поворот и шаг сразу видны на карте.
        Мягкий край остался переключателем `FOG_SOFT_EDGE_PX`.

        Порядок сборки — на painter'е холста, без буфера всего кадра: подложка
        ч/б, туман полосами вне сектора, цветной слой в рамке сектора, ч/б
        круги тёмного зрения, туман в рамке по маске. Всё, что требует маски,
        считается только в рамке: полные экранные маски стоили 2,4 мс каждая.
        """
        size = self.size()
        if dark is None and dark_key is None:
            dark, dark_key, dark_parts = self.player_darkvision_state()
        # Пересекать с общей маской зрения больше не нужно: каждый круг уже
        # обрезан своим сектором в `player_darkvision_state`. Именно это
        # пересечение и делало тёмное зрение общим на всех, кто смотрит в ту
        # же сторону, — и оно же было самой дорогой операцией кадра.
        if dark is not None and dark.isEmpty():
            dark = None
        self._night_cut_path = dark
        self._night_cut_parts = dark_parts or ()
        # Слою ночи ключ нужен БЕЗ камеры, но С формой зрения: маска ночи
        # живёт в мировых координатах и не пересобирается при сдвиге вида,
        # а поворот взгляда (R) вырезает из ночи другой сектор. Раньше здесь
        # стоял только ключ кругов тёмного зрения, и поворот был виден лишь
        # после сдвига камеры: до этого ночь оставалась вырезанной в старом
        # секторе.
        self._night_cut_key = (dark_key,
                               getattr(self, "_vision_world_key", None)
                               or vision_key)
        image = self.fog_scene_image(size)
        image.fill(QColor(35, 35, 38))
        own = QPainter(image)
        own.setRenderHint(QPainter.Antialiasing)
        own.setRenderHint(QPainter.SmoothPixmapTransform)
        self._visible_path = visible
        self._fog_overlay_ids = frozenset(
            token.id for token in self.fog_vision_tokens())
        try:
            self._paint_scene(own)
        finally:
            self._visible_path = None
            self._fog_overlay_ids = frozenset()
            self._night_cut_path = None
            self._night_cut_key = None
            self._night_cut_parts = ()
            own.end()
        gray = image.convertToFormat(QImage.Format_Grayscale8)
        # Кадр собирается из готовых картинок, а не обрезкой прямо на painter'е
        # холста. Стол по умолчанию рисует видеокарта (QOpenGLWidget), а GL-движок
        # Qt не умеет обрезать картинку произвольным путём: вместо цветной
        # области зрения он заливал её чёрным — туман выглядел вывернутым
        # (видно всё, кроме того, куда смотрят токены). Готовые картинки без
        # обрезки по пути ложатся на видеокарту штатно и одинаково в обоих
        # движках.
        mask_key = ("vision", hash(vision_key), size.width(), size.height())
        mask = self.soft_vision_mask(visible, mask_key, visible_parts)
        # Цветным кадр бывает только в рамке сектора зрения, а за её пределами
        # туман ложится сплошной плотностью. Всё, что стоит по маске (цветной
        # слой и мягкий край тумана), считается в этой рамке; полные экранные
        # маски стоили 2,4 мс каждая — вдвое больше всего остального.
        box = self.fog_color_box(visible, size, visible_parts)
        # Плотность и цвет тумана — одни на весь кадр.
        world_alpha, room_alpha = self.fog_alphas()
        shade = self.fog_tint_color()
        rooms = self.fog_room_path() if room_alpha > 0 else None
        painter.save()
        # Подложка — ч/б кадр: он непрозрачен и сам закрывает прошлый кадр
        # целиком, поэтому чистить буфер отдельным проходом не нужно.
        painter.setCompositionMode(QPainter.CompositionMode_Source)
        painter.drawImage(0, 0, gray)
        painter.setCompositionMode(QPainter.CompositionMode_SourceOver)
        self.paint_fog_bands(painter, box, size, shade, rooms,
                             world_alpha, room_alpha)
        if not box.isEmpty():
            # Цветной слой умножается на маску в рамке сектора: на кромке он
            # полупрозрачен и потому смешивается с ч/б подложкой.
            clip = QPainter(image)
            clip.setCompositionMode(QPainter.CompositionMode_DestinationIn)
            clip.drawImage(QRectF(box), mask, QRectF(box))
            clip.end()
            painter.drawImage(box.topLeft(), image, box)
        if dark is not None and not dark.isEmpty():
            # Ключ зрения — мировой: поворот меняет форму кусков, а сдвиг
            # камеры уже учтён в самом `dark_mask_key`.
            self._compose_dark_patch(
                painter, gray, dark, dark_key, size,
                vision_key=getattr(self, "_vision_world_key", None),
                parts=dark_parts)
        if not box.isEmpty():
            self.paint_fog_box(painter, box, size, mask, mask_key, shade, rooms,
                               world_alpha, room_alpha)
        painter.restore()
        # Свои токены — поверх тумана: без дырки в маске они иначе уходили
        # в ч/б. Сама дырка была видна как пятно света и открывала чужое.
        self._paint_own_tokens_over_fog(painter)

    def fog_color_box(self, visible: QPainterPath, size: QSize,
                      parts=None) -> QRect:
        """Рамка сектора зрения: только в ней кадр цветной.

        За её пределами цветного слоя нет вовсе, а туман лежит сплошной
        плотностью — маска зрения там не нужна. Пустая рамка значит, что
        зрения нет: кадр целиком ч/б.
        """
        if visible is None or visible.isEmpty():
            return QRect()
        # Запас на сглаживание кромки: у мягкого края маска выходит за путь.
        pad = int(round(max(0.0, FOG_SOFT_EDGE_PX))) * 2 + 2
        if parts:
            # Рамка — по кускам: объединение путей может потерять кусок, и
            # тогда часть цветного слоя просто не нарисовалась бы.
            total = QRectF()
            for part in parts:
                total = total.united(part.boundingRect())
            bounds = total.toAlignedRect()
        else:
            bounds = visible.boundingRect().toAlignedRect()
        return bounds.adjusted(-pad, -pad, pad, pad).intersected(
            QRect(0, 0, size.width(), size.height()))

    @staticmethod
    def fog_band_rects(frame: QRect, box: QRect) -> list:
        """Полосы кадра вне рамки сектора — по ним ложится сплошной туман."""
        if box.isEmpty():
            return [frame]
        bands = []
        # Сверху и снизу — во всю ширину, слева и справа — между ними: полосы
        # не пересекаются, поэтому каждый пиксель красится ровно один раз.
        for rect in (
                QRect(frame.left(), frame.top(), frame.width(),
                      max(0, box.top() - frame.top())),
                QRect(frame.left(), box.bottom() + 1, frame.width(),
                      max(0, frame.bottom() - box.bottom())),
                QRect(frame.left(), box.top(), max(0, box.left() - frame.left()),
                      box.height()),
                QRect(box.right() + 1, box.top(),
                      max(0, frame.right() - box.right()), box.height())):
            rect = rect.intersected(frame)
            if rect.width() > 0 and rect.height() > 0:
                bands.append(rect)
        return bands

    def paint_fog_bands(self, painter: QPainter, box: QRect, size: QSize,
                        shade: QColor, rooms, world_alpha: int,
                        room_alpha: int):
        """Туман войны вне сектора зрения — без маски, сплошной плотностью.

        Неразведанная комната за стенами идёт в чёрный (игрок не знает даже,
        что там есть помещение), а открытый мир — полупрозрачным туманом:
        карта читается, но деталей не видно. Плотность обоих — в освещении,
        крыша считается миром.
        """
        if world_alpha <= 0 and (room_alpha <= 0 or rooms is None):
            return
        frame = QRect(0, 0, size.width(), size.height())
        bands = self.fog_band_rects(frame, box)
        if not bands:
            return
        fog = self.fog_frame(size)
        fill = QPainter(fog)
        # Замена: полосы заполняются заново каждый кадр, и в них не должно
        # оставаться прошлой заливки.
        fill.setCompositionMode(QPainter.CompositionMode_Source)
        world = QColor(shade)
        world.setAlpha(int(round(255.0 * world_alpha / 100.0)))
        for rect in bands:
            fill.fillRect(QRectF(rect), world)
        if rooms is not None:
            # Замена, а не наложение: иначе комната получила бы сумму
            # плотностей мира и комнаты и стала бы темнее выставленного.
            room = QColor(shade)
            room.setAlpha(int(round(255.0 * room_alpha / 100.0)))
            fill.fillPath(rooms, room)
        # Рамка сектора в этом буфере не нужна (в ней туман ляжет отдельно,
        # по маске), но без прозрачности она закрыла бы цветной слой.
        fill.fillRect(QRectF(box), Qt.transparent)
        fill.end()
        # Одной картинкой целиком: четыре куска по краям рисовались вдвое
        # дольше (2,4 мс на кадр) — Qt тратит время на каждый кусок отдельно.
        painter.drawImage(0, 0, fog)

    def paint_fog_box(self, painter: QPainter, box: QRect, size: QSize,
                      mask: QImage, mask_key, shade: QColor, rooms,
                      world_alpha: int, room_alpha: int):
        """Туман внутри рамки сектора: он растворяется на кромке зрения.

        Слой собирается только в рамке, а не во весь экран: маска обрезает
        его только здесь, за пределами рамки туман уже залит полосами. Сам
        буфер живёт между кадрами — см. `scratch_image`.
        """
        if world_alpha <= 0 and (room_alpha <= 0 or rooms is None):
            return
        # Слой собирается в постоянном буфере с запасом на шаг и ложится
        # куском рамки: новая маленькая картинка на видеокарте рисовалась
        # чёрным прямоугольником во всю рамку сектора.
        fog = self.scratch_image("fog_box", box.size(), FOG_LAYER_STEP_PX)
        fill = QPainter(fog)
        fill.setCompositionMode(QPainter.CompositionMode_Source)
        world = QColor(shade)
        world.setAlpha(int(round(255.0 * world_alpha / 100.0)))
        fill.fillRect(QRectF(0, 0, box.width(), box.height()), world)
        if rooms is not None:
            room = QColor(shade)
            room.setAlpha(int(round(255.0 * room_alpha / 100.0)))
            fill.translate(-box.x(), -box.y())
            fill.fillPath(rooms, room)
        fill.end()
        # Мягкий край: там, где зрения нет, туман во всю силу, а на кромке
        # плавно растворяется. Маска берётся только в рамке.
        dim = QPainter(fog)
        dim.setCompositionMode(QPainter.CompositionMode_DestinationIn)
        dim.drawImage(QRectF(0, 0, box.width(), box.height()),
                      self.inverse_vision_mask(mask, mask_key), QRectF(box))
        dim.end()
        painter.drawImage(box.topLeft(), fog, QRect(0, 0, box.width(),
                                                    box.height()))

    def draw_empty_hint(self, painter: QPainter):
        painter.setPen(QPen(QColor(170, 170, 178)))
        f = painter.font()
        f.setPointSize(13)
        painter.setFont(f)
        painter.drawText(self.rect(), Qt.AlignCenter,
                         "Карта не загружена.\n\n"
                         "Нажмите правую кнопку мыши -> «Добавить карту»\n"
                         "или перетащите файл изображения прямо в это окно.\n\n"
                         "Вид: колесо мыши — масштаб, СКМ — перемещение, Tab — центрировать.")

    def draw_map_pixmap(self, painter: QPainter, rect: QRectF):
        """Нарисовать карту — плитками, если она большая.

        Qt передаёт QPixmap видеокарте ОДНОЙ текстурой. Если сторона больше
        ``GL_MAX_TEXTURE_SIZE`` или под текстуру не хватает памяти, загрузка
        обрывается молча, и на холсте остаётся чёрный прямоугольник — именно
        так вели себя карты 6000–9000 px. Плитка — своя маленькая текстура,
        поэтому карта рисуется на любой видеокарте. Мир, сетка и координаты
        считаются по исходным пикселям и от нарезки не зависят.
        """
        pixmap = self.map_image
        if not pixmap or pixmap.isNull():
            return
        if not self._map_tiles:
            painter.drawPixmap(rect, pixmap,
                               QRectF(0, 0, pixmap.width(), pixmap.height()))
            return
        # Плитки ложатся тем же преобразованием, что и целая карта: кусок
        # картинки пересчитывается в мировые координаты ровно так же, как
        # вся карта, поэтому содержимое стыкуется пиксель в пиксель.
        step_x = rect.width() / float(max(1, pixmap.width()))
        step_y = rect.height() / float(max(1, pixmap.height()))
        visible = QRectF((-self.offset_x) / self.scale,
                         (-self.offset_y) / self.scale,
                         self.width() / self.scale,
                         self.height() / self.scale)

        def world(piece: QRectF) -> QRectF:
            return QRectF(rect.left() + piece.x() * step_x,
                          rect.top() + piece.y() * step_y,
                          piece.width() * step_x,
                          piece.height() * step_y)

        for own, padded, tile in self._map_tiles:
            own_target = world(own)
            if not own_target.intersects(visible):
                continue
            # Обрезка по своей части: запас берёт соседние пиксели только
            # для сглаживания, чтобы на стыке не было тёмной полосы.
            painter.save()
            painter.setClipRect(own_target)
            painter.drawPixmap(world(padded), tile,
                               QRectF(0, 0, tile.width(), tile.height()))
            painter.restore()

    @property
    def time_of_day(self) -> str:
        """Освещение открытой карты: "day" или "night"."""
        return normalize_time_of_day(getattr(self.current_map,
                                             "time_of_day", None))

    def set_time_of_day(self, value, notify: bool = True):
        """Переключить освещение карты и (по умолчанию) сказать об этом всем."""
        m = self.current_map
        if m is None:
            return
        mode = normalize_time_of_day(value)
        if normalize_time_of_day(getattr(m, "time_of_day", None)) == mode:
            return
        m.time_of_day = mode
        self.update()
        if notify:
            self.time_of_day_changed.emit(mode)

    def toggle_time_of_day(self, night: bool = None) -> bool:
        """Пункт меню «Ночь»: переключить день/ночь. -> теперь ночь?"""
        if self.current_map is None:
            return False
        if night is None:
            night = self.time_of_day != "night"
        self.set_time_of_day("night" if night else "day")
        return self.time_of_day == "night"

    def night_tint_pair(self) -> tuple:
        """Цвет ночи и плотность в процентах для открытой карты."""
        m = self.current_map
        return (lighting_rules.normalize_night_color(
                    getattr(m, "night_color", None)),
                lighting_rules.normalize_night_alpha(
                    getattr(m, "night_alpha", None)))

    def night_tint_color(self) -> QColor:
        """Цвет затемнения с альфой из процентов плотности."""
        color, alpha = self.night_tint_pair()
        tint = QColor(color)
        tint.setAlpha(int(round(alpha * 255.0 / 100.0)))
        return tint

    def set_night_tint(self, color: str = None, alpha: int = None,
                       notify: bool = True):
        """Сменить цвет и/или плотность ночи (мастер, всем участникам).

        Плотность — проценты: 0 — ночь ничего не затемняет, 100 — карта
        полностью закрашена. Параметры принадлежат карте, поэтому у каждого
        стола своё ночное освещение.
        """
        m = self.current_map
        if m is None:
            return
        current_color, current_alpha = self.night_tint_pair()
        m.night_color = lighting_rules.normalize_night_color(
            color if color is not None else current_color)
        m.night_alpha = lighting_rules.normalize_night_alpha(
            alpha if alpha is not None else current_alpha)
        self.update()
        if notify:
            self.night_tint_changed.emit(m.night_color, m.night_alpha)

    def night_level(self, now: float = None) -> float:
        """Доля ночи на экране: 0 — день, 1 — полная ночь.

        Включение и выключение ночи идёт не рывком, а за NIGHT_FADE_S с
        кривой smoothstep: темнота наплывает и уходит мягко. Переход
        замечается здесь же при отрисовке (как у створки двери), поэтому
        одинаково плавно смотрят и щелчок в меню «Стол», и кнопки во
        вкладке «Отдых», и ночь по эху сервера.
        """
        now = time.monotonic() if now is None else now
        target = 1.0 if self.time_of_day == "night" else 0.0
        fade = self._night_fade
        if fade is None:
            # Первый кадр карты: сразу в её состоянии, без наплыва
            # затемнения при каждом открытии мира.
            self._night_fade = {"from": target, "to": target, "start": now}
            return target
        if fade["to"] != target:
            fade = {"from": self._night_level_at(fade, now), "to": target,
                    "start": now}
            self._night_fade = fade
            self._ensure_anim_timer()
        return self._night_level_at(fade, now)

    @staticmethod
    def _night_level_at(fade: dict, now: float) -> float:
        """Значение перехода в момент now: smoothstep от from к to."""
        span = fade["to"] - fade["from"]
        if abs(span) < 1e-6:
            return float(fade["to"])
        progress = (now - fade["start"]) / NIGHT_FADE_S
        progress = max(0.0, min(1.0, progress))
        eased = progress * progress * (3.0 - 2.0 * progress)
        return float(fade["from"]) + span * eased

    def _night_anim_pending(self) -> bool:
        """Идёт ли ещё наплыв темноты (нужен ли кадр таймера)."""
        fade = self._night_fade
        if fade is None or fade["from"] == fade["to"]:
            return False
        return time.monotonic() < fade["start"] + NIGHT_FADE_S

    def lighting_lights(self) -> list:
        """Все источники света открытой карты (не только включённые)."""
        m = self.current_map
        if m is None:
            return []
        return lighting_rules.normalize_lights(getattr(m, "lights", None))

    def set_graphics(self, settings):
        """Применить настройки графики: качество теней, сглаживание, отсвет.

        Всё, что посчитано по этим числам, живёт в кэшах (многоугольники
        источников, маски ночи и отсвета, картинки факелов), поэтому после
        смены настроек кэши сбрасываются: иначе мастер снизил бы качество,
        а стол продолжал бы показывать старые тени.
        """
        self.graphics = graphics_rules.normalize(settings)
        self._light_polygons.clear()
        self._light_paths.clear()
        self._sight_index = None
        self._sight_index_version = -1
        self._night_mask_signature = None
        self._day_glow_signature = None
        self._torch_icon_cache.clear()
        self.update()

    def graphics_report(self) -> dict:
        """Цифры для окна настроек: буферы холста и время кадра."""
        return {"buffers": self.buffer_bytes(),
                "frame_ms": self.frame_ms_avg or None,
                "lights": len(self.night_lights()),
                "walls": len(self.wall_sight_segments())}

    def buffer_bytes(self) -> int:
        """Сколько памяти занимают буферы холста (байты).

        Считаем только то, что держим сами: маски ночи, отсвета и тумана
        плюс картинки карты. Видеопамять драйвера отсюда не видна — её
        показывает `shared.hwinfo` по данным драйвера.
        """
        total = 0
        for image in (self._night_mask_image, self._day_glow_image,
                      self._object_layer_image,
                      self._fog_scene_image,
                      self._fog_frame_image,
                      *self._scratch_images.values(),
                      self._grid_image):
            if image is not None:
                total += int(image.sizeInBytes())
        seen = set()
        for pixmap in list(self.object_images.values()) + [self.map_image]:
            if pixmap is None or pixmap.isNull() or id(pixmap) in seen:
                continue
            seen.add(id(pixmap))
            total += int(pixmap.width()) * int(pixmap.height()) * 4
        return total

    def set_lighting_enabled(self, enabled: bool):
        """Включить модуль освещения (галочка стартового окна)."""
        self.lighting_enabled = bool(enabled)
        if not self.lighting_enabled:
            self.light_editing = False
            self._dragging_light_id = None
        self.update()

    def set_player_vision_mode(self, mode: str, notify: bool = True):
        """Настройка мастера: что игроку видно цветным.

        ``notify=False`` — режим пришёл с сервера, обратно его не шлём.

        ``"cone"`` — только сектор обзора токена (угол и дальность из его
        карточки), ``"around"`` — всё вокруг токена в радиусе зрения, как
        было до настройки. Маска зрения кэшируется, поэтому режим входит в
        ключ кэша, а не просто запоминается.
        """
        mode = str(mode or "around").strip().casefold()
        mode = "cone" if mode == "cone" else "around"
        changed = mode != self.player_vision_mode
        self.player_vision_mode = mode
        self._vision_cache_key = None
        self._vision_cache_path = None
        if changed and notify and self.is_dm:
            self.vision_mode_changed.emit(mode)
        self.update()

    def set_hide_dm_walls(self, hidden: bool):
        """Скрыть у мастера все стены и окна: двери остаются видны.

        Нужно для игры на телевизоре и оффлайн-стола: мастер готовит сцену
        заранее и одним переключателем убирает со своего экрана то, чего
        игроки видеть не должны. Двери — предмет стола, их видно всегда.
        """
        hidden = bool(hidden)
        if hidden == self.hide_dm_walls:
            return
        self.hide_dm_walls = hidden
        self.update()

    def set_dm_fog_enabled(self, enabled: bool):
        """Туман войны для мастера: вид как у игроков, но права те же.

        Туман считается по объединению зрения **всех** токенов игроков,
        поэтому мастер сразу видит то, что видит стол, и не видит своих
        актёров в неразведанных местах. Актёра, выбранного в списке сцены,
        холст покажет — иначе им нельзя было бы управлять мышью.
        """
        enabled = bool(enabled)
        if enabled == self.dm_fog_enabled:
            return
        self.dm_fog_enabled = enabled
        self._vision_cache_key = None
        self._vision_cache_path = None
        self.update()

    def set_sheet_lookup(self, lookup):
        """Отдать холсту способ достать лист персонажа по токену.

        Тёмное зрение записано в листе или в статблоке, а не в токене;
        без листа ночью персонаж с тёмным зрением оставался в темноте.
        """
        self.sheet_lookup = lookup
        self._vision_cache_key = None
        self._vision_cache_path = None
        self.update()

    def set_light_editing(self, active: bool):
        """Вкладка освещения открыта: маркеры света можно таскать мышью.

        Вне этой вкладки клики по карте остаются прежними: свет не должен
        перехватывать щелчки по токенам и рисование.
        """
        self.light_editing = bool(active and self.is_dm
                                  and self.lighting_enabled)
        if not self.light_editing:
            self._dragging_light_id = None
        self.update()

    def set_map_lights(self, lights, notify: bool = True,
                       remember: bool = True):
        """Записать источники света карты и (по умолчанию) сообщить окну.

        ``remember=False`` — правка не должна попасть в историю отмены.
        Так меняется сила света: мастер подбирает её ползунком, и шаги
        ползунка не должны становиться отдельными действиями Ctrl+Z.
        """
        m = self.current_map
        if m is None:
            return
        # Снимок «до» берём только для зафиксированных правок: при
        # перетаскивании иконка двигается с notify=False, и промежуточные
        # положения мыши не должны попадать в историю.
        before = self.lights_snapshot() if notify and remember else None
        m.lights = lighting_rules.normalize_lights(lights)
        if self.selected_light_id not in {l["id"] for l in m.lights}:
            self.selected_light_id = None
        self.update()
        if notify:
            self._emit_lights_changed(before)

    def lights_snapshot(self) -> list:
        """Список источников карты для истории: копии словарей."""
        return [dict(light) for light in self.lighting_lights()]

    def take_lights_before(self):
        """Снимок света до последней правки; None — снимать было нечего.

        Окно забирает его в своём слоте (сигнал синхронный), а холст тут же
        забывает: иначе следующий Ctrl+Z вернул бы чужую правку.
        """
        before = self._lights_before
        self._lights_before = None
        return before

    def _emit_lights_changed(self, before=None):
        """Разослать свет и отдать окну снимок «до» — для истории."""
        self._lights_before = before
        try:
            self.lights_changed.emit(
                [dict(light) for light in self.lighting_lights()])
        finally:
            self._lights_before = None

    def add_light(self, x: float = None, y: float = None,
                  preset: str = None) -> Optional[dict]:
        """Поставить свет заготовкой в точку или в центр экрана.

        Заготовка (``preset``: свеча, факел, костёр, лампа, магия) приносит
        с собой радиус, температуру и мягкость кромки, поэтому новый источник
        сразу выглядит правильно, а не серым кругом по умолчанию.
        """
        if (not self.lighting_enabled or not self.is_dm
                or self.current_map is None):
            return None
        lights = self.lighting_lights()
        if x is None or y is None:
            x, y = self.view_center_snapped()
        key = preset or lighting_rules.DEFAULT_LIGHT_PRESET
        chosen = lighting_rules.light_preset(key)
        if chosen is None:
            key = lighting_rules.DEFAULT_LIGHT_PRESET
            chosen = lighting_rules.light_preset(key)
        # Нумерация по своему виду: «Свеча 2», а не «Свеча 7» из-за костров.
        number = 1 + sum(1 for light in lights
                         if str(light["name"]).startswith(chosen["name"] + " "))
        light = lighting_rules.light_from_preset(key, x, y, number)
        self.set_map_lights(lights + [light])
        self.selected_light_id = light["id"]
        return light

    def set_light_drop_preview(self, key: str = None, wx: float = None,
                               wy: float = None):
        """Круг-подсказка: где и с каким радиусом встанет свет.

        Заготовку несут из вкладки «Освещение» на карту — без подсказки не
        видно ни точки, ни радиуса будущего источника, и отпускать
        приходилось вслепую.
        """
        if key is None or wx is None or wy is None:
            if self._light_drop_preview is not None:
                self._light_drop_preview = None
                self.update()
            return
        preset = lighting_rules.light_preset(key)
        if preset is None:
            self.set_light_drop_preview()
            return
        preview = {
            "key": key,
            "x": float(wx),
            "y": float(wy),
            "radius": self.light_radius_world(
                {"radius_ft": preset["radius_ft"]}),
            "color": lighting_rules.kelvin_to_color(preset["kelvin"]),
        }
        if preview != self._light_drop_preview:
            self._light_drop_preview = preview
            self.update()

    def drop_light_preset(self, key: str, wx: float, wy: float):
        """Отпустили заготовку на карте: источник ровно в этой точке.

        Заготовка приносит свой радиус, температуру и мягкость края через
        ``add_light``, так что новый свет сразу выглядит правильно и
        уходит всем участникам обычным `UPDATE_LIGHTS`.
        """
        self.set_light_drop_preview()
        light = self.add_light(x=wx, y=wy, preset=key)
        if light is not None:
            self.light_preset_dropped.emit(dict(light))
        return light

    def update_light(self, light_id: str, notify: bool = True,
                     remember: bool = True, **fields):
        """Поменять поля одного источника (радиус, цвет, включённость, имя).

        Температура — основной способ задать цвет: когда приходит только
        ``kelvin``, цвет пересчитывается из неё, и мастеру не нужно держать
        в голове два согласованных параметра.
        """
        if "kelvin" in fields and "color" not in fields:
            fields["color"] = lighting_rules.kelvin_to_color(fields["kelvin"])
        lights = []
        for light in self.lighting_lights():
            if light["id"] == light_id:
                merged = dict(light)
                merged.update(fields)
                light = lighting_rules.normalize_light(merged)
                light["id"] = light_id
            lights.append(light)
        self.set_map_lights(lights, notify=notify, remember=remember)

    def update_lights(self, light_ids, notify: bool = True,
                      remember: bool = True, **fields):
        """Поменять поля сразу у нескольких источников — одной правкой.

        Один вызов `set_map_lights` — это одно сообщение `UPDATE_LIGHTS`
        всем и одна запись в истории, а не по записи на каждый факел:
        глазок и замок в списке ставятся на всё выделение разом.
        """
        wanted = {str(item) for item in (light_ids or [])}
        if not wanted:
            return
        if "kelvin" in fields and "color" not in fields:
            fields["color"] = lighting_rules.kelvin_to_color(fields["kelvin"])
        lights = []
        for light in self.lighting_lights():
            if light["id"] in wanted:
                merged = dict(light)
                merged.update(fields)
                light = lighting_rules.normalize_light(merged)
                light["id"] = merged["id"]
            lights.append(light)
        self.set_map_lights(lights, notify=notify, remember=remember)

    def remove_light(self, light_id: str):
        """Убрать источник света с карты."""
        self.remove_lights([light_id])

    def remove_lights(self, light_ids):
        """Убрать несколько источников одной правкой.

        Del/X в списке может снять сколько угодно выделенных рамкой
        факелов: сервер должен получить одно сообщение, а история — одну
        запись, как и при массовом глазке.
        """
        wanted = {str(item) for item in (light_ids or [])}
        if not wanted:
            return
        lights = [light for light in self.lighting_lights()
                  if light["id"] not in wanted]
        if len(lights) == len(self.lighting_lights()):
            return
        if self.selected_light_id in wanted:
            self.selected_light_id = None
        self.set_map_lights(lights)

    def light_radius_world(self, light) -> float:
        """Радиус света в мировых единицах по сетке; 0 — сетки нет."""
        cell_w = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        if cell_w <= 0:
            return 0.0
        radius_ft = lighting_rules.normalize_radius(light.get("radius_ft"))
        return radius_ft / vision_rules.FT_PER_CELL * cell_w

    def light_marker_radius_world(self) -> float:
        """Радиус попадания по иконке факела — от размера клетки."""
        return self.design(12.0)

    def light_at(self, wx: float, wy: float) -> Optional[dict]:
        """Какой источник света под точкой (для перетаскивания).

        Спрятанную глазком иконку мышью не зацепить: иначе мастер таскал бы
        невидимый источник и не понимал, что двигает.
        """
        reach = max(self.light_marker_radius_world() * 1.6, 1.0)
        for light in reversed(self.lighting_lights()):
            if (light.get("marker_hidden")
                    and light["id"] != self.selected_light_id):
                continue
            if (abs(light["x"] - wx) <= reach
                    and abs(light["y"] - wy) <= reach):
                return light
        return None

    def light_at_screen(self, sx: float, sy: float) -> Optional[dict]:
        """Источник под курсором по самой иконке факела (экранные координаты).

        Мазать по точке источника неудобно: факел нарисован вверх от неё,
        и клик по пламени уходил мимо — источник «не тащился». Поэтому
        попадание считается по прямоугольнику рисунка с запасом в пару
        пикселей, как у любого инструмента.
        """
        size = self.light_icon_px()
        pad = self.overlay_px(3.0)
        rect = QRectF((self.TORCH_LEFT * size) - pad,
                      (self.TORCH_TOP * size) - pad,
                      (self.TORCH_RIGHT - self.TORCH_LEFT) * size + 2 * pad,
                      (self.TORCH_BOTTOM - self.TORCH_TOP) * size + 2 * pad)
        for light in reversed(self.lighting_lights()):
            if (light.get("marker_hidden")
                    and light["id"] != self.selected_light_id):
                continue
            center = self.light_marker_center(light)
            if rect.translated(center).contains(QPointF(sx, sy)):
                return light
        return None

    def _start_light_drag(self, light, wx: float, wy: float):
        """Взять источник мышью: выделить и начать перенос.

        Снимок «до» берётся один раз на весь жест: в историю отмены
        попадает перетаскивание целиком, а не каждый пиксель.
        """
        self.selected_light_id = light["id"]
        # Выбор виден в двух местах: на холсте и строкой в списке.
        self.light_selected.emit(light["id"])
        if light.get("locked"):
            self.show_hint("Источник закреплён — снимите замок "
                           "на вкладке «Освещение»")
            self.update()
            return
        self._dragging_light_id = light["id"]
        self._light_drag_offset = (wx - light["x"], wy - light["y"])
        self._light_drag_before = self.lights_snapshot()
        self.update()

    def night_lights(self) -> list:
        """Горящие сейчас источники с радиусом в мире: список (свет, радиус).

        Учитывается «только ночью»: днём такие источники не светят.
        """
        if not self.lighting_enabled or self.current_map is None:
            return []
        result = []
        for light in lighting_rules.active_lights(self.current_map):
            radius = self.light_radius_world(light)
            if radius > 0:
                result.append((light, radius))
        return result

    def object_geometry_key(self) -> tuple:
        """Дешёвая подпись объектов: где они стоят и как повёрнуты.

        Тени света зависят только от этих чисел. Раньше в подпись маски
        входили все углы всех объектов (по четыре точки с округлением),
        и она собиралась на КАЖДОМ кадре — при сотне объектов это было
        дороже, чем сама отрисовка.
        """
        key = []
        for obj in self._object_z_order():
            if not obj.visible:
                continue
            key.append((obj.id, round(float(obj.x), 2), round(float(obj.y), 2),
                        round(float(obj.width), 2),
                        round(float(obj.height), 2),
                        round(float(obj.rotation or 0.0), 2)))
        return tuple(key)

    def light_occluders(self) -> list:
        """Четырёхугольники видимых объектов — препятствия для света.

        Считаются один раз на расстановку объектов: пока их не двигали,
        список берётся из кэша (подпись — `object_geometry_key`).
        """
        key = self.object_geometry_key()
        if self._occluders_cache is not None and self._occluders_key == key:
            return self._occluders_cache
        visible = {obj.id for obj in self._object_z_order() if obj.visible}
        corners = [self.object_corners_world(obj)
                   for obj in self._object_z_order()
                   if obj.id in visible]
        self._occluders_cache = corners
        self._occluders_key = key
        return corners

    def sight_index(self):
        """Индекс отрезков стен для света — живёт до правки геометрии."""
        if (self._sight_index is not None
                and self._sight_index_version == self._geometry_version):
            return self._sight_index
        self._sight_index = wall_rules.SegmentIndex(
            self.wall_sight_segments())
        self._sight_index_version = self._geometry_version
        return self._sight_index

    def draw_time_of_day(self, painter: QPainter, rect: QRectF):
        """Темнота ночи — под токенами, поверх поверхности карты.

        С включённым модулем освещения источники вырезают из темноты
        освещённые круги; без модуля (или без света) карта просто темнеет,
        как раньше.

        Свет собирается в один слой маски: каждый источник «вытирает» из
        затемнения свой круг с плавной кромкой (ширину кромки задаёт
        интенсивность). Раньше на общий путь накладывался ещё и градиент
        каждого источника — у соседних факелов кромки складывались, и вокруг
        света появлялось тёмное кольцо, которого быть не должно.
        """
        # Доля ночи — не 0/1, а плавный переход: при включении и выключении
        # карта гаснет и разгорается за NIGHT_FADE_S, а не моргает.
        level = self.night_level()
        if level <= 0.004:
            return
        # Цвет ночи выбирает мастер: по умолчанию глубокий синий, но стол
        # можно залить красным или зелёным. Плотность — проценты альфы.
        tint = self.night_tint_color()
        if tint.alpha() <= 0:
            return
        lights = self.night_lights()
        cut = self._night_cut_path
        if not lights and cut is None:
            painter.save()
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(tint))
            # Альфа накладывается один раз здесь, при отрисовке: маска и
            # цвет не зависят от доли ночи и не пересчитываются каждый кадр.
            painter.setOpacity(level)
            painter.drawRect(rect)
            painter.restore()
            return

        # Маска ночи живёт в МИРОВЫХ координатах и привязана к сетке мира,
        # а не к камере. Раньше в подпись входили смещение и зум, и каждый
        # сдвиг мыши пересчитывал все тени с нуля — на двух десятках светов
        # это были секунды на кадр. Теперь маска просто едет вместе с картой.
        span = self.mask_world_rect()
        if span is None:
            return
        if not lights:
            # Ночь без источников, но с тёмным зрением: заливка сплошная,
            # из неё вырезаются круги тёмного зрения игрока. Заливка всего
            # экрана и вырез путей стоят дороже, чем кажется: без кэша этот
            # кадр выходил 43 мс на 1600×900 — дороже, чем ночь с 57
            # источниками. Подпись здесь своя: заливка и вырез, без света.
            if self._night_mask_signature is None:
                self._night_plain_signature = None
            size = self.mask_size(span)
            mask = self.night_mask(size)
            signature = (tint.rgba(), round(span.x(), 2),
                         round(span.y(), 2), size.width(), size.height(),
                         self._geometry_version, self._night_cut_key)
            if self._night_plain_signature != signature:
                mask.fill(tint)
                self._erase_night_cut(mask, span)
                self._night_plain_signature = signature
            self._night_mask_signature = signature
            painter.save()
            painter.setOpacity(level)
            self.draw_mask_image(painter, span, mask)
            painter.restore()
            return
        # Маска перерисовывается только когда меняются свет, цвет, зум,
        # геометрия стен или тёмное зрение — но НЕ смещение камеры.
        occluders = self.light_occluders()
        lights_key = (round(span.x(), 2), round(span.y(), 2),
                      round(span.width(), 2), round(span.height(), 2),
                      tint.rgba(), round(float(self.scale), 6),
                      self.light_rays(),
                     bool(self.graphics.get("shadows", True)),
                     tuple((light["id"], round(float(light["x"]), 3),
                            round(float(light["y"]), 3), light["radius_ft"],
                            light["color"], light["intensity"])
                           for light, _radius in lights),
                     # Объекты и стены отбрасывают тени: пока их не было в
                     # подписи, поставленная среди сессии стена не вырезала
                     # свет из маски, пока камера или источник не менялись.
                     # Берём дешёвые подписи (`_occluders_key` — где стоят
                     # объекты) и версию геометрии: перечислять углы сотни
                     # стен каждый кадр дороже самой отрисовки.
                     self._occluders_key or (),
                     tuple((item["id"], bool(item.get("open")),
                            round(float(item.get("at") or 0.0), 2))
                           for item in self.map_openings()),
                     self._geometry_version)
        # Полная подпись (что за кадр на экране) отдельно от подписи света:
        # по ней тесты и сбросы понимают, что маску надо собрать заново.
        signature = lights_key + (self._night_cut_key,)
        if self._night_mask_signature is None:
            # Сброс кэшей (правка стен, смена карты, тесты): всё заново.
            self._night_lights_image = None
        mask = self.night_mask(self.mask_size(span))
        no_cut = cut is None or cut.isEmpty()
        image = self._night_lights_image
        if self._night_mask_signature == signature:
            # Ничего не поменялось (камера едет, свет и взгляд стоят):
            # на экран идёт готовая маска прошлого кадра.
            layer_image = image if no_cut else mask
        else:
            if (image is None or image.size() != mask.size()
                    or self._night_lights_signature != lights_key):
                self._paint_night_mask(mask, tint, lights, span, occluders,
                                       with_cut=False)
                self._night_lights_image = mask.copy()
                self._night_lights_signature = lights_key
                self._night_plain_signature = None
                image = self._night_lights_image
            if no_cut:
                # Смотреть из темноты некому: готовый слой света идёт как есть.
                layer_image = image
            else:
                # Вырез тёмного зрения меняется на каждый шаг взгляда, а
                # свет — нет. Поэтому свет берём из кэша, а вырез кладём в
                # свободный буфер: копия готового слоя дешевле, чем 57
                # кругов с тенями.
                mask.fill(QColor(0, 0, 0, 0))
                copy = QPainter(mask)
                copy.setCompositionMode(QPainter.CompositionMode_Source)
                copy.drawImage(0, 0, image)
                copy.end()
                self._erase_night_cut(mask, span)
                self._night_plain_signature = None
                layer_image = mask
            self._night_mask_signature = signature

        # Маска кладётся в мировом прямоугольнике: painter уже в координатах
        # карты, поэтому сдвиг камеры — это просто перенос готовой картинки.
        painter.save()
        painter.setOpacity(level)
        self.draw_mask_image(painter, span, layer_image)
        painter.restore()

    def day_glow_lights(self) -> list:
        """Горячие источники, видимые и днём: список (свет, радиус, альфа).

        Обычные свеча и факел днём не видны: их свет слабее дневного. С
        `DAYLIGHT_GLOW_KELVIN` (8000 K) источник уже «сверх силы» — его
        отсвет рисуется и на светлой карте.
        """
        if not self.lighting_enabled or self.current_map is None:
            return []
        result = []
        for light in lighting_rules.daylight_lights(self.current_map):
            radius = self.light_radius_world(light)
            alpha = lighting_rules.daylight_glow_alpha(light)
            if radius > 0 and alpha > 0:
                result.append((light, radius, alpha))
        return result

    def draw_day_glow(self, painter: QPainter, rect: QRectF):
        """Свет «сверх силы» днём: мягкий отсвет поверх светлой карты.

        Без него горячий источник в день просто невидим: на столе темнота
        не рисуется, и понять, что маяк или магический свет вообще что-то
        освещает, нельзя. Отсвет кладётся осветлением (`CompositionMode_
        Screen`): он именно добавляет света к рисунку, а не закрашивает его
        цветной плёнкой. Сложение (`Plus`) здесь не годится: на светлой карте
        оно упирается в белый и стирает под собой и сетку, и стены, — вместо
        освещённого пятачка получается белое пятно. Крутится по тому же пути,
        что и ночь: маска кэшируется по подписи, тени объектов и стены
        учитываются `light_clip_path`.
        """
        level = self.night_level()
        if not self.graphics.get("day_glow", True):
            return
        lights = self.day_glow_lights()
        if not lights or level >= 0.996:
            # Глубокая ночь: там свет и так вырезает темноту.
            return
        # Тот же мировой прямоугольник, что и у ночи: отсвет привязан к
        # карте, а не к камере, и при панорамировании не пересчитывается.
        span = self.mask_world_rect()
        if span is None:
            return
        occluders = self.light_occluders()
        signature = (round(span.x(), 2), round(span.y(), 2),
                     round(span.width(), 2), round(span.height(), 2),
                     round(float(self.scale), 6),
                     self.light_rays(),
                     bool(self.graphics.get("shadows", True)),
                     tuple((light["id"], round(float(light["x"]), 3),
                            round(float(light["y"]), 3), light["radius_ft"],
                            light["color"], light["intensity"], alpha)
                           for light, _radius, alpha in lights),
                     self._occluders_key or (),
                     self._geometry_version)
        mask = self.day_glow_mask(self.mask_size(span))
        if self._day_glow_signature != signature:
            self._paint_day_glow_mask(mask, lights, span, occluders)
            self._day_glow_signature = signature
        # На закате дневной отсвет уступает место настоящему ночному свету.
        fade = 1.0 - level
        painter.save()
        painter.setCompositionMode(QPainter.CompositionMode_Screen)
        painter.setOpacity(fade)
        self.draw_mask_image(painter, span, mask)
        painter.restore()

    def _paint_day_glow_mask(self, mask: QImage, lights: list, span: QRectF,
                             occluders=None):
        """Слой дневного отсвета: пятна горячих источников без темноты."""
        mask.fill(Qt.transparent)
        layer = QPainter(mask)
        self._mask_antialias(layer)
        # Осветление: два горячих источника рядом дают вместе ярче пятно,
        # как настоящий свет, но карта под ними не выцветает в белое.
        layer.setCompositionMode(QPainter.CompositionMode_Screen)
        if occluders is None:
            occluders = self.light_occluders()
        for light, radius, alpha in lights:
            center = self.world_to_mask(light["x"], light["y"], span)
            edge = radius * self.scale
            if edge <= 0.5 or not self._mask_touches(center, edge, mask):
                continue
            clip = self.light_clip_path(light, radius, center, edge, span,
                                        occluders)
            layer.save()
            if clip is not None:
                layer.setClipPath(clip)
            core = max(0.02, min(0.999, lighting_rules.falloff(light)))
            # Отсвет днём — белее самого света: на солнце виден не оттенок
            # лампы, а яркость. Холодный сизый цвет на тёплом скане читался бы
            # как туман, а не как свет.
            color = QColor(lighting_rules.daylight_glow_color(light))
            hot = QColor(color)
            hot.setAlpha(alpha)
            warm = QColor(color)
            warm.setAlpha(max(1, int(alpha * 0.7)))
            clear = QColor(color)
            clear.setAlpha(0)
            gradient = QRadialGradient(center, edge)
            gradient.setColorAt(0.0, hot)
            gradient.setColorAt(core, warm)
            gradient.setColorAt(1.0, clear)
            layer.setPen(Qt.NoPen)
            layer.setBrush(QBrush(gradient))
            layer.drawEllipse(center, edge, edge)
            layer.restore()
        layer.end()

    def day_glow_mask(self, size: QSize) -> QImage:
        """Буфер слоя дневного отсвета: пересоздаётся только при смене размера."""
        image = self._day_glow_image
        if image is not None and image.size() == size:
            return image
        image = QImage(size, QImage.Format_ARGB32_Premultiplied)
        self._day_glow_image = image
        return image

    def mask_world_rect(self):
        """Мировой прямоугольник под маску ночи и отсвета.

        Хитрость простая: берём видимую часть карты, добавляем запас и
        привязываем края к мировой сетке (`MASK_SNAP`). Пока камера едет
        внутри запаса, прямоугольник не меняется — значит, маску можно не
        перерисовывать, а просто сдвинуть вместе с картой. Размер маски в
        пикселях почти не зависит от зума: это видимый кусок, умноженный на
        масштаб (и запас).
        """
        if self.width() <= 0 or self.height() <= 0:
            return None
        left, top = self.screen_to_world(0, 0)
        right, bottom = self.screen_to_world(self.width(), self.height())
        if right <= left or bottom <= top:
            return None
        margin_x = (right - left) * MASK_MARGIN
        margin_y = (bottom - top) * MASK_MARGIN
        left -= margin_x
        right += margin_x
        top -= margin_y
        bottom += margin_y
        step = MASK_SNAP
        left = math.floor(left / step) * step
        top = math.floor(top / step) * step
        right = math.ceil(right / step) * step
        bottom = math.ceil(bottom / step) * step
        return QRectF(left, top, right - left, bottom - top)

    def mask_size(self, span: QRectF) -> QSize:
        """Размер маски в пикселях: мировой прямоугольник × зум."""
        width = max(1, int(round(span.width() * float(self.scale))))
        height = max(1, int(round(span.height() * float(self.scale))))
        return QSize(width, height)

    def world_to_mask(self, x: float, y: float, span: QRectF) -> QPointF:
        """Мировая точка → пиксель маски (левый верхний угол — это span)."""
        scale = float(self.scale)
        return QPointF((float(x) - span.x()) * scale,
                       (float(y) - span.y()) * scale)

    def draw_mask_image(self, painter: QPainter, span: QRectF, image: QImage):
        """Положить маску на карту — куском, ровно пиксель в пиксель.

        Маска посчитана в мировых координатах, но её размер — это
        `span × зум` (`mask_size`), то есть она уже лежит 1:1 с пикселями
        экрана. Раньше она всё равно рисовалась в мировых координатах под
        преобразованием, и Qt каждый кадр растягивал всю картинку
        билинейно — по замеру 6 мс на кадр только на ночь, больше, чем вся
        остальная карта вместе. Теперь слой кладётся без преобразования,
        целым пиксельным сдвигом: Qt копирует его быстрым путём.

        Маска с запасом заметно больше экрана: при 1920×1080 со запасом в
        30% это 2304×1536 пикселей на слой, поэтому копируется только та
        часть, которая попадает в окно, и ещё с запасом в пиксель — чтобы
        край сдвига не мылил.
        """
        if image is None or image.isNull():
            return
        scale = float(self.scale)
        if scale <= 0 or self.width() <= 0 or self.height() <= 0:
            painter.drawImage(span, image)
            return
        left, top = self.screen_to_world(0, 0)
        right, bottom = self.screen_to_world(self.width(), self.height())
        x0 = max(left, span.left())
        y0 = max(top, span.top())
        x1 = min(right, span.right())
        y1 = min(bottom, span.bottom())
        if x1 <= x0 or y1 <= y0:
            painter.drawImage(span, image)
            return
        sx = (x0 - span.x()) * scale
        sy = (y0 - span.y()) * scale
        sw = (x1 - x0) * scale
        sh = (y1 - y0) * scale
        # Границы картинки: округление в `mask_size` может дать на пиксель
        # меньше, и Qt тогда растянул бы маску.
        sw = min(sw, image.width() - sx)
        sh = min(sh, image.height() - sy)
        if sw <= 0 or sh <= 0:
            return
        painter.drawImage(QRectF(x0, y0, x1 - x0, y1 - y0), image,
                          QRectF(max(0.0, sx), max(0.0, sy), sw, sh))

    def _mask_touches(self, center: QPointF, edge: float, mask: QImage) -> bool:
        """Пересекается ли круг света с маской: остальное можно не рисовать."""
        return (center.x() + edge >= 0.0 and center.y() + edge >= 0.0
                and center.x() - edge <= mask.width()
                and center.y() - edge <= mask.height())

    def _mask_antialias(self, layer: QPainter):
        """Сглаживание кромок света, если оно включено в настройках графики."""
        layer.setRenderHint(QPainter.Antialiasing,
                            bool(self.graphics.get("antialiasing", True)))

    def _erase_night_cut(self, mask: QImage, span: QRectF):
        """Стереть из слоя ночи круги тёмного зрения (экранные координаты)."""
        path = self._night_cut_path
        if path is None or path.isEmpty():
            return
        # Путь тёмного зрения построен в экранных координатах; маска — в
        # мировых, поэтому сдвигаем путь на экранное положение её угла.
        origin = QPointF(*self.world_to_screen(span.x(), span.y()))
        layer = QPainter(mask)
        layer.setRenderHint(QPainter.Antialiasing, True)
        layer.setCompositionMode(QPainter.CompositionMode_DestinationOut)
        # Куски стираются по одному: у объединённого пути перекрытия идут с
        # обратным обходом, и в ночи оставались бы непробитые серпы.
        for part in (self._night_cut_parts or (path,)):
            shifted = QPainterPath(part)
            shifted.translate(-origin.x(), -origin.y())
            layer.fillPath(shifted, QColor(0, 0, 0, 255))
        layer.end()

    def _paint_night_mask(self, mask: QImage, tint: QColor, lights: list,
                          span: QRectF, occluders=None, with_cut=True):
        """Нарисовать слой ночи: заливка и вырезанные круги источников.

        `span` — мировой прямоугольник маски; всё внутри считается в её
        пикселях, поэтому результат не зависит от положения камеры.

        `with_cut=False` оставляет круги тёмного зрения на потом: слой
        света кэшируется отдельно от выреза, который двигается каждый шаг.
        """
        mask.fill(tint)
        layer = QPainter(mask)
        self._mask_antialias(layer)
        # DestinationOut стирает альфу там, где рисует кисть: центр круга
        # становится прозрачным, кромка — по градиенту интенсивности.
        layer.setCompositionMode(QPainter.CompositionMode_DestinationOut)
        erase = QColor(0, 0, 0, 255)
        clear = QColor(0, 0, 0, 0)
        if occluders is None:
            occluders = self.light_occluders()
        clips = {}
        for light, radius in lights:
            center = self.world_to_mask(light["x"], light["y"], span)
            edge = radius * self.scale
            if edge <= 0.5 or not self._mask_touches(center, edge, mask):
                continue
            # Объекты — препятствия: свет не проходит сквозь крышу или
            # дерево и обходит их, оставляя тень. Источник, стоящий внутри
            # объекта (лампа в доме), его не затеняет.
            clip = self.light_clip_path(light, radius, center, edge, span,
                                        occluders)
            if clip is not None:
                layer.save()
                layer.setClipPath(clip)
            # Две остановки не могут стоять в одной точке: у совершенно
            # резкой кромки вторая сдвигается на тысячную радиуса, иначе
            # Qt гасит весь круг вместо резкой границы.
            core = max(0.02, min(0.999, lighting_rules.falloff(light)))
            gradient = QRadialGradient(center, edge)
            gradient.setColorAt(0.0, erase)
            gradient.setColorAt(core, erase)
            gradient.setColorAt(1.0, clear)
            layer.setPen(Qt.NoPen)
            layer.setBrush(QBrush(gradient))
            layer.drawEllipse(center, edge, edge)
            if clip is not None:
                layer.restore()
            clips[light["id"]] = clip
        # Тёплый отсвет: свет читается как свет, а не как дырка в темноте.
        layer.setCompositionMode(QPainter.CompositionMode_SourceOver)
        for light, radius in lights:
            center = self.world_to_mask(light["x"], light["y"], span)
            edge = radius * self.scale
            if edge <= 0.5 or not self._mask_touches(center, edge, mask):
                continue
            warm = QColor(light["color"])
            warm.setAlpha(46)
            glow = QRadialGradient(center, max(edge * 0.9, 0.01))
            glow.setColorAt(0.0, warm)
            glow.setColorAt(1.0, QColor(warm.red(), warm.green(), warm.blue(), 0))
            layer.save()
            clip = clips.get(light["id"])
            if clip is not None:
                layer.setClipPath(clip)
            layer.setPen(Qt.NoPen)
            layer.setBrush(QBrush(glow))
            layer.drawEllipse(center, edge * 0.9, edge * 0.9)
            layer.restore()
        layer.end()
        # Тёмное зрение важнее света: в своём круге токен видит и без факела.
        if with_cut:
            self._erase_night_cut(mask, span)

    def light_clip_path(self, light, radius: float, center: QPointF,
                        edge: float, span: QRectF, occluders):
        """Круг света с вырезанными тенями объектов; None — теней нет.

        Геометрия теней считается в мировых координатах (общая с тестами),
        а на слой кладётся уже в экранных.
        """
        # Геометрия теней не зависит от камеры: луч и тень считаются в
        # мировых координатах и живут, пока стоит свет и не менялись стены.
        # Без этого каждый сдвиг камеры заново пускал 220 лучей на каждый
        # источник — при двух десятках светов это секунды на кадр.
        polygon, shadows = self.light_shadow_geometry(light, radius, occluders)
        path = None
        if polygon:
            # Многоугольник уже переведён в пиксели маски — запоминаем его
            # путём и при сдвиге маски просто переносим. Иначе на каждой
            # пересборке из-за двуx десятков источников получалось больше
            # пяти тысяч вызовов перевода точки в пиксели.
            scale = float(self.scale)
            span_x, span_y = float(span.x()), float(span.y())
            cached = self._light_paths.get(id(polygon))
            if cached is not None:
                old_x, old_y, base, old_scale, _polygon = cached
                # Путь собран в пикселях маски при старом зуме. При смене
                # масштаба его надо не только перенести, но и растянуть:
                # иначе после зума свет уезжает от источника к углу карты
                # (переноса без множителя мало — точки уже умножены на
                # старый масштаб).
                ratio = (scale / old_scale) if old_scale else 1.0
                transform = QTransform(ratio, 0.0, 0.0, ratio,
                                       (old_x - span_x) * scale,
                                       (old_y - span_y) * scale)
                path = transform.map(base)
            else:
                screen = [QPointF((px - span_x) * scale,
                                  (py - span_y) * scale)
                          for px, py in polygon]
                path = QPainterPath()
                path.addPolygon(QPolygonF(screen))
                path.closeSubpath()
                if len(self._light_paths) > 512:
                    self._light_paths.clear()
                # Полигон держим рядом с путём: ключ — id(), и если сам
                # полигон собран сборщиком мусора, новый свет мог получить
                # тот же адрес и чужой путь.
                self._light_paths[id(polygon)] = (span_x, span_y,
                                                  QPainterPath(path), scale,
                                                  polygon)
        if path is None:
            if not shadows:
                return None
            path = QPainterPath()
            path.addEllipse(center, edge, edge)
        elif not shadows:
            return path
        for shadow in shadows:
            points = [self.world_to_mask(px, py, span) for px, py in shadow]
            if len(points) < 3:
                continue
            cut = QPainterPath()
            cut.addPolygon(QPolygonF(points))
            cut.closeSubpath()
            path = path.subtracted(cut)
        return path if not path.isEmpty() else None

    def light_shadow_geometry(self, light, radius: float, occluders) -> tuple:
        """Полигон видимости и тени источника в мировых координатах.

        Считается один раз на свет: пока он стоит на месте и стены не
        правили, результат берётся из кэша. Ключ включает версию геометрии и
        качество теней — после правки стены или смены качества в интерфейсе
        многоугольники пересчитаются сами.
        """
        rays = self.light_rays()
        shadows_on = bool(self.graphics.get("shadows", True))
        # В ключ входит и расстановка объектов: они тоже бросают тень и
        # могут измениться без правки стен (объект подвинули или добавили).
        key = (round(float(light["x"]), 2), round(float(light["y"]), 2),
               round(float(radius), 2), self._geometry_version, rays,
               shadows_on, self._occluders_key or ())
        cached = self._light_polygons.get(key)
        if cached is not None:
            return cached
        polygon = []
        # Только стены рядом со светом: луч в 20 футов до дальнего конца
        # подземелья всё равно не достанет, а пересечения с ним стоят
        # столько же, сколько с ближней стеной.
        segments = self.sight_index().near(light["x"], light["y"], radius)
        if segments:
            polygon = wall_rules.visibility_polygon(
                light["x"], light["y"], radius, segments, rays=rays)
        shadows = []
        if shadows_on:
            shadows = lighting_rules.light_shadows(
                light["x"], light["y"], radius, occluders)
        # Кэш маленький и живёт до правки геометрии; смена камеры его не
        # трогает, а десятки источников с запасом помещаются.
        if len(self._light_polygons) > 512:
            self._light_polygons.clear()
        self._light_polygons[key] = (polygon, shadows)
        return polygon, shadows

    def light_rays(self) -> int:
        """Лучи теней из настроек графики (90, 140 или 220)."""
        return graphics_rules.normalize_rays(
            self.graphics.get("rays", graphics_rules.DEFAULT_RAYS))

    def fog_frame(self, size: QSize) -> QImage:
        """Буфер кадра тумана: пересоздаётся только при смене размера окна."""
        if (self._fog_frame_image is not None
                and self._fog_frame_image.size() == size):
            return self._fog_frame_image
        image = QImage(size, QImage.Format_ARGB32_Premultiplied)
        self._fog_frame_image = image
        return image

    def fog_scene_image(self, size: QSize) -> QImage:
        """Буфер сцены для игрока: пересоздаётся только при смене размера.

        Каждый кадр сцена рисуется в него заново, но новую картинку на 5,5 МБ
        каждый кадр выделять незачем: аллокация и первое касание страниц
        стоят дороже самой заливки.
        """
        if (self._fog_scene_image is not None
                and self._fog_scene_image.size() == size):
            return self._fog_scene_image
        image = QImage(size, QImage.Format_ARGB32_Premultiplied)
        self._fog_scene_image = image
        return image

    def scratch_image(self, slot: str, size: QSize,
                      step: int = 0) -> QImage:
        """Небольшой буфер слоя кадра — живёт между кадрами.

        Такой слой нельзя собирать в новой картинке на каждый кадр: на
        видеокарте (QOpenGLWidget) только что созданная небольшая картинка
        ложится сплошным чёрным прямоугольником по своему размеру. Именно так
        чёрной рамкой пропадала область зрения и чёрным квадратом — пятно
        тёмного зрения, пока слой собирался заново каждый кадр. Буфер,
        который уже лежит в памяти холста, рисуется правильно, поэтому
        содержимое просто перезаписывается по месту.

        ``step`` — округлить размер вверх до шага и уже его держать: рамка
        сектора меняет размер на каждый градус поворота, и без шага буфер
        пересобирался бы снова на каждом кадре. Наружу уходит кусок буфера.
        """
        if step > 0:
            size = QSize(min(self.width(), int(math.ceil(size.width() / step))
                             * step),
                         min(self.height(), int(math.ceil(size.height() / step))
                             * step))
        size = QSize(max(1, size.width()), max(1, size.height()))
        image = self._scratch_images.get(slot)
        if image is not None and image.size() == size:
            return image
        image = QImage(size, QImage.Format_ARGB32_Premultiplied)
        self._scratch_images[slot] = image
        return image

    def night_mask(self, size: QSize) -> QImage:
        """Буфер маски ночи: пересоздаётся только при смене размера окна."""
        if (self._night_mask_image is not None
                and self._night_mask_image.size() == size):
            return self._night_mask_image
        image = QImage(size, QImage.Format_ARGB32_Premultiplied)
        self._night_mask_image = image
        return image

    #: Размер факела метки в пикселях оформления: иконка нарисована в мире.
    LIGHT_ICON_PX = 26.0

    def light_icon_px(self) -> float:
        """Иконка света в экранных пикселях — следует за размером клетки.

        Округление до чётного держит кэш картинок маленьким: зум меняется
        ступенями, и перепекать факел каждый пиксель колеса не нужно.
        """
        return max(6.0, round(self.overlay_px(self.LIGHT_ICON_PX) / 2.0) * 2.0)

    def light_marker_center(self, light) -> QPointF:
        """Центр иконки источника на экране (в координатах виджета)."""
        x, y = self.world_to_screen(light["x"], light["y"])
        return QPointF(x, y)

    def draw_light_markers(self, painter: QPainter):
        """Метки источников света — только мастеру: факел, радиус, замок.

        Игрок не видит ни иконок, ни пунктирных радиусов: это служебная
        геометрия стола. Мастер может спрятать иконку глазком (тогда она
        рисуется лишь у выбранного источника, чтобы её можно было утащить).
        """
        preview = self._light_drop_preview
        if not self.lighting_enabled or not self.is_dm:
            return
        lights = self.lighting_lights()
        if not lights and preview is None:
            return
        painter.save()
        painter.resetTransform()
        painter.setRenderHint(QPainter.Antialiasing, True)
        # Что вообще видно в окне: источник за краем экрана рисовать не надо
        # (а целиком за кадром могут быть все, если карта большая).
        view = QRectF(self.rect())
        size = self.light_icon_px()
        icon_w = (self.TORCH_RIGHT - self.TORCH_LEFT) * size
        icon_h = (self.TORCH_BOTTOM - self.TORCH_TOP) * size
        for light in lights:
            selected = light["id"] == self.selected_light_id
            hidden = bool(light.get("marker_hidden"))
            if hidden and not selected:
                continue
            center = self.light_marker_center(light)
            icon_rect = QRectF(center.x() + self.TORCH_LEFT * size,
                               center.y() + self.TORCH_TOP * size,
                               icon_w, icon_h)
            if not view.intersects(icon_rect):
                continue
            radius_px = self.light_radius_world(light) * self.scale
            ring = QRectF(center.x() - radius_px, center.y() - radius_px,
                          radius_px * 2.0, radius_px * 2.0)
            if radius_px > 1.0 and view.intersects(ring):
                color = QColor(light["color"])
                alpha = 45 if hidden else 110
                pen = QPen(QColor(color.red(), color.green(), color.blue(),
                                  alpha))
                pen.setWidthF(self.overlay_px(1.0))
                pen.setStyle(Qt.DashLine)
                painter.setPen(pen)
                painter.setBrush(Qt.NoBrush)
                painter.drawEllipse(center, radius_px, radius_px)
            self.draw_torch_marker(painter, center, light, selected, hidden)
        if preview is not None:
            self._draw_light_drop_preview(painter, preview)
        painter.restore()

    def _draw_light_drop_preview(self, painter: QPainter, preview: dict):
        """Круг будущего света под курсором при перетаскивании заготовки."""
        center = QPointF(*self.world_to_screen(preview["x"], preview["y"]))
        radius_px = preview["radius"] * self.scale
        color = QColor(preview["color"])
        if radius_px > 1.0:
            fill = QColor(color)
            fill.setAlpha(38)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(fill))
            painter.drawEllipse(center, radius_px, radius_px)
            pen = QPen(QColor(color.red(), color.green(), color.blue(), 190),
                       self.overlay_px(1.4), Qt.DashLine)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(center, radius_px, radius_px)
        # Точка постановки: сам источник встанет именно здесь.
        painter.setPen(QPen(QColor(255, 245, 220, 230), 1.2))
        painter.setBrush(QBrush(QColor(255, 214, 90, 190)))
        dot = self.overlay_px(4.0)
        painter.drawEllipse(center, dot, dot)

    #: Границы рисунка факела в его собственных координатах (низ — точка
    #: источника). Нужны и для картинки в кэше, и для отсечения по экрану.
    TORCH_LEFT = -0.80
    TORCH_TOP = -1.10
    TORCH_RIGHT = 0.80
    TORCH_BOTTOM = 0.60

    def torch_icon(self, color: QColor, burning: bool,
                   device_ratio: float = 1.0) -> QPixmap:
        """Готовая картинка факела: древко, ореол и пламя — один раз на цвет.

        Раньше всё это рисовалось путями и градиентами на каждый источник
        в каждом кадре. На двух десятках светов одна только эта метка
        стоила около 9 мс кадра — больше, чем вся карта. Иконка живёт
        в мире, поэтому её размер входит в ключ кэша: пересборка —
        только при смене зума, а не каждый кадр.
        """
        dpr = max(1.0, float(device_ratio or 1.0))
        size = self.light_icon_px()
        key = (color.rgb(), bool(burning), round(dpr, 2), round(size, 2))
        cached = self._torch_icon_cache.get(key)
        if cached is not None:
            return cached
        left = self.TORCH_LEFT * size
        top = self.TORCH_TOP * size
        width = (self.TORCH_RIGHT - self.TORCH_LEFT) * size
        height = (self.TORCH_BOTTOM - self.TORCH_TOP) * size
        pixmap = QPixmap(max(1, int(round(width * dpr))),
                         max(1, int(round(height * dpr))))
        pixmap.fill(Qt.transparent)
        pixmap.setDevicePixelRatio(dpr)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing, True)
        # Координаты рисунка — как раньше, от точки источника вниз/вверх.
        painter.translate(-left, -top)
        # Древко с обмоткой: низ иконки совпадает с точкой источника.
        painter.setPen(QPen(QColor(28, 20, 12), 1.0))
        painter.setBrush(QBrush(QColor(124, 84, 46)))
        painter.drawRoundedRect(QRectF(-2.0, 0.0, 4.0, size * 0.5), 1.5, 1.5)
        painter.setBrush(QBrush(QColor(72, 48, 28)))
        painter.drawRoundedRect(QRectF(-2.6, size * 0.34, 5.2, size * 0.14),
                                1.5, 1.5)
        # Пламя: ореол, внешний язык и светлая сердцевина.
        flame_h = size * 0.55
        if burning:
            halo = QRadialGradient(QPointF(0, -flame_h * 0.55), size * 0.75)
            halo.setColorAt(0.0, QColor(color.red(), color.green(),
                                        color.blue(), 150))
            halo.setColorAt(1.0, QColor(color.red(), color.green(),
                                        color.blue(), 0))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(halo))
            painter.drawEllipse(QPointF(0, -flame_h * 0.55), size * 0.75,
                                size * 0.75)
        outer = QPainterPath()
        outer.moveTo(0.0, -flame_h)
        outer.cubicTo(size * 0.30, -flame_h * 0.55, size * 0.26, 0.0, 0.0, 0.0)
        outer.cubicTo(-size * 0.26, 0.0, -size * 0.30, -flame_h * 0.55,
                      0.0, -flame_h)
        painter.setPen(QPen(QColor(60, 30, 6, 200), 1.0))
        painter.setBrush(QBrush(QColor(color.red(), color.green(),
                                       color.blue(), 255 if burning else 150)))
        painter.drawPath(outer)
        if burning:
            inner = QPainterPath()
            inner.moveTo(0.0, -flame_h * 0.62)
            inner.cubicTo(size * 0.16, -flame_h * 0.34, size * 0.14, -size * 0.06,
                          0.0, -size * 0.06)
            inner.cubicTo(-size * 0.14, -size * 0.06, -size * 0.16,
                          -flame_h * 0.34, 0.0, -flame_h * 0.62)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(255, 238, 168, 235)))
            painter.drawPath(inner)
        painter.end()
        self._torch_icon_cache[key] = pixmap
        return pixmap

    def draw_torch_marker(self, painter: QPainter, center: QPointF, light,
                          selected: bool, hidden: bool):
        """Иконка факела вместо цветного кружка: горит — пламя, погас — копоть."""
        size = self.light_icon_px()
        painter.save()
        painter.translate(center)
        if hidden:
            painter.setOpacity(0.45)
        if selected:
            ring = QPen(QColor(255, 214, 90, 230))
            ring.setWidthF(self.overlay_px(1.6))
            painter.setPen(ring)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPointF(0, 0), size * 0.62, size * 0.62)
        # «Только ночью» днём показывается погасшим: источник есть, но не горит.
        burning = lighting_rules.burning(light,
                                         self.time_of_day == "night")
        color = QColor(light["color"])
        device = painter.device()
        ratio = 1.0
        if device is not None and hasattr(device, "devicePixelRatioF"):
            ratio = float(device.devicePixelRatioF() or 1.0)
        pixmap = self.torch_icon(color, burning, ratio)
        painter.drawPixmap(QPointF(self.TORCH_LEFT * size,
                                   self.TORCH_TOP * size), pixmap)
        if light.get("locked"):
            self.draw_lock_badge(painter, QPointF(size * 0.42, size * 0.34))
        painter.restore()

    def draw_lock_badge(self, painter: QPainter, at: QPointF):
        """Замок на иконке закреплённого источника."""
        painter.save()
        painter.translate(at)
        painter.setPen(QPen(QColor(20, 20, 24, 230), 1.0))
        painter.setBrush(QBrush(QColor(240, 208, 96, 235)))
        painter.drawRoundedRect(QRectF(-3.6, -1.2, 7.2, 5.6), 1.2, 1.2)
        painter.setBrush(Qt.NoBrush)
        painter.setPen(QPen(QColor(240, 208, 96, 235), 1.4))
        painter.drawArc(QRectF(-2.4, -4.4, 4.8, 4.8), 0, 180 * 16)
        painter.restore()

    def grid_signature(self, span: QRectF) -> tuple:
        """От чего зависит картинка сетки: карта, шаг, зум и кусок мира."""
        m = self.current_map
        if m is None:
            return ()
        xs, ys = m.grid.line_ratios()
        return (m.id, len(xs), len(ys), round(xs[0], 6), round(ys[0], 6),
                round(xs[-1], 6), round(ys[-1], 6),
                round(float(self.scale), 6),
                round(span.x(), 2), round(span.y(), 2),
                round(span.width(), 2), round(span.height(), 2))

    def _paint_grid_mask(self, image: QImage, span: QRectF):
        """Нарисовать сетку в мировой слой (в пикселях маски)."""
        rect = self.map_rect_world()
        m = self.current_map
        image.fill(Qt.transparent)
        if not rect or m is None or not m.grid.valid:
            return
        painter = QPainter(image)
        self._mask_antialias(painter)
        pen = QPen(QColor(255, 255, 255, 110))
        # Сетка — тоже оформление: её толщина в мире, иначе при отдалении
        # она оставалась экранной и спорила с картой.
        pen.setWidthF(self.design(GRID_PEN_WIDTH) * float(self.scale))
        pen.setStyle(Qt.CustomDashLine)
        # Штрихи считаются в единицах толщины пера: (2, 2) при толщине 2 —
        # ровно 2 px штрих и 2 px пробел, как было при прямой отрисовке.
        pen.setDashPattern(list(GRID_DASH))
        painter.setPen(pen)
        xs, ys = m.grid.line_ratios()
        left, top = rect.left(), rect.top()
        width, height = rect.width(), rect.height()
        scale = float(self.scale)
        # Линии живут только внутри карты. Маска нарочно шире видимого
        # куска (MASK_MARGIN), и пока линии шли от края до края маски, сетка
        # рисовалась за картинкой: на 5% зума карта занимала десятки
        # пикселей, а полосы шли через весь экран. Прямая отрисовка до маски
        # всегда шла от rect.top() до rect.bottom() — здесь те же границы в
        # пикселях маски, ещё и обрезанные её размером.
        top_px = max(0.0, (top - span.top()) * scale)
        bottom_px = min(float(image.height()),
                        (rect.bottom() - span.top()) * scale)
        left_px = max(0.0, (left - span.left()) * scale)
        right_px = min(float(image.width()),
                       (rect.right() - span.left()) * scale)
        if bottom_px <= top_px or right_px <= left_px:
            painter.end()
            return
        for ratio in xs:
            x = left + ratio * width
            if not (span.left() <= x <= span.right()):
                continue
            sx = (x - span.x()) * scale
            painter.drawLine(QPointF(sx, top_px), QPointF(sx, bottom_px))
        for ratio in ys:
            y = top + ratio * height
            if not (span.top() <= y <= span.bottom()):
                continue
            sy = (y - span.y()) * scale
            painter.drawLine(QPointF(left_px, sy), QPointF(right_px, sy))
        painter.end()

    def draw_grid(self, painter: QPainter):
        """Сетка как в Dungeondraft: линии от края до края, пунктир 2 px
        оформления (design), то есть в мире — сетка не живёт на камере.

        Линии кладутся на границы клеток: x_i = i * ширина / cols. Первая
        линия лежит на левом краю, последняя — на правом, поэтому крайние
        квадраты вписаны в углы и не обрезаются. Толщина линии — 2 px экрана,
        штрих и пробел — тоже 2 px.

        Сетка рисуется в мировой слой с запасом, а не линиями на каждом
        кадре: у пунктира каждая чёрточка — отдельный штрих пера, и на
        большом столе из двухсот строк это было 11 мс кадра — больше, чем
        свет и маска вместе. Слой живёт до смены зума или шага сетки.
        """
        rect = self.map_rect_world()
        m = self.current_map
        if not rect or m is None or not m.grid.valid:
            return
        span = self.mask_world_rect()
        if span is None:
            return
        signature = self.grid_signature(span)
        image = self._grid_image
        size = self.mask_size(span)
        if image is None or image.size() != size:
            image = QImage(size, QImage.Format_ARGB32_Premultiplied)
            self._grid_image = image
            self._grid_signature = None
        if self._grid_signature != signature:
            self._paint_grid_mask(image, span)
            self._grid_signature = signature
        self.draw_mask_image(painter, span, image)

    def draw_chess_cells(self, painter: QPainter):
        """Подсветить клетки, куда токен может пойти в бою."""
        cells = self.chess_cells()
        m = self.current_map
        if not cells or m is None:
            return
        cell_w, cell_h = m.grid_cell_world
        painter.setBrush(QBrush(QColor(80, 200, 120, 55)))
        pen = QPen(QColor(90, 220, 140, 175))
        pen.setWidthF(self.design(1.2))
        painter.setPen(pen)
        for gx, gy in cells:
            painter.drawRect(QRectF(m.pos_x + gx * cell_w,
                                    m.pos_y + gy * cell_h,
                                    cell_w, cell_h))

    def draw_item_drop_target(self, painter: QPainter):
        """Зелёное кольцо с плюсом вокруг токена под перетаскиваемым предметом.

        Цвет — цвет лечения: в 99% случаев тащат именно зелье. Кольцо
        заметно и на светлой, и на тёмной карте: сначала мягкое свечение,
        потом чёткая линия и бейдж «+» в правом верхнем углу.
        """
        token = self.tokens.get(self.item_drop_target_id)
        if token is None or not token.visible:
            return
        if not self.token_belongs_to_current_map(token):
            return
        rect = self._token_screen_rect_world(token)
        margin = self.design(RING_OFFSET_PX + 2.0)
        ring = rect.adjusted(-margin, -margin, margin, margin)
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        # Широкое полупрозрачное свечение — чтобы кольцо читалось на любой
        # текстуре карты, не превращаясь в толстую рамку.
        glow = QPen(QColor(126, 226, 152, 70))
        glow.setWidthF(self.design(7.0))
        painter.setPen(glow)
        painter.setBrush(Qt.NoBrush)
        painter.drawEllipse(ring)
        pen = QPen(QColor(168, 240, 186))
        pen.setWidthF(self.design(2.2))
        painter.setPen(pen)
        painter.drawEllipse(ring)

        # Бейдж «+» задан в пикселях оформления: он виден тем же размером,
        # что и кольцо, а не подстраивается под камеру.
        radius = ring.width() / 2.0
        badge = min(self.design(9.0), max(self.design(3.0), radius * 0.30))
        center = QPointF(ring.center().x() + radius * 0.72,
                         ring.center().y() - radius * 0.72)
        painter.setPen(QPen(QColor(18, 38, 24, 220), self.design(1.2)))
        painter.setBrush(QBrush(QColor(168, 240, 186, 245)))
        painter.drawEllipse(center, badge, badge)
        arm = badge * 0.52
        plus = QPen(QColor(20, 52, 30), max(self.design(1.2), badge * 0.30))
        plus.setCapStyle(Qt.RoundCap)
        painter.setPen(plus)
        painter.drawLine(QPointF(center.x() - arm, center.y()),
                         QPointF(center.x() + arm, center.y()))
        painter.drawLine(QPointF(center.x(), center.y() - arm),
                         QPointF(center.x(), center.y() + arm))
        painter.restore()

    def draw_token(self, painter: QPainter, token: Token):
        if token.id in self._fog_overlay_ids:
            # Свой токен рисуется отдельно, поверх собранного тумана (см.
            # `_paint_own_tokens_over_fog`). Второй раз в кадр его не кладём.
            return
        size = max(MIN_TOKEN_DRAW_PX, self.grid_cell_world * token.size)
        # Плавное перемещение и боевой выпад/тряска не трогают token.x/y:
        # модель всегда хранит конечную точку, а смещение живёт только на экране.
        draw_x, draw_y = self._token_visual_pos(token)
        fx, fy = self._token_combat_offset(token)
        draw_x += fx
        draw_y += fy
        # Игрок не видит чужих существ за стеной: маска зрения уже посчитана
        # для кадра, и всё, что вне неё, не рисуется вовсе (а не серым).
        # У мастера с туманом войны так же прячутся его актёры.
        if self._visible_path is not None and self.fog_hides_token(token):
            return
        x = draw_x - size / 2
        y = draw_y - size / 2
        rect = QRectF(x, y, size, size)
        # Рамка и её отверстие: портрет обрезается по кругу, поэтому раны,
        # вспышка попадания и кольцо игрока рисуются по кругу портрета,
        # а не поверх оправы.
        frame_key = token_frames.token_frame(token)
        hole = token_frames.hole_ratio(frame_key)
        portrait_circle = token_frames.hole_rect(rect, hole)
        # Отступ колец — в «пикселях оформления», то есть в мире: при любом
        # зуме колею видно ровно так же, как и сам токен.
        margin = self.design(RING_OFFSET_PX)
        drag_margin = self.design(RING_OFFSET_PX + 1.0)

        # Тон смерти и вспышку попадания считаем ДО портрета: в рамке они
        # запекаются в его же слой одним проходом и выводятся одной
        # картинкой. Иначе один и тот же буфер выводился за кадр два-три
        # раза подряд (портрет, заливка, вспышка), а на видеокарте повторный
        # вывод ложится чёрным квадратом во весь токен.
        death = (combat_rules.death_save_state(
            getattr(token, 'death_saves', None))
            if token.hp is not None else None)
        tint = None
        if death is not None and token.hp <= 0:
            tint = (QColor(120, 20, 20, 140) if death['dead']
                    else QColor(215, 45, 45, 85))
        flash, critical_hit = self._token_hit_flash(token.id)
        flash_color = None
        if flash > 0:
            flash_color = (QColor(255, 205, 70) if critical_hit
                           else QColor(235, 70, 60))
            flash_color.setAlpha(int(120 * flash))
        overlays = tuple(c for c in (tint, flash_color) if c is not None)

        # «Невидим» делает полупрозрачным только сам портрет. Кольца,
        # состояния и череп остаются полностью видимыми: мастер должен
        # видеть, что токен здесь и что на нём висит невидимость.
        invisible = any(str(name).strip().casefold() == "невидим"
                        for name in (getattr(token, "conditions", None) or []))
        painter.save()
        if invisible:
            painter.setOpacity(painter.opacity() * 0.5)
        if token.id in self.token_images:
            img = self.token_images[token.id]
            # Токен поворачивается вместе со взглядом, вокруг своего центра.
            # Угол берётся из facing: 90° — «смотрит вниз», то есть обычное
            # положение картинки, поэтому поворот равен facing − 90°. Так
            # картинка не хранит второй угол и не расходится с сектором
            # обзора, серверным запретом скрытности и отменой по Ctrl+Z.
            # Подгонка под рамку (увеличение, сдвиг) живёт на токене, а
            # рисует её та же функция, что и окно подгонки: предпросмотр
            # не может разойтись с картой.
            turn = (vision_rules.normalize_facing(
                getattr(token, "facing", None)) - 90.0) % 360.0
            token_frames.draw_portrait(
                painter, img, rect, frame=frame_key,
                zoom=getattr(token, "portrait_zoom", 1.0) or 1.0,
                dx=getattr(token, "portrait_dx", 0.0) or 0.0,
                dy=getattr(token, "portrait_dy", 0.0) or 0.0,
                turn=turn,
                overlays=overlays if hole > 0.0 else ())
        else:
            # Токен без картинки: вместо портрета — ровная заливка. В рамке
            # она тоже идёт по отверстию, иначе синий круг ложился бы на
            # когти оправы.
            body_color = QColor(100, 150, 200)
            if hole > 0.0:
                token_frames.fill_hole(painter, frame_key, rect, body_color,
                                       overlays=overlays)
            else:
                painter.setBrush(QBrush(body_color))
                painter.setPen(QPen(QColor(255, 255, 255), 2))
                painter.drawEllipse(rect)
            token_frames.draw_frame(painter, frame_key, rect)
        painter.restore()

        # В рамке тон смерти уже лежит в слое портрета (см. вычисление tint
        # выше): второй вывод того же буфера за кадр не нужен. Без рамки
        # заливки идут кругами поверх готового портрета.
        if tint is not None and hole <= 0.0:
            painter.setBrush(QBrush(tint))
            painter.setPen(Qt.NoPen)
            painter.drawEllipse(portrait_circle)

        # Вспышка попадания в рамке тоже собрана в слое портрета; без рамки —
        # круг поверх портрета, чтобы не заслонять сам рисунок краем.
        if flash_color is not None and hole <= 0.0:
            painter.setBrush(QBrush(flash_color))
            painter.setPen(Qt.NoPen)
            painter.drawEllipse(portrait_circle)

        # Подсветка выделения. Без неё выделение рамкой было бы не видно, и
        # выглядело бы так, что рамка «ничего не делает».
        selected = (token.id in self.selected_tokens
                    or token.id == self.selected_token)
        # Взведённая быстрая атака: атакующий обведён пунктирным красным.
        # Без этого режим был виден только по курсору — и его забывали.
        if self.quick_attack_mode and token.id == self.selected_token:
            quick_margin = self.design(RING_OFFSET_PX + TURN_RING_OFFSET_PX)
            pen = QPen(QColor(226, 89, 63))
            pen.setWidthF(self.design(2.0))
            pen.setStyle(Qt.DashLine)
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(rect.adjusted(-quick_margin, -quick_margin,
                                              quick_margin, quick_margin))
        # Янтарное кольцо текущего хода — до кольца выделения, чтобы
        # выделение рисовалось поверх и оставалось различимым.
        if token.id == self.turn_token_id:
            turn_margin = self.design(RING_OFFSET_PX + TURN_RING_OFFSET_PX)
            pen = QPen(QColor(255, 180, 40))
            pen.setWidthF(self.design(TURN_RING_WIDTH))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(rect.adjusted(-turn_margin, -turn_margin,
                                              turn_margin, turn_margin))
        # Постоянная рамка персонажа игрока: синяя, как цвет игрока в
        # Foundry. Без неё токен игрока ничем не отличался от актёра, и
        # единственной цветной обводкой оставалось оранжевое кольцо
        # текущего хода — его и принимали за рамку «это игрок».
        # У токена в декоративной рамке своё кольцо не рисуется: оно легло бы
        # поверх бронзы и спорило с ней (из-за этого внутри рамки висела
        # прежняя синяя обводка).
        if token_kind.is_player(token) and frame_key == token_frames.NO_FRAME:
            inner = self.design(PLAYER_RING_INSET_PX)
            pen = QPen(PLAYER_RING_COLOR)
            pen.setWidthF(self.design(PLAYER_RING_WIDTH))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            # У токена в рамке кольцо идёт по краю портрета: по краю квадрата
            # оно легло бы поверх бронзовой оправы и спорило с ней.
            if hole > 0.0:
                painter.drawEllipse(portrait_circle.adjusted(
                    inner, inner, -inner, -inner))
            else:
                painter.drawEllipse(rect.adjusted(inner, inner, -inner, -inner))
        if selected:
            # Толщина в мире: кольцо рисуется тем же размером, что и токен,
            # поэтому при любом масштабе выделение читается одинаково.
            pen = QPen(QColor(90, 190, 255))
            pen.setWidthF(self.design(SELECTION_RING_WIDTH))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(rect.adjusted(-margin, -margin, margin, margin))
        # Жёлтая рамка — поверх всего: видно, что именно тянем прямо сейчас.
        if token.id == self.dragging_token or token.id in self.dragging_tokens:
            pen = QPen(QColor(255, 200, 0))
            pen.setWidthF(self.design(DRAG_RING_WIDTH))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(rect.adjusted(-drag_margin, -drag_margin,
                                              drag_margin, drag_margin))

        # Спасброски от смерти — ряд кружков в правом верхнем углу.
        # Когда провалены все три, кружки уступают место черепу.
        dead_now = bool(death is not None and death['dead']
                        and token.hp <= 0)
        dying = bool(death is not None and token.hp <= 0)
        if dead_now:
            self._draw_death_cross(painter, x, y, size)
        if dying:
            # Череп появляется уже на нуле хитов, когда только начинаются
            # спасброски. Крест рисуется раньше, поэтому череп остаётся
            # видимым поверх X.
            self._draw_death_status(painter, token, x, y, size)
        # Состояния (Отравлен, Сбит с ног, Опутан…) рисуем поверх токена,
        # иначе мастер не видит статус, не открывая диалог. На нуле хитов
        # они обходят занятый черепом правый верхний угол.
        self._draw_condition_icons(painter, token, x, y, size, dying)

        selected = (token.id in self.selected_tokens
                    or token.id == self.selected_token)
        if self.labels_selected_only and not selected:
            return
        if not self.show_token_names and not self.show_token_hp:
            return
        if token.name or token.hp is not None:
            self._draw_token_label(painter, token, x, y, size)

    def set_token_overlay_options(self, *, names=None, hp=None,
                                  selected_only=None):
        """Настроить подписи и полосу хитов на поле."""
        if names is not None:
            self.show_token_names = bool(names)
        if hp is not None:
            self.show_token_hp = bool(hp)
        if selected_only is not None:
            self.labels_selected_only = bool(selected_only)
        self.update()

    def _condition_icon(self, key: str):
        """Загрузить иконку состояния один раз и запомнить результат.

        Внутри отрисовки картинка не создаётся: на холсте с видеокартой новый
        QPixmap, выведенный в том же кадре, ложится чёрным квадратом. В кадре
        отдаётся None (вызывающий рисует запасной кружок), а загрузка уходит
        в очередь и выполняется сразу после кадра.
        """
        if key in self._condition_icon_cache:
            return self._condition_icon_cache[key]
        if self._painting and self._condition_icons_wait:
            self._queue_condition_icon(key)
            return None
        return self._load_condition_icon(key)

    def _queue_condition_icon(self, key: str):
        """Попросить иконку состояния после кадра (в кадре — только кэш)."""
        if key in self._icon_pending:
            return
        self._icon_pending.add(key)
        QTimer.singleShot(0, lambda name=key: self._finish_condition_icon(name))

    def _finish_condition_icon(self, key: str):
        """Загрузить отложенную иконку вне отрисовки и перерисовать кадр."""
        self._icon_pending.discard(key)
        if key in self._condition_icon_cache:
            return
        self._load_condition_icon(key)
        self.update()

    def _load_condition_icon(self, key: str):
        """Прочитать PNG состояния с диска и запомнить (None — файла нет)."""
        path = os.path.join(CONDITION_ICON_DIR, key + ".png")
        pixmap = QPixmap(path) if os.path.isfile(path) else QPixmap()
        if pixmap.isNull():
            pixmap = None
        self._condition_icon_cache[key] = pixmap
        return pixmap

    @staticmethod
    def condition_icon_names(token: Token) -> list:
        """Состояния токена без повторов, в порядке добавления."""
        names = []
        for name in (getattr(token, "conditions", None) or []):
            text = str(name or "").strip()
            if text and text.casefold() not in {n.casefold() for n in names}:
                names.append(text)
        return names

    def design(self, value: float) -> float:
        """Пиксель оформления (как на клетке DESIGN_CELL_PX) → мировые единицы.

        Единственный правильный способ задать толщину линии, отступ или
        диаметр ручки на холсте: размер привязан к клетке карты. Экранные
        пиксели оставляли оформление на камере — при отдалении кольца
        оставались толстыми и наезжали на портрет, а сетка, стены и линейка
        «тонули» в карте при приближении.
        """
        cell = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        if cell <= 0.0:
            return float(value)
        return float(value) * cell / DESIGN_CELL_PX

    def overlay_px(self, value: float) -> float:
        """Пиксель оформления → экранные пиксели (для слоёв в координатах виджета).

        Нужен там, где рисование идёт в экранных координатах (ручки, рамки
        надписей, метки света): размер всё равно остаётся привязан к карте,
        а не к камере.
        """
        return self.design(value) * max(0.01, float(self.scale))

    def screen_px(self, value: float) -> float:
        """Экранные пиксели → мировые единицы при текущем зуме.

        Единственный способ держать отметку одного размера на экране:
        мировое расстояние, которое на экране занимает ровно `value` px.
        """
        return float(value) / max(0.01, float(self.scale))

    def condition_icon_layout(self, token: Token, x: float, y: float,
                              size: float, dying: bool = False) -> list:
        """Где стоят значки состояний: [(имя, cx, cy, диаметр)] в мире.

        Размеры — доли размера токена, поэтому ряд живёт вместе с портретом:
        на общем виде это крошечные точки в масштабе клетки, на приближении —
        крупные иконки. Экранный размер давал обратное: токен в шесть
        пикселей обрастал значками по тринадцать, и они висели над картой
        гирляндой, не связанной с токеном.

        Ряд идёт по верхнему краю токена. На нуле хитов верхний правый угол
        занимает череп, поэтому ряд переезжает на нижний край: иначе значки
        наезжали бы на череп и на кружки спасбросков.

        Координаты отдаются в мире, потому что та же геометрия нужна маске
        зрения — без неё значки уходили в ч/б, хотя портрет был цветным.
        """
        names = self.condition_icon_names(token)
        if not names:
            return []
        diameter = size * CONDITION_ICON_DIAMETER_RATIO
        step = diameter + size * CONDITION_ICON_GAP_RATIO
        row_y = (y + size - diameter / 2.0 if dying
                 else y + diameter / 2.0)
        start_x = x + size / 2.0 - step * (len(names) - 1) / 2.0
        return [(name, start_x + index * step, row_y, diameter)
                for index, name in enumerate(names)]

    def _draw_condition_icons(self, painter: QPainter, token: Token,
                              x: float, y: float, size: float,
                              dying: bool = False):
        """Значки состояний рядом с токеном — в долях его размера.

        Живой токен несёт ряд по верхнему краю, токен на нуле хитов — по
        нижнему: верхний правый угол занят черепом с кружками спасбросков.
        """
        for name, cx, cy, diameter in self.condition_icon_layout(
                token, x, y, size, dying):
            self._draw_named_condition(painter, name, cx, cy, diameter)

    def _draw_named_condition(self, painter: QPainter, name: str,
                              cx: float, cy: float, diameter: float):
        """Нарисовать иконку состояния; неизвестное состояние — цветной кружок."""
        key = condition_icon_key(name)
        pixmap = self._condition_icon(key) if key else None
        if pixmap is not None:
            self._draw_status_icon(painter, key, cx, cy, diameter)
            return
        radius = diameter / 2.0
        heavy = (name in SEVERE_CONDITIONS
                 or (key in _SEVERE_ICON_KEYS if key else False))
        painter.setBrush(QBrush(QColor(220, 70, 70) if heavy
                                else QColor(230, 190, 80)))
        pen = QPen(QColor(20, 20, 22))
        pen.setWidthF(max(0.4, radius * 0.16))
        painter.setPen(pen)
        painter.drawEllipse(QRectF(cx - radius, cy - radius,
                                   diameter, diameter))

    def _draw_status_icon(self, painter: QPainter, key: str,
                          cx: float, cy: float, diameter: float):
        """Круглая PNG-иконка состояния в мировых координатах."""
        pixmap = self._condition_icon(key)
        if pixmap is None:
            # Файл потерялся — не оставляем пустое место: рисуем тёмный круг.
            painter.setBrush(QBrush(QColor(40, 36, 34, 230)))
            painter.setPen(QPen(QColor(220, 210, 190), max(0.4, diameter * 0.05)))
            painter.drawEllipse(QRectF(cx - diameter / 2.0,
                                       cy - diameter / 2.0,
                                       diameter, diameter))
            return
        target = QRectF(cx - diameter / 2.0, cy - diameter / 2.0,
                        diameter, diameter)
        painter.drawPixmap(target, pixmap,
                           QRectF(0, 0, pixmap.width(), pixmap.height()))

    def _draw_death_cross(self, painter: QPainter, x: float, y: float,
                          size: float):
        """Тёмно-серый X поверх портрета окончательно мёртвого токена.

        Толщина в пикселях оформления: крест едет вместе с портретом и на
        любом зуме остаётся пропорционален ему.
        """
        inset = size * 0.17
        pen = QPen(QColor(52, 50, 54, 235))
        pen.setWidthF(max(self.design(1.6), self.design(DEATH_CROSS_PX)))
        pen.setCapStyle(Qt.RoundCap)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawLine(QPointF(x + inset, y + inset),
                         QPointF(x + size - inset, y + size - inset))
        painter.drawLine(QPointF(x + size - inset, y + inset),
                         QPointF(x + inset, y + size - inset))

    def death_status_layout(self, token: Token, x: float, y: float,
                            size: float):
        """Где стоят череп и кружки спасбросков: ((cx, cy, d), [кружки]).

        Кружок — (cx, cy, радиус, отметка). Всё в мире и в долях размера
        токена: череп и отметки — часть токена, поэтому при отдалении они
        уменьшаются вместе с портретом, а не висят крупными точками над
        крошечным токеном.

        Ряд уплотняется, только если не влезает в ширину токена, но сами
        кружки не уменьшаются: слить три отметки в одну кляксу хуже, чем
        выйти за край маленького токена.
        """
        state = combat_rules.death_save_state(
            getattr(token, 'death_saves', None))
        marks = state['results']
        skull_d = size * DEATH_SKULL_DIAMETER_RATIO
        skull_cx = x + size - skull_d / 2.0
        skull_cy = y + skull_d / 2.0
        radius = size * DEATH_DOT_DIAMETER_RATIO / 2.0
        step = size * DEATH_DOT_STEP_RATIO
        room = max(size - size * DEATH_DOT_INSET_RATIO - radius,
                   radius * 2.0 * len(marks))
        if len(marks) > 1:
            step = min(step, room / (len(marks) - 1))
        last_x = x + size - size * DEATH_DOT_INSET_RATIO - radius
        row_y = skull_cy + skull_d / 2.0 + size * DEATH_DOT_GAP_RATIO + radius
        dots = [(last_x - (len(marks) - 1 - index) * step, row_y, radius, mark)
                for index, mark in enumerate(marks)]
        return (skull_cx, skull_cy, skull_d), dots

    def _draw_death_status(self, painter: QPainter, token: Token,
                           x: float, y: float, size: float):
        """Череп в правом верхнем углу и кружки спасбросков под ним.

        Череп виден уже на нуле хитов — с первого спасброска, а не только
        после третьего провала. Кружки идут под черепом слева направо:
        зелёный — успех, красный — провал, тёмный — ещё не брошен.
        Размеры — долями токена, поэтому отметки масштабируются с портретом.
        """
        skull, dots = self.death_status_layout(token, x, y, size)
        self._draw_status_icon(painter, "dead", skull[0], skull[1], skull[2])
        for cx, cy, radius, mark in dots:
            if mark == combat_rules.DEATH_SUCCESS:
                fill = QColor(70, 190, 95)
                pen_color = QColor(25, 60, 30)
            elif mark == combat_rules.DEATH_FAILURE:
                fill = QColor(215, 60, 55)
                pen_color = QColor(70, 20, 18)
            else:
                fill = QColor(30, 30, 34, 215)
                pen_color = QColor(225, 225, 230)
            painter.setBrush(QBrush(fill))
            pen = QPen(pen_color)
            pen.setWidthF(max(0.4, radius * 0.32))
            painter.setPen(pen)
            painter.drawEllipse(QRectF(cx - radius, cy - radius,
                                       radius * 2, radius * 2))

    def token_label_box(self, token: Token, x: float, y: float, size: float,
                        font=None):
        """Плашка подписи в экранных координатах — одна на рисование и маску.

        Возвращает (прямоугольник, шрифт, высота имени, высота полосы хитов,
        ширина текста, внутренний отступ) или None, если подписи нет. Без
        общей геометрии маска зрения строилась только по телу токена, и
        плашка с именем оставалась ч/б, хотя сам портрет уже цветной.
        """
        if not (self.show_token_names and token.name) and \
                not (self.show_token_hp and token.hp is not None):
            return None
        view_scale = max(self.scale, 0.01)
        sx, sy = self.world_to_screen(x, y)
        token_px = max(1.0, size * view_scale)

        # Шрифт и отступы — экранные пиксели, как у интерфейса: подпись не
        # должна расти вместе с зумом. Крупный токен получает шрифт крупнее,
        # но в пределах LABEL_MIN_FONT_PX…LABEL_MAX_FONT_PX, поэтому при
        # сильном приближении имя не превращается в транспарант, а при
        # отдалении остаётся читаемым.
        pad_px = LABEL_PAD_PX
        gap_px = LABEL_GAP_PX
        font_px = 0.0
        if self.show_token_names and token.name:
            font_px = max(LABEL_MIN_FONT_PX,
                          min(LABEL_MAX_FONT_PX, token_px * LABEL_FONT_RATIO))
        name_px = (font_px + pad_px * 2) if font_px else 0.0
        bar_px = (LABEL_BAR_PX
                  if (self.show_token_hp and token.hp is not None) else 0.0)
        total_px = name_px + bar_px
        if total_px <= 0:
            return None

        label_font = QFont(font if font is not None else self.font())
        label_font.setBold(True)
        label_font.setPixelSize(max(1, int(round(font_px))) if font_px else 1)
        text_w = (QFontMetricsF(label_font).horizontalAdvance(token.name)
                  if font_px else 0.0)

        # Ширина плашки — по тексту, но не уже токена; предел растёт вместе
        # со шрифтом, поэтому длинное имя обрезается многоточием, а короткое
        # не превращается в точку.
        max_w = LABEL_MAX_WIDTH_PX * (font_px / LABEL_MIN_FONT_PX
                                      if font_px else 1.0)
        box_w = max(token_px, min(text_w + pad_px * 2, max_w))
        cx = sx + token_px / 2.0                 # центр токена
        box = QRectF(cx - box_w / 2.0, sy + token_px + gap_px,
                     box_w, total_px)
        text_width = max(0.0, box_w - pad_px * 2)
        return box, label_font, name_px, bar_px, text_width, pad_px

    def label_alpha(self, alpha: int) -> int:
        """Прозрачность плашки: поверх тумана она непрозрачная.

        Сквозь полупрозрачную плашку просвечивает кромка зрения, а она при
        повороте взгляда едет как раз под токеном: подпись начинала мигать.
        """
        return 255 if getattr(self, "_token_overlay_opaque", False) else alpha

    def _draw_token_label(self, painter: QPainter, token: Token,
                          x: float, y: float, size: float):
        """Подпись под токеном — как в Foundry: плашка по тексту, по центру.

        Что было сломано:

        1. Подпись рисовалась ВНУТРИ мирового преобразования, поэтому при
           отдалении сжималась вместе с картой и превращалась в точку.
        2. Ширина плашки равнялась ширине токена на экране. При мелком
           масштабе токен занимает считанные пиксели, и имя обрезалось
           clipRect-ом до нечитаемого огрызка.

        Теперь плашка считается в экранных пикселях по РЕАЛЬНОЙ ширине текста,
        центрируется под токеном и не зависит от зума: при отдалении имя не
        сжимается в точку, а при приближении не растёт транспарантом.
        """
        # x, y — уже верхний левый угол с учётом анимации; берём их, а не
        # token.x/y, иначе подпись оставалась бы на старом месте во время
        # плавного движения и боевого выпада.
        geometry = self.token_label_box(token, x, y, size, painter.font())
        if geometry is None:
            return
        box, font, name_px, bar_px, text_width, pad_px = geometry

        # Дальше — экранные координаты. resetTransform делает систему координат
        # пиксельной, а world_to_screen уже вернул координаты виджета (со
        # смещением внутри), поэтому повторно применять offset НЕ нужно.
        painter.save()
        painter.resetTransform()
        painter.setClipRect(box)

        if name_px:
            name_box = QRectF(box.left(), box.top(), box.width(), name_px)
            painter.setFont(font)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(20, 20, 24, self.label_alpha(200))))
            painter.drawRoundedRect(name_box, 3.0, 3.0)
            painter.setPen(QPen(QColor(255, 255, 255)))
            fitted = QFontMetricsF(font).elidedText(
                token.name, Qt.ElideRight, text_width)
            painter.drawText(QRectF(name_box.left() + pad_px,
                                    name_box.top(), text_width,
                                    name_box.height()),
                             Qt.AlignCenter | Qt.TextSingleLine, fitted)

        if bar_px:
            bar = QRectF(box.left(), box.top() + name_px, box.width(), bar_px)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(18, 24, 20, self.label_alpha(220))))
            painter.drawRoundedRect(bar, bar_px * 0.35, bar_px * 0.35)
            ratio = self._hp_ratio(token)
            if ratio > 0:
                fill = QRectF(bar.left(), bar.top(),
                              bar.width() * ratio, bar.height())
                painter.setBrush(QBrush(QColor(70, 210, 105)))
                painter.drawRoundedRect(fill, bar_px * 0.35, bar_px * 0.35)

        painter.restore()


    def draw_current_drawing(self, painter: QPainter):
        """Превью текущего штриха — тем же кодом, что и в растровый слой.

        Поэтому предпросмотр совпадает с тем, что получится после отпускания
        кнопки: и толщина, и форма, и полупрозрачность.
        """
        pts = list(self.drawing_points)
        if self._preview_points and tool_needs_second_point(self.drawing_mode):
            pts = pts + list(self._preview_points)
        # У фигуры курсор показывает будущее ребро, но вершиной ещё не стал:
        # добавляем его только для рисовки, в drawing_points он не попадает.
        dangling = None
        if (self.drawing_mode == 'polygon' and self._preview_points
                and self.drawing_points):
            dangling = self._preview_points[0]
        if not pts:
            return
        tool = self.drawing_mode or 'brush'
        op = {
            'tool': tool,
            'points': pts,
            'color': self.drawing_color,
            'width': self.brush_size,
            'opacity': self.brush_opacity,
            'filled': tool in ('circle', 'square', 'polygon'),
        }
        # Рисуем во временный слой, чтобы CompositionMode_Clear (ластик)
        # не задел уже нарисованное.
        if self.drawing_mode == 'eraser':
            painter.setPen(QPen(QColor(255, 90, 90, 180),
                                max(1.0, self.brush_size), Qt.DashLine))
            painter.setBrush(Qt.NoBrush)
            pts_world = [QPointF(x, y) for x, y in pts]
            if len(pts_world) == 1:
                painter.drawEllipse(pts_world[0], self.brush_size, self.brush_size)
            else:
                for i in range(len(pts_world) - 1):
                    painter.drawLine(pts_world[i], pts_world[i + 1])
            return
        op['filled'] = self.fill_shapes and tool in ('circle', 'square', 'polygon')
        self._layer_pen(op, painter)
        pts_l = [QPointF(x, y) for x, y in pts]   # в мире совпадает со слоем
        if tool in ('brush', 'line'):
            if len(pts_l) == 1:
                painter.drawPoint(pts_l[0])
            else:
                for i in range(len(pts_l) - 1):
                    painter.drawLine(pts_l[i], pts_l[i + 1])
        elif tool == 'circle' and len(pts_l) >= 2:
            r = math.hypot(pts_l[1].x() - pts_l[0].x(), pts_l[1].y() - pts_l[0].y())
            painter.drawEllipse(pts_l[0], r, r)
        elif tool == 'square' and len(pts_l) >= 2:
            painter.drawRect(QRectF(pts_l[0], pts_l[1]).normalized())
        elif tool == 'polygon':
            # Пока контур не замкнут: линия по поставленным вершинам, ребро до
            # курсора и отметки вершин. Видно, что выйдет при следующем клике.
            if len(pts_l) >= 2:
                painter.drawPolyline(QPolygonF(pts_l))
            if dangling is not None:
                painter.drawLine(pts_l[-1], QPointF(dangling[0], dangling[1]))
            marker = self.overlay_px(3.0)
            for pt in pts_l:
                painter.drawEllipse(pt, marker, marker)
        painter.setCompositionMode(QPainter.CompositionMode_SourceOver)

    def handle_positions(self) -> Dict[str, QPointF]:
        rect = self.map_rect_world()
        if not rect:
            return {}
        corners = {
            'nw': (rect.left(), rect.top()),
            'ne': (rect.right(), rect.top()),
            'sw': (rect.left(), rect.bottom()),
            'se': (rect.right(), rect.bottom()),
        }
        return {k: QPointF(*self.world_to_screen(x, y)) for k, (x, y) in corners.items()}

    def draw_handles(self, painter: QPainter):
        size = self.overlay_px(HANDLE_SIZE)
        painter.setPen(QPen(QColor(255, 255, 255), self.overlay_px(2.0)))
        painter.setBrush(QBrush(QColor(0, 170, 255)))
        half = size / 2.0
        for pos in self.handle_positions().values():
            painter.drawRect(QRectF(pos.x() - half, pos.y() - half,
                                    size, size))

    # ------------------------------------------------------------------
    # Стены, окна и двери
    # ------------------------------------------------------------------
    def map_walls(self) -> list:
        """Стены открытой карты в одном виде (правила — shared/walls.py).

        Нормализация прогоняет все точки и режет мусор — на сотне стен
        это заметные миллисекунды, а функцию ждут и свет, и туман, и
        инструменты по несколько раз за кадр. Поэтому результат кэшируется
        до следующей правки геометрии (`invalidate_walls_cache`).
        """
        if self._walls_cache is None:
            self._walls_cache = wall_rules.map_walls(self.current_map)
        return self._walls_cache

    def openings_signature(self) -> tuple:
        """Живое состояние дверей: открыта, заперта, насколько отведена.

        Читается прямо из модели карты, без нормализации: дверь меняют не
        только действия этого холста (эхо сервера, тест, загрузка мира), а
        кэш нормализованных проёмов об этом иначе не узнал бы.
        """
        raw = getattr(self.current_map, "openings", None) or []
        signature = []
        for item in raw:
            if not isinstance(item, dict):
                continue
            signature.append((str(item.get("id") or ""),
                              bool(item.get("open")),
                              bool(item.get("locked")),
                              round(float(item.get("at") or 0.0), 2)))
        return tuple(signature)

    def map_openings(self, walls=None) -> list:
        """Проёмы открытой карты; проём без стены отбрасывается."""
        if walls is not None and walls is not self._walls_cache:
            return wall_rules.map_openings(self.current_map, walls)
        signature = self.openings_signature()
        if (self._openings_cache is not None
                and self._openings_signature == signature):
            return self._openings_cache
        self._openings_cache = wall_rules.map_openings(
            self.current_map, self.map_walls())
        self._openings_signature = signature
        return self._openings_cache

    def invalidate_walls_cache(self):
        """Сбросить всё, что посчитано по стенам: после правки геометрии.

        Вместе со стенами устаревают куски стен (для света и для хода),
        многоугольники видимости источников и маски ночи и зрения.
        """
        self._walls_cache = None
        self._openings_cache = None
        self._openings_signature = None
        self._spans_cache = {}
        self._spans_signature = {}
        self._light_polygons = {}
        self._light_paths = {}
        # Комнаты тумана тоже зависят от стен: стена убрана или добавлена —
        # «замкнутые области» уже другие.
        self._rooms_cache = None
        self._rooms_key = None
        self._room_path_cache = None
        self._room_path_key = None
        self._geometry_version += 1
        self._vision_cache_key = None
        self._night_mask_signature = None
        self._day_glow_signature = None

    def walls_snapshot(self) -> tuple:
        """Стены и проёмы карты «как есть» — снимок для отмены правки.

        Возвращаются нормализованные копии: правка на месте (перетаскивание
        точки) меняет те же словари, поэтому хранить ссылки на них нельзя.
        """
        map_data = self.current_map
        walls = wall_rules.normalize_walls(getattr(map_data, "walls", None))
        return (walls,
                wall_rules.normalize_openings(
                    getattr(map_data, "openings", None), walls))

    def take_walls_before(self):
        """Снимок стен до последней зафиксированной правки; None — не было.

        Окно забирает его в своём слоте (сигнал синхронный), а холст тут же
        забывает: иначе следующий Ctrl+Z вернул бы чужую правку.
        """
        before = self._walls_before
        self._walls_before = None
        return before

    def _emit_walls_changed(self, before=None):
        """Разослать стены и отдать окну снимок «до» — для истории."""
        self._walls_before = before
        try:
            self.walls_changed.emit(
                [dict(wall) for wall in self.map_walls()],
                [dict(item) for item in self.map_openings()])
        finally:
            self._walls_before = None

    def set_map_walls(self, walls, openings, notify: bool = True):
        """Записать стены и проёмы карты и (по умолчанию) сообщить окну."""
        m = self.current_map
        if m is None or not self.is_dm:
            return
        # Снимок «до» снимаем только для зафиксированных правок: при
        # перетаскивании точки notify=False, и промежуточные положения
        # не должны попадать в историю.
        before = self.walls_snapshot() if notify else None
        m.walls = wall_rules.normalize_walls(walls)
        m.openings = wall_rules.normalize_openings(openings, m.walls)
        known = {wall["id"] for wall in m.walls}
        if self.selected_wall_id not in known:
            self.selected_wall_id = None
        opening_ids = {item["id"] for item in m.openings}
        if self.selected_opening_id not in opening_ids:
            self.selected_opening_id = None
        # Геометрия изменилась: кэш стен, кусков и многоугольников устарел.
        self.invalidate_walls_cache()
        self.update()
        if notify:
            self._emit_walls_changed(before)

    def set_wall_tool(self, tool: Optional[str]):
        """Выбрать инструмент стен: rect, points, edit, window, door, delete.

        Без инструмента и без выделенной стены стены не редактируются и
        не показывают точек: случайный клик по карте их не тронет.
        """
        if tool not in (None, "rect", "points", "edit", "window", "door",
                        "delete") or not self.is_dm:
            tool = None
        if tool != self.wall_tool:
            self._wall_draft = []
            self._wall_rect_start = None
            self._wall_drag_point = None
            self._wall_draft_cursor = None
            self._wall_hover_point = None
            self._wall_hover_opening = None
        self.wall_tool = tool
        if tool:
            self.setCursor(Qt.CrossCursor)
        else:
            self.unsetCursor()
        self.update()

    def wall_width_world(self, feet: float) -> float:
        """Ширина проёма в мировых единицах: футы через шаг сетки."""
        cell = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        if cell <= 0:
            return 0.0
        return float(feet) / vision_rules.FT_PER_CELL * cell

    @property
    def wall_snap(self) -> bool:
        """Магнит стен: включён ли он на открытой карте.

        Настройка живёт в MapData (`wall_snap`), а не в холсте: файл мира
        пишет сервер, и клиентская галочка иначе не пережила бы перезапуск.
        """
        m = self.current_map
        return bool(getattr(m, "wall_snap", False)) if m is not None else False

    @property
    def wall_snap_step(self) -> float:
        """Шаг магнита в долях клетки: 1.0 — клетка, 0.5 — половина."""
        m = self.current_map
        step = getattr(m, "wall_snap_step", None) if m is not None else None
        return wall_rules.normalize_snap_step(step)

    def set_wall_snap(self, enabled: bool, notify: bool = True):
        """Включить/выключить магнит стен по клеткам."""
        m = self.current_map
        if m is None:
            return
        m.wall_snap = bool(enabled)
        self._refresh_wall_preview()
        self.update()
        if notify:
            self.wall_snap_changed.emit(self.wall_snap, self.wall_snap_step)

    def set_wall_snap_step(self, step, notify: bool = True):
        """Шаг магнита: клетка или её половина."""
        m = self.current_map
        if m is None:
            return
        m.wall_snap_step = wall_rules.normalize_snap_step(step)
        self._refresh_wall_preview()
        self.update()
        if notify:
            self.wall_snap_changed.emit(self.wall_snap, self.wall_snap_step)

    def _refresh_wall_preview(self):
        """Пересчитать призрак вершины: шаг магнита мог измениться."""
        if self._wall_draft_cursor is not None:
            # Подсказка сразу переезжает на ближайший узел, а не после
            # следующего движения мыши.
            self._wall_draft_cursor = self.snap_wall_point(
                *self._wall_draft_cursor)

    def map_point_clamped(self, wx: float, wy: float) -> tuple:
        """Зажать точку в прямоугольник карты.

        Стена принадлежит карте: клик по серому полю вокруг неё не должен
        ставить вершину за холстом (из такой точки пунктир предпросмотра
        тянулся к краю экрана и выглядел линией «из ниоткуда»).
        """
        rect = self.map_rect_world()
        if rect is None:
            return float(wx), float(wy)
        x = min(max(float(wx), rect.left()), rect.right())
        y = min(max(float(wy), rect.top()), rect.bottom())
        return float(x), float(y)

    def point_on_map(self, wx: float, wy: float) -> bool:
        """Лежит ли точка на самой карте (а не на сером поле вокруг)."""
        rect = self.map_rect_world()
        if rect is None:
            return False
        return rect.contains(QPointF(float(wx), float(wy)))

    def snap_wall_point(self, wx: float, wy: float) -> tuple:
        """Точка стены: с включённым Snap — ближайшее пересечение сетки.

        Сетка рисуется от левого верхнего угла карты (`map_rect_world`),
        поэтому привязка считается от него же, а не от нуля мира: иначе
        магнит тянул бы вершины мимо видимых линий. Результат всегда лежит
        на карте: стена за краем холста — не стена.
        """
        wx, wy = self.map_point_clamped(wx, wy)
        if not self.wall_snap:
            return wx, wy
        rect = self.map_rect_world()
        m = self.current_map
        if rect is None or m is None or not m.grid.valid:
            return wx, wy
        cols = max(1, int(m.grid.cols))
        rows = max(1, int(m.grid.rows))
        step = self.wall_snap_step
        cell_w = rect.width() / cols * step
        cell_h = rect.height() / rows * step
        if cell_w <= 0 or cell_h <= 0:
            return wx, wy
        x = rect.left() + round((wx - rect.left()) / cell_w) * cell_w
        y = rect.top() + round((wy - rect.top()) / cell_h) * cell_h
        return float(x), float(y)

    def set_wall_opening_ft(self, feet: float):
        """Ширина новых окон и дверей в футах (5–60)."""
        self.wall_opening_ft = max(wall_rules.MIN_OPENING_FT,
                                   min(wall_rules.MAX_OPENING_FT,
                                       float(feet or wall_rules.DEFAULT_DOOR_FT)))

    def wall_hit_test(self, wx: float, wy: float, reach: float = None):
        """Ближайшая стена под точкой: (стена, номер отрезка, расстояние)."""
        if reach is None:
            # Восемь пикселей экрана в мировых единицах: попадание не
            # зависит от зума, как у ручек объектов.
            reach = self.design(8.0)
        best = None
        for wall in self.map_walls():
            for index, segment in enumerate(wall_rules.wall_segments(wall)):
                at, distance = wall_rules.point_on_segment(segment, wx, wy)
                if distance <= reach and (best is None or distance < best[3]):
                    best = (wall, index, at, distance)
        return best

    def wall_point_at(self, wx: float, wy: float, reach: float = None):
        """Точка стены под курсором: (wall_id, индекс точки)."""
        if reach is None:
            reach = self.design(9.0)
        best = None
        for wall in self.map_walls():
            for index, (px, py) in enumerate(wall["points"]):
                distance = math.hypot(px - wx, py - wy)
                if distance <= reach and (best is None or distance < best[2]):
                    best = (wall["id"], index, distance)
        return None if best is None else (best[0], best[1])

    def add_wall(self, points, closed: bool = False, notify: bool = True):
        """Добавить стену по точкам. -> словарь стены или None."""
        if not self.is_dm or self.current_map is None:
            return None
        walls = self.map_walls()
        wall = wall_rules.normalize_wall({"id": generate_id(),
                                          "points": points,
                                          "closed": bool(closed)})
        if wall is None:
            return None
        self.selected_wall_id = wall["id"]
        self.selected_opening_id = None
        self.set_map_walls(walls + [wall], self.map_openings(walls),
                           notify=notify)
        return wall

    def add_wall_rect(self, x1: float, y1: float, x2: float, y2: float,
                      notify: bool = True):
        """Стена рамкой — сразу комната: четыре угла и замкнутый контур."""
        left, right = sorted((float(x1), float(x2)))
        top, bottom = sorted((float(y1), float(y2)))
        if right - left < 2 or bottom - top < 2:
            return None
        return self.add_wall([(left, top), (right, top), (right, bottom),
                              (left, bottom)], closed=True, notify=notify)

    def delete_wall(self, wall_id: str):
        """Удалить стену вместе с её окнами и дверями."""
        walls = [wall for wall in self.map_walls() if wall["id"] != wall_id]
        openings = [item for item in self.map_openings()
                    if item.get("wall_id") != wall_id]
        if self.selected_wall_id == wall_id:
            self.selected_wall_id = None
        if self._wall_hover_point and self._wall_hover_point[0] == wall_id:
            # Подсветка ластика указывала на вершину удалённой стены.
            self._wall_hover_point = None
        gone = {item["id"] for item in self.map_openings()}
        gone -= {item["id"] for item in openings}
        if self._wall_hover_opening in gone:
            self._wall_hover_opening = None
        self.set_map_walls(walls, openings)

    def delete_opening(self, opening_id: str):
        """Убрать дверь или окно из стены; сама стена остаётся целой.

        Именно поэтому стены из .dd2vtt проходят сквозь проём: удаление
        двери убирает только створку, а не вырезает кусок периметра —
        иначе в комнате оставалась бы дыра, через которую видно и ходят.
        """
        if not self.is_dm or self.current_map is None:
            return
        openings = [item for item in self.map_openings()
                    if item.get("id") != opening_id]
        if self.selected_opening_id == opening_id:
            self.selected_opening_id = None
        self._wall_hover_opening = None
        self._door_anims.pop(str(opening_id or ""), None)
        self.set_map_walls(self.map_walls(), openings)

    def move_wall_point(self, wall_id: str, index: int, x: float, y: float,
                        notify: bool = True):
        """Передвинуть точку стены (окна и двери едут вместе с ней)."""
        if not self.is_dm:
            return
        walls = self.map_walls()
        for wall in walls:
            if wall["id"] != wall_id:
                continue
            if 0 <= index < len(wall["points"]):
                wall["points"][index] = [float(x), float(y)]
        self.set_map_walls(walls, self.map_openings(walls), notify=notify)

    def insert_wall_point(self, wall_id: str, seg: int,
                          x: float, y: float):
        """Вставить точку в стену: двойной клик по отрезку в правке точек."""
        walls = self.map_walls()
        for wall in walls:
            if wall["id"] != wall_id:
                continue
            points = wall["points"]
            position = min(len(points), max(1, int(seg) + 1))
            points.insert(position, [float(x), float(y)])
        self.set_map_walls(walls, self.map_openings(walls))

    def delete_wall_point(self, wall_id: str, index: int):
        """Убрать точку: у стены из двух точек удаляется вся стена."""
        walls = self.map_walls()
        for wall in walls:
            if wall["id"] != wall_id:
                continue
            if len(wall["points"]) <= 2:
                self.delete_wall(wall_id)
                return
            if 0 <= index < len(wall["points"]):
                del wall["points"][index]
        self.set_map_walls(walls, self.map_openings(walls))

    def add_opening(self, wall_id: str, seg: int, at: float,
                    kind: str = wall_rules.DOOR, notify: bool = True):
        """Вставить окно или дверь в стену на расстоянии ``at`` от её начала."""
        if not self.is_dm:
            return None
        walls = self.map_walls()
        wall = next((item for item in walls if item["id"] == wall_id), None)
        if wall is None:
            return None
        segments = wall_rules.wall_segments(wall)
        if not segments:
            return None
        seg = max(0, min(len(segments) - 1, int(seg)))
        length = wall_rules.segment_length(segments[seg])
        width = self.wall_width_world(
            self.wall_opening_ft if kind == wall_rules.WINDOW
            else self.wall_opening_ft)
        if width <= 0:
            self.show_hint("Сетка карты не задана: ширина проёма неизвестна")
            return None
        width = min(width, length)
        # Проём целиком внутри стены: половинка ширины от каждого конца.
        at = max(width / 2.0, min(length - width / 2.0, float(at)))
        openings = self.map_openings(walls)
        opening = wall_rules.normalize_opening({
            "id": generate_id(),
            "wall_id": wall_id,
            "seg": seg,
            "at": at,
            "width": width,
            "kind": kind,
            "open": False,
        })
        if opening is None:
            return None
        self.selected_opening_id = opening["id"]
        self.set_map_walls(walls, openings + [opening], notify=notify)
        return opening

    def opening_hit_test(self, wx: float, wy: float, reach: float = None,
                         kind: str = None):
        """Проём под точкой: (стена, проём)."""
        if reach is None:
            reach = self.design(10.0)
        walls = self.map_walls()
        by_id = {wall["id"]: wall for wall in walls}
        for opening in self.map_openings(walls):
            if kind is not None and opening.get("kind") != kind:
                continue
            wall = by_id.get(opening.get("wall_id"))
            segment = wall_rules.opening_segment(wall, opening) if wall else None
            if segment is None:
                continue
            _, distance = wall_rules.point_on_segment(segment, wx, wy)
            if distance <= reach:
                return wall, opening
        return None

    def toggle_door(self, opening_id: str, open_state=None, notify: bool = True):
        """Открыть или закрыть дверь; окно и замок не трогаются."""
        m = self.current_map
        if m is None:
            return None
        target = next((item for item in self.map_openings()
                       if item["id"] == opening_id), None)
        live = next((item for item in
                     (getattr(m, "openings", None) or [])
                     if isinstance(item, dict)
                     and item.get("id") == opening_id), None)
        if (live or target or {}).get("locked"):
            # Запертую дверь не открывает даже токен: сначала «Отпереть».
            self.show_hint("Дверь заперта")
            return None
        opening = wall_rules.toggle_door(m, opening_id, open_state)
        if opening is None:
            return None
        self.selected_opening_id = opening["id"]
        # Открытая дверь перестаёт заслонять свет и взгляд, а `map_openings`
        # отдаёт кэш нормализованных проёмов. Без сброса кэша дверь
        # открывалась только на бумаге: старый словарь с `open: False`
        # оставался в памяти, и ни туман, ни двери, ни меню этого не видели.
        self.invalidate_walls_cache()
        # Створка не перескакивает в новое положение, а идёт к нему.
        self._start_door_swing(opening["id"], bool(opening.get("open")))
        self.update()
        if notify:
            self.door_toggled.emit(opening["id"], bool(opening.get("open")))
        return opening

    def finish_wall_draft(self, closed: bool = False):
        """Завершить ломаную по точкам: клик по первой точке или Enter."""
        points = list(self._wall_draft)
        self._wall_draft = []
        self._wall_draft_cursor = None
        if len(points) < 2:
            self.update()
            return None
        return self.add_wall(points, closed=bool(closed))

    def cancel_wall_draft(self):
        """Esc: бросить недорисованную ломаную."""
        self._wall_draft = []
        self._wall_draft_cursor = None
        self._wall_rect_start = None
        self._wall_drag_point = None
        self.update()

    def undo_wall_point(self) -> bool:
        """Ctrl+Z во время расстановки по точкам: убрать последнюю вершину.

        -> True, если вершина снята. Пока ломаная рисуется, отменять в
        истории нечего: последняя запись там — чужая готовая стена, и
        Ctrl+Z вместо «убрать промахнувшуюся точку» стирал бы её. Когда
        точек не осталось, возвращаем False — и Ctrl+Z снова становится
        общей отменой окна.

        Курсор-подсказка не трогается: превью и дальше тянется от последней
        оставшейся вершины к мыши.
        """
        if not self._wall_draft:
            return False
        self._wall_draft.pop()
        if not self._wall_draft:
            self._wall_draft_cursor = None
        self.update()
        return True

    def handle_wall_press(self, wx: float, wy: float) -> bool:
        """Клик инструментом стен. -> True, если клик занят.

        Инструменты не мешают друг другу: рамка начинает комнату, точки
        собирают ломаную, правка таскает вершины, окно и дверь вставляются
        только в стену (мимо стены — подсказка, а не проём в пустоте).
        """
        tool = self.wall_tool
        if tool == "rect":
            wx, wy = self.snap_wall_point(wx, wy)
            self._wall_rect_start = (wx, wy)
            self._wall_rect_current = (wx, wy)
            self.update()
            return True
        if tool == "points":
            # Замыкание проверяем до привязки: клик по первой точке должен
            # закрывать комнату, а не ставить вершину рядом с ней.
            if self._wall_draft:
                first_x, first_y = self._wall_draft[0]
                reach = self.design(12.0)
                if (len(self._wall_draft) >= 3
                        and math.hypot(wx - first_x, wy - first_y) <= reach):
                    self.finish_wall_draft(closed=True)
                    return True
            wx, wy = self.snap_wall_point(wx, wy)
            # Повтор по тому же узлу сетки ничего не добавляет: иначе при
            # включённом Snap два клика рядом дают нулевой отрезок.
            if (self._wall_draft
                    and math.hypot(wx - self._wall_draft[-1][0],
                                   wy - self._wall_draft[-1][1]) < 1e-6):
                return True
            self._wall_draft.append((wx, wy))
            self._wall_draft_cursor = (wx, wy)
            self.update()
            return True
        if tool == "edit":
            point = self.wall_point_at(wx, wy)
            if point is not None:
                self._wall_drag_point = point
                # Запоминаем геометрию до перетаскивания: за один жест
                # приходит десяток положений, а в историю попадает одно.
                self._wall_drag_before = self.walls_snapshot()
                self.selected_wall_id = point[0]
                self.selected_opening_id = None
                self.update()
                return True
            hit = self.wall_hit_test(wx, wy)
            self.selected_wall_id = hit[0]["id"] if hit else None
            self.selected_opening_id = None
            self.update()
            return True
        if tool == "door":
            # Клик по уже стоящей двери открывает её, а не ставит вторую
            # поверх: иначе мастеру нечем показать «дверь открыта».
            existing = self.opening_hit_test(wx, wy,
                                             kind=wall_rules.DOOR)
            if existing is not None:
                self.toggle_door(existing[1]["id"])
                return True
        if tool in ("window", "door"):
            hit = self.wall_hit_test(wx, wy)
            if hit is None:
                self.show_hint(
                    "Окно и дверь вставляются только в стену")
                return True
            wall, index, at, _distance = hit
            kind = wall_rules.WINDOW if tool == "window" else wall_rules.DOOR
            self.add_opening(wall["id"], index, at, kind)
            return True
        if tool == "delete":
            # Цель корзины — точка, проём и вся стена. Порядок важен: створка
            # лежит на стене, и без отдельной проверки ластик по двери сносил
            # бы всю комнату — а дверь удаляют куда чаще, чем стену.
            # Клик по точке убирает точку, по створке — только её, по полотну
            # — стену вместе с её окнами и дверями.
            point = self.wall_point_at(wx, wy)
            if point is not None:
                # Индекс соседних вершин сдвигается — снимаем подсветку,
                # иначе она висела бы уже на другой точке.
                self._wall_hover_point = None
                self.delete_wall_point(*point)
                return True
            opened = self.opening_hit_test(wx, wy)
            if opened is not None:
                self.delete_opening(opened[1]["id"])
                return True
            hit = self.wall_hit_test(wx, wy)
            if hit is not None:
                self.delete_wall(hit[0]["id"])
                return True
            self.show_hint("Кликните по стене или по её точке, чтобы удалить")
            return True
        return False

    def wall_sight_segments(self) -> list:
        """Куски стен, заслоняющие свет и взгляд (окна и открытые двери — нет)."""
        return self.wall_spans(light=True)

    def wall_spans(self, light: bool = True) -> list:
        """Куски стен для света (`light=True`) или для хода: кэш по геометрии.

        `blocking_spans` пересобирает все проёмы на каждой стене — на сотне
        стен и десятке дверей это дороже, чем сами лучи. Результат зависит
        только от геометрии, поэтому живёт до следующей правки стен.
        """
        if self.current_map is None:
            return []
        signature = self.openings_signature()
        cached = self._spans_cache.get(bool(light))
        if (cached is not None
                and self._spans_signature.get(bool(light)) == signature):
            return cached
        walls = self.map_walls()
        openings = self.map_openings(walls)
        spans = []
        for wall in walls:
            spans.extend(wall_rules.blocking_spans(wall, openings,
                                                   light=bool(light)))
        self._spans_cache[bool(light)] = spans
        self._spans_signature[bool(light)] = signature
        return spans

    def vision_radius_world(self, token) -> float:
        """Дальность зрения токена в мировых единицах."""
        cell = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        if cell <= 0:
            return 0.0
        return (vision_rules.token_range_ft(token)
                / vision_rules.FT_PER_CELL * cell)

    def token_vision_feet_world(self, feet) -> float:
        """Футы в мировые единицы по сетке карты; 0 — сетки нет."""
        cell = float(getattr(self, "grid_cell_world", 0.0) or 0.0)
        try:
            feet = float(feet or 0.0)
        except (TypeError, ValueError):
            return 0.0
        if cell <= 0 or feet <= 0:
            return 0.0
        return feet / vision_rules.FT_PER_CELL * cell

    def token_darkvision_world(self, token) -> float:
        """Тёмное зрение токена в мировых единицах: статблок или лист."""
        lookup = self.sheet_lookup if callable(self.sheet_lookup) else None
        sheet = None
        if lookup is not None:
            try:
                sheet = lookup(token)
            except Exception:
                sheet = None
        return self.token_vision_feet_world(
            lighting_rules.token_darkvision_ft(token, sheet))

    def fog_vision_tokens(self) -> list:
        """Чьими глазами считается туман на этом холсте.

        У игрока — его собственные токены. У мастера с включённым туманом —
        все видимые токены игроков: он видит то, что видит стол, а его
        актёры в неразведанных местах не видны. Без тумана — пусто (мастер
        видит весь стол).
        """
        if self.current_map is None:
            return []
        tokens = self.current_map_tokens().values()
        if self.is_dm:
            if not self.dm_fog_enabled:
                return []
            return [token for token in tokens
                    if token.visible and token_kind.is_player(token)]
        return [token for token in tokens
                if token.visible and token.owner_id == self.player_id]

    def fog_alphas(self) -> tuple:
        """Плотность тумана карты: (мир, комнаты) в процентах."""
        m = self.current_map
        if m is None:
            return (lighting_rules.DEFAULT_FOG_WORLD_ALPHA,
                    lighting_rules.DEFAULT_FOG_ROOM_ALPHA)
        return (lighting_rules.normalize_fog_world_alpha(
                    getattr(m, "fog_world_alpha", None)),
                lighting_rules.normalize_fog_room_alpha(
                    getattr(m, "fog_room_alpha", None)))

    def fog_style(self) -> str:
        """Вид тумана открытой карты: "mono", "sepia", "color" или "custom"."""
        m = self.current_map
        return lighting_rules.normalize_fog_style(
            getattr(m, "fog_style", None) if m is not None else None)

    def fog_custom_color(self) -> str:
        """Свой цвет тумана (используется в виде "custom")."""
        m = self.current_map
        return lighting_rules.normalize_fog_color(
            getattr(m, "fog_color", None) if m is not None else None)

    def fog_tint_color(self) -> QColor:
        """Цвет, которым заливается неразведанное прямо сейчас."""
        m = self.current_map
        if m is None:
            return QColor(lighting_rules.fog_tint(None, None))
        return QColor(lighting_rules.fog_tint(
            getattr(m, "fog_style", None), getattr(m, "fog_color", None)))

    def set_fog_style(self, style: str = None, color: str = None,
                      notify: bool = True):
        """Сменить вид тумана и/или свой цвет — настройка мастера.

        Вид принадлежит карте (`MapData.fog_style`), поэтому едет вместе с
        миром и одинаков у всех: у одного стола туман сепией, у другого
        синим. Свой цвет хранится рядом и работает только в виде "custom".
        """
        m = self.current_map
        if m is None or not self.is_dm:
            return
        m.fog_style = lighting_rules.normalize_fog_style(
            style if style is not None else getattr(m, "fog_style", None))
        m.fog_color = lighting_rules.normalize_fog_color(
            color if color is not None else getattr(m, "fog_color", None))
        self.update()
        if notify:
            self.fog_style_changed.emit(m.fog_style, m.fog_color)

    def set_fog_alpha(self, kind: str, value: int):
        """Плотность тумана одной из двух частей карты — выбор мастера."""
        m = self.current_map
        if m is None or not self.is_dm:
            return
        if kind == "room":
            m.fog_room_alpha = lighting_rules.normalize_fog_room_alpha(value)
        else:
            m.fog_world_alpha = lighting_rules.normalize_fog_world_alpha(
                value)
        self.fog_alpha_changed.emit(kind, int(getattr(
            m, "fog_room_alpha" if kind == "room" else "fog_world_alpha")))
        self.update()

    def room_regions(self) -> list:
        """Замкнутые области карты (комнаты) в мировых координатах.

        Считаются один раз на геометрию: стены поменялись — пересчёт, а
        камера и туман на это не влияют, поэтому панорама ничего не стоит.
        """
        m = self.current_map
        if m is None:
            return []
        key = (m.id, self._geometry_version)
        if self._rooms_cache is not None and self._rooms_key == key:
            return self._rooms_cache
        self._rooms_cache = wall_rules.enclosed_regions(m)
        self._rooms_key = key
        return self._rooms_cache

    def room_polygons(self) -> list:
        """Комнаты полигонами в мире: контур по стенам, а не клетки.

        Считается один раз на геометрию: стены поменялись — пересчёт, а
        камера и туман на это не влияют, поэтому панорама ничего не стоит.
        """
        m = self.current_map
        if m is None:
            return []
        key = (m.id, self._geometry_version)
        if self._room_polys_cache is not None and self._room_polys_key == key:
            return self._room_polys_cache
        self._room_polys_cache = wall_rules.room_polygons(m)
        self._room_polys_key = key
        return self._room_polys_cache

    def room_screen_path(self) -> Optional[QPainterPath]:
        """Комнаты в экранных координатах: что именно красить чёрным.

        Заливка идёт по настоящему контуру комнаты (`wall_rules.room_polygons`),
        поэтому край тумана лежит на линии стены, а не ступеньками грубой
        сетки. Отступ на половину полосы стены (`ROOM_FOG_INSET_PX`) берётся
        только когда стены действительно нарисованы (мастер с инструментом
        стен): иначе туман ложился бы на саму стену. У игрока стен нет, и там
        заливка совпадает с комнатой точно — иначе отступ съедал бы всё
        большую долю комнаты при отдалении.
        """
        polygons = self.room_polygons()
        # Запасной путь: граф стен не замкнулся (очень рваная геометрия) —
        # тогда комнаты считаются старым клеточным способом.
        regions = None if polygons else self.room_regions()
        if not polygons and not regions:
            return None
        scale = float(self.scale or 1.0)
        # Отступ от стены нужен только когда стены нарисованы: у игрока их
        # нет, и фиксированные 4,5 px отступа при отдалении съедали 
        # заметную долю комнаты — туман выглядел меньше помещения.
        inset = bool(polygons) and self.walls_visible()
        key = (self._room_polys_key, self._rooms_key, bool(polygons),
               inset, round(scale, 6), round(float(self.offset_x), 2),
               round(float(self.offset_y), 2))
        if self._room_path_cache is not None and self._room_path_key == key:
            return self._room_path_cache
        path = QPainterPath()
        if polygons:
            for polygon in polygons:
                screen = [QPointF(*self.world_to_screen(x, y))
                          for x, y in polygon]
                part = QPainterPath()
                part.addPolygon(QPolygonF(screen))
                part.closeSubpath()
                path.addPath(part)
        else:
            for x, y, w, h in regions:
                sx, sy = self.world_to_screen(x, y)
                path.addRect(QRectF(sx, sy, w * scale, h * scale))
        if inset:
            path = self._inset_room_path(path)
        self._room_path_cache = path if not path.isEmpty() else None
        self._room_path_key = key
        return self._room_path_cache

    def _inset_room_path(self, path: QPainterPath) -> QPainterPath:
        """Поджать заливку комнаты на половину полосы стены.

        Стена рисуется полосой WALL_STRIP_WIDTH в пикселях оформления, то
        есть по половине этой полосы в каждую сторону от линии. Без отступа
        туман ложился бы на саму стену и у мастера (туман «как у игроков»)
        стена темнела бы наполовину.
        """
        stroker = QPainterPathStroker()
        stroker.setWidth(self.design(WALL_STRIP_WIDTH) * float(self.scale or 1.0))
        outline = stroker.createStroke(path)
        inset = path.subtracted(outline)
        return inset if not inset.isEmpty() else path

    def fog_hides_token(self, token, path=None) -> bool:
        """Скрыт ли этот токен туманом прямо сейчас.

        Один ответ для рисования и для мыши: невидимый токен не рисуется и
        не ловит клики — иначе игрок тянул бы врага, которого не видит.
        Свои токены игрока видны всегда; мастеру виден ещё и тот актёр,
        которого он выделил в списке сцены, — иначе им нельзя управлять.
        """
        if path is None:
            path = self._visible_path
            if path is None:
                path = self.player_vision_path()
        if path is None:
            return False
        if not self.is_dm and getattr(token, "owner_id", None) == self.player_id:
            return False
        if self.is_dm:
            if token.id in self.selected_token_ids():
                return False
            # Туман «как у игроков» — это взгляд глазами стола, а каждый
            # игрок свой токен видит всегда. Без этого у мастера в тумане
            # исчезали сами персонажи игроков: их точка лежит в вершине
            # конуса зрения и в сам конус не попадала.
            if self.dm_fog_enabled and token_kind.is_player(token):
                return False
        sx, sy = self.world_to_screen(token.x, token.y)
        point = QPointF(sx, sy)
        # Объединённый путь для этой проверки не годится: `united` отдаёт
        # контуры с разным направлением обхода, и `contains` в перекрытии
        # двух областей зрения отвечает «нет» — токен пропадал из виду,
        # хотя цветной слой там есть. Поэтому куски проверяются по одному.
        if (path is getattr(self, "_visible_path", None)
                or path is getattr(self, "_vision_cache_path", None)):
            parts = getattr(self, "_vision_cache_parts", ())
            if parts:
                return not any(part.contains(point) for part in parts)
        return not path.contains(point)

    def player_darkvision_state(self):
        """(круги тёмного зрения, ключ кэша, куски для заливки).

        Ночью такой токен видит в чёрно-белом и на дальность тёмного
        зрения: в этих кругах ночной окрас не ложится вовсе. Ключ нужен
        маске ночи — по нему она пересчитывается только при сдвиге токена.

        Смотрим на долю ночи, а не на `time_of_day`: при возврате дня
        темнота уходит за NIGHT_FADE_S, и круги тёмного зрения должны гаснуть
        вместе с ней, а не пропадать в первый же кадр — иначе у такого
        токена зрение внезапно проваливалось бы в темноту.
        """
        if self.current_map is None or self.night_level() <= 0.004:
            self._dark_state_cache = None
            return None, None, ()
        tokens = [token for token in self.fog_vision_tokens() if token.visible]
        # Круги тёмного зрения режутся по сектору СВОЕГО токена. Раньше они
        # объединялись и пересекались с общей маской зрения стола, и кружок
        # одного персонажа открывал глаза соседям: токен без тёмного зрения
        # видел в чужом круге как его владелец.
        vision = self.player_vision_path()
        marks_by_token = (getattr(self, "_vision_token_marks", {})
                          if vision is not None else {})
        segments = self.wall_sight_segments() if vision is not None else ()
        cone = self.player_vision_mode == "cone"
        # Подпись дешевле самих кругов: объединение путей — самая дорогая
        # часть, а меняется оно только вместе с токеном, камерой или
        # дальностью зрения. За кадр это состояние спрашивают несколько
        # раз (отрисовка, маска ночи), и без кэша круги собирались заново.
        # Ключ зрения в подписи обязателен: обрезка по сектору меняется от
        # поворота (R) и от стен, хотя токен и камера остались на месте, —
        # без него тёмное зрение отставало от поворота.
        signature = (
            self.current_map.id, self.is_dm, self.dm_fog_enabled,
            self.player_id, self.player_vision_mode,
            getattr(self, "_vision_world_hash", None),
            round(float(self.scale or 1.0), 6),
            round(float(self.offset_x), 2), round(float(self.offset_y), 2),
            self.width(), self.height(),
            tuple((token.id, round(float(token.x), 2),
                   round(float(token.y), 2),
                   round(self.token_darkvision_world(token), 2))
                  for token in tokens))
        cached = self._dark_state_cache
        if cached is not None and cached[0] == signature:
            return cached[1], cached[2], cached[3]
        path = None
        key = []
        parts = []
        for token in tokens:
            radius = self.token_darkvision_world(token)
            if radius <= 0:
                continue
            sight = self.vision_radius_world(token)
            if sight <= 0:
                # Слепой токен не видит и тёмным зрением: иначе его кусок
                # выходил за собственную область зрения, и ночь вырезалась
                # там, куда он не смотрит вовсе.
                continue
            # Тёмное зрение не выходит за предел зрения токена.
            radius = min(radius, sight)
            sx, sy = self.world_to_screen(token.x, token.y)
            if vision is not None:
                # Своё зрение тем же правилом, что и цветной слой: чужой
                # сектор в тёмное зрение больше не попадает.
                piece = self.token_vision_part(token, radius, segments, cone,
                                               sx, sy)
            else:
                # Туман не ограничен (нет стен и «вокруг токена»): все видят
                # всё, и кружок тёмного зрения работает сам по себе.
                piece = QPainterPath()
                piece.addEllipse(QPointF(sx, sy), radius * self.scale,
                                 radius * self.scale)
            pieces = [] if piece.isEmpty() else [piece]
            marks = marks_by_token.get(token.id)
            if marks is not None and not marks.isEmpty():
                pieces.append(marks)
            for piece in pieces:
                piece = QPainterPath(piece)
                piece.setFillRule(Qt.WindingFill)
                parts.append(piece)
                path = piece if path is None else path.united(piece)
            # Ключ — мировой, а не экранный: и ночь, и свет живут в мировых
            # координатах, и при сдвиге камеры ту же маску можно не
            # пересобирать. Экранное положение добавляет `dark_mask_key`.
            key.append((token.id, round(float(token.x), 2),
                        round(float(token.y), 2), round(float(radius), 2)))
        if path is None:
            self._dark_state_cache = (signature, None, None, ())
            return None, None, ()
        # Круги объединены — пересечения не должны вычитаться: иначе у
        # соседних токенов в общей части тёмного зрения появлялись дыры.
        path.setFillRule(Qt.WindingFill)
        # Обрезки тоже заливаются по одному: их объединение давало те же
        # серпы в местах перекрытия, только в ч/б слое тёмного зрения.
        self._dark_state_cache = (signature, path, tuple(key), tuple(parts))
        return path, self._dark_state_cache[2], self._dark_state_cache[3]

    def player_darkvision_path(self):
        """Только круги тёмного зрения игрока (без ключа кэша)."""
        return self.player_darkvision_state()[0]

    def darkvision_signature(self) -> tuple:
        """Подпись тёмного зрения стола: чьи токены и на сколько футов.

        Дешёвая альтернатива самим кругам: по ней видно, поменялось ли
        тёмное зрение вообще (открыли лист, пришёл ответ сервера).
        """
        if self.current_map is None:
            return ()
        return tuple((token.id, round(self.token_darkvision_world(token), 2))
                     for token in self.fog_vision_tokens() if token.visible)

    def refresh_darkvision(self):
        """Лист или статблок могли поменяться: пересчитать тёмное зрение.

        Дальность тёмного зрения лежит в листе персонажа, а лист приезжает с
        сервера или его правят на странице. Пересчёт идёт только когда
        дальность действительно изменилась: лист переписывают и на каждый
        удар, а пересборка кадра с туманом стоит миллисекунды.
        """
        signature = self.darkvision_signature()
        if signature == self._darkvision_signature:
            return
        self._darkvision_signature = signature
        self._dark_state_cache = None
        self._sight_poly_cache.clear()
        self._night_mask_signature = None
        self._soft_mask_cache.clear()
        self.update()

    def token_overlay_circles(self, token: Token, size: float) -> list:
        """Значки состояний и череп в ЭКРАННЫХ кругах: [(cx, cy, радиус)].

        Иконки рисуются поверх тела, но маска зрения строилась только по
        телу и плашке имени — поэтому значки оставались ч/б, хотя портрет
        уже был цветным. Геометрия берётся из тех же функций, что и
        рисование, так что маска не расходится с картинкой.
        """
        if not self.condition_icon_names(token) and token.hp is None:
            return []
        x = token.x - size / 2.0
        y = token.y - size / 2.0
        death = (combat_rules.death_save_state(
            getattr(token, 'death_saves', None))
            if token.hp is not None else None)
        dying = bool(death is not None and token.hp <= 0)
        circles = []
        if dying:
            skull, dots = self.death_status_layout(token, x, y, size)
            circles.append((skull[0], skull[1], skull[2] / 2.0))
            circles.extend((cx, cy, radius) for cx, cy, radius, _mark
                           in dots)
        circles.extend((cx, cy, diameter / 2.0)
                       for _name, cx, cy, diameter
                       in self.condition_icon_layout(token, x, y, size, dying))
        result = []
        for cx, cy, radius in circles:
            sx, sy = self.world_to_screen(cx, cy)
            result.append((sx, sy, max(0.0, radius * self.scale) + 1.0))
        return result

    def _drop_vision_cache(self):
        """Зрение кончилось: кэш формы больше не описывает кадр.

        Ранние выходы `player_vision_path` обязаны сбрасывать и ключ, и
        мировую подпись: иначе ночь и тёмное зрение считали бы форму зрения
        прежней карты действующей.
        """
        self._vision_world_key = None
        self._vision_world_hash = None
        self._vision_token_marks = {}
        self._vision_cache_key = None
        self._vision_cache_path = None
        self._vision_cache_parts = ()
        return None

    def player_vision_path(self):
        """Маска зрения игрока в экранных координатах; None — тумана нет.

        Мастер видит весь стол, а игрок — только то, куда смотрят его токены:
        стены режут обзор, поэтому в соседнюю комнату не заглянуть. Пока в
        комнате никого из своих, она остаётся серой.

        Настройка мастера «Зрение игроков» сужает цветную область до сектора
        обзора (``"cone"``): токен видит цветным только перед собой, а всё,
        что за спиной, остаётся ч/б. Режим ``"around"`` — как раньше: круг
        вокруг токена до дальности зрения.
        """
        if self.current_map is None:
            return self._drop_vision_cache()
        cone = self.player_vision_mode == "cone"
        segments = self.wall_sight_segments()
        if not segments and not cone:
            return self._drop_vision_cache()
        # У мастера туман включается галочкой и считается сразу по всем
        # токенам игроков (см. fog_vision_tokens).
        tokens = self.fog_vision_tokens()
        if not tokens:
            return self._drop_vision_cache()
        openings = self.map_openings()
        world = (self.current_map.id, self.player_vision_mode, self.is_dm,
                 bool(self.show_token_names), bool(self.show_token_hp),
                 tuple((token.id, round(float(token.x), 1),
                        round(float(token.y), 1),
                        round(self.vision_radius_world(token), 1),
                        round(vision_rules.token_facing(token), 1),
                        round(vision_rules.token_angle(token), 1),
                        round(float(getattr(token, "size", 1.0) or 1.0), 2),
                        len(token.name or ""), token.hp is not None,
                        tuple(str(name) for name in
                              (getattr(token, "conditions", None) or [])),
                        tuple(combat_rules.death_save_state(
                            getattr(token, "death_saves", None))["results"]
                            if token.hp is not None else ()))
                       for token in tokens),
                 tuple((wall["id"],
                        tuple(tuple(point) for point in wall["points"]),
                        bool(wall.get("closed"))) for wall in self.map_walls()),
                 tuple((item["id"], bool(item.get("open")))
                       for item in openings))
        # Часть ключа без камеры — форма зрения на карте. По ней слой ночи
        # понимает, что сектор повернулся, и пересобирает свого маску,
        # хотя сама маска от сдвига вида не зависит.
        self._vision_world_key = world
        # Хэш считается здесь и один раз: по нему подпись тёмного зрения
        # понимает, что сектор повернулся, и не хэширует все стены за кадр.
        self._vision_world_hash = hash(world)
        key = world + (round(float(self.scale), 4),
                       round(float(self.offset_x), 2),
                       round(float(self.offset_y), 2),
                       self.width(), self.height())
        if key == getattr(self, "_vision_cache_key", None):
            return self._vision_cache_path
        path = QPainterPath()
        path.setFillRule(Qt.WindingFill)
        # Куски области зрения по токенам: по ним маска заливается без
        # вычитания перекрытий (см. `soft_vision_mask`). Объединённый путь
        # остаётся для `contains` и рамки кадра.
        parts = []
        # Плашка, тело и значки каждого токена отдельно: они входят в его
        # кусок тёмного зрения (`player_darkvision_state`), иначе собственная
        # фишка стояла бы в темноте.
        token_marks = {}
        # Круга тела и плашки в маске зрения больше нет: это была дырка в
        # тумане — под фишкой и под именем появлялось светлое пятно, а если
        # в него попадала чужая фишка за стеной, игрок её видел. Свой токен
        # теперь рисуется поверх тумана (`_paint_own_tokens_over_fog`), и в
        # маске остаются только куски настоящего зрения.
        for token in tokens:
            radius = self.vision_radius_world(token)
            if radius <= 0:
                continue
            sx, sy = self.world_to_screen(token.x, token.y)
            size = max(MIN_TOKEN_DRAW_PX, self.grid_cell_world * token.size)
            body = (size * float(self.scale) / 2.0
                    + self.overlay_px(RING_OFFSET_PX + 3.0))
            # Плашка с именем — тем же прямоугольником, что и при рисовании:
            # иначе имя оставалось ч/б, а тело было цветным.
            marks = QPainterPath()
            marks.setFillRule(Qt.WindingFill)
            marks.addEllipse(QPointF(sx, sy), body, body)
            label = self.token_label_box(token, token.x - size / 2.0,
                                         token.y - size / 2.0, size)
            if label is not None:
                box = label[0].adjusted(-1.0, -1.0, 1.0, 1.0)
                marks.addRoundedRect(box, 4.0, 4.0)
            # Значки состояний и череп со спасбросками: у них своя геометрия
            # вокруг токена, и без этого они уходили в ч/б.
            for icx, icy, reach_px in self.token_overlay_circles(token, size):
                marks.addEllipse(QPointF(icx, icy), reach_px, reach_px)
            part = self.token_vision_part(token, radius, segments, cone,
                                          sx, sy)
            if not marks.isEmpty():
                token_marks[token.id] = marks
            if part.isEmpty():
                continue
            parts.append(part)
            path = part if path.isEmpty() else path.united(part)
        path.setFillRule(Qt.WindingFill)
        self._vision_token_marks = token_marks
        self._vision_cache_key = key
        self._vision_cache_path = None if path.isEmpty() else path
        self._vision_cache_parts = tuple(parts)
        return self._vision_cache_path

    def token_sight_polygon(self, token, radius_world: float, segments) -> list:
        """Полигон видимости токена с кэшем: позиция, дальность, геометрия.

        `visibility_polygon` — самая дорогая часть кадра, а спрашивают её
        дважды за токен: для цветной области зрения и для тёмного зрения.
        Когда тёмное зрение упирается в дальность зрения (частый случай),
        дальности совпадают, и второй расчёт — это тот же полигон.
        """
        key = (round(float(token.x), 3), round(float(token.y), 3),
               round(float(radius_world), 4), self._geometry_version,
               self._spans_signature.get(True))
        cached = self._sight_poly_cache.get(key)
        if cached is not None:
            return cached
        polygon = list(wall_rules.visibility_polygon(
            token.x, token.y, radius_world, segments) or ())
        if len(self._sight_poly_cache) >= 48:
            self._sight_poly_cache.clear()
        self._sight_poly_cache[key] = polygon
        return polygon

    def token_vision_part(self, token, radius_world: float, segments,
                          cone: bool, sx: float = None,
                          sy: float = None) -> QPainterPath:
        """Кусок зрения одного токена на экране: стены × сектор обзора.

        Одно правило и для цветной области зрения, и для тёмного зрения —
        только с другой дальностью. Так кусок тёмного зрения гарантированно
        лежит внутри своего сектора и не достаётся соседям.

        Пересекать готовый кусок зрения с кругом тёмного зрения нельзя: у них
        общая дуга (обе окружности радиуса зрения), и `intersected` на
        совпадающих кривых возвращает огрызок в стороне от центра.
        """
        part = QPainterPath()
        if radius_world <= 0:
            return part
        if sx is None or sy is None:
            sx, sy = self.world_to_screen(token.x, token.y)
        if segments:
            polygon = self.token_sight_polygon(token, radius_world, segments)
            if len(polygon) >= 3:
                screen = [QPointF(*self.world_to_screen(px, py))
                          for px, py in polygon]
                part.addPolygon(QPolygonF(screen))
                part.closeSubpath()
            else:
                # Стены дали вырожденный полигон (токен встал на линию
                # стены). Раньше такой токен выкидывался из маски совсем,
                # и игрок оставался без цветной области вообще. Лучше
                # показать сектор по дальности: туман гасится по видимому,
                # а не по сломанной геометрии.
                reach = radius_world * self.scale
                part.addEllipse(QPointF(sx, sy), reach, reach)
        else:
            # Без стен сектор обзора — единственное ограничение, и
            # маску приходится строить кружком.
            reach = radius_world * self.scale
            part.addEllipse(QPointF(sx, sy), reach, reach)
        if cone:
            part = part.intersected(self.vision_cone_path(
                sx, sy, radius_world * self.scale,
                vision_rules.token_facing(token),
                vision_rules.token_angle(token)))
        return part

    def player_vision_parts(self) -> tuple:
        """Куски области зрения (по токену) для заливки маски.

        Маска собирается из них по отдельности: объединение путей даёт
        перекрытия с обратным обходом, и цветной слой резался тёмными
        серпами тем сильнее, чем ближе зум.
        """
        self.player_vision_path()
        return getattr(self, "_vision_cache_parts", ())

    @staticmethod
    def vision_cone_path(cx: float, cy: float, radius: float, facing,
                         angle) -> QPainterPath:
        """Сектор обзора в экранных координатах: общий для подсветки и маски."""
        path = QPainterPath()
        if radius <= 0:
            return path
        width = vision_rules.normalize_angle(angle)
        look = vision_rules.normalize_facing(facing)
        if width >= 360.0:
            path.addEllipse(QPointF(cx, cy), radius, radius)
            return path
        half = width / 2.0
        rect = QRectF(cx - radius, cy - radius, radius * 2.0, radius * 2.0)
        path.moveTo(cx, cy)
        # Qt отсчитывает углы против часовой стрелки от 3 часов, а facing —
        # по часовой (atan2 при y вниз): знак меняется.
        path.arcTo(rect, -(look + half), width)
        path.closeSubpath()
        return path

    def draw_walls(self, painter: QPainter):
        """Стены на столе: полупрозрачная чёрная линия с проёмами.

        Рисуются в мировых координатах, толщина — в пикселях оформления:
        полоса стены едет вместе с картой и не зависит от камеры. Стена — тёмная
        полупрозрачная полоса: карта под ней видна, но препятствие читается
        сразу и не спорит с рисунком пола. Проёмы — дырки в линии: окно
        перекрыто голубой полоской, дверь — коричневой, а открытая дверь
        откинута в сторону. Выделенная стена светится синим.
        """
        walls = self.map_walls()
        if not walls:
            return
        openings = self.map_openings(walls)
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        by_id = {wall["id"]: wall for wall in walls}
        # Стены — разметка мастера, а не часть карты: без инструмента и без
        # выделенной стены они не рисуются вовсе. Иначе чёрные полосы
        # спорят с рисунком пола и заслоняют то, что видит игрок. Двери
        # остаются всегда: это предмет стола, а не линия геометрии.
        walls_visible = self.walls_visible()
        for wall in (walls if walls_visible else ()):
            selected = wall["id"] == self.selected_wall_id
            spans = wall_rules.blocking_spans(wall, openings, light=True)
            if selected:
                # Подсветка — ореол под стеной, а не цвет самой стены:
                # толщина и форма остаются те же, меняется только вид.
                glow = QPen(QColor(110, 185, 255, 120))
                glow.setWidthF(self.design(15.0))
                glow.setCapStyle(Qt.RoundCap)
                painter.setPen(glow)
                for start, end in spans:
                    painter.drawLine(QPointF(*start), QPointF(*end))
            body = QPen(QColor(8, 8, 10, 150))
            body.setWidthF(self.design(WALL_STRIP_WIDTH))
            body.setCapStyle(Qt.RoundCap)
            painter.setPen(body)
            for start, end in spans:
                painter.drawLine(QPointF(*start), QPointF(*end))
            # Тонкая жила внутри: без неё полупрозрачная полоса на светлом
            # полу расплывается и стена не отличима от тени.
            core = QPen(QColor(0, 0, 0, 200))
            core.setWidthF(self.design(3.0))
            core.setCapStyle(Qt.RoundCap)
            painter.setPen(core)
            for start, end in spans:
                painter.drawLine(QPointF(*start), QPointF(*end))
        for opening in openings:
            wall = by_id.get(opening.get("wall_id"))
            segment = wall_rules.opening_segment(wall, opening) if wall else None
            if segment is None:
                continue
            if (opening.get("kind") == wall_rules.WINDOW
                    and not walls_visible):
                # Окно — дырка в стене: без самой стены это просто щель.
                continue
            self._draw_wall_opening(
                painter, opening, segment, walls_visible,
                highlighted=opening.get("id") == self._wall_hover_opening)
        painter.restore()

    def walls_visible(self) -> bool:
        """Видны ли стены сейчас.

        Стена — разметка мастера, а не предмет карты: пока не выбран
        инструмент стен и ничего не выделено, линий на холсте нет. Двери и
        окна живут отдельно от этой разметки (двери видны всегда).
        """
        if not self.is_dm or self.hide_dm_walls:
            # Мастер спрятал у себя стены для игры на телевизоре — инструмент
            # стен и выделение тут уже не должны показывать линии.
            return False
        return bool(self.wall_tool or self.selected_wall_id)

    def door_angle(self, opening, now: Optional[float] = None) -> float:
        """Угол створки двери: 0 — лежит в стене, 90 — распахнута.

        Модель хранит только «открыта/закрыта», а плавность — здесь:
        изменение состояния запускает ход на DOOR_SWING_S, и каждый кадр
        угол пересчитывается. Отдельного таймера у двери нет — ход
        замечается при отрисовке, поэтому один и тот же путь работает и
        для своей двери, и для эха сервера, и для загруженного мира.
        """
        now = time.monotonic() if now is None else now
        key = str(opening.get("id") or "")
        target = DOOR_OPEN_ANGLE if opening.get("open") else 0.0
        tween = self._door_anims.get(key)
        if tween is None:
            # Дверь ещё ни разу не рисовалась: сразу в своём состоянии.
            tween = {"from": target, "to": target, "start": now}
            self._door_anims[key] = tween
        elif tween["to"] != target:
            tween = {"from": self._door_angle_at(tween, now), "to": target,
                     "start": now}
            self._door_anims[key] = tween
            # Перерисовка идёт таймером анимаций: кадр уже рисуется, но
            # следующий сам себя не закажет.
            self._ensure_anim_timer()
        return self._door_angle_at(tween, now)

    @staticmethod
    def _door_angle_at(tween: dict, now: float) -> float:
        """Угол створки в момент ``now``: разгон в начале, мягкий финиш."""
        span = tween["to"] - tween["from"]
        if abs(span) < 1e-6:
            return float(tween["to"])
        progress = (now - tween["start"]) / DOOR_SWING_S
        progress = max(0.0, min(1.0, progress))
        # Открывается с разгоном (створка тяжёлая), закрывается с торможением
        # у косяка — так стук слышен в конце, а не в начале.
        if span > 0:
            eased = 1.0 - (1.0 - progress) ** 3
        else:
            eased = progress * progress
        return float(tween["from"]) + span * eased

    def animate_door(self, opening_id: str, open_state):
        """Запустить ход створки (эхо сервера, замок, чужой клиент)."""
        self._start_door_swing(opening_id, bool(open_state))
        self.update()

    def _start_door_swing(self, opening_id, open_state, now=None):
        """Поставить створку в движение к новому состоянию.

        Угол «откуда» берётся из текущего хода (или с противоположной
        стороны, если дверь рисуется впервые): без этого только что
        открытая дверь сразу считалась бы распахнутой, и токен прошёл бы
        сквозь ещё не двинувшуюся створку.
        """
        key = str(opening_id or "")
        if not key:
            return
        target = DOOR_OPEN_ANGLE if open_state else 0.0
        now = time.monotonic() if now is None else now
        tween = self._door_anims.get(key)
        if tween is not None and tween["to"] == target:
            # Створка уже идёт туда (своя дверь + эхо сервера): второй раз
            # не начинаем, иначе ход растягивался бы на два срока.
            return
        if tween is None:
            from_angle = 0.0 if target > 0 else DOOR_OPEN_ANGLE
        else:
            from_angle = self._door_angle_at(tween, now)
        self._door_anims[key] = {"from": from_angle, "to": target,
                                 "start": now}
        self._ensure_anim_timer()
        # Скрип в момент, когда створка тронулась: по эху сервера звук
        # приходил с сетевым запозданием и не совпадал с движением.
        self.door_swing_started.emit(key, bool(open_state))

    def _doors_animating(self) -> bool:
        """Есть ли створка в движении (для таймера перерисовки)."""
        now = time.monotonic()
        for tween in self._door_anims.values():
            if abs(self._door_angle_at(tween, now) - tween["to"]) > 0.5:
                return True
        return False

    def _draw_wall_opening(self, painter: QPainter, opening, segment,
                           wall_visible: bool = True,
                           highlighted: bool = False):
        """Окно или дверь в проёме.

        Окно — полоска в стене. Дверь — створка на петле: закрытая лежит в
        стене, открытая стоит поперёк, в пути — где-то между. Раньше
        открытая дверь рисовалась ВТОРОЙ линией поверх закрытой, и на
        холсте оставались две створки; теперь створка одна и поворачивается.
        """
        (x1, y1), (x2, y2) = segment
        chosen = opening.get("kind") == wall_rules.WINDOW
        if highlighted:
            # Ластик навёлся на створку: клик уберёт её, а не всю стену.
            color = QColor(236, 70, 70)
        elif chosen:
            color = QColor(150, 205, 245)
        elif opening.get("locked"):
            # Замок видно сразу: иначе мастер полчаса вспоминает, почему
            # никто не может открыть дверь.
            color = QColor(226, 190, 92)
        else:
            color = QColor(196, 140, 84)
        length = math.hypot(x2 - x1, y2 - y1)
        if length <= 0:
            return
        dx, dy = (x2 - x1) / length, (y2 - y1) / length
        # Правая нормаль к стене: в эту сторону створка и отходит.
        nx, ny = -dy, dx
        if highlighted:
            glow = QPen(QColor(255, 80, 80, 90))
            glow.setWidthF(self.design(11.0))
            glow.setCapStyle(Qt.RoundCap)
            painter.setPen(glow)
            painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))
        if chosen:
            pen = QPen(color)
            pen.setWidthF(self.design(5.0))
            painter.setPen(pen)
            painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))
            return
        angle = self.door_angle(opening)
        # Косяк — только когда стены видны: иначе это лишняя чёрточка в
        # пустом месте, а дверь и без него читается по створке.
        if wall_visible:
            threshold = QPen(QColor(150, 120, 90, 110))
            threshold.setWidthF(self.design(2.0))
            threshold.setStyle(Qt.DashLine)
            painter.setPen(threshold)
            painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))
        radians = math.radians(angle)
        cos_a, sin_a = math.cos(radians), math.sin(radians)
        # Петля — в начале проёма; створка поворачивается от стены к
        # нормали, то есть открывается в ту же сторону, что и раньше.
        tip_x = x1 + (dx * cos_a + nx * sin_a) * length
        tip_y = y1 + (dy * cos_a + ny * sin_a) * length
        pen = QPen(color)
        pen.setWidthF(self.design(6.0))
        pen.setCapStyle(Qt.RoundCap)
        painter.setPen(pen)
        painter.drawLine(QPointF(x1, y1), QPointF(tip_x, tip_y))
        # Ручка на конце створки: без неё открытая дверь — просто палочка.
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(70, 48, 26)))
        knob = self.design(2.6)
        painter.drawEllipse(QPointF(tip_x, tip_y), knob, knob)
        painter.setBrush(Qt.NoBrush)
        if opening.get("locked"):
            self._draw_door_lock(painter, (x1 + tip_x) / 2.0,
                                 (y1 + tip_y) / 2.0)

    def _draw_door_lock(self, painter: QPainter, x: float, y: float):
        """Замок на двери: дужка и тело в пикселях оформления.

        Координаты мировые, поэтому и размер мировый: при отдалении замок
        уменьшается вместе с дверью, а не висит на ней крупной иконкой.
        """
        unit = self.design(1.0)
        size = self.design(6.0)
        body = QRectF(x - size * 0.8, y - size * 0.2, size * 1.6, size * 1.5)
        shackle = QRectF(x - size * 0.5, y - size * 1.05, size, size * 1.1)
        painter.save()
        painter.setBrush(Qt.NoBrush)
        painter.setPen(QPen(QColor(20, 16, 8, 220), 1.8 * unit))
        painter.drawRect(body)
        painter.drawArc(shackle, 0, 180 * 16)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(240, 205, 110)))
        painter.drawRect(body)
        painter.setBrush(QBrush(QColor(60, 44, 16)))
        painter.drawEllipse(QPointF(x, y + size * 0.35), size * 0.28, size * 0.28)
        painter.restore()

    def draw_wall_ui(self, painter: QPainter):
        """Точки правки и подсказки стен — только мастеру и только в правке.

        Без инструмента и без выделенной стены точек не видно: они не
        мешают смотреть стол, но стены при этом работают.
        """
        if not self.is_dm or self.current_map is None or self.hide_dm_walls:
            # Режим «скрыть у меня стены»: ни линий, ни точек правки.
            return
        editing = self.wall_tool is not None or self.selected_wall_id is not None
        if not editing and not self._wall_draft:
            return
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        walls = self.map_walls()
        show_all = self.wall_tool in ("edit", "points", "rect")
        for wall in walls:
            if not show_all and wall["id"] != self.selected_wall_id:
                continue
            selected = wall["id"] == self.selected_wall_id
            for px, py in wall["points"]:
                centre = QPointF(*self.world_to_screen(px, py))
                # Круглые маркеры: квадраты читались как уголки сетки, а не
                # как узлы стены.
                knob = self.overlay_px(WALL_NODE_RADIUS)
                painter.setPen(QPen(QColor(15, 15, 18),
                                    self.overlay_px(1.5)))
                painter.setBrush(QBrush(QColor(95, 175, 255) if selected
                                        else QColor(232, 232, 238)))
                painter.drawEllipse(centre, knob, knob)
        # Ластик: красная точка под курсором — то, что удалит клик. Точки
        # стен в этом режиме не рисуются, поэтому без подсветки мастер
        # целился вслепую.
        if self.wall_tool == "delete" and self._wall_hover_point is not None:
            wall_id, index = self._wall_hover_point
            target = next((wal for wal in walls
                           if wal["id"] == wall_id), None)
            if target is not None and 0 <= index < len(target["points"]):
                spot = QPointF(*self.world_to_screen(
                    *target["points"][index]))
                glow = QPen(QColor(255, 80, 80, 90))
                glow.setWidthF(self.overlay_px(9.0))
                glow.setCapStyle(Qt.RoundCap)
                painter.setPen(glow)
                brush = QBrush(Qt.NoBrush)
                painter.setBrush(brush)
                painter.drawEllipse(spot, self.overlay_px(8.0),
                                    self.overlay_px(8.0))
                painter.setPen(QPen(QColor(255, 245, 245),
                                    self.overlay_px(1.5)))
                painter.setBrush(QBrush(QColor(226, 62, 62)))
                painter.drawEllipse(spot, self.overlay_px(5.5),
                                    self.overlay_px(5.5))
        # Недорисованная ломаная: точки, линия до курсора и подсказка.
        if self._wall_draft:
            points = [QPointF(*self.world_to_screen(px, py))
                      for px, py in self._wall_draft]
            pen = QPen(QColor(120, 200, 255))
            pen.setWidthF(self.overlay_px(2.0))
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            for index in range(len(points) - 1):
                painter.drawLine(points[index], points[index + 1])
            if self._wall_draft_cursor is not None:
                pen.setStyle(Qt.DashLine)
                painter.setPen(pen)
                # Точки уже переведены в экранные координаты, а курсор ещё
                # хранится в мировых: без перевода пунктир тянулся в точку
                # с координатами мира, то есть далеко за холст — линия
                # «из ниоткуда» при любом зуме, кроме 100%.
                painter.drawLine(
                    points[-1],
                    QPointF(*self.world_to_screen(
                        *self._wall_draft_cursor)))
            for point in points:
                painter.setPen(QPen(QColor(20, 20, 24),
                                    self.overlay_px(1.5)))
                painter.setBrush(QBrush(QColor(120, 200, 255)))
                painter.drawEllipse(point, self.overlay_px(4.0),
                                    self.overlay_px(4.0))
        # Призрак следующей вершины: полый кружок с перекрестием там, где
        # она встанет по клику (с учётом Snap). Без него место будущей точки
        # видно только после нажатия.
        if self.wall_tool == "points" and self._wall_draft_cursor is not None:
            spot = QPointF(*self.world_to_screen(*self._wall_draft_cursor))
            pen = QPen(QColor(140, 210, 255))
            pen.setWidthF(self.overlay_px(1.6))
            pen.setStyle(Qt.DashLine)
            painter.setPen(pen)
            painter.setBrush(QBrush(QColor(140, 210, 255, 55)))
            painter.drawEllipse(spot, self.overlay_px(6.0),
                                self.overlay_px(6.0))
            painter.setBrush(Qt.NoBrush)
            arm = self.overlay_px(10.0)
            painter.drawLine(QPointF(spot.x() - arm, spot.y()),
                             QPointF(spot.x() + arm, spot.y()))
            painter.drawLine(QPointF(spot.x(), spot.y() - arm),
                             QPointF(spot.x(), spot.y() + arm))
        # Прямоугольник, который тянут мышью.
        if self._wall_rect_start is not None and self._wall_rect_current:
            start = QPointF(*self.world_to_screen(*self._wall_rect_start))
            end = QPointF(*self.world_to_screen(*self._wall_rect_current))
            pen = QPen(QColor(120, 200, 255))
            pen.setWidthF(self.overlay_px(2.0))
            pen.setStyle(Qt.DashLine)
            painter.setPen(pen)
            painter.setBrush(QBrush(QColor(120, 200, 255, 40)))
            painter.drawRect(QRectF(start, end).normalized())
        painter.restore()

    # ------------------------------------------------------------------
    # Отрисовка объектов карты
    # ------------------------------------------------------------------
    def draw_map_objects(self, painter: QPainter, above: bool):
        """PNG-объекты своего слоя: под токенами или поверх них.

        Ночью объект — такой же элемент поверхности, как карта: он гаснет
        вместе с ней, но свет его не освещает. Крыша над освещённым полом
        остаётся тёмным силуэтом, а не светится пятном.
        """
        objects = [obj for obj in self._object_z_order()
                   if obj.visible and bool(obj.above_tokens) == above]
        if not objects:
            return
        tint = self.object_night_tint()
        if tint is None:
            # День: объект — часть карты, а не экранный виджет. Преобразование
            # задаём заново, чтобы ни один предыдущий слой не мог сдвинуть
            # картинку относительно карты: при панораме и зуме она едет с ней.
            painter.save()
            painter.resetTransform()
            painter.translate(self.offset_x, self.offset_y)
            painter.scale(self.scale, self.scale)
            # Порядок — z: кто добавлен позже (или выше z), тот сверху.
            for obj in objects:
                self.draw_map_object(painter, obj)
            painter.restore()
            return

        area = self.objects_screen_area(objects)
        if area.isEmpty():
            return
        layer = self.object_night_layer(area.size())
        layer.fill(Qt.transparent)
        own = QPainter(layer)
        own.setRenderHint(QPainter.Antialiasing, True)
        own.translate(self.offset_x - area.left(), self.offset_y - area.top())
        own.scale(self.scale, self.scale)
        for obj in objects:
            self.draw_map_object(own, obj)
        # Затемнение ложится только туда, где есть сам объект (SourceAtop
        # сохраняет альфу картинки), и без пятен света: накладка над полом
        # свет не ловит.
        own.resetTransform()
        own.setCompositionMode(QPainter.CompositionMode_SourceAtop)
        own.setPen(Qt.NoPen)
        own.setBrush(QBrush(tint))
        own.drawRect(QRectF(layer.rect()))
        own.end()

        painter.save()
        painter.resetTransform()
        painter.drawImage(QRectF(area), layer)
        painter.restore()

    def object_night_tint(self) -> Optional[QColor]:
        """Цвет ночного затемнения для объектов; None — день или плотность 0.

        Альфа умножается на долю ночи: объекты гаснут вместе с картой, а не
        проваливаются в темноту мгновенно, пока пол ещё светлый.
        """
        level = self.night_level()
        if level <= 0.004:
            return None
        tint = self.night_tint_color()
        if tint.alpha() <= 0:
            return None
        tint.setAlpha(int(round(tint.alpha() * level)))
        return tint if tint.alpha() > 0 else None

    def object_night_layer(self, size: QSize) -> QImage:
        """Буфер слоя объектов: пересоздаётся только при смене размера."""
        if (self._object_layer_image is not None
                and self._object_layer_image.size() == size):
            return self._object_layer_image
        image = QImage(size, QImage.Format_ARGB32_Premultiplied)
        self._object_layer_image = image
        return image

    def objects_screen_area(self, objects) -> QRect:
        """Видимая часть слоя объектов в экранных координатах."""
        left = top = float("inf")
        right = bottom = float("-inf")
        for obj in objects:
            for px, py in self.object_corners_world(obj):
                sx, sy = self.world_to_screen(px, py)
                left = min(left, sx)
                right = max(right, sx)
                top = min(top, sy)
                bottom = max(bottom, sy)
        if not all(math.isfinite(v) for v in (left, top, right, bottom)):
            return QRect()
        area = QRectF(left - 2.0, top - 2.0,
                      right - left + 4.0, bottom - top + 4.0)
        return area.toAlignedRect().intersected(self.rect())

    def draw_map_object(self, painter: QPainter, obj):
        rect = self.object_rect_world(obj)
        roof_alpha = (self._roof_alpha.get(obj.id, 1.0) if obj.roof else 1.0)
        alpha = (max(0.0, min(100, int(obj.opacity))) / 100.0) * roof_alpha
        if alpha <= 0.01:
            return
        cx, cy = self._object_center(obj)
        local = QRectF(-rect.width() / 2.0, -rect.height() / 2.0,
                       rect.width(), rect.height())
        # Холст уже переведён в мировые координаты и отмасштабирован:
        # поворачиваем объект вокруг его центра, не трогая масштаб вида.
        painter.save()
        painter.setOpacity(alpha)
        painter.translate(cx, cy)
        painter.rotate(float(obj.rotation or 0.0))
        pix = self.object_images.get(obj.id)
        if pix is not None and not pix.isNull():
            painter.drawPixmap(local, pix, QRectF(pix.rect()))
        else:
            # Картинка ещё не доехала — место объекта видно, но не бросается
            # в глаза: рамка с диагоналями, как у потерянного файла.
            painter.setPen(QPen(QColor(180, 180, 190, 160), 1))
            painter.setBrush(QBrush(QColor(90, 90, 100, 70)))
            painter.drawRect(local)
            painter.drawLine(local.topLeft(), local.bottomRight())
            painter.drawLine(local.topRight(), local.bottomLeft())
        painter.restore()

    def draw_object_ui(self, painter: QPainter):
        """Рамка и углы выбранного объекта — в экранных px.

        Стрелки настроек и замка на холсте нет: оба действия живут в
        левой панели «Объекты», чтобы не цепляться к картинке.
        """
        if not self.is_dm:
            return

        obj = self.objects.get(self.selected_object_id)
        if obj is None or not self.object_belongs_to_current_map(obj):
            return
        corners = [QPointF(*self.world_to_screen(x, y))
                   for x, y in self.object_corners_world(obj)]
        pen = QPen(QColor(0, 200, 255))
        pen.setWidthF(self.overlay_px(2.0))
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawPolygon(QPolygonF(corners))
        if not obj.locked:
            # Ручка поворота — над верхним краем, на короткой ножке.
            top = QPointF((corners[0].x() + corners[1].x()) / 2.0,
                          (corners[0].y() + corners[1].y()) / 2.0)
            handle = self.object_rotation_handle_pos(obj)
            painter.setPen(QPen(QColor(0, 200, 255),
                                self.overlay_px(1.5)))
            painter.drawLine(top, handle)
            painter.setBrush(QBrush(QColor(20, 22, 28, 230)))
            knob = self.overlay_px(OBJECT_ROTATE_RADIUS_PX)
            painter.drawEllipse(handle, knob, knob)

            painter.setPen(QPen(QColor(255, 255, 255),
                                self.overlay_px(2.0)))
            painter.setBrush(QBrush(QColor(0, 200, 255)))
            size = self.overlay_px(HANDLE_SIZE)
            h = size / 2.0
            for pos in self.object_handle_positions(obj).values():
                painter.drawRect(QRectF(pos.x() - h, pos.y() - h,
                                        size, size))

    # ------------------------------------------------------------------
    # Линейка: измерение расстояний в футах (1 клетка = 5 футов)
    # ------------------------------------------------------------------
    def ruler_distance_cells(self) -> float:
        """Расстояние между началом и концом линейки в клетках.

        По осям считаем отдельно: если клетка не квадратная, делить общее
        расстояние на средний размер клетки было бы неверно. Диагональ —
        по теореме Пифагора, поэтому значение не всегда целое.
        """
        if self.ruler_start is None or self.ruler_end is None:
            return 0.0
        m = self.current_map
        if m is None:
            return 0.0
        cell_w, cell_h = m.grid_cell_world
        if cell_w <= 0 or cell_h <= 0:
            return 0.0
        dx = (self.ruler_end[0] - self.ruler_start[0]) / cell_w
        dy = (self.ruler_end[1] - self.ruler_start[1]) / cell_h
        return math.hypot(dx, dy)

    def ruler_feet(self) -> float:
        """Расстояние в футах: клетки × 5."""
        return self.ruler_distance_cells() * FEET_PER_CELL

    @staticmethod
    def format_feet(feet: float) -> str:
        """Футы в текст: 30 фт, 21.2 фт. Хвостовые нули не показываем."""
        if feet <= 0:
            return '0 фт'
        if abs(feet - round(feet)) < 0.05:
            return f'{int(round(feet))} фт'
        return f'{feet:.1f} фт'

    def clear_ruler(self):
        self.ruler_start = None
        self.ruler_end = None
        self.ruler_active = False
        self.update()

    # --- Шаблоны областей (AoE): круг, конус, линия, квадрат ---
    # Режим 'template': клик ставит центр, движение мыши задаёт направление
    # (для конуса и линии), второй клик подтверждает. Геометрия — shared/templates.
    TEMPLATE_KINDS = ('circle', 'cone', 'line', 'square')

    def start_template(self, kind: str = 'circle', size_ft: float = 20.0,
                       origin_cell=None):
        """Включить режим шаблона: kind — форма, size_ft — размер в футах.

        ``origin_cell`` нужен конусу и линии: их начало — клетка колдуна.
        Круг и квадрат ставятся первым кликом, как раньше.
        """
        if kind not in self.TEMPLATE_KINDS:
            raise ValueError(f"неизвестная форма шаблона: {kind}")
        self.drawing_mode = 'template'
        self.template_kind = kind
        self.template_size_ft = float(size_ft)
        self.template_origin = (tuple(origin_cell)
                                if origin_cell is not None else None)
        self.template_preset = self.template_origin is not None
        self.template_aim = None      # (wx, wy) точка прицеливания в мире
        self.drawing_points = []
        self._preview_points = []
        self.setCursor(Qt.CrossCursor)
        self.tool_changed.emit('template')
        self.update()

    def _template_cell_of(self, wx: float, wy: float):
        """Клетка сетки под точкой мира или None (если сетки нет)."""
        grid = self.grid
        if not grid or not grid.cols or not grid.rows:
            return None
        m = self.current_map
        if m is None or not m.width or not m.height:
            return None
        cw = m.width / grid.cols
        ch = m.height / grid.rows
        col = int((wx - m.pos_x) // cw)
        row = int((wy - m.pos_y) // ch)
        if not (0 <= col < grid.cols and 0 <= row < grid.rows):
            return None
        return col, row

    def _handle_template_press(self, wx: float, wy: float):
        if self.template_origin is None:
            cell = self._template_cell_of(wx, wy)
            if cell is None:
                return
            self.template_origin = cell
            self.template_aim = (wx, wy)
            self.template_preset = False
            self.update()
            return
        if self.template_preset:
            # Конус/линия: начало уже на колдуне, этот клик задаёт
            # направление и сразу применяет область.
            self.template_aim = (wx, wy)
            self.template_preset = False
            self.finish_template()
            return
        # второй клик — подтвердить шаблон
        self.finish_template()

    def _template_cells(self):
        """Клетки, которые попадают в шаблон при текущем прицеливании."""
        if self.template_origin is None:
            return []
        col, row = self.template_origin
        grid = self.grid
        cols, rows = grid.cols, grid.rows
        kind = self.template_kind
        size = self.template_size_ft
        if kind == 'circle':
            return aoe.circle(col, row, size, cols, rows)
        if self.template_aim is None:
            return []
        cell = self._template_cell_of(*self.template_aim)
        dc = (cell[0] - col) if cell else 1
        dr = (cell[1] - row) if cell else 0
        if dc == 0 and dr == 0:
            dc = 1
        if kind == 'cone':
            return aoe.cone(col, row, dc, dr, size, cols, rows)
        if kind == 'line':
            return aoe.line(col, row, dc, dr, size, 5, cols, rows)
        return aoe.square(col, row, size, cols, rows)

    def draw_template(self, painter: QPainter):
        """Подсветить клетки шаблона поверх карты (только превью)."""
        cells = self._template_cells()
        if not cells:
            return
        grid = self.grid
        m = self.current_map
        if m is None:
            return
        cw = m.width / grid.cols
        ch = m.height / grid.rows
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(255, 170, 60, 90)))
        for c, r in cells:
            x1, y1 = self.world_to_screen(m.pos_x + c * cw, m.pos_y + r * ch)
            x2, y2 = self.world_to_screen(m.pos_x + (c + 1) * cw,
                                          m.pos_y + (r + 1) * ch)
            painter.drawRect(QRectF(x1, y1, x2 - x1, y2 - y1))

    def cancel_template(self):
        """Выйти из шаблона без применения: ячейка и цель не тратятся."""
        self.drawing_mode = None
        self.template_origin = None
        self.template_aim = None
        self.template_preset = False
        self.setCursor(Qt.ArrowCursor)
        self.tool_changed.emit('')
        self.template_cancelled.emit()
        self.update()

    def finish_template(self):
        """Зафиксировать шаблон: сообщаем подсвеченные клетки и выходим из режима."""
        cells = self._template_cells()
        origin = list(self.template_origin) if self.template_origin else None
        aim = None
        if self.template_aim is not None:
            aim = self._template_cell_of(*self.template_aim)
            aim = list(aim) if aim else None
        self.template_result = {'kind': self.template_kind,
                                'size_ft': self.template_size_ft,
                                'origin_cell': origin,
                                'aim_cell': aim,
                                'map_id': (self.current_map.id
                                           if self.current_map else None),
                                'cells': [list(c) for c in cells]}
        self.template_done.emit(self.template_result)
        self.drawing_mode = None
        self.template_origin = None
        self.template_aim = None
        self.template_preset = False
        self.setCursor(Qt.ArrowCursor)
        self.tool_changed.emit('')
        self.update()

    # ------------------------------------------------------------------
    # Выбор цели заклинания
    # ------------------------------------------------------------------
    def start_target_pick(self, label: str = "") -> None:
        """Взвести заклинание на цель: прицел, кольцо и плашка отмены.

        Раньше заклинание без цели молча писало «не выбрана цель» в чат:
        было непонятно, что приложение чего-то ждёт и как это отменить.
        Теперь холст сразу показывает, что он в режиме выбора: стрелка
        меняется на прицел, токен под курсором обводится золотым кольцом,
        а сверху висит плашка с подсказкой.
        """
        if self.drawing_mode == 'template':
            # Шаблон и выбор цели взаимоисключающие: оставленный шаблон
            # перехватил бы первый же клик по цели.
            self.cancel_template()
        self.target_pick_mode = True
        self.target_pick_label = str(label or "").strip()
        self.target_pick_hover = None
        self.setCursor(Qt.CrossCursor)
        self.update()

    def cancel_target_pick(self, silent: bool = False) -> None:
        """Снять режим выбора цели. Ячейка и цель при этом не тратятся."""
        if not self.target_pick_mode:
            return
        self.target_pick_mode = False
        self.target_pick_label = ""
        self.target_pick_hover = None
        self._apply_tool_cursor()
        self.update()
        if not silent:
            self.target_pick_cancelled.emit()

    def set_target_pick_hover(self, token_id) -> None:
        """Перерисовать только два кольца — старое и новое."""
        token_id = str(token_id or "") or None
        if token_id == self.target_pick_hover:
            return
        old, self.target_pick_hover = self.target_pick_hover, token_id
        for tid in (old, token_id):
            region = self._token_screen_region(tid) if tid else None
            if region is not None:
                self.update(region.toRect().adjusted(-8, -8, 8, 8))

    def _finish_target_pick(self, token_id: str) -> None:
        self.target_pick_mode = False
        self.target_pick_label = ""
        self.target_pick_hover = None
        self._apply_tool_cursor()
        self.update()
        self.target_picked.emit(str(token_id))

    def draw_target_pick_ring(self, painter: QPainter) -> None:
        """Золотое кольцо вокруг токена под курсором в режиме выбора цели.

        Цвет отличается от зелёного кольца перетаскиваемого предмета: тут
        не «отпустить», а «выбрать», поэтому кольцо нарисовано пунктиром
        с мягким свечением — видно и на светлой, и на тёмной карте.
        """
        token = self.tokens.get(self.target_pick_hover or "")
        if token is None or not token.visible:
            return
        if not self.token_belongs_to_current_map(token):
            return
        rect = self._token_screen_rect_world(token)
        margin = self.design(RING_OFFSET_PX + 2.0)
        ring = rect.adjusted(-margin, -margin, margin, margin)
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        glow = QPen(QColor(255, 214, 128, 80))
        glow.setWidthF(self.design(7.0))
        painter.setPen(glow)
        painter.setBrush(Qt.NoBrush)
        painter.drawEllipse(ring)
        pen = QPen(QColor(255, 226, 158))
        pen.setWidthF(self.design(2.2))
        pen.setStyle(Qt.CustomDashLine)
        pen.setDashPattern([4.0, 3.0])
        painter.setPen(pen)
        painter.drawEllipse(ring)
        painter.restore()

    def draw_cast_banner(self, painter: QPainter) -> None:
        """Плашка сверху: что сейчас ждёт холст и как это отменить.

        Строка состояния внизу далеко от курсора, а книга заклинаний
        открывается сбоку — без плашки на карте нажатие «Применить»
        выглядело как «ничего не произошло».
        """
        if self.target_pick_mode:
            title = self.target_pick_label or "Заклинание"
            hint = "клик по токену — цель · ПКМ или Esc — отмена"
        elif self.drawing_mode == 'template':
            title = "Область заклинания"
            hint = "клик — центр · второй клик — применить · ПКМ или Esc — отмена"
        else:
            return
        f = QFont(painter.font())
        f.setPointSize(10)
        f.setBold(True)
        small = QFont(f)
        small.setPointSize(8)
        small.setBold(False)
        title_width = QFontMetrics(f).horizontalAdvance(title)
        hint_width = QFontMetrics(small).horizontalAdvance(hint)
        # Плашка не шире холста: в узком окне длинная подсказка ужимается
        # многоточием, а не уезжает за край.
        width = min(max(title_width, hint_width) + 26.0,
                    max(180.0, self.width() - 24.0))
        title = QFontMetrics(f).elidedText(title, Qt.ElideRight,
                                           int(width) - 22)
        hint = QFontMetrics(small).elidedText(hint, Qt.ElideRight,
                                              int(width) - 22)
        height = 40.0
        left = (self.width() - width) / 2.0
        top = 12.0
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(24, 20, 12, 230)))
        painter.drawRoundedRect(QRectF(left, top, width, height), 8.0, 8.0)
        border = QPen(QColor(242, 204, 118, 190))
        border.setCosmetic(True)
        border.setWidthF(1.4)
        painter.setPen(border)
        painter.setBrush(Qt.NoBrush)
        painter.drawRoundedRect(QRectF(left, top, width, height), 8.0, 8.0)
        painter.setPen(QPen(QColor(247, 231, 196)))
        painter.setFont(f)
        painter.drawText(QRectF(left, top + 5.0, width, 16.0),
                         Qt.AlignHCenter | Qt.AlignVCenter, title)
        painter.setPen(QPen(QColor(214, 198, 166)))
        painter.setFont(small)
        painter.drawText(QRectF(left, top + 21.0, width, 14.0),
                         Qt.AlignHCenter | Qt.AlignVCenter, hint)

    def start_ruler(self):
        """Включить линейку. Начало ставится первым нажатием."""
        self.drawing_mode = 'ruler'
        self.drawing_points = []
        self._preview_points = []
        self.drawing_is_eraser = False
        self.ruler_start = None
        self.ruler_end = None
        self.ruler_active = False
        self.setCursor(Qt.CrossCursor)
        self.tool_changed.emit('ruler')
        self.update()

    def draw_ruler(self, painter: QPainter):
        """Нарисовать стрелку и подпись в ЭКРАННЫХ координатах.

        Рисуем вне мирового преобразования, поэтому наконечник, толщина линии
        и шрифт не меняются при зуме — растягивается только сама стрелка.
        """
        if self.ruler_start is None or self.ruler_end is None:
            return
        x1, y1 = self.world_to_screen(*self.ruler_start)
        x2, y2 = self.world_to_screen(*self.ruler_end)
        dx, dy = x2 - x1, y2 - y1
        length = math.hypot(dx, dy)
        if length < 1.0:
            return

        color = QColor(255, 235, 120)
        pen = QPen(color)
        pen.setWidthF(RULER_LINE_WIDTH)
        pen.setCapStyle(Qt.RoundCap)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))

        # Наконечник у конца стрелки: вершина в точке конца, основание — на
        # длине head позади. Всё в экранных пикселях, поэтому при отдалении
        # наконечник не растягивается.
        ux, uy = dx / length, dy / length
        head = min(RULER_HEAD_PX, length)
        # Полуширина через тангенс: получается ровно 2*head*tan(угол).
        half_w = head * math.tan(RULER_HEAD_ANGLE)
        base_x, base_y = x2 - ux * head, y2 - uy * head
        # Перпендикуляр к направлению стрелки
        px_, py_ = -uy, ux
        left = QPointF(base_x + px_ * half_w, base_y + py_ * half_w)
        right = QPointF(base_x - px_ * half_w, base_y - py_ * half_w)
        painter.setBrush(QBrush(color))
        painter.setPen(Qt.NoPen)
        painter.drawPolygon(QPolygonF([QPointF(x2, y2), left, right]))

        # Начало: кружок, чтобы было видно, откуда мерим
        painter.setBrush(QBrush(color))
        painter.drawEllipse(QPointF(x1, y1), RULER_DOT_RADIUS, RULER_DOT_RADIUS)

        # Подпись с футами в середине стрелки, чуть выше линии
        text = self.format_feet(self.ruler_feet())
        font = QFont(painter.font())
        font.setPointSizeF(11.0)
        font.setBold(True)
        painter.setFont(font)
        metrics = painter.fontMetrics()
        tw, th = metrics.horizontalAdvance(text), metrics.height()
        cx, cy = (x1 + x2) / 2, (y1 + y2) / 2
        nx, ny = -uy, ux
        if ny > 0:
            nx, ny = -nx, -ny
        pad = 6.0
        box = QRectF(cx - tw / 2 - pad, cy - th - 10.0, tw + pad * 2, th + pad)
        box.translate(nx * 8.0, ny * 8.0)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(20, 20, 24, 205)))
        painter.drawRoundedRect(box, 5.0, 5.0)
        painter.setPen(QPen(QColor(255, 240, 150)))
        painter.drawText(box, Qt.AlignCenter, text)

    def snap_ruler_point(self, wx: float, wy: float) -> Tuple[float, float]:
        """Привязать точку линейки к центру или середине стороны клетки."""
        m = self.current_map
        if m is None or not m.grid.valid:
            return wx, wy
        return m.grid.snap_point(wx, wy, m.pos_x, m.pos_y, m.width, m.height)

    def _handle_ruler_press(self, wx: float, wy: float):
        """Первое нажатие задаёт начало, дальше тянем конец.

        Обе точки магнитятся к опорным точкам клетки: так измерение даёт
        ровные футы, а не случайную дробь от пикселя под курсором.
        """
        wx, wy = self.snap_ruler_point(wx, wy)
        self.ruler_start = (wx, wy)
        self.ruler_end = (wx, wy)
        self.ruler_active = True
        self.update()

    def _handle_ruler_move(self, wx: float, wy: float):
        if not self.ruler_active:
            return
        self.ruler_end = self.snap_ruler_point(wx, wy)
        self.update()

    def _handle_ruler_release(self):
        """Отпускаем кнопку — измерение остаётся на экране, чтобы прочитать."""
        if not self.ruler_active:
            return
        self.ruler_active = False
        self.update()

    def draw_map_loading(self, painter: QPainter):
        """Заставка загрузки карты: жёлтый d20 и подпись под ним."""
        state = self._map_loading
        if not state:
            return
        now = time.monotonic()
        painter.save()

        # Приглушаем карту, чтобы заставка читалась даже на светлой картинке.
        painter.fillRect(self.rect(), QColor(10, 10, 13, 125))

        panel_w = min(560.0, max(300.0, self.width() - 48.0))
        panel_h = min(252.0, max(176.0, self.height() - 52.0))
        left = (self.width() - panel_w) / 2.0
        top = (self.height() - panel_h) / 2.0
        panel = QRectF(left, top, panel_w, panel_h)

        # Тень и тёмная плашка в тон интерфейсу.
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(0, 0, 0, 120)))
        painter.drawRoundedRect(panel.adjusted(5, 7, 5, 7), 20, 20)
        painter.setBrush(QBrush(QColor(24, 23, 27, 242)))
        painter.setPen(QPen(QColor(202, 164, 58, 165), 1.3))
        painter.drawRoundedRect(panel, 18, 18)

        # Заголовок мелкий и негромкий: подписи под кубом — главное.
        title = QFont(painter.font())
        title.setPointSize(9)
        title.setBold(True)
        painter.setFont(title)
        painter.setPen(QColor(190, 158, 82))
        painter.drawText(QRectF(left, top + 12, panel_w, 18),
                         Qt.AlignHCenter | Qt.AlignVCenter,
                         "ЗАГРУЖАЕМ КАРТУ")

        # Куб рисуем в экранных координатах: при зуме карты он не должен
        # уменьшаться вместе с ней.
        die_cx = self.width() / 2.0
        die_cy = top + min(103.0, panel_h * 0.43)
        die_r = min(44.0, panel_h * 0.20)
        phase = now - state['start']
        self._draw_loading_d20(painter, die_cx, die_cy, die_r, phase)

        # Подпись сменяется каждые 2 секунды и мягко проявляется.
        captions = state.get('captions') or []
        index = int(state.get('caption_index', 0))
        caption = captions[index] if 0 <= index < len(captions) else ""
        caption_age = max(0.0, now - state['caption_start'])
        fade = min(1.0, caption_age / 0.22,
                   max(0.0, (MAP_LOADING_CAPTION_S - caption_age) / 0.22))
        painter.setOpacity(max(0.0, min(1.0, fade)))
        font = QFont(painter.font())
        font.setPointSize(12)
        font.setBold(True)
        painter.setFont(font)
        painter.setPen(QColor(246, 219, 142))
        painter.drawText(QRectF(left + 24, top + panel_h - 76,
                                panel_w - 48, 58),
                         Qt.AlignHCenter | Qt.AlignTop | Qt.TextWordWrap,
                         caption)
        painter.setOpacity(1.0)

        painter.restore()

    def _draw_loading_d20(self, painter: QPainter, cx: float, cy: float,
                          radius: float, phase: float):
        """Нарисовать вращающийся жёлтый d20 как проекцию икосаэдра."""
        angle_y = phase * 2.1
        angle_x = 0.32 + math.sin(phase * 1.25) * 0.30
        cos_y, sin_y = math.cos(angle_y), math.sin(angle_y)
        cos_x, sin_x = math.cos(angle_x), math.sin(angle_x)
        unit = radius / 1.902

        # Мягкое золотое свечение под кубом.
        pulse = 0.5 + 0.5 * math.sin(phase * 3.1)
        glow = QRadialGradient(cx, cy, radius * 2.2)
        glow.setColorAt(0.0, QColor(255, 205, 70, int(58 + 28 * pulse)))
        glow.setColorAt(0.55, QColor(255, 190, 50, int(18 + 14 * pulse)))
        glow.setColorAt(1.0, QColor(255, 190, 50, 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(glow))
        painter.drawEllipse(QPointF(cx, cy), radius * 2.0, radius * 2.0)

        points = []
        for x, y, z in _D20_VERTICES:
            x1 = x * cos_y + z * sin_y
            z1 = -x * sin_y + z * cos_y
            y1 = y * cos_x - z1 * sin_x
            z2 = y * sin_x + z1 * cos_x
            # Лёгкая перспектива: ближние вершины чуть крупнее.
            perspective = 1.0 / (1.0 - z2 * 0.14)
            points.append((cx + x1 * perspective * unit,
                           cy + y1 * perspective * unit, z2))

        # Света сверху-слева, как будто лампа стола над картой.
        light = (-0.42, -0.70, 0.58)
        light_len = math.sqrt(sum(v * v for v in light)) or 1.0
        light = tuple(v / light_len for v in light)

        shaded = []
        for face in _D20_FACES:
            a, b, c = (points[i] for i in face)
            ux, uy, uz = b[0] - a[0], b[1] - a[1], b[2] - a[2]
            vx, vy, vz = c[0] - a[0], c[1] - a[1], c[2] - a[2]
            nx, ny, nz = uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx
            n_len = math.sqrt(nx * nx + ny * ny + nz * nz) or 1.0
            nx, ny, nz = nx / n_len, ny / n_len, nz / n_len
            shade = abs(nx * light[0] + ny * light[1] + nz * light[2])
            shade = 0.24 + 0.76 * shade
            depth = (a[2] + b[2] + c[2]) / 3.0
            shaded.append((depth, face, shade))

        # Дальние грани рисуем первыми — так куб выглядит объёмным.
        shaded.sort(key=lambda item: item[0])
        low = (126, 86, 10)
        high = (255, 224, 103)
        for _depth, face, shade in shaded:
            color = QColor(
                int(low[0] + (high[0] - low[0]) * shade),
                int(low[1] + (high[1] - low[1]) * shade),
                int(low[2] + (high[2] - low[2]) * shade))
            painter.setBrush(QBrush(color))
            painter.setPen(QPen(QColor(79, 55, 7, 210), 1.15))
            painter.drawPolygon(QPolygonF([
                QPointF(points[i][0], points[i][1]) for i in face]))


    def show_hint(self, text: str, msec: int = 2600):
        """Показать короткую подсказку справа в строке состояния.

        Подсказка живёт ``msec`` миллисекунд и гаснет сама: строка
        состояния не должна превращаться в журнал.
        """
        text = str(text or "").strip()
        if not text:
            return
        self.statusBar_hint = text
        self._hint_timer.start(max(600, int(msec)))
        self.update()

    def _clear_status_hint(self):
        if not self.statusBar_hint:
            return
        self.statusBar_hint = ""
        self.update()

    def draw_status_bar(self, painter: QPainter):
        if not self.current_map:
            return
        mode = self.drawing_mode or ('выбор' if not self.is_dm else 'DM')
        tool_names = {'brush': 'кисть', 'line': 'линия', 'circle': 'круг',
                      'square': 'квадрат', 'polygon': 'фигура',
                      'eraser': 'ластик', 'ruler': 'линейка'}
        mode = tool_names.get(mode, mode)
        text = (f"Масштаб: {int(self.scale * 100)}%  |  "
                f"Карта: {int(self.current_map.width)}x{int(self.current_map.height)}  |  "
                f"Клетка: {self.grid_cell_world:.1f}  |  Режим: {mode}")
        if self.drawing_mode in RASTER_TOOLS:
            text += f"  |  Кисть: {self.brush_size:.0f}px"
            if self.drawing_mode != 'eraser':
                text += f", непрозр.: {int(self.brush_opacity * 100)}%"
            text += "  |  Ctrl+Z — отменить штрих"
        f = painter.font()
        f.setPointSize(9)
        painter.setFont(f)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(0, 0, 0, 150)))
        painter.drawRect(0, self.height() - 22, self.width(), 22)
        painter.setPen(QPen(QColor(225, 225, 232)))
        painter.drawText(8, self.height() - 7, text)
        # Подсказка — отдельной плашкой справа: не спорит с длинной
        # строкой режима, не уезжает за край и обрезается многоточием,
        # если окно узкое.
        if self.statusBar_hint:
            hint_font = QFont(f)
            hint_font.setBold(True)
            painter.setFont(hint_font)
            metrics = QFontMetrics(hint_font)
            max_width = max(120, int(self.width() * 0.52))
            hint = metrics.elidedText(self.statusBar_hint, Qt.ElideRight,
                                      max_width)
            text_width = metrics.horizontalAdvance(hint)
            pill = QRectF(self.width() - text_width - 18.0,
                          self.height() - 20.0, text_width + 12.0, 17.0)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor(62, 50, 22, 235)))
            painter.drawRoundedRect(pill, 8.0, 8.0)
            painter.setPen(QPen(QColor(242, 204, 118)))
            painter.drawText(pill, Qt.AlignCenter, hint)

    # ------------------------------------------------------------------
    # Клавиатура
    # ------------------------------------------------------------------
    def focusNextPrevChild(self, next_widget):
        """Не отдавать Tab смене фокуса: он центрирует карту."""
        return False

    def keyReleaseEvent(self, event):
        """Отпустили клавишу направления — шаг прекращается."""
        if self.wasd_movement:
            key = event_key(event)
            if key in WASD_DIRECTIONS:
                if key in self._wasd_keys:
                    self._wasd_keys.remove(key)
                if not self._wasd_keys:
                    self.stop_wasd_movement()
                event.accept()
                return
        super().keyReleaseEvent(event)

    def handle_escape(self) -> bool:
        """Esc: отменить то, что сейчас включено. True — что-то отменили.

        QShortcut окна срабатывает РАНЬШЕ холста, поэтому Esc никогда не
        доходит до `keyPressEvent`: окно зовёт этот метод из
        `_escape_pressed`. Раньше здесь было «оставим Esc холсту» — и
        отмена поворота, стены и калибровки молча не работала.

        Порядок — от самого частного режима к общему: поворот токена,
        недорисованная стена, выделенная надпись, взведённое заклинание,
        калибровка сетки, шаблон области, линейка, фигура, штрих, подсветка
        хода. Всё остальное (быстрая атака, выделение) — уже в окне.
        """
        if self.rotating_token_id:
            self.cancel_token_rotation()
            return True
        if self._wall_draft or self._wall_rect_start is not None:
            self.cancel_wall_draft()
            self.show_hint("Стена отменена")
            return True
        if self._editing_text_id:
            # Набор идёт в поле правки, и Esc уже забрал его eventFilter
            # (ShortcutOverride). Сюда событие может дойти только в обход —
            # тогда просто не трогаем выделение токенов.
            return True
        if self.selected_text_id:
            # Escape снимает выделение с надписи, не выходя из инструмента.
            self._set_selected_text(None)
            return True
        if self.target_pick_mode:
            # Взведённое заклинание снимается раньше инструментов: Esc в
            # этом режиме означает именно «передумал», а не смену кисти.
            self.cancel_target_pick()
            self.show_hint('выбор цели отменён')
            return True
        if self._grid_calibrating:
            self.cancel_grid_calibration()
            self.show_hint('калибровка отменена')
            return True
        if self.drawing_mode == 'template':
            self.cancel_template()
            self.show_hint('шаблон отменён')
            return True
        if self.drawing_mode == 'ruler':
            self.clear_ruler()
            self.stop_drawing()
            return True
        if self.drawing_mode == 'polygon':
            # У фигуры Escape отменяет набор целиком: незамкнутый контур
            # сохранять незачем.
            self.drawing_points = []
            self._preview_points = []
            self.drawing_mode = None
            self._apply_tool_cursor()
            self.tool_changed.emit('')
            self.update()
            return True
        if self.drawing_mode:
            self.finish_drawing()
            return True
        if self.chess_token_id:
            # Escape отменяет подсветку хода в бою.
            self.chess_token_id = None
            self.setCursor(Qt.ArrowCursor)
            self.update()
            return True
        if self.rubber_active:
            # Брошенная рамка выделения (отпускание мыши ушло другому окну).
            self.rubber_active = False
            self.rubber_origin = None
            self.rubber_current = None
            self.update()
            return True
        return False

    def keyPressEvent(self, event):
        """Горячие клавиши инструментов рисования (в любой раскладке)"""
        key = event_key(event)
        mods = event.modifiers()

        # Esc — одной веткой: вся цепочка режимов живёт в handle_escape(),
        # потому что окно вызывает её же, когда Esc перехватил QShortcut.
        if key == Qt.Key_Escape and mods == Qt.NoModifier:
            if self.handle_escape():
                event.accept()
                return

        # Поворот токена важнее остальных клавиш: пока режим включён,
        # R фиксирует угол. Проверка стоит первой — иначе R закрывал бы
        # инструмент рисования.
        if self.rotating_token_id:
            if mods == Qt.NoModifier and key == Qt.Key_R:
                self.finish_token_rotation()
                event.accept()
                return

        # WASD: необязательное движение токена с клавиатуры. Проверяем до
        # инструментов и до рывка: пока режим включён, W/A/S/D принадлежат
        # ходу токена, а не кисти или меню. Повтор клавиши от системы
        # игнорируем — шаги ведёт таймер, иначе токен побежал бы вдвое быстрее.
        if self.wasd_movement and not self.rotating_token_id:
            direction = WASD_DIRECTIONS.get(key)
            if direction is not None and not (mods & (Qt.ControlModifier
                                                      | Qt.AltModifier
                                                      | Qt.ShiftModifier)):
                if key not in self._wasd_keys:
                    self._wasd_keys.append(key)
                if not event.isAutoRepeat():
                    self.wasd_step(direction)
                    self._ensure_wasd_timer()
                event.accept()
                return

        # Стены: Enter завершает ломаную, Esc бросает недорисованную.
        # Проверяем раньше инструментов рисования: пока идёт расстановка
        # комнаты, Enter не должен сменить кисть.
        if self._wall_draft or self._wall_rect_start is not None:
            if (mods & Qt.ControlModifier) and key == Qt.Key_Z:
                # Незаконченная ломаная: Ctrl+Z снимает последнюю вершину,
                # а не откатывает готовую стену из истории окна. Если
                # вершин нет (рисуется только рамка) — не перехватываем
                # клавишу, пусть её обработает общая отмена ниже.
                if self.undo_wall_point():
                    self.show_hint("Вершина убрана")
                    event.accept()
                    return
            if key in (Qt.Key_Return, Qt.Key_Enter):
                self.finish_wall_draft(closed=False)
                return
            # Esc бросает недорисованную стену в handle_escape() — там он
            # проверяется до инструментов рисования.

        # Delete/Backspace убирает выбранную надпись. Пока идёт набор,
        # клавиши принадлежат полю правки и сюда не попадают.
        if (key in (Qt.Key_Delete, Qt.Key_Backspace)
                and not self._editing_text_id
                and self.drawing_mode in ('text', 'move')
                and self.selected_text_id):
            if self.delete_selected_text():
                return

        # Вся цепочка Esc (надпись, взведённое заклинание, калибровка,
        # шаблон, линейка, фигура, штрих, подсветка хода) — в handle_escape().
        if (mods & Qt.ControlModifier) and key == Qt.Key_Z:
            self.undo_drawing(emit=True)
            return

        if (mods == Qt.NoModifier and key == Qt.Key_Q
                and event.key() != Qt.Key_Q):
            # Запасной путь для русской раскладки: физическая Q присылает
            # «й», а QShortcut с кириллицей на практике не срабатывает.
            # Латинскую Q оставляем QShortcut — иначе режим переключился бы
            # дважды, если Qt успеет обработать и шорткат, и это событие.
            self.quick_attack_toggle_requested.emit()
            event.accept()
            return
        if (mods == Qt.NoModifier and key == Qt.Key_C
                and event.key() != Qt.Key_C):
            # C/С — рывок. Для кириллицы тот же запасной путь, что у Q:
            # если QShortcut не поймал «с», холст сделает это сам.
            self.dash_action()
            event.accept()
            return
        if mods == Qt.NoModifier and key == Qt.Key_M:
            self.start_ruler()
            return
        if mods == Qt.NoModifier and key == Qt.Key_R:
            # R больше не включает квадрат: эта клавиша теперь крутит токен.
            # Квадрат остаётся на панели инструментов рисования.
            self.toggle_token_rotation()
            return
        if mods == Qt.NoModifier and self.special_attack_hotkeys:
            # Хоткей особой атаки. Букву берём из нормализованного ключа,
            # а не из текста события: в русской раскладке Q приходит как
            # «й», и назначенная в карточке K не срабатывала как «л».
            # Занятые клавиши стола (Q/С/R/M/N и кисти) сюда не попадают:
            # их отсекает shared.special_attacks.hotkey_conflict.
            if Qt.Key_A <= key <= Qt.Key_Z or Qt.Key_0 <= key <= Qt.Key_9:
                pressed = chr(key)
            else:
                pressed = ""
            if len(pressed) == 1 and pressed in self.special_attack_hotkeys:
                token_id, attack_id = self.special_attack_hotkeys[pressed]
                self.special_attack_hotkey_requested.emit(str(token_id),
                                                          str(attack_id))
                event.accept()
                return
        # Del/X при открытой вкладке «Освещение» убирает выбранный на
        # холсте источник: окно удаляет его и обновляет список. Проверка
        # после надписей и хоткеев существ: назначенная клавиша мастера
        # и правка текста важнее уборки света.
        if (key in (Qt.Key_Delete, Qt.Key_X) and self.light_editing
                and not self._editing_text_id and self.selected_light_id):
            self.light_delete_requested.emit([self.selected_light_id])
            event.accept()
            return
        shortcuts = {
            Qt.Key_B: 'brush',
            Qt.Key_L: 'line',
            # Круг — на O, а не на C: C теперь рывок (как и D раньше жила
            # на рывке, пока её не забрал WASD).
            Qt.Key_O: 'circle',
            Qt.Key_F: 'polygon',
            Qt.Key_E: 'eraser',
            # T — текст, как в Photoshop. Перемещение — Н ("хвать рукой"),
            # а не V: клавиша V уже возвращает обычный курсор.
            Qt.Key_T: 'text',
            Qt.Key_H: 'move',
        }
        if mods == Qt.NoModifier and key in shortcuts:
            self.start_drawing(shortcuts[key])
            return
        if mods == Qt.NoModifier and key == Qt.Key_Tab:
            # Tab центрирует карту. Фокус при этом не переключаем — иначе Qt
            # уводит его на следующий виджет и до обработчика дело не доходит.
            self.fit_map_to_screen()
            return
        if mods == Qt.NoModifier and key in (Qt.Key_Delete, Qt.Key_Backspace):
            self.delete_selection()
            return
        if mods == Qt.NoModifier and key == Qt.Key_V:
            self.stop_drawing()
            return
        if mods == Qt.NoModifier and key in (Qt.Key_BracketLeft, Qt.Key_BracketRight):
            step = -2.0 if key == Qt.Key_BracketLeft else 2.0
            self.set_brush_size(self.brush_size + step)
            return

        super().keyPressEvent(event)

    # ------------------------------------------------------------------
    # Мышь
    # ------------------------------------------------------------------
    def wheelEvent(self, event: QWheelEvent):
        delta = event.angleDelta().y()
        if delta == 0:
            return
        pos = event.pos()
        before = self.screen_to_world(pos.x(), pos.y())
        factor = 1.15 if delta > 0 else 1 / 1.15
        self.scale = max(self.min_scale, min(self.max_scale, self.scale * factor))
        after = self.screen_to_world(pos.x(), pos.y())
        self.offset_x += (after[0] - before[0]) * self.scale
        self.offset_y += (after[1] - before[1]) * self.scale
        # Зум меняет экранный размер кисти — курсор должен расти вместе с ней
        self._apply_tool_cursor()
        # Поле правки надписи живёт в экранных координатах: при зуме его
        # нужно переставить, иначе оно останется от старого масштаба.
        self.update_text_editor_geometry()
        self.update()

    def mousePressEvent(self, event: QMouseEvent):
        """Клик по холсту с правильным приоритетом слоёв.

        Порядок: панорама (СКМ) -> меню (ПКМ) -> рисование -> стрелка/тело
        объекта выше токенов -> ТОКЕНЫ -> ручки выбранного объекта ->
        объекты ниже токенов -> ручки выбранной карты -> перетаскивание
        карты -> пустое место (снять выделение).

        Токены стоят выше ручек карты намеренно: если токен лежит у угла карты,
        клик по нему должен тащить токен, а не тянуть угол карты.
        """
        wx, wy = self.screen_to_world(event.x(), event.y())

        # Клик в режиме поворота — это «смотрю туда»: ставим взгляд и
        # фиксируем его вместо того, чтобы начать тащить токен по карте.
        if self.rotating_token_id:
            if event.button() == Qt.RightButton:
                self.cancel_token_rotation()
            else:
                self.rotate_token_towards(wx, wy)
                self.finish_token_rotation()
            return

        # Факел под курсором важнее инструмента стен: с «Точками» метку
        # иначе вообще нельзя было взять мышью — клик уходил в вершину
        # стены. Считаем только попадание по самому рисунку иконки: мимо
        # неё инструмент стен работает как раньше.
        if (self.light_editing and self.is_dm
                and event.button() == Qt.LeftButton):
            light = self.light_at_screen(event.x(), event.y())
            if light is not None:
                self._start_light_drag(light, wx, wy)
                return

        # Инструмент стен перехватывает клик раньше токенов и света: пока
        # он выбран, ЛКМ строит и правит стены, а не тащит фигурку.
        if self.is_dm and self.wall_tool and event.button() == Qt.LeftButton:
            if self.handle_wall_press(wx, wy):
                return

        # Метка источника света: тащим её, пока открыта вкладка освещения.
        if self.light_editing and event.button() == Qt.LeftButton:
            light = self.light_at(wx, wy)
            if light is not None:
                self._start_light_drag(light, wx, wy)
                return
            # Пустой клик по карте снимает выделение источника.
            if self.selected_light_id is not None:
                self.selected_light_id = None
                self.update()

        # Выбор цели заклинания перехватывает клики раньше любых слоёв:
        # пока заклинание взведено, ЛКМ выбирает цель, ПКМ отменяет.
        if (self.target_pick_mode
                and event.button() in (Qt.LeftButton, Qt.RightButton)):
            if event.button() == Qt.RightButton:
                self.cancel_target_pick()
                self.show_hint('выбор цели отменён')
                return
            token_id = self.get_token_at(wx, wy)
            if token_id:
                self._finish_target_pick(token_id)
            else:
                self.show_hint('Кликните по токену-цели')
            return

        if event.button() == Qt.MiddleButton:
            self.dragging_map_view = True
            self.drag_start_pos = QPointF(event.pos())
            self.setCursor(Qt.ClosedHandCursor)
            return

        if event.button() == Qt.RightButton:
            # ПКМ по точке в правке стен убирает вершину: так же привычно,
            # как правка контура в редакторе, и не нужно лезть в меню.
            if self.is_dm and self.wall_tool == "edit":
                point = self.wall_point_at(wx, wy)
                if point is not None:
                    self.delete_wall_point(*point)
                    return
            # Ломаная стены по точкам на ПКМ закрывается, как на Esc: мастер
            # не ищет клавишу, пока ставит комнату.
            if self.wall_tool == "points" and self._wall_draft:
                self.finish_wall_draft(closed=False)
                return
            # Шаблон области ПКМ закрывает, а не подтверждает: то же
            # действие, что Esc, — привычнее и ближе к курсору.
            if self.drawing_mode == 'template':
                self.cancel_template()
                self.show_hint('шаблон отменён')
                return
            try:
                if self.drawing_mode:
                    self.finish_drawing()
                else:
                    self.show_context_menu(event.pos(), wx, wy)
            except RuntimeError:
                # Обработчики Qt-сигналов могут сменить карту/закрыть холст
                # синхронно с закрытием меню; игнорируем только уничтожение C++-виджета.
                pass
            return

        if event.button() != Qt.LeftButton:
            return

        # Калибровка сетки перехватывает клики раньше остальных слоёв.
        if self._grid_calibrating:
            self._handle_calibration_click(wx, wy)
            return

        if self.drawing_mode == 'template':
            self._handle_template_press(wx, wy)
            return

        if self.drawing_mode == 'ruler':
            # Линейка перехватывает клик: начало ставится первым нажатием,
            # конец тянется за курсором.
            self._handle_ruler_press(wx, wy)
            return

        if self.drawing_mode == 'polygon':
            # Фигура по точкам: каждый клик добавляет вершину. Клик по первой
            # точке замыкает контур и завершает штрих.
            if not self.drawing_points:
                self.drawing_points = [(wx, wy)]
                self._preview_points = []
                self.update()
                return
            first_x, first_y = self.drawing_points[0]
            reach = self.design(POLYGON_CLOSE_RADIUS_PX)
            if (math.hypot(wx - first_x, wy - first_y) <= reach
                    and len(self.drawing_points) >= 3):
                self.finish_drawing()
                return
            self.drawing_points.append((wx, wy))
            self._preview_points = []
            self.update()
            return



        # Надписи: инструмент «Текст» создаёт/правит, «Перемещение» тащит.
        # Стоит ДО общего рисования: иначе клик по надписи добавлял бы
        # точку штриха и создавал пустой мазок.
        if self.drawing_mode in ('text', 'move'):
            self._handle_text_press(wx, wy)
            return

        if self.drawing_mode:
            # Кисть/линия/ластик накапливают точки в движении, фигуры — две
            # точки (начало и текущий угол).
            if not self.drawing_points:
                self.drawing_points = [(wx, wy)]
            else:
                self.drawing_points.append((wx, wy))
            self._preview_points = []
            self.update()
            return

        # 0. Объекты карты (только ДМ). Стрелка настроек ловится раньше
        # тела объекта, а объекты «выше токенов» — раньше самих токенов:
        # иначе крышу, лежащую на персонаже, нельзя было бы схватить.
        if self.is_dm:
            # Ручка поворота живёт снаружи объекта, но проверяем её первой:
            # иначе она могла бы попасть под клик по другому слою.
            if self.hit_test_object_rotation_handle(event.pos()):
                self._start_object_rotation(self.selected_object_id, wx, wy)
                return
            # Углы выбранного объекта проверяем раньше его тела: угол лежит
            # внутри прямоугольника, и без этого вместо ресайза начинался
            # бы драг всего объекта.
            object_handle = self.hit_test_object_handle(event.pos())
            if object_handle:
                self.resizing_object = True
                self.moving_object = False
                self.object_resize_handle = object_handle
                sel = self.objects.get(self.selected_object_id)
                if sel is not None:
                    self._object_drag_before = self._object_payload(sel)
                return
            above_id = self.get_object_at(wx, wy, above=True)
            if above_id:
                self._start_object_drag(above_id, wx, wy)
                return

        # 1. ТОКЕНЫ — самый приоритетный слой при выборе на холсте.
        token_id = self.get_token_at(wx, wy)

        # Взведённая быстрая атака: клик по другому токену — удар.
        # Удар одноразовый: режим снимается сразу, поэтому второй клик
        # снова выбирает токен, а не бьёт второй раз непонятно чем.
        if self.quick_attack_mode:
            if not self.selected_token:
                self.set_quick_attack_mode(False)
            elif not token_id:
                # Клик мимо цели — отмена, как Esc.
                self.set_quick_attack_mode(False)
                return
            elif token_id != self.selected_token:
                self.token_quick_attack_requested.emit(self.selected_token,
                                                       token_id)
                self.set_quick_attack_mode(False)
                return

        # В бою клик по пустому месту — это либо ход в подсвеченную клетку,
        # либо отказ от хода. Клик по токену обрабатывается ниже.
        if not token_id and self.chess_token_id:
            if self._try_chess_move(wx, wy):
                return
            self.chess_token_id = None
            self.setCursor(Qt.ArrowCursor)
            self.update()

        if token_id:
            token = self.tokens[token_id]
            if combat_rules.death_save_state(
                    getattr(token, 'death_saves', None))['dead']:
                # Мёртвого не тащат, но выбрать можно: иначе не открыть
                # карточку и кнопку воскрешения.
                self.selected_tokens = set()
                self.dragging_token = None
                self.dragging_tokens = []
                self.selected_token = token_id
                self.token_selected.emit(token_id)
                self.setCursor(Qt.ArrowCursor)
                self.update()
                return
            if self._token_in_combat(token) and self._can_control_token(token):
                # В бою токен не тащится мышью: клик выбирает его и
                # показывает клетки хода в радиусе скорости.
                self.selected_tokens = set()
                self.dragging_token = None
                self.dragging_tokens = []
                self.selected_token = token_id
                self.token_selected.emit(token_id)
                allowed, why = self._turn_allows_move(token)
                if not allowed:
                    self.chess_token_id = None
                    self.movement_blocked.emit(why)
                    self.setCursor(Qt.ArrowCursor)
                    self.update()
                    return
                self._arm_chess_move(token_id)
                if not self.chess_cells():
                    # Подсветки нет — говорим почему, иначе клик выглядит
                    # как «ничего не произошло».
                    movable, why = conditions_rules.can_move(
                        getattr(token, 'conditions', None),
                        hp=getattr(token, 'hp', None))
                    if not movable:
                        self.movement_blocked.emit(
                            f"«{token.name}» не может двигаться: {why}")
                    elif self._token_speed_feet(token) <= 0:
                        self.movement_blocked.emit(
                            f"«{token.name}»: скорость 0")
                self.setCursor(Qt.PointingHandCursor)
                self.update()
                return
            if self.chess_token_id:
                # Вне боя подсветка хода не нужна.
                self.chess_token_id = None
                self.update()
            if ((self.is_dm or token.owner_id == self.player_id)
                    and not self.is_token_movable(token)):
                # Чужой ход важнее состояний: даже полностью дееспособного
                # персонажа нельзя сдвинуть, пока очередь не дошла до него.
                allowed, turn_why = self._turn_allows_move(token)
                if not allowed:
                    self.selected_tokens = set()
                    self.dragging_token = None
                    self.dragging_tokens = []
                    self.selected_token = token_id
                    self.token_selected.emit(token_id)
                    self.movement_blocked.emit(turn_why)
                    self.setCursor(Qt.ArrowCursor)
                    self.update()
                    return
                # Схваченный/опутанный/парализованный выбирается, но не
                # тащится — никем, включая мастера: скорость 0 это правило,
                # а не украшение.
                can_move, why = conditions_rules.can_move(
                    getattr(token, 'conditions', None),
                    hp=getattr(token, 'hp', None))
                if not can_move:
                    self.selected_tokens = set()
                    self.dragging_token = None
                    self.dragging_tokens = []
                    self.selected_token = token_id
                    self.token_selected.emit(token_id)
                    self.movement_blocked.emit(f"«{token.name}» не может двигаться: {why}")
                    self.setCursor(Qt.ArrowCursor)
                    self.update()
                    return
            if self.is_token_movable(token):
                # Схватили токен, который уже в группе выделения -> тащим всю
                # группу. Иначе выделение сбрасывается и тянем только его.
                self._token_drag_trail = []
                self._token_move_path = []
                self._token_drag_trails = {}
                if token_id in self.selected_tokens and len(self.selected_tokens) > 1:
                    self.dragging_tokens = self._movable_selected_ids()
                    self._token_drag_trails = {
                        tid: [(self.tokens[tid].x, self.tokens[tid].y)]
                        for tid in self.dragging_tokens}
                    self.group_drag_offsets = {
                        tid: (self.tokens[tid].x - wx, self.tokens[tid].y - wy)
                        for tid in self.dragging_tokens}
                    self._group_magnet_anchor = (wx, wy)
                    self._group_magnet_start = {
                        tid: (self.tokens[tid].x, self.tokens[tid].y)
                        for tid in self.dragging_tokens}
                    self.dragging_token = None
                    self._drag_snapshot = {
                        'kind': 'tokens',
                        'positions': {tid: (self.tokens[tid].x, self.tokens[tid].y)
                                      for tid in self.dragging_tokens}}
                else:
                    self.dragging_tokens = []
                    self.group_drag_offsets = {}
                    self._group_magnet_anchor = None
                    self._group_magnet_start = {}
                    self.dragging_token = token_id
                    self._token_drag_trail = [(token.x, token.y)]
                    self.selected_tokens = set()
                    self.selected_token = token_id
                    self._drag_snapshot = {
                        'kind': 'tokens',
                        'positions': {token_id: (token.x, token.y)}}
                if self.map_is_selected:
                    self.map_is_selected = False
                    self.map_deselected.emit()
                self.token_selected.emit(token_id)
                self.setCursor(Qt.ClosedHandCursor)
                self.update()
                return

        # 2. Объекты «ниже токенов»: если токена здесь нет, клик ихний.
        if self.is_dm:
            object_handle = self.hit_test_object_handle(event.pos())
            if object_handle:
                self.resizing_object = True
                self.moving_object = False
                self.object_resize_handle = object_handle
                sel = self.objects.get(self.selected_object_id)
                if sel is not None:
                    self._object_drag_before = self._object_payload(sel)
                return
            below_id = self.get_object_at(wx, wy, above=False)
            if below_id:
                self._start_object_drag(below_id, wx, wy)
                return

        # 3. Ручки изменения размера — только у выбранной карты.
        if self.is_dm and self.map_is_selected:
            handle = self.hit_test_handle(event.pos())
            if handle:
                self.resizing_map = True
                self.resize_handle = handle
                if self.current_map:
                    m = self.current_map
                    self._drag_snapshot = {
                        'kind': 'map_geometry',
                        'geometry': {'map_id': m.id, 'pos_x': m.pos_x,
                                     'pos_y': m.pos_y, 'width': m.width,
                                     'height': m.height}}
                return

        # 4. Перетаскивание карты — только когда она выбрана в левой панели.
        rect = self.map_rect_world()
        if self.is_dm and self.map_is_selected and rect and rect.contains(wx, wy):
            # Если кнопку отпустят без движения, mouseReleaseEvent сочтёт это
            # кликом по пустому месту и снимет выделение.
            self.moving_map = True
            self._map_drag_moved = False
            self.map_drag_offset = QPointF(wx - self.current_map.pos_x,
                                           wy - self.current_map.pos_y)
            m = self.current_map
            self._drag_snapshot = {
                'kind': 'map_geometry',
                'geometry': {'map_id': m.id, 'pos_x': m.pos_x, 'pos_y': m.pos_y,
                             'width': m.width, 'height': m.height}}
            self.setCursor(Qt.SizeAllCursor)
            return

        # 5. Пустое место — начинаем выделение рамкой.
        # Рамка заменяет прежнее «просто снять выделение»: клик без движения
        # по-прежнему очищает выделение (ение (см. mouseReleaseEvent), а протяжка
        # выбирает все токены внутри прямоугольника.
        was_selected = (self.selected_token is not None or self.map_is_selected
                        or bool(self.selected_tokens)
                        or self.selected_object_id is not None)
        self.selected_token = None
        self.selected_object_id = None
        self.dragging_token = None
        self.moving_map = False
        self.resizing_map = False
        self.resize_handle = None
        self.moving_object = False
        self.resizing_object = False
        self.rotating_object = False
        self.object_resize_handle = None
        self._rotate_start_angle = None
        self.map_is_selected = False
        self.selected_tokens.clear()
        self.setCursor(Qt.CrossCursor)
        if was_selected:
            self.token_deselected.emit()
            self.map_deselected.emit()
        # Рамку включаем всем: игрок тоже выделяет свои токены и двигает их
        # группой. Чужие токены в выделение не попадут (см. _select_tokens_in_rect).
        self.rubber_origin = QPointF(wx, wy)
        self.rubber_current = QPointF(wx, wy)
        self.rubber_active = True
        self.update()

    def _handle_text_press(self, wx: float, wy: float):
        """Клик по холсту инструментом текста или перемещения."""
        item = self.text_at(wx, wy)
        if item is None:
            if self.drawing_mode == 'text':
                # Клик по пустому месту — новая надпись, как в Photoshop.
                self.begin_text_edit(None, wx, wy)
            else:
                self._set_selected_text(None)
            return
        self._set_selected_text(item['id'])
        if self.drawing_mode == 'text':
            self.begin_text_edit(item['id'])
            return
        # Держим за точку захвата: надпись не прыгает под курсор.
        self._text_drag = {
            'id': item['id'],
            'dx': wx - float(item.get('x') or 0.0),
            'dy': wy - float(item.get('y') or 0.0),
        }
        self.setCursor(Qt.ClosedHandCursor)

    def mouseDoubleClickEvent(self, event: QMouseEvent):
        """Двойной клик по надписи — правка.

        Только инструментом «Текст»: у «Перемещения» задача — таскать
        надписи по карте, а не менять их содержимое.
        """
        if (event.button() == Qt.LeftButton
                and self.drawing_mode == 'text'):
            wx, wy = self.screen_to_world(event.x(), event.y())
            item = self.text_at(wx, wy)
            if item is not None:
                self._set_selected_text(item['id'])
                self.begin_text_edit(item['id'])
                return
        # Двойной клик по отрезку в правке точек — новая вершина стены.
        if (event.button() == Qt.LeftButton and self.is_dm
                and self.wall_tool == "edit"):
            wx, wy = self.screen_to_world(event.x(), event.y())
            hit = self.wall_hit_test(wx, wy)
            if hit is not None and self.wall_point_at(wx, wy) is None:
                wall, index, at, _distance = hit
                wx, wy = self.snap_wall_point(wx, wy)
                self.insert_wall_point(wall["id"], index, wx, wy)
                return
        super().mouseDoubleClickEvent(event)

    def leaveEvent(self, event):
        """Курсор ушёл с холста: подсказка стены гаснет вместе с ним.

        Иначе пунктир от последней вершины оставался висеть до края
        экрана — выглядело так, будто линия идёт из пустоты.
        """
        if (self._wall_draft_cursor is not None or self._wall_hover is not None
                    or self._wall_hover_point is not None
                    or self._wall_hover_opening is not None):
            self._wall_draft_cursor = None
            self._wall_hover = None
            self._wall_hover_point = None
            self._wall_hover_opening = None
            self.update()
        super().leaveEvent(event)

    def mouseMoveEvent(self, event: QMouseEvent):
        wx, wy = self.screen_to_world(event.x(), event.y())

        # Режим поворота токена: мышь вокруг токена задаёт направление
        # взгляда. Остальные жесты мыши в это время не работают, чтобы
        # случайно не сдвинуть токен вместо поворота.
        if self.rotating_token_id:
            self.rotate_token_towards(wx, wy)
            return

        if self._dragging_light_id:
            light = next((item for item in self.lighting_lights()
                          if item["id"] == self._dragging_light_id), None)
            if light is not None and not light.get("locked"):
                dx, dy = self._light_drag_offset
                self.update_light(light["id"], notify=False,
                                  x=wx - dx, y=wy - dy)
            return

        # Стены: тянем точку или показываем, где встанет проём.
        if self.is_dm and self.wall_tool:
            if self._wall_drag_point is not None:
                wall_id, index = self._wall_drag_point
                px, py = self.snap_wall_point(wx, wy)
                self.move_wall_point(wall_id, index, px, py, notify=False)
                return
            if self._wall_rect_start is not None:
                self._wall_rect_current = self.snap_wall_point(wx, wy)
                self.update()
                return
            if self.wall_tool == "points":
                # Подсказка «где встанет вершина» нужна и до первого клика:
                # раньше точка появлялась только после нажатия.
                # Вне карты подсказки нет совсем: иначе пунктир тянулся к
                # самому краю экрана (а при перетаскивании — и за холст).
                self._wall_draft_cursor = (self.snap_wall_point(wx, wy)
                                           if self.point_on_map(wx, wy)
                                           else None)
                self.update()
                return
            if self._wall_draft:
                self._wall_draft_cursor = (self.snap_wall_point(wx, wy)
                                           if self.point_on_map(wx, wy)
                                           else None)
                self.update()
                return
            if self.wall_tool == "delete":
                # Ластик: подсвечиваем вершину или створку под курсором,
                # чтобы было видно, что именно удалит клик — точек в этом
                # режиме нет.
                point = self.wall_point_at(wx, wy)
                opened = None if point is not None else self.opening_hit_test(
                    wx, wy)
                opening_id = opened[1]["id"] if opened is not None else None
                if (point != self._wall_hover_point
                        or opening_id != self._wall_hover_opening):
                    self._wall_hover_point = point
                    self._wall_hover_opening = opening_id
                    self.update()
            elif self.wall_tool in ("window", "door"):
                hit = self.wall_hit_test(wx, wy)
                self._wall_hover = hit
                self.update()

        # Взведённая цель: кольцо следует за токеном под курсором.
        if self.target_pick_mode:
            self.set_target_pick_hover(self.get_token_at(wx, wy))

        # Рамка выделения: тянем, пока зажата левая кнопка
        if self.rubber_active:
            self.rubber_current = QPointF(wx, wy)
            self.update()
            return

        if self.drawing_mode == 'template' and self.template_origin is not None:
            self.template_aim = (wx, wy)
            self.update()
            return

        if self.ruler_active:
            self._handle_ruler_move(wx, wy)
            return

        if self.dragging_map_view:
            delta = event.pos() - self.drag_start_pos
            self.offset_x += delta.x()
            self.offset_y += delta.y()
            self.drag_start_pos = QPointF(event.pos())
            self.update_text_editor_geometry()
            self.update()
            return

        # Объект тащим/растягиваем раньше карты: это отдельный слой.
        if self.rotating_object and self.selected_object_id:
            self.apply_object_rotation(wx, wy)
            return

        if self.moving_object and self.selected_object_id:
            obj = self.objects.get(self.selected_object_id)
            if obj is not None and not obj.locked:
                obj.x = wx - self._object_drag_offset.x()
                obj.y = wy - self._object_drag_offset.y()
                if self._roofs_exist():
                    self._ensure_anim_timer()
                self.update()
            return

        if self.resizing_object and self.selected_object_id:
            self.apply_object_resize(wx, wy)
            return

        if self.moving_map and self.current_map:
            self.current_map.pos_x = wx - self.map_drag_offset.x()
            self.current_map.pos_y = wy - self.map_drag_offset.y()
            self._map_drag_moved = True
            self.update()
            return

        if self.resizing_map and self.current_map:
            self.apply_resize(wx, wy)
            return

        # Группа, выделенная рамкой: двигаем все токены вместе, сохраняя их
        # взаимное расположение через сохранённые смещения.
        if self.dragging_tokens:
            if self._group_magnet_anchor is not None:
                self._drag_token_cluster(wx, wy)
                return
            for tid in self.dragging_tokens:
                ox, oy = self.group_drag_offsets.get(tid, (0.0, 0.0))
                tx, ty = wx + ox, wy + oy
                if self.snap_active():
                    tx, ty = self.snap_to_grid(tx, ty)
                self.update_token_position(tid, tx, ty)
            return

        if self._text_drag:
            item = self.text_by_id(self._text_drag.get('id'))
            if item is not None:
                item['x'] = wx - float(self._text_drag.get('dx') or 0.0)
                item['y'] = wy - float(self._text_drag.get('dy') or 0.0)
                self.update()
            return

        if self.dragging_token:
            if self.snap_active():
                wx, wy = self.snap_to_grid(wx, wy)
            self.update_token_position(self.dragging_token, wx, wy)
            return

        # Рисование в процессе: кисть/линия/ластик — тянем точки,
        # фигуры — тянем только вторую точку.
        if self.drawing_mode and self.drawing_points:
            mode = self.drawing_mode
            if mode in ('brush', 'eraser'):
                last = self.drawing_points[-1]
                if math.hypot(wx - last[0], wy - last[1]) >= 1.5:
                    self.drawing_points.append((wx, wy))
            elif mode in ('line', 'circle', 'square'):
                self._preview_points = [(wx, wy)]
            elif mode == 'polygon':
                # Свободная вершина под курсором: видно, куда встанет
                # следующая точка и как пройдёт ребро.
                self._preview_points = [(wx, wy)]
            self.update()
            return

        cursors = {'nw': Qt.SizeFDiagCursor, 'se': Qt.SizeFDiagCursor,
                   'ne': Qt.SizeBDiagCursor, 'sw': Qt.SizeBDiagCursor}
        # Открытая вкладка освещения: над факелом курсор говорит, что метку
        # можно взять и тащить. Без этого источник выглядел картинкой.
        if self.light_editing and self.is_dm:
            hovered = self.light_at_screen(event.x(), event.y())
            if hovered is not None:
                self.setCursor(Qt.ClosedHandCursor
                               if hovered.get("locked")
                               else Qt.OpenHandCursor)
                return
        if self.is_dm:
            if self.hit_test_object_rotation_handle(event.pos()):
                self.setCursor(Qt.CrossCursor)
                return
            object_handle = self.hit_test_object_handle(event.pos())
            if object_handle:
                self.setCursor(cursors[object_handle])
                return
            if (self.get_object_at(wx, wy, above=True)
                    or self.get_object_at(wx, wy, above=False)):
                self.setCursor(Qt.OpenHandCursor)
                return
        if self.is_dm and self.map_is_selected:
            handle = self.hit_test_handle(event.pos())
            if handle:
                self.setCursor(cursors[handle])
                return
        # Курсор вернулся с ручки/объекта на пустое место: иначе он так и
        # остаётся «растягивающим» и вводит в заблуждение. У инструмента —
        # свой курсор (у кисти это кольцо по толщине мазка).
        if self.quick_attack_mode:
            self.setCursor(Qt.CrossCursor)
        elif self.drawing_mode:
            self._apply_tool_cursor()
        else:
            self.setCursor(Qt.ArrowCursor)

    def mouseReleaseEvent(self, event: QMouseEvent):
        mode_before = self.drawing_mode

        if event.button() == Qt.MiddleButton and self.dragging_map_view:
            self.dragging_map_view = False
            self.setCursor(Qt.ArrowCursor)
            return

        if event.button() != Qt.LeftButton:
            return

        if self._dragging_light_id:
            # Источник перетащен: один список уходит всем, как и при
            # добавлении, вместе со снимком «до» — для истории отмены.
            self._dragging_light_id = None
            before = self._light_drag_before
            self._light_drag_before = None
            self._emit_lights_changed(before)
            self.update()
            return

        # Стены: отпустили кнопку — фиксируем прямоугольник и точку.
        if self.is_dm and (self._wall_rect_start is not None
                            or self._wall_drag_point is not None):
            if self._wall_rect_start is not None and self._wall_rect_current:
                start = self._wall_rect_start
                end = self._wall_rect_current
                self._wall_rect_start = None
                self._wall_rect_current = None
                self.add_wall_rect(start[0], start[1], end[0], end[1])
                self.update()
                return
            if self._wall_drag_point is not None:
                self._wall_drag_point = None
                before = self._wall_drag_before
                self._wall_drag_before = None
                self._emit_walls_changed(before)
                self.update()
                return

        if self._text_drag:
            # Перенос закончен: координаты уходят одним сообщением, а не
            # десятком на каждое движение мыши.
            drag = self._text_drag
            self._text_drag = None
            item = self.text_by_id(drag.get('id'))
            self._apply_tool_cursor()
            if item is not None:
                self.edit_text(str(item['id']),
                               {'x': item['x'], 'y': item['y']})
            return

        if self.drawing_mode == 'ruler':
            self._handle_ruler_release()
            return

        # Штрих закрывается отпусканием кнопки: нажал-провёл-отпустил = один
        # штрих. Это одинаково для кисти, линии и фигур — все идут в растр.
        if (self.drawing_mode in RASTER_TOOLS and self.drawing_mode != 'polygon'
                and self.drawing_points):
            # Кисть, линия и фигуры по двум точкам завершаются отпусканием.
            # «Фигура» — нет: она набирается кликами, иначе первый клик сразу
            # закрывал бы контур.
            self.finish_drawing()
            if self.drawing_mode is None:
                # после завершения штриха инструмент остаётся активным
                self.drawing_mode = mode_before
                # ...а значит и курсор нужно вернуть к его виду
                self._apply_tool_cursor()
            return

        # Рамка выделения: собираем токены, попавшие внутрь прямоугольника
        if self.rubber_active:
            self.rubber_active = False
            rect = None
            if self.rubber_origin and self.rubber_current:
                rect = QRectF(self.rubber_origin, self.rubber_current).normalized()
            self.rubber_origin = None
            self.rubber_current = None
            self.setCursor(Qt.ArrowCursor)
            if rect is not None and (rect.width() > 3 or rect.height() > 3):
                self._select_tokens_in_rect(rect)
            self.update()
            return

        # Отпустили ручку поворота: угол уходит одним сообщением вместе
        # с прежним значением для Ctrl+Z.
        if self.rotating_object and self.selected_object_id:
            obj = self.objects.get(self.selected_object_id)
            self.rotating_object = False
            self._rotate_start_angle = None
            self.setCursor(Qt.ArrowCursor)
            if obj is not None and not obj.locked:
                payload = self._object_payload(obj)
                if self._object_drag_before:
                    payload['before'] = self._object_drag_before
                self.object_updated.emit(payload)
            self._object_drag_before = None
            self.update()
            return

        # Отпустили объект: геометрию рассылаем одним сообщением.
        if self.moving_object and self.selected_object_id:
            obj = self.objects.get(self.selected_object_id)
            self.moving_object = False
            self.setCursor(Qt.ArrowCursor)
            if obj is not None and not obj.locked:
                payload = self._object_payload(obj)
                if self._object_drag_before:
                    payload['before'] = self._object_drag_before
                self.object_updated.emit(payload)
            self._object_drag_before = None
            self.update()
            return

        if self.resizing_object and self.selected_object_id:
            obj = self.objects.get(self.selected_object_id)
            self.resizing_object = False
            self.object_resize_handle = None
            self.setCursor(Qt.ArrowCursor)
            if obj is not None and not obj.locked:
                payload = self._object_payload(obj)
                if self._object_drag_before:
                    payload['before'] = self._object_drag_before
                self.object_updated.emit(payload)
            self._object_drag_before = None
            self.update()
            return

        # Отпустили группу: отправляем все перемещения одним сообщением,
        # чтобы остальные участники применили их разом, а не по одному.
        if self.dragging_tokens:
            # Размагнитить группу: пока кнопка была зажата, токены шли
            # кучкой вокруг курсора (так они проходят дверь), а отпустили —
            # снова встают своей расстановкой вокруг точки броска.
            if self._group_magnet_anchor is not None:
                wx, wy = self.screen_to_world(event.x(), event.y())
                self._release_token_cluster(wx, wy)
            self._group_magnet_anchor = None
            self._group_magnet_start = {}
            ends = [{'token_id': tid, 'x': self.tokens[tid].x,
                     'y': self.tokens[tid].y}
                    for tid in self.dragging_tokens if tid in self.tokens]
            # Каждый токен идёт своим путём: по прямой группа упёрлась бы в
            # стену и вернулась назад, хотя дверь рядом и все обошли её.
            paths = {}
            moved = []
            for offer in ends:
                tid = offer['token_id']
                path = self._compress_drag_trail(
                    self._token_drag_trails.get(tid), self.current_map)
                if len(path) > 2:
                    paths[tid] = [list(point) for point in path]
                    moved.extend({'token_id': tid, 'x': point[0],
                                  'y': point[1]} for point in path[1:])
                else:
                    moved.append(offer)
            self._token_drag_trails = {}
            snapshot = self._drag_snapshot
            self.dragging_tokens = []
            self.group_drag_offsets = {}
            self.setCursor(Qt.ArrowCursor)
            self._drag_snapshot = None
            if moved:
                self.tokens_moved.emit(moved)
                if snapshot:
                    payload = {
                        'kind': 'tokens',
                        'before': snapshot.get('positions', {}),
                        'after': {m['token_id']: (m['x'], m['y'])
                                  for m in ends},
                    }
                    if paths:
                        payload['path'] = paths
                    self.edit_finished.emit(payload)
            self.update()
            return

        if self.dragging_token:
            token = self.tokens[self.dragging_token]
            snapshot = self._drag_snapshot
            # Путь уходит в окно вместе с концом жеста: прямая от начала к
            # концу может резать стену, хотя фишку обвели кругом.
            path = self._compress_drag_trail(self._token_drag_trail,
                                             self.current_map)
            self._token_drag_trail = []
            # Сигнал забирает путь и очищает поле — поэтому запоминаем его
            # ещё до отправки, чтобы он же попал в запись истории.
            self._token_move_path = path
            self.token_moved.emit(self.dragging_token, token.x, token.y)
            self._token_move_path = []
            if snapshot:
                before = snapshot.get('positions', {}).get(self.dragging_token)
                after = (token.x, token.y)
                # Клик без движения запись в историю не создаёт.
                if before is not None and (abs(before[0] - after[0]) > 0.01
                                           or abs(before[1] - after[1]) > 0.01):
                    payload = {
                        'kind': 'tokens',
                        'before': {self.dragging_token: before},
                        'after': {self.dragging_token: after},
                    }
                    if len(path) > 2:
                        payload['path'] = {self.dragging_token:
                                           [list(point) for point in path]}
                    self.edit_finished.emit(payload)
            self.dragging_token = None
            self._drag_snapshot = None
            self.setCursor(Qt.ArrowCursor)
        elif self.moving_map:
            dragged = self._map_drag_moved
            self.moving_map = False
            self._map_drag_moved = False
            self.setCursor(Qt.ArrowCursor)
            if dragged:
                self.emit_map_update()
                snapshot = self._drag_snapshot
                m = self.current_map
                if snapshot and m is not None:
                    before = dict(snapshot.get('geometry') or {})
                    if before:
                        self.edit_finished.emit({
                            'kind': 'map_geometry',
                            'before': {m.id: before},
                            'after': {m.id: {'map_id': m.id, 'pos_x': m.pos_x,
                                             'pos_y': m.pos_y, 'width': m.width,
                                             'height': m.height}},
                        })
                self._drag_snapshot = None
            else:
                # Нажали и отпустили, не сдвинув мышь -> это клик по пустому
                # месту: снимаем выделение с карты.
                self.map_is_selected = False
                self.map_deselected.emit()
                self.update()
        elif self.resizing_map:
            self.resizing_map = False
            self.resize_handle = None
            self.setCursor(Qt.ArrowCursor)
            self.emit_map_update()
            snapshot = self._drag_snapshot
            m = self.current_map
            if snapshot and m is not None:
                before = dict(snapshot.get('geometry') or {})
                changed = (abs(before.get('width', 0.0) - m.width) > 0.01
                           or abs(before.get('height', 0.0) - m.height) > 0.01
                           or abs(before.get('pos_x', 0.0) - m.pos_x) > 0.01
                           or abs(before.get('pos_y', 0.0) - m.pos_y) > 0.01)
                if changed:
                    self.edit_finished.emit({
                        'kind': 'map_geometry',
                        'before': {m.id: before},
                        'after': {m.id: {'map_id': m.id, 'pos_x': m.pos_x,
                                         'pos_y': m.pos_y, 'width': m.width,
                                         'height': m.height}},
                    })
            self._drag_snapshot = None

    def emit_map_update(self):
        if not self.current_map:
            return
        self.map_updated.emit({
            'map_id': self.current_map.id,
            'pos_x': self.current_map.pos_x,
            'pos_y': self.current_map.pos_y,
            'width': self.current_map.width,
            'height': self.current_map.height,
        })

    def hit_test_handle(self, screen_pos: QPoint) -> Optional[str]:
        for name, pos in self.handle_positions().items():
            if (abs(pos.x() - screen_pos.x()) <= HANDLE_HIT_TOLERANCE and
                    abs(pos.y() - screen_pos.y()) <= HANDLE_HIT_TOLERANCE):
                return name
        return None

    def apply_resize(self, wx: float, wy: float):
        m = self.current_map
        rect = self.map_rect_world()
        left, top = rect.left(), rect.top()
        right, bottom = rect.right(), rect.bottom()

        if self.resize_handle in ('nw', 'sw'):
            left = wx
        if self.resize_handle in ('ne', 'se'):
            right = wx
        if self.resize_handle in ('nw', 'ne'):
            top = wy
        if self.resize_handle in ('sw', 'se'):
            bottom = wy

        new_w = max(50.0, abs(right - left))
        new_h = max(50.0, abs(bottom - top))

        # Пропорции сохраняются при зажатом Shift (как в Photoshop)
        if QApplication.keyboardModifiers() & Qt.ShiftModifier and m.height:
            ratio = m.width / m.height
            if new_w / max(new_h, 1.0) > ratio:
                new_w = new_h * ratio
            else:
                new_h = new_w / ratio

        m.pos_x = min(left, right)
        m.pos_y = min(top, bottom)
        m.width = new_w
        m.height = new_h
        self.update()

    def _select_tokens_in_rect(self, rect: QRectF):
        """Выбрать все токены, целиком или частично попавшие в рамку.

        В рамку попадают все видимые токены, которыми вправе распоряжаться
        пользователь: мастер — любые, игрок — только свои. Прежняя проверка
        `is_token_movable` отсекала ещё и токены не в свой ход: в бою рамка
        не выбирала никого, и массовое лечение не находило целей, хотя
        выделять для цели заклинания можно и не в свой ход.
        """
        self.selected_tokens = set()
        for token_id, token in self.current_map_tokens().items():
            if not token.visible:
                continue
            if not self.is_dm and token.owner_id != self.player_id:
                continue   # чужими токенами игрок не управляет
            if self.fog_hides_token(token):
                continue   # что не видно — тем и не выделить
            size = max(MIN_TOKEN_DRAW_PX, self.grid_cell_world * token.size)
            half = size / 2
            token_rect = QRectF(token.x - half, token.y - half, size, size)
            if rect.intersects(token_rect):
                self.selected_tokens.add(token_id)
        # Если выделили ровно один — это он и есть в смысле «выбранный»
        if len(self.selected_tokens) == 1:
            self.selected_token = next(iter(self.selected_tokens))
            self.token_selected.emit(self.selected_token)
        else:
            self.selected_token = None
        # Список сцены подсвечивает всю группу, а не только последнюю строку.
        self.token_selection_changed.emit()

    def selected_token_ids(self) -> list:
        """Список выделенных токенов с учётом одиночного выделения"""
        ids = set(self.selected_tokens)
        if self.selected_token:
            ids.add(self.selected_token)
        return sorted(ids)

    def token_belongs_to_current_map(self, token) -> bool:
        """Показывать ли токен на текущей карте.

        Карта ещё не загружена — ограничивать нечем, показываем всё: иначе
        токены, добавленные до выбора карты, молча исчезли бы из списка.
        Токен без map_id — из старого сохранения либо создан без карты:
        считаем его токеном открытой карты, чтобы он не пропал из виду.
        """
        if self.current_map is None or token.map_id is None:
            return True
        return token.map_id == self.current_map.id

    def current_map_tokens(self) -> Dict[str, object]:
        """Только токены текущей карты — рисовать, ловить клики и выделять надо их."""
        return {tid: tok for tid, tok in self.tokens.items()
                if self.token_belongs_to_current_map(tok)}

    def delete_selection(self) -> bool:
        """Del: удалить выделенные токены, а если их нет — выделенную карту.

        Токены важнее карты: если выделено и то и другое, удаляем только
        токены. Снести карту со всем содержимым одним нажатием было бы
        слишком легко.
        """
        ids = [tid for tid in self.selected_tokens if tid in self.tokens]
        if not ids and self.selected_token in self.tokens:
            ids = [self.selected_token]
        if ids:
            self.selected_tokens.clear()
            self.selected_token = None
            self.update()
            self.remove_tokens_requested.emit(ids)
            return True
        if self.map_is_selected and self.current_map is not None:
            map_id = self.current_map.id
            self.map_is_selected = False
            self.map_deselected.emit()
            self.update()
            self.remove_map_requested.emit(map_id)
            return True
        return False

    def is_token_movable(self, token) -> bool:
        """Можно ли тащить токен мышью.

        Права: мастер — любой токен, игрок — только свой. Но скорость 0
        (схвачен, опутан, парализован, ошеломлён, без сознания, окаменел,
        истощение 5) не даёт двигать токен никому, в том числе мастеру:
        иначе правило работало бы только на половину стола. Мёртвого тоже
        не двигает никто — сначала воскрешение.

        Состояния-ограничения без скорости 0 (сбит с ног — ползком,
        истощение 2 — вдвое медленнее) не блокируют: это мастер считает сам.
        """
        if combat_rules.death_save_state(
                getattr(token, 'death_saves', None))['dead']:
            return False
        if not self.is_dm and token.owner_id != self.player_id:
            return False
        allowed, _why = self._turn_allows_move(token)
        if not allowed:
            return False
        return conditions_rules.can_move(
            getattr(token, 'conditions', None),
            hp=getattr(token, 'hp', None))[0]

    def _movable_selected_ids(self) -> List[str]:
        """Выделенные токены, которые пользователь вправе двигать.

        В бою токены с инициативой ходят по клеткам, поэтому в групповое
        перетаскивание не попадают.
        """
        out = []
        for tid in self.selected_tokens:
            tok = self.tokens.get(tid)
            if (tok is not None and tok.visible and self.is_token_movable(tok)
                    and not self._token_in_combat(tok)):
                out.append(tid)
        return out

    def _cluster_offset(self, index: int, spacing: float) -> tuple:
        """Смещение токена в кучке: 0 — под курсором, дальше кольцами."""
        if index <= 0:
            return 0.0, 0.0
        spots = []
        ring = 1
        while len(spots) <= index:
            spots = [(gx * gx + gy * gy, gx, gy)
                     for gx in range(-ring, ring + 1)
                     for gy in range(-ring, ring + 1)]
            spots.sort()
            ring += 1
        _distance, gx, gy = spots[index]
        return gx * spacing, gy * spacing

    def _drag_token_cluster(self, wx: float, wy: float):
        """Собрать перетаскиваемую группу вокруг курсора.

        Своей расстановкой группа в коридоре упирается в стены и проходит
        в дверь по одному, а то и вовсе не проходит: фишки шире проёма.
        Поэтому все токены идут плотной кучкой под курсором — через дверь
        группа проезжает целиком. Исходная расстановка запомнена и вернётся
        при отпускании (см. `_release_token_cluster`).
        """
        spacing = max(float(getattr(self, "grid_cell_world", 0.0) or 0.0) * 0.3,
                      1.0)
        for index, tid in enumerate(sorted(self.dragging_tokens)):
            ox, oy = self._cluster_offset(index, spacing)
            self.update_token_position(tid, wx + ox, wy + oy)

    def _release_token_cluster(self, wx: float, wy: float):
        """Размагнитить группу: вернуть расстановку вокруг точки броска.

        Сдвиг берётся от начала жеста, поэтому взаимное расположение тел
        остаётся прежним. Если место токена оказалось за стеной, он
        остаётся в кучке: фишка внутри стены хуже, чем плотный отряд.
        """
        anchor = self._group_magnet_anchor
        start = dict(self._group_magnet_start or {})
        if anchor is None or not start:
            return
        dx = wx - anchor[0]
        dy = wy - anchor[1]
        map_data = self.current_map
        for tid in sorted(self.dragging_tokens):
            token = self.tokens.get(tid)
            origin = start.get(tid)
            if token is None or origin is None:
                continue
            target_x = origin[0] + dx
            target_y = origin[1] + dy
            if self.snap_active():
                target_x, target_y = self.snap_to_grid(target_x, target_y)
            if (map_data is not None
                    and wall_rules.token_path_blocked(
                        map_data, token.x, token.y, target_x, target_y)):
                continue
            self.update_token_position(tid, target_x, target_y)

    def get_token_at(self, wx: float, wy: float) -> Optional[str]:
        for token_id in reversed(list(self.tokens.keys())):
            token = self.tokens[token_id]
            # Токены других карт не участвуют: их нет на этом холсте.
            if not self.token_belongs_to_current_map(token):
                continue
            # Скрытый токен не должен ловить клики: его не видно на холсте,
            # значит и тянуть его мышью нельзя.
            if not token.visible:
                continue
            # То же с туманом: клик по пустому месту не должен хватать
            # невидимого врага (у мастера — невидимого актёра).
            if self.fog_hides_token(token):
                continue
            size = max(MIN_TOKEN_DRAW_PX, self.grid_cell_world * token.size)
            half = size / 2
            if (token.x - half <= wx <= token.x + half and
                    token.y - half <= wy <= token.y + half):
                return token_id
        return None

    # ------------------------------------------------------------------
    # Drag & Drop файлов (карты прямо в окно)
    # ------------------------------------------------------------------
    def _token_screen_region(self, token_id) -> Optional[QRectF]:
        """Прямоугольник токена на экране с запасом под кольцо."""
        token = self.tokens.get(token_id) if token_id else None
        if token is None or not token.visible:
            return None
        rect = self._token_screen_rect_world(token)
        pad = self.design(RING_OFFSET_PX + 12.0)
        rect = rect.adjusted(-pad, -pad, pad, pad)
        left, top = self.world_to_screen(rect.left(), rect.top())
        right, bottom = self.world_to_screen(rect.right(), rect.bottom())
        return QRectF(left, top, right - left, bottom - top)

    def set_item_drop_target(self, token_id):
        """Подсветить токен, на который сейчас упадёт перетаскиваемый предмет.

        Перерисовываются только два прямоугольника — старый и новый, — а не
        весь холст: при перетаскивании dragMoveEvent приходит на каждый шаг
        мыши, и полная перерисовка карты была бы заметно тяжёлой.
        """
        token_id = str(token_id or "") or None
        if token_id == self.item_drop_target_id:
            return
        old, self.item_drop_target_id = self.item_drop_target_id, token_id
        for tid in (old, token_id):
            region = self._token_screen_region(tid) if tid else None
            if region is not None:
                self.update(region.toRect().adjusted(-6, -6, 6, 6))

    def dragEnterEvent(self, event):
        if event.mimeData().hasFormat(ITEM_MIME):
            payload = payload_from_mime(event.mimeData())
            if payload and not payload.get("usable", True):
                # Курсора «запрещено» мало: объясняем, почему предмет не
                # ложится на токен, прямо в строке состояния.
                self.show_hint("Этот предмет нельзя применить на токен: "
                               "перетаскивайте зелья и расходники")
            event.acceptProposedAction()
            return
        if event.mimeData().hasFormat(LIGHT_PRESET_MIME):
            if self.lighting_enabled and self.is_dm:
                event.acceptProposedAction()
            return
        if (event.mimeData().hasUrls()
                or event.mimeData().hasFormat('application/x-vtt-my-actor')):
            event.acceptProposedAction()

    def dragLeaveEvent(self, event):
        # Курсор ушёл с холста — кольцо цели и круг света больше не актуальны.
        self.set_item_drop_target(None)
        self.set_light_drop_preview()
        super().dragLeaveEvent(event)

    def dragMoveEvent(self, event):
        if event.mimeData().hasFormat(ITEM_MIME):
            payload = payload_from_mime(event.mimeData())
            wx, wy = self.screen_to_world(event.pos().x(), event.pos().y())
            usable = bool(payload.get("usable", True))
            target_id = self.get_token_at(wx, wy) if usable else None
            # Кольцо плюса показывает точную цель отпускания.
            self.set_item_drop_target(target_id)
            if target_id:
                event.acceptProposedAction()
            else:
                event.ignore()
            return
        if event.mimeData().hasFormat(LIGHT_PRESET_MIME):
            raw = bytes(event.mimeData().data(LIGHT_PRESET_MIME))
            key = raw.decode("utf-8", "ignore").strip()
            wx, wy = self.screen_to_world(event.pos().x(), event.pos().y())
            self.set_light_drop_preview(key, wx, wy)
            if self.lighting_enabled and self.is_dm:
                event.acceptProposedAction()
            else:
                event.ignore()
            return
        event.acceptProposedAction()

    def dropEvent(self, event):
        if event.mimeData().hasFormat(ITEM_MIME):
            payload = payload_from_mime(event.mimeData())
            wx, wy = self.screen_to_world(event.pos().x(), event.pos().y())
            target_id = self.get_token_at(wx, wy)
            # Отпустили кнопку — подсветка больше не нужна, даже если
            # предмет не подошёл и окно сейчас покажет объяснение.
            self.set_item_drop_target(None)
            if payload and payload.get("usable", True) and target_id:
                payload["target_id"] = target_id
                self.item_dropped.emit(payload, target_id)
                event.acceptProposedAction()
            else:
                event.ignore()
            return
        if event.mimeData().hasFormat(LIGHT_PRESET_MIME):
            raw = bytes(event.mimeData().data(LIGHT_PRESET_MIME))
            key = raw.decode("utf-8", "ignore").strip()
            wx, wy = self.screen_to_world(event.pos().x(), event.pos().y())
            if key and self.drop_light_preset(key, wx, wy) is not None:
                event.acceptProposedAction()
            else:
                self.set_light_drop_preview()
                event.ignore()
            return
        if event.mimeData().hasFormat('application/x-vtt-my-actor'):
            raw = bytes(event.mimeData().data('application/x-vtt-my-actor'))
            actor_id = raw.decode('utf-8', 'ignore').strip()
            if actor_id:
                wx, wy = self.screen_to_world(event.pos().x(), event.pos().y())
                self.my_actor_dropped.emit(actor_id, wx, wy)
                event.acceptProposedAction()
            return
        for url in event.mimeData().urls():
            path = url.toLocalFile()
            if path:
                self.files_dropped.emit(path)
                break

    # ------------------------------------------------------------------
    # Контекстное меню
    # ------------------------------------------------------------------
    def show_context_menu(self, screen_pos: QPoint, wx: float, wy: float):
        """ПКМ: два разных меню — по токену и по самой игре.

        Раньше клик по токену показывал ещё «Добавить карту», «Рисовать»,
        «Настройки сетки» и прочее: меню пухло, и в нём не было видно, что
        относится к существу, а что ко всему столу. Теперь разделено:

        * по токену — только действия над ним: имя, видимость, хиты и КД,
          атака, спасбросок, состояния, карточка, удаление;
        * по пустому холсту — только действия стола: добавить токен или
          карту, рисование, области, сетка, привязка, цвет, центрирование.
        """
        menu = QMenu(self)
        token_id = self.get_token_at(wx, wy)
        # Дверь — единственное, у чего есть своё меню, кроме токена: у неё
        # всего два действия, и искать их в общем меню стола неудобно.
        # Токен важнее: если фишка стоит на двери, мастер явно кликнул по ней.
        door_hit = None
        if not token_id and self.is_dm:
            door_hit = self.opening_hit_test(wx, wy, kind=wall_rules.DOOR)

        if token_id:
            # Действия над токеном живут в client/token_menu.py: там же
            # решается, что положено актёру, а что персонажу игрока.
            if self.is_dm:
                tok = self.tokens.get(token_id)
                if tok is not None:
                    token_menu.fill_menu(menu, self, tok)
                # Пакетное удаление — тоже про токены, поэтому только здесь.
                selected = self.selected_token_ids()
                if len(selected) > 1 and token_id in selected:
                    first = menu.actions()[0] if menu.actions() else None
                    act = QAction(
                        f"Удалить выбранные токены ({len(selected)})", self)
                    act.triggered.connect(
                        lambda: self.remove_tokens_requested.emit(selected))
                    menu.insertAction(first, act)
                    menu.insertSeparator(first)
        elif door_hit is not None:
            fill_menu_entries(menu, self.door_menu_entries(door_hit[1]))
        else:
            self._fill_board_menu(menu, wx, wy)

        if menu.actions():
            try:
                menu.exec_(self.mapToGlobal(screen_pos))
            except RuntimeError as exc:
                # На Windows Qt иногда уничтожает меню/холст, пока меню
                # закрывается из-за смены карты или обновления с сервера.
                # Перехватываем только ошибки уничтоженного Qt wrapper.
                if "wrapped C/C++ object" not in str(exc) and "deleted" not in str(exc).lower():
                    raise

    def board_menu_entries(self, wx: float = None, wy: float = None):
        """Действия стола — один список на два меню: ПКМ и кнопку «Стол».

        Действий над конкретным токеном здесь нет: для них есть меню по
        самому токену (``client/token_menu.py``). Игроку из всего стола
        доступно только центрирование карты.

        Если координаты не переданы (кнопка «Стол» в верхней панели), точка
        берётся в момент нажатия пункта — центр экрана: новый токен или
        область появятся там, куда сейчас смотрит мастер.
        """
        def point():
            if wx is None and wy is None:
                return self.view_center_snapped()
            return wx, wy

        if not self.is_dm:
            return [("Центрировать карту (Tab)",
                     "Вписать карту в окно", self.fit_map_to_screen)]

        entries = [
            ("Добавить токен", "Новый токен на открытой карте",
             lambda: self.add_token_requested.emit(*point())),
            ("Добавить карту", "Новая карта в левой панели",
             lambda: self.add_map_requested.emit(*point())),
            ("Рисовать", "Кисть, линии и фигуры прямо на карте", [
                ("Кисть", "Свободный штрих",
                 lambda: self.start_drawing("brush")),
                ("Линия", "Прямая линия",
                 lambda: self.start_drawing("line")),
                ("Круг", "Окружность",
                 lambda: self.start_drawing("circle")),
                ("Квадрат", "Прямоугольник",
                 lambda: self.start_drawing("square")),
                ("Ластик", "Стирать штрихи",
                 lambda: self.start_drawing("eraser")),
                None,
                ("Убрать последний штрих (Ctrl+Z)",
                 "Отменить последнюю операцию рисования",
                 lambda: self.undo_drawing(emit=True)),
                ("Стереть весь рисунок", "Очистить рисунок на карте",
                 lambda: self.clear_drawings(emit=True)),
                ("Курсор", "Выйти из режима рисования",
                 self.stop_drawing),
            ]),
            ("Создать область", "Шаблон области для заклинаний", [
                ("Круг", "Область-круг",
                 lambda: self.start_area("circle", *point())),
                ("Квадрат", "Область-квадрат",
                 lambda: self.start_area("square", *point())),
                ("Фигура", "Многоугольник по точкам",
                 lambda: self.start_area("polygon", *point())),
            ]),
            None,
            ("Настройки сетки (Ctrl+G)",
             "Шаг и смещение начала сетки",
             self.grid_settings_requested.emit),
            ("Графика…",
             "Качество теней, сглаживание и отчёт о памяти: главная ручка "
             "производительности, когда светов и стен много",
             self.graphics_settings_requested.emit),
            ("Ночь на карте",
             "Затемнить карту; выключить — вернуть день. Видят все участники",
             self.toggle_time_of_day,
             {"checkable": True, "checked": self.time_of_day == "night"}),
            ("Привязка токенов к клеткам",
             "Ставить и двигать токен по центру клетки",
             self.set_snap, {"checkable": True,
                             "checked": self.snap_tokens}),
            ("Цвет рисования…", "Цвет кисти и фигур", self.pick_color),
            ("Центрировать карту (Tab)", "Вписать карту в окно",
             self.fit_map_to_screen),
        ]
        # «Удалить карту» — только когда карта открыта: пункт в меню, а не
        # по клику в её прямоугольник, иначе из верхней панели он терялся.
        if self.current_map is not None:
            entries += [None, ("Удалить карту",
                               "Удалить открытую карту со всем содержимым",
                               self.remove_map_current)]
        return entries

    def _fill_board_menu(self, menu: QMenu, wx: float, wy: float):
        """Меню стола по ПКМ — из того же списка, что кнопка «Стол»."""
        fill_menu_entries(menu, self.board_menu_entries(wx, wy))

    def door_menu_entries(self, opening) -> list:
        """ПКМ по двери: только «открыть/закрыть» и «запереть/отпереть».

        Больше ничего: это два действия, которые нужны у двери постоянно,
        и оба без диалогов. Запертая дверь открываться не может, поэтому
        первый пункт погашен, пока её не отопрут.
        """
        if not isinstance(opening, dict) or not self.is_dm:
            return []
        opening_id = opening.get("id")
        locked = bool(opening.get("locked"))
        is_open = bool(opening.get("open")) and not locked
        if is_open:
            label, hint = "Закрыть дверь", "Захлопнуть и услышать замок"
        else:
            label, hint = "Открыть дверь", "Распахнуть настежь"
        return [
            (label, hint if not locked else "Сначала отоприте дверь",
             None if locked
             else (lambda: self.toggle_door(opening_id)),
             {"enabled": not locked}),
            ("Отпереть дверь" if locked else "Запереть дверь",
             "Закрыть на замок: её не откроет ни токен, ни игрок",
             lambda: self.door_lock_requested.emit(opening_id, not locked)),
        ]

    def remove_map_current(self):
        """Запросить удаление текущей карты (решает сервер)"""
        if self.current_map:
            self.remove_map_requested.emit(self.current_map.id)

    def request_token_visibility(self, token_id: str, visible=None):
        """Попросить сервер скрыть/показать токен.

        Локально ничего не меняем: сервер — источник истины, он разошлёт
        новое состояние всем, и холст применит его.
        """
        self.token_visibility_toggled.emit(token_id, visible)

    def set_token_visible(self, token_id: str, visible: bool):
        """Применить видимость токена, полученную от сервера"""
        token = self.tokens.get(token_id)
        if token is None:
            return
        token.visible = bool(visible)
        self.update()

    def rename_token(self, token_id: str):
        token = self.tokens.get(token_id)
        if not token:
            return
        name, ok = QInputDialog.getText(self, "Переименовать токен",
                                        "Новое имя:", text=token.name)
        if ok and name.strip():
            # _before — прежнее значение для отмены (Ctrl+Z). Окно его вырежет
            # и на сервер не отправит. Без него откат был бы невозможен: модель
            # на этот момент уже изменена.
            self.token_updated_requested.emit({'token_id': token_id,
                                               'name': name.strip(),
                                               '_before': {'name': token.name}})

    def snap_active(self) -> bool:
        """Включена ли привязка к клеткам для этого клиента.

        У игрока она есть всегда: фишка ходит по клеткам, даже если мастер
        выключил привязку у себя. У мастера — как выбрано в меню «Стол».
        """
        return bool(self.snap_tokens or not self.is_dm)

    def set_snap(self, checked: bool, notify: bool = True):
        """Привязка токенов к клеткам: выбор мастера и эхо сервера.

        ``notify=False`` — значение пришло с сервера, обратно его не шлём.
        """
        checked = bool(checked)
        changed = checked != self.snap_tokens
        self.snap_tokens = checked
        if changed and notify and self.is_dm:
            self.snap_changed.emit(checked)

    # ---------------------------------------------------------------
    # Движение токена с клавиатуры (WASD)
    # ---------------------------------------------------------------
    def set_wasd_movement(self, enabled: bool):
        """Включить/выключить WASD. Режим необязательный и у каждого свой.

        Это не правило стола, а удобство одного клиента: игрок двигает
        своего персонажа, мастер — тот токен, что выделил. Поэтому
        настройка живёт в `settings.json` клиента, а не на сервере.
        """
        self.wasd_movement = bool(enabled)
        if not self.wasd_movement:
            self.stop_wasd_movement()

    def _wasd_can_move(self, token) -> bool:
        """Можно ли этому клиенту вести токен с клавиатуры.

        Те же права, что у мыши: игрок — только свой персонаж, мастер —
        любого. Мёртвого не двигает никто, невидимого — тоже.
        """
        if token is None or not getattr(token, "visible", True):
            return False
        if combat_rules.death_save_state(token.death_saves)["dead"]:
            return False
        if self.is_dm:
            return True
        return (getattr(token, "owner_id", None) == self.player_id
                and token_kind.is_player(token))

    def wasd_token(self):
        """Кем двигает WASD: у мастера — выделенным, у игрока — своим.

        Игрок может кликнуть по чужой фишке, но вести её это не даёт: без
        своего токена в выделении берётся свой персонаж на этой карте.
        """
        if self.current_map is None:
            return None
        selected = self.tokens.get(self.selected_token) \
            if self.selected_token else None
        if self._wasd_can_move(selected):
            return selected
        for token in self.current_map_tokens().values():
            if self._wasd_can_move(token):
                return token
        return None

    def _wasd_direction(self):
        """Текущее направление: ходит последняя зажатая клавиша."""
        if not self._wasd_keys:
            return None
        return WASD_DIRECTIONS.get(self._wasd_keys[-1])

    def wasd_step(self, direction=None) -> bool:
        """Один шаг: целая клетка в сторону. Вернёт False, если не вышло.

        Шаг идёт через ту же проверку стен, что и перетаскивание мышью:
        закрытая дверь толкается, стена останавливает, запертая — ругается.
        Дальше путь уходит серверу обычным `MOVE_TOKEN`, поэтому бюджет
        хода, права и открытие дверей считаются там же, где и всегда.
        """
        direction = direction or self._wasd_direction()
        if direction is None:
            return False
        token = self.wasd_token()
        if token is None or self.current_map is None:
            return False
        cell = float(self.grid_cell_world or 0.0)
        if cell <= 0.0:
            cell = WASD_FALLBACK_CELL
        start_x, start_y = float(token.x), float(token.y)
        if self.snap_active():
            start_x, start_y = self.snap_to_grid(start_x, start_y)
        target_x = start_x + direction[0] * cell
        target_y = start_y + direction[1] * cell
        if not self.point_on_map(target_x, target_y):
            return False
        walk = self._walk_token_to(token, self.current_map,
                                  target_x, target_y)
        if not walk:
            return False
        end_x, end_y = walk[-1]
        if math.hypot(end_x - target_x, end_y - target_y) > 0.5:
            # Упёрлись в стену или запертую дверь: стоим на месте, а не
            # дёргаемся вперёд-назад каждый шаг.
            return False
        self._token_move_path = walk
        self.update_token_position(token.id, target_x, target_y,
                                   animate=True)
        self.token_moved.emit(token.id, target_x, target_y)
        self._token_move_path = []
        return True

    def _ensure_wasd_timer(self):
        """Таймер шагов: пока клавиша зажата, токен идёт сам."""
        if self._wasd_timer is None:
            self._wasd_timer = QTimer(self)
            self._wasd_timer.setInterval(WASD_STEP_MS)
            self._wasd_timer.timeout.connect(self._on_wasd_tick)
        if not self._wasd_timer.isActive():
            self._wasd_timer.start()

    def _on_wasd_tick(self):
        if not self.wasd_movement or not self._wasd_keys:
            self.stop_wasd_movement()
            return
        # Упёрлись — ничего не делаем, но таймер оставляем: как только
        # игрок отпустит клавишу или повернёт, шаг пойдёт снова.
        self.wasd_step()

    def stop_wasd_movement(self):
        """Отпустить клавиши: остановить ход (без сети — шаги уже ушли)."""
        self._wasd_keys = []
        if self._wasd_timer is not None:
            self._wasd_timer.stop()

    def focusOutEvent(self, event):
        # Клавиши, зажатые до потери фокуса, иначе так и ходили бы: отпуск
        # приходит в другое окно, и набор направлений остаётся «зажатым».
        self.stop_wasd_movement()
        super().focusOutEvent(event)

    def pick_color(self):
        color = QColorDialog.getColor(QColor(*self.drawing_color), self,
                                      "Цвет рисования")
        if color.isValid():
            self.drawing_color = (color.red(), color.green(), color.blue())

    # ------------------------------------------------------------------
    # Рисование
    # ------------------------------------------------------------------
    # ------------------------------------------------------------------
    # Курсоры инструментов
    # ------------------------------------------------------------------
    def _brush_cursor(self, diameter: int) -> QCursor:
        """Собрать курсор-окружность заданного диаметра (в экранных пикселях).

        Кольцо рисуем двумя обводками: белой снизу и чёрной поверх. На тёмной
        карте видно белую, на светлой — чёрную, поэтому курсор читается на
        любом фоне. В центре — точка: она показывает точное место попадания.
        """
        d = max(MIN_CURSOR_CIRCLE_PX, min(MAX_CURSOR_PX, int(diameter)))
        cached = self._cursor_cache.get(d)
        if cached is not None:
            return cached

        pm = QPixmap(d, d)
        pm.fill(Qt.transparent)
        painter = QPainter(pm)
        painter.setRenderHint(QPainter.Antialiasing, True)

        # Белая обводка — для тёмного фона
        pen = QPen(QColor(255, 255, 255))
        pen.setWidth(2)
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawEllipse(QRectF(1.0, 1.0, d - 2.0, d - 2.0))

        # Чёрная обводка поверх — для светлого фона
        pen = QPen(QColor(0, 0, 0))
        pen.setWidth(1)
        painter.setPen(pen)
        painter.drawEllipse(QRectF(1.5, 1.5, d - 3.0, d - 3.0))

        # Точка ровно по центру: без неё непонятно, куда именно попадает кисть
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(QColor(0, 0, 0)))
        painter.drawRect(QRectF(d / 2.0 - 0.5, d / 2.0 - 0.5, 1.0, 1.0))
        painter.end()

        cursor = QCursor(pm, d // 2, d // 2)
        self._cursor_cache[d] = cursor
        return cursor

    def _apply_tool_cursor(self):
        """Поставить курсор, подходящий активному инструменту.

        Кисть и ластик показывают окружность по толщине (как в Photoshop),
        линия и фигуры — перекрестье: у них важен не размер мазка, а точки,
        между которыми тянется фигура. Текст — текстовый курсор, перенос
        надписей — «перемещение».
        """
        mode = self.drawing_mode
        if mode == 'text':
            self.setCursor(Qt.IBeamCursor)
            return
        if mode == 'move':
            self.setCursor(Qt.SizeAllCursor)
            return
        if mode == 'ruler':
            self.setCursor(Qt.CrossCursor)
            return
        if mode in ('brush', 'eraser'):
            # Толщина задана в мировых единицах, а курсор живёт в экранных,
            # поэтому масштаб вида умножаем: 20 px при 50% выглядят как 10 px.
            diameter = int(round(self.brush_size * self.scale))
            if diameter >= MIN_CURSOR_CIRCLE_PX:
                self.setCursor(self._brush_cursor(diameter))
            else:
                # Кисть в 1 пиксель (или очень мелкий масштаб): кольцо
                # выродилось бы в точку, поэтому показываем перекрестье.
                self.setCursor(Qt.CrossCursor)
            return
        if mode in RASTER_TOOLS:
            self.setCursor(Qt.CrossCursor)
            return
        self.setCursor(Qt.ArrowCursor)

    def start_drawing(self, mode: str):
        """Активировать инструмент рисования"""
        # Смена инструмента закрывает правку надписи: иначе поле осталось
        # бы висеть поверх карты без своего инструмента.
        if mode not in ('text', 'move'):
            self.finish_text_edit(commit=True)
            self._set_selected_text(None)
        self._text_drag = None
        self.drawing_mode = mode
        self.drawing_points = []
        self._preview_points = []
        self.drawing_is_eraser = (mode == 'eraser')
        if mode in RASTER_TOOLS and self.current_map:
            self.ensure_draw_layer()
        self._apply_tool_cursor()
        self.tool_changed.emit(mode or '')
        self.update()

    def stop_drawing(self):
        """Вернуться в режим курсора"""
        if self.drawing_mode == 'ruler':
            # Измерение со экрана убираем: иначе стрелка осталась бы висеть.
            self.ruler_start = None
            self.ruler_end = None
            self.ruler_active = False
        self.finish_text_edit(commit=True)
        self._text_drag = None
        self._set_selected_text(None)
        self.drawing_mode = None
        self.drawing_points = []
        self._preview_points = []
        self.drawing_is_eraser = False
        self._apply_tool_cursor()
        self.tool_changed.emit('')
        self.update()

    def set_brush_size(self, size: float):
        self.brush_size = max(1.0, float(size))
        # Курсор зависит от толщины, поэтому пересобираем его сразу — иначе
        # после сдвига ползунка кольцо осталось бы прежнего размера.
        self._apply_tool_cursor()
        self.update()

    def set_brush_opacity(self, value: float):
        self.brush_opacity = max(0.05, min(1.0, float(value)))
        self.update()

    def set_fill_shapes(self, enabled: bool):
        """Заливать круг/квадрат/треугольник полупрозрачным цветом"""
        self.fill_shapes = bool(enabled)
        self.update()

    def start_area(self, kind: str, wx: float, wy: float):
        self.drawing_mode = kind
        self.drawing_points = [(wx, wy)]
        self._preview_points = []
        self._apply_tool_cursor()

    def finish_drawing(self):
        """Завершить штрих и записать его в растровый слой."""
        mode = self.drawing_mode
        points = self.drawing_points[:]
        preview = self._preview_points[:]
        self.drawing_mode = None
        self.drawing_points = []
        self._preview_points = []
        self._apply_tool_cursor()
        self.update()

        if not points:
            return

        # Фигуры тянут вторую точку отдельно
        if mode in ('line', 'circle', 'square') and preview:
            points = [points[0], preview[0]]

        # Сюда попадают все инструменты рисования: и кисть, и линия,
        # и фигуры. Всё уходит в растровый слой.
        if mode in RASTER_TOOLS:
            op = {
                'tool': mode,
                'points': [list(pt) for pt in points],
                # цвет всегда списком: кортеж после JSON стал бы списком,
                # и операции перестали бы совпадать при сравнении
                'color': list(self.drawing_color) if mode != 'eraser' else [0, 0, 0],
                'width': float(self.brush_size),
                'opacity': float(self.brush_opacity),
                'filled': self.fill_shapes and mode in ('circle', 'square', 'polygon'),
            }
            self.commit_draw_op(op)
            return


